// Associate Quality Engineer (AQE) Professional Certificate
// 8 modules, 40 lessons, 8 practice labs, 8 quizzes, 113 interactive labs
// Idempotent: safe to run again — overwrites course files, skips registry if already patched.
import { readFileSync, writeFileSync, existsSync, mkdirSync } from "fs";
import { dirname } from "path";
const fail = (m) => { console.error("STOPPED, nothing written: " + m); process.exit(1); };
if (!existsSync("client/src/lms/registry.ts")) fail("client/src/lms/registry.ts not found — run this from the analytix360 folder");
const TEXT = {"client/src/data/courses/aqe.ts":"import type { LmsCourse } from \"../../lms/types\";\nimport { m1 } from \"./aqe/m1\";\nimport { m2 } from \"./aqe/m2\";\nimport { m3 } from \"./aqe/m3\";\nimport { m4 } from \"./aqe/m4\";\nimport { m5 } from \"./aqe/m5\";\nimport { m6 } from \"./aqe/m6\";\nimport { m7 } from \"./aqe/m7\";\nimport { m8 } from \"./aqe/m8\";\n\nexport const AQE_COURSE: LmsCourse = {\n  id: \"aqe\",\n  code: \"AQE\",\n  title: \"Associate Quality Engineer\",\n  subtitle: \"Statistical methods, measurement systems, FMEA, DOE, SPC and continuous improvement for quality engineers\",\n  accent: \"#F59E0B\",\n  hours: 132,\n  certification: \"Analytix Engineering professional certificate with QR verification\",\n  modules: [m1, m2, m3, m4, m5, m6, m7, m8],\n};\n","client/src/data/courses/aqe/m1.ts":"import type { CourseModule } from \"../../../lms/types\";\n\n/* ──────────────────────────────────────────────────────────────────────\n   Module 1 — Quality Management Systems and Leadership\n   Associate Quality Engineer (AQE) Certification Course\n   ────────────────────────────────────────────────────────────────────── */\n\nconst L1_ID = \"aqe-m1-l1\";\nconst L2_ID = \"aqe-m1-l2\";\nconst L3_ID = \"aqe-m1-l3\";\nconst L4_ID = \"aqe-m1-l4\";\nconst L5_ID = \"aqe-m1-l5\";\nconst PRACTICE_ID = \"aqe-m1-practice\";\nconst QUIZ_ID = \"aqe-m1-quiz\";\n\nexport const m1: CourseModule = {\n  id: \"aqe-m1\",\n  number: 1,\n  title: \"Quality Management Systems and Leadership\",\n  summary:\n    \"This module establishes the foundation of quality management for the associate quality engineer. It covers the seven quality management principles defined in ISO 9000:2015 and the process approach that underpins ISO 9001:2015, including its high-level structure clauses 4–10. Sector-specific standards — IATF 16949 for automotive, AS9100 for aerospace, and ISO 13485 for medical devices — are examined alongside their unique requirements. The module addresses auditing competencies: planning, conducting, and reporting audits per ISO 19011, writing findings and verifying corrective actions. Quality costs are analysed through the prevention–appraisal–failure (PAF) model, and key metrics such as ppm, DPMO, sigma level, FPY, RTY, and OEE are derived with worked examples. Finally, the module defines the quality engineer's leadership role in cross-functional teams, influencing without authority, and driving continual improvement.\",\n  hours: 16,\n\n  lessons: [\n    /* ================================================================\n       LESSON 1 — Quality management principles and the process approach\n       ================================================================ */\n    {\n      id: L1_ID,\n      title: \"Quality management principles and the process approach\",\n      minutes: 25,\n      objectives: [\n        \"Explain each of the seven quality management principles from ISO 9000:2015 and give a workplace example for each.\",\n        \"Describe the process approach including inputs, outputs, resources, owner, indicators, and risk considerations.\",\n        \"Apply the Plan–Do–Check–Act (PDCA) cycle at system, process, and product levels.\",\n      ],\n      blocks: [\n        {\n          type: \"p\",\n          text: \"Every quality management system rests on a set of principles that guide organisations toward sustained success. ISO 9000:2015 defines seven quality management principles (QMPs) that form the philosophical backbone of the ISO 9001 standard. As a quality engineer, you must not only know these principles — you must be able to translate them into measurable actions within your organisation.\",\n        },\n        {\n          type: \"h\",\n          text: \"The seven quality management principles\",\n        },\n        {\n          type: \"table\",\n          head: [\"Principle\", \"Core intent\", \"Workplace example\"],\n          rows: [\n            [\n              \"Customer focus\",\n              \"Understand current and future customer needs, meet requirements, exceed expectations\",\n              \"A Douala brewing company surveys distributors quarterly to align product specifications with market demand\",\n            ],\n            [\n              \"Leadership\",\n              \"Establish unity of purpose and direction, create conditions for people to achieve quality objectives\",\n              \"Plant manager in Bafoussam sets measurable quality targets and reviews them at weekly stand-ups\",\n            ],\n            [\n              \"Engagement of people\",\n              \"Competent, empowered, engaged people at all levels create value\",\n              \"Operators at a Bonabéri machining shop are trained to halt the line when a defect is detected\",\n            ],\n            [\n              \"Process approach\",\n              \"Manage activities as interrelated processes that function as a coherent system\",\n              \"A Yaoundé cement plant maps each process from raw material receipt to dispatch with defined owners\",\n            ],\n            [\n              \"Improvement\",\n              \"Maintain focus on improvement to sustain current performance and react to changing conditions\",\n              \"Monthly kaizen events at a food processing line in Douala target a 5 % reduction in rework each quarter\",\n            ],\n            [\n              \"Evidence-based decision making\",\n              \"Decisions based on analysis and evaluation of data are more likely to produce desired results\",\n              \"Using SPC charts to decide whether to adjust a filling machine rather than relying on operator intuition\",\n            ],\n            [\n              \"Relationship management\",\n              \"Manage relationships with relevant interested parties to optimise their impact on performance\",\n              \"A Bonabéri automotive parts supplier conducts annual audits and development workshops with key raw-material vendors\",\n            ],\n          ],\n        },\n        {\n          type: \"callout\",\n          tone: \"key\",\n          title: \"Principles vs requirements\",\n          text: \"The seven QMPs are principles, not auditable requirements. ISO 9001 translates these principles into specific 'shall' statements. During an audit you assess compliance against ISO 9001 requirements, but you use the principles to interpret intent.\",\n        },\n        {\n          type: \"h\",\n          text: \"The process approach\",\n        },\n        {\n          type: \"p\",\n          text: \"The process approach requires organisations to understand and manage interrelated processes as a system. Each process transforms inputs into outputs using resources, under the direction of a process owner. The quality engineer's role is to ensure every process has defined indicators (KPIs) and that risks and opportunities are identified and addressed.\",\n        },\n        {\n          type: \"table\",\n          head: [\"Element\", \"Description\", \"Example (machining process)\"],\n          rows: [\n            [\"Inputs\", \"Materials, information, requirements entering the process\", \"Raw steel bar stock, engineering drawing, customer PO\"],\n            [\"Activities\", \"Steps that transform inputs\", \"Turning, milling, deburring, inspection\"],\n            [\"Outputs\", \"Products, services, information leaving the process\", \"Finished shaft, inspection report, delivery note\"],\n            [\"Owner\", \"Person accountable for the process\", \"Production supervisor — Mr Nkeng\"],\n            [\"Resources\", \"People, equipment, infrastructure, environment\", \"CNC lathe, trained operator, calibrated micrometer, climate-controlled shop\"],\n            [\"Indicators\", \"Metrics to monitor process performance\", \"Cpk ≥ 1.33, first-pass yield ≥ 97 %, cycle time ≤ 4.2 min\"],\n            [\"Risks & opportunities\", \"Factors that could affect ability to achieve intended results\", \"Risk: tool wear causing out-of-tolerance parts; Opportunity: new insert grade reducing scrap by 15 %\"],\n          ],\n        },\n        {\n          type: \"equip\",\n          title: \"Process flow chart\",\n          items: [\n            {\n              art: \"process-flow-chart\",\n              name: \"Process flow chart\",\n              caption: \"A process flow chart documents the sequence of operations, decision points, inspections, and material movements. It is a key documented information requirement in ISO 9001 clause 8.1 and is essential for FMEA, control plan development, and auditing.\",\n            },\n          ],\n        },\n        {\n          type: \"h\",\n          text: \"PDCA at three levels\",\n        },\n        {\n          type: \"p\",\n          text: \"The Plan–Do–Check–Act cycle, attributed to Deming, operates at three levels in a quality management system. At the system level, PDCA drives the overall QMS planning and review. At the process level, it governs how individual processes are established, monitored, and improved. At the product level, it guides design, verification, validation, and release.\",\n        },\n        {\n          type: \"table\",\n          head: [\"Level\", \"Plan\", \"Do\", \"Check\", \"Act\"],\n          rows: [\n            [\n              \"System\",\n              \"Establish QMS policy, objectives, context (clauses 4–6)\",\n              \"Implement processes and allocate resources (clauses 7–8)\",\n              \"Monitor, measure, analyse, evaluate; conduct internal audits and management review (clause 9)\",\n              \"Address nonconformities, take corrective actions, drive continual improvement (clause 10)\",\n            ],\n            [\n              \"Process\",\n              \"Define process inputs, outputs, KPIs, risks\",\n              \"Execute the process per documented procedures\",\n              \"Measure KPIs, analyse trends, compare to targets\",\n              \"Adjust process parameters, update procedures, retrain\",\n            ],\n            [\n              \"Product\",\n              \"Design and development planning, design inputs\",\n              \"Create prototypes, produce pilot run\",\n              \"Design verification and validation, inspection results\",\n              \"Release product or initiate corrective design changes\",\n            ],\n          ],\n        },\n        {\n          type: \"callout\",\n          tone: \"tip\",\n          title: \"PDCA is not sequential\",\n          text: \"In practice, PDCA operates as a continuous spiral. The 'Act' phase feeds directly into new planning. A quality engineer facilitating a corrective action will often cycle through PDCA multiple times before closing a finding.\",\n        },\n        {\n          type: \"sorter\",\n          id: \"aqe-m1-sorter-principles\",\n          title: \"Classify the seven QMP examples\",\n          task: \"Drag each workplace scenario into the correct quality management principle bucket.\",\n          layout: \"columns\",\n          buckets: [\n            { label: \"Customer focus\", desc: \"Understanding and meeting customer needs\" },\n            { label: \"Leadership\", desc: \"Creating unity of purpose\" },\n            { label: \"Engagement of people\", desc: \"Empowering competent people\" },\n            { label: \"Process approach\", desc: \"Managing interrelated processes\" },\n            { label: \"Improvement\", desc: \"Focus on continual improvement\" },\n            { label: \"Evidence-based decision making\", desc: \"Data-driven decisions\" },\n          ],\n          items: [\n            {\n              text: \"The Douala plant manager defines clear quality objectives and personally chairs the weekly quality review\",\n              bucket: 1,\n              explain: \"Setting direction and reviewing progress are core leadership behaviours.\",\n            },\n            {\n              text: \"A Bafoussam cement factory analyses customer complaint trends before revising its product specification\",\n              bucket: 0,\n              explain: \"Using customer feedback to adjust specifications demonstrates customer focus.\",\n            },\n            {\n              text: \"Operators at a Bonabéri food processing line are authorised to stop the conveyor when they detect contamination\",\n              bucket: 2,\n              explain: \"Empowering operators to act demonstrates engagement of people.\",\n            },\n            {\n              text: \"A Yaoundé machining shop maps its heat-treatment process with defined inputs, outputs, and KPIs\",\n              bucket: 3,\n              explain: \"Documenting process elements is the process approach in action.\",\n            },\n            {\n              text: \"The quality team uses Pareto analysis of scrap data to prioritise which defect category to tackle first\",\n              bucket: 5,\n              explain: \"Using data analysis to direct resources is evidence-based decision making.\",\n            },\n            {\n              text: \"A monthly kaizen event targets a 10 % reduction in customer returns for the beverage filling line\",\n              bucket: 4,\n              explain: \"Structured improvement events with measurable targets exemplify the improvement principle.\",\n            },\n          ],\n        },\n        {\n          type: \"form\",\n          id: \"aqe-m1-form-pdca\",\n          title: \"Match PDCA steps to actions\",\n          task: \"For each action below, select the PDCA phase it belongs to.\",\n          fields: [\n            {\n              kind: \"select\",\n              label: \"Conduct an internal audit of the receiving inspection process\",\n              options: [\"Plan\", \"Do\", \"Check\", \"Act\"],\n              answer: 2,\n              explain: \"Internal audits are a 'Check' activity — they evaluate whether the process conforms to planned arrangements.\",\n            },\n            {\n              kind: \"select\",\n              label: \"Define quality objectives for the next fiscal year\",\n              options: [\"Plan\", \"Do\", \"Check\", \"Act\"],\n              answer: 0,\n              explain: \"Setting objectives is part of 'Plan' — establishing what you intend to achieve.\",\n            },\n            {\n              kind: \"select\",\n              label: \"Implement a revised work instruction for soldering operations\",\n              options: [\"Plan\", \"Do\", \"Check\", \"Act\"],\n              answer: 1,\n              explain: \"Executing updated procedures is a 'Do' activity.\",\n            },\n            {\n              kind: \"select\",\n              label: \"Issue a corrective action request after finding a recurring nonconformity\",\n              options: [\"Plan\", \"Do\", \"Check\", \"Act\"],\n              answer: 3,\n              explain: \"Taking corrective action to eliminate a nonconformity's root cause is the 'Act' phase.\",\n            },\n            {\n              kind: \"select\",\n              label: \"Review SPC trend charts during the monthly management review\",\n              options: [\"Plan\", \"Do\", \"Check\", \"Act\"],\n              answer: 2,\n              explain: \"Reviewing performance data against objectives is a 'Check' activity.\",\n            },\n          ],\n        },\n        {\n          type: \"check\",\n          id: \"aqe-m1-check-l1\",\n          question: \"Which quality management principle is MOST directly linked to ISO 9001's requirement for organisations to determine external and internal issues relevant to their purpose (clause 4.1)?\",\n          options: [\n            \"Customer focus\",\n            \"Process approach\",\n            \"Evidence-based decision making\",\n            \"Leadership\",\n          ],\n          answer: 3,\n          explain: \"Clause 4.1 requires top management to understand the organisation's context and establish strategic direction — a core leadership responsibility. While other principles are relevant, leadership is the driver for establishing context, purpose, and direction.\",\n        },\n        {\n          type: \"links\",\n          items: [\n            {\n              label: \"ISO 9000:2015 — Quality management systems — Fundamentals and vocabulary\",\n              url: \"https://www.iso.org/standard/45481.html\",\n              source: \"ISO\",\n            },\n            {\n              label: \"ASQ — Seven quality management principles\",\n              url: \"https://asq.org/quality-resources/quality-management-system\",\n              source: \"ASQ\",\n            },\n          ],\n        },\n      ],\n    },\n\n    /* ================================================================\n       LESSON 2 — ISO 9001:2015 requirements for the quality engineer\n       ================================================================ */\n    {\n      id: L2_ID,\n      title: \"ISO 9001:2015 requirements for the quality engineer\",\n      minutes: 30,\n      objectives: [\n        \"Describe the high-level structure (HLS) of ISO 9001:2015 and explain the purpose of clauses 4 through 10.\",\n        \"Distinguish between 'maintained' documented information (procedures, policies) and 'retained' documented information (records, evidence).\",\n        \"Apply clause 8 operational planning requirements to a manufacturing scenario including design inputs, verification, and control of external providers.\",\n      ],\n      blocks: [\n        {\n          type: \"p\",\n          text: \"ISO 9001:2015 uses the Annex SL high-level structure (HLS) shared by all ISO management system standards. This common framework makes integration of quality, environmental (ISO 14001), and occupational health and safety (ISO 45001) systems straightforward. For the quality engineer, deep familiarity with clauses 4–10 is non-negotiable — you must know which requirements apply to each situation you encounter.\",\n        },\n        {\n          type: \"h\",\n          text: \"High-level structure overview\",\n        },\n        {\n          type: \"table\",\n          head: [\"Clause\", \"Title\", \"Key focus for quality engineers\"],\n          rows: [\n            [\"4\", \"Context of the organisation\", \"Internal/external issues, interested parties, QMS scope, process interactions\"],\n            [\"5\", \"Leadership\", \"Quality policy, roles and responsibilities, customer focus\"],\n            [\"6\", \"Planning\", \"Risks and opportunities, quality objectives, planning of changes\"],\n            [\"7\", \"Support\", \"Resources, competence, awareness, communication, documented information\"],\n            [\"8\", \"Operation\", \"Operational planning, design and development, production, release, control of nonconforming outputs\"],\n            [\"9\", \"Performance evaluation\", \"Monitoring, measurement, analysis, evaluation, internal audit, management review\"],\n            [\"10\", \"Improvement\", \"Nonconformity, corrective action, continual improvement\"],\n          ],\n        },\n        {\n          type: \"h\",\n          text: \"Clause 4 — Context of the organisation\",\n        },\n        {\n          type: \"p\",\n          text: \"Clause 4 requires the organisation to determine external and internal issues that are relevant to its purpose and strategic direction. For a Douala-based brewing company, external issues might include regulatory changes by ANOR (Agence des Normes et de la Qualité), currency fluctuation of the FCFA, or supply-chain disruptions. Internal issues could include ageing equipment, workforce competency gaps, or production capacity constraints.\",\n        },\n        {\n          type: \"callout\",\n          tone: \"workplace\",\n          title: \"Interested parties in practice\",\n          text: \"At a Bafoussam machining shop, interested parties include: customers (automotive OEMs), employees, regulatory bodies (Ministry of Mines), raw-material suppliers, the local community (noise and environmental impact), and shareholders. Each party's relevant requirements must be determined and monitored.\",\n        },\n        {\n          type: \"h\",\n          text: \"Clause 6 — Planning: risks, opportunities, and objectives\",\n        },\n        {\n          type: \"p\",\n          text: \"Clause 6.1 requires the organisation to address risks and opportunities when planning the QMS. This is not a requirement for formal risk assessment (such as an FMEA), but rather a systematic consideration of what could go wrong or be improved. Quality objectives (clause 6.2) must be measurable, monitored, communicated, and updated. They must be consistent with the quality policy and relevant to product conformity.\",\n        },\n        {\n          type: \"steps\",\n          title: \"Setting effective quality objectives\",\n          items: [\n            \"Align each objective with the quality policy and strategic direction\",\n            \"Make it measurable — specify the metric, target, and timeframe (e.g., 'Reduce customer complaints to fewer than 5 per month by Q4')\",\n            \"Assign responsibility — name the process owner accountable for achieving the objective\",\n            \"Determine actions needed, resources required, and timeline\",\n            \"Define how results will be evaluated — which reports, at which review meetings\",\n          ],\n        },\n        {\n          type: \"h\",\n          text: \"Clause 8 — Operation\",\n        },\n        {\n          type: \"p\",\n          text: \"Clause 8 is the largest clause and covers the core value-creating activities. For a quality engineer, clauses 8.3 (design and development), 8.4 (control of externally provided processes, products, and services), and 8.7 (control of nonconforming outputs) are particularly critical.\",\n        },\n        {\n          type: \"table\",\n          head: [\"Sub-clause\", \"Requirement\", \"Quality engineer's role\"],\n          rows: [\n            [\"8.1\", \"Operational planning and control\", \"Establish process criteria, implement controls, maintain documented information\"],\n            [\"8.2\", \"Requirements for products and services\", \"Review customer requirements, confirm capability before acceptance\"],\n            [\"8.3\", \"Design and development\", \"Define design inputs/outputs, conduct design reviews, verification, validation\"],\n            [\"8.4\", \"Control of external providers\", \"Evaluate, select, monitor, and re-evaluate suppliers; define verification activities\"],\n            [\"8.5\", \"Production and service provision\", \"Control production conditions, identification, traceability, preservation\"],\n            [\"8.6\", \"Release of products and services\", \"Ensure planned arrangements are satisfied before release; maintain evidence\"],\n            [\"8.7\", \"Control of nonconforming outputs\", \"Identify, segregate, disposition; document the nonconformity and actions taken\"],\n          ],\n        },\n        {\n          type: \"h\",\n          text: \"Clauses 9 and 10 — Checking and improving\",\n        },\n        {\n          type: \"p\",\n          text: \"Clause 9 requires monitoring, measurement, analysis, and evaluation of QMS performance. This includes customer satisfaction monitoring, internal audits per a defined programme, and management review at planned intervals. Clause 10 demands that organisations react to nonconformities by taking corrective action proportional to the effects, and pursue continual improvement through analysis of data and audit results.\",\n        },\n        {\n          type: \"callout\",\n          tone: \"key\",\n          title: \"Maintained vs retained documented information\",\n          text: \"ISO 9001:2015 uses two specific phrases: 'maintain documented information' means keep it current — these are your procedures, policies, process descriptions. 'Retain documented information' means keep it as evidence — these are your records: inspection results, calibration certificates, audit reports, training records. Confusing the two is a common audit finding.\",\n        },\n        {\n          type: \"form\",\n          id: \"aqe-m1-form-clauses\",\n          title: \"Match clauses to situations\",\n          task: \"For each workplace situation, select the ISO 9001:2015 clause that most directly applies.\",\n          fields: [\n            {\n              kind: \"select\",\n              label: \"A Bonabéri supplier delivers steel bar stock that fails incoming inspection. The quality team must segregate, tag, and decide whether to return, rework, or scrap the material.\",\n              options: [\n                \"Clause 6.1 — Actions to address risks\",\n                \"Clause 8.4 — Control of external providers\",\n                \"Clause 8.7 — Control of nonconforming outputs\",\n                \"Clause 10.2 — Nonconformity and corrective action\",\n              ],\n              answer: 2,\n              explain: \"Clause 8.7 specifically covers identifying and controlling outputs that do not conform to requirements, including segregation, disposition (return, rework, scrap, concession), and documentation.\",\n            },\n            {\n              kind: \"select\",\n              label: \"The management team at a Yaoundé food processing plant reviews customer satisfaction data, audit results, and quality objective performance at a quarterly meeting.\",\n              options: [\n                \"Clause 5.1 — Leadership and commitment\",\n                \"Clause 9.1 — Monitoring, measurement, analysis\",\n                \"Clause 9.3 — Management review\",\n                \"Clause 10.3 — Continual improvement\",\n              ],\n              answer: 2,\n              explain: \"Management review (clause 9.3) requires top management to review the QMS at planned intervals, using inputs including audit results, customer feedback, and process performance data.\",\n            },\n            {\n              kind: \"select\",\n              label: \"A quality engineer must verify that a new CNC operator has the required training, certifications, and demonstrated competency before being allowed to operate unsupervised.\",\n              options: [\n                \"Clause 7.2 — Competence\",\n                \"Clause 7.3 — Awareness\",\n                \"Clause 8.5.1 — Control of production\",\n                \"Clause 8.1 — Operational planning\",\n              ],\n              answer: 0,\n              explain: \"Clause 7.2 requires the organisation to determine necessary competence, ensure persons are competent on the basis of education, training, or experience, and retain documented information as evidence of competence.\",\n            },\n          ],\n        },\n        {\n          type: \"sorter\",\n          id: \"aqe-m1-sorter-docinfo\",\n          title: \"Maintained vs retained documented information\",\n          task: \"Classify each item as documented information that should be 'maintained' (kept current) or 'retained' (kept as evidence).\",\n          layout: \"columns\",\n          buckets: [\n            { label: \"Maintained\", desc: \"Procedures, policies — kept current\" },\n            { label: \"Retained\", desc: \"Records, evidence — kept as proof\" },\n          ],\n          items: [\n            {\n              text: \"Quality policy statement\",\n              bucket: 0,\n              explain: \"The quality policy is a living document that must be maintained current and communicated.\",\n            },\n            {\n              text: \"Calibration certificate for a micrometer\",\n              bucket: 1,\n              explain: \"A calibration certificate is evidence (a record) that the instrument was calibrated — it is retained.\",\n            },\n            {\n              text: \"Work instruction for the heat-treatment process\",\n              bucket: 0,\n              explain: \"A work instruction describes how to perform an activity and must be kept current — maintained.\",\n            },\n            {\n              text: \"Internal audit report from last quarter\",\n              bucket: 1,\n              explain: \"An audit report is evidence that the audit was conducted — it is retained.\",\n            },\n            {\n              text: \"Training record showing an operator completed SPC training\",\n              bucket: 1,\n              explain: \"Training records are evidence of competence — retained documented information.\",\n            },\n            {\n              text: \"Incoming inspection procedure\",\n              bucket: 0,\n              explain: \"A procedure describing how to perform incoming inspection must be kept current — maintained.\",\n            },\n          ],\n        },\n        {\n          type: \"check\",\n          id: \"aqe-m1-check-l2\",\n          question: \"Under ISO 9001:2015, which clause requires the organisation to evaluate and select external providers based on their ability to provide processes, products, or services in accordance with requirements?\",\n          options: [\n            \"Clause 7.1.6 — Organisational knowledge\",\n            \"Clause 8.4.1 — Control of externally provided processes\",\n            \"Clause 9.1.3 — Analysis and evaluation\",\n            \"Clause 6.1 — Actions to address risks and opportunities\",\n          ],\n          answer: 1,\n          explain: \"Clause 8.4.1 specifically requires organisations to determine and apply criteria for the evaluation, selection, monitoring of performance, and re-evaluation of external providers.\",\n        },\n        {\n          type: \"links\",\n          items: [\n            {\n              label: \"ISO 9001:2015 — Quality management systems — Requirements\",\n              url: \"https://www.iso.org/standard/62085.html\",\n              source: \"ISO\",\n            },\n          ],\n        },\n      ],\n    },\n\n    /* ================================================================\n       LESSON 3 — Sector-specific standards\n       ================================================================ */\n    {\n      id: L3_ID,\n      title: \"Sector-specific standards: IATF 16949, AS9100 and ISO 13485\",\n      minutes: 25,\n      objectives: [\n        \"Explain the additional requirements IATF 16949 imposes beyond ISO 9001 for automotive quality, including APQP, PPAP, and the five core tools.\",\n        \"Describe the key aerospace-specific requirements of AS9100, including product safety, configuration management, and first article inspection.\",\n        \"Identify ISO 13485 requirements for medical device quality including design controls, risk management per ISO 14971, and traceability.\",\n      ],\n      blocks: [\n        {\n          type: \"p\",\n          text: \"While ISO 9001 provides the universal framework for quality management, high-risk industries demand additional controls. Three major sector standards build upon ISO 9001 and add industry-specific requirements. As a quality engineer, you may encounter any of these depending on your organisation's customer base and product portfolio.\",\n        },\n        {\n          type: \"h\",\n          text: \"IATF 16949 — Automotive quality management\",\n        },\n        {\n          type: \"p\",\n          text: \"IATF 16949 is published by the International Automotive Task Force and incorporates the full text of ISO 9001:2015 with automotive-specific supplemental requirements. It is mandatory for any organisation supplying production parts, service parts, or accessories to major automotive OEMs. A Bonabéri factory producing brake disc assemblies for export to European OEMs would require IATF 16949 certification.\",\n        },\n        {\n          type: \"table\",\n          head: [\"Core tool\", \"Purpose\", \"Key deliverable\"],\n          rows: [\n            [\"APQP (Advanced Product Quality Planning)\", \"Structured framework for product development from concept to launch\", \"Control plan, PFMEA, measurement system plan\"],\n            [\"PPAP (Production Part Approval Process)\", \"Demonstrate that the production process can consistently produce parts meeting requirements\", \"PPAP submission package (18 elements)\"],\n            [\"FMEA (Failure Mode and Effects Analysis)\", \"Systematically identify potential failures, assess risk, and define controls\", \"DFMEA and PFMEA worksheets with RPN and AP ratings\"],\n            [\"SPC (Statistical Process Control)\", \"Monitor process stability and capability using control charts\", \"X̄-R charts, Cpk calculations, process capability studies\"],\n            [\"MSA (Measurement Systems Analysis)\", \"Evaluate the adequacy of measurement systems\", \"Gage R&R studies, bias, linearity, stability studies\"],\n          ],\n        },\n        {\n          type: \"equip\",\n          title: \"PPAP package\",\n          items: [\n            {\n              art: \"ppap-package\",\n              name: \"PPAP submission package\",\n              caption: \"The Production Part Approval Process package contains 18 elements including design records, engineering change documents, DFMEA, process flow diagram, PFMEA, control plan, MSA results, dimensional results, material/performance test results, initial process studies, qualified laboratory documentation, appearance approval report, sample parts, master sample, checking aids, customer-specific requirements, part submission warrant (PSW), and bulk material requirements (if applicable).\",\n            },\n          ],\n        },\n        {\n          type: \"callout\",\n          tone: \"workplace\",\n          title: \"Customer-specific requirements (CSRs)\",\n          text: \"Each automotive OEM publishes customer-specific requirements that supplement IATF 16949. For example, one OEM may require statistical capability of Cpk ≥ 1.67 for safety-critical characteristics while the standard minimum is 1.33. A Bonabéri brake disc manufacturer must maintain a register of all applicable CSRs and ensure they flow down to sub-tier suppliers.\",\n        },\n        {\n          type: \"h\",\n          text: \"AS9100 — Aerospace quality management\",\n        },\n        {\n          type: \"p\",\n          text: \"AS9100 (also published as EN 9100 in Europe) adds aerospace-specific requirements to ISO 9001. The standard emphasises product safety, configuration management, and the control of special processes. Organisations must implement a product safety programme and assess risks of counterfeit parts entering the supply chain.\",\n        },\n        {\n          type: \"list\",\n          items: [\n            \"Product safety: organisations must assess product safety risks during design and manufacturing, and have a process for reporting safety issues\",\n            \"Configuration management: control of product configuration throughout its lifecycle — identification, control, status accounting, and audit\",\n            \"First article inspection (FAI): detailed verification that the production process produces parts conforming to engineering specifications — documented per AS9102\",\n            \"Special processes: processes where the output cannot be fully verified by inspection (e.g., welding, heat treatment, plating) require qualification and ongoing monitoring\",\n            \"Risk management of counterfeit parts: controls to prevent the use of fraudulent, recycled, or non-conforming parts misrepresented as genuine\",\n            \"Key characteristics: features whose variation significantly affects product fit, performance, or ability to be manufactured — require tighter process control\",\n          ],\n        },\n        {\n          type: \"h\",\n          text: \"ISO 13485 — Medical device quality management\",\n        },\n        {\n          type: \"p\",\n          text: \"ISO 13485 provides a comprehensive quality management system for the design and manufacture of medical devices. Unlike ISO 9001, which emphasises continual improvement, ISO 13485 focuses on maintaining the effectiveness of the QMS to consistently meet customer and regulatory requirements. This reflects the regulatory environment where changes to validated processes require formal change control.\",\n        },\n        {\n          type: \"table\",\n          head: [\"Requirement\", \"ISO 13485 clause\", \"Significance\"],\n          rows: [\n            [\"Design controls\", \"7.3\", \"Formal design and development process with planning, inputs, outputs, review, verification, validation, and transfer\"],\n            [\"Risk management\", \"7.1 (ISO 14971)\", \"Application of ISO 14971 throughout the product lifecycle to identify hazards, estimate risk, and implement controls\"],\n            [\"Process validation\", \"7.5.6\", \"Validation of processes where output cannot be verified by subsequent monitoring or measurement\"],\n            [\"Traceability\", \"7.5.3\", \"Ability to trace each medical device back to raw materials, manufacturing records, and distribution\"],\n            [\"Clinical evaluation\", \"Regulatory\", \"Evidence that the device performs as intended and is safe when used as specified\"],\n          ],\n        },\n        {\n          type: \"callout\",\n          tone: \"key\",\n          title: \"Common themes across sector standards\",\n          text: \"All three sector standards share: risk-based thinking woven throughout (not bolted on), enhanced documented information requirements beyond ISO 9001, rigorous control of product realisation processes, supply-chain management and flow-down of requirements, and emphasis on product safety and traceability.\",\n        },\n        {\n          type: \"sorter\",\n          id: \"aqe-m1-sorter-standards\",\n          title: \"Match requirements to standards\",\n          task: \"Drag each requirement to the sector standard that specifically mandates it.\",\n          layout: \"columns\",\n          buckets: [\n            { label: \"IATF 16949\", desc: \"Automotive\" },\n            { label: \"AS9100\", desc: \"Aerospace\" },\n            { label: \"ISO 13485\", desc: \"Medical devices\" },\n          ],\n          items: [\n            {\n              text: \"Production Part Approval Process (PPAP) submission before start of production\",\n              bucket: 0,\n              explain: \"PPAP is an automotive core tool required by IATF 16949 to demonstrate production readiness.\",\n            },\n            {\n              text: \"First article inspection documented per a standardised report format\",\n              bucket: 1,\n              explain: \"AS9100 requires FAI per AS9102 to verify that the production process produces conforming parts.\",\n            },\n            {\n              text: \"Design and development process with formal design transfer to manufacturing\",\n              bucket: 2,\n              explain: \"ISO 13485 clause 7.3.8 specifically requires design and development transfer activities.\",\n            },\n            {\n              text: \"Control of counterfeit parts through supply-chain risk assessment\",\n              bucket: 1,\n              explain: \"AS9100 has specific requirements for awareness and control of counterfeit parts.\",\n            },\n            {\n              text: \"Measurement systems analysis (Gage R&R) for all measurement systems used in the control plan\",\n              bucket: 0,\n              explain: \"MSA is one of the five core tools required by IATF 16949.\",\n            },\n            {\n              text: \"Application of ISO 14971 risk management throughout the product lifecycle\",\n              bucket: 2,\n              explain: \"ISO 13485 requires the application of ISO 14971 for risk management of medical devices.\",\n            },\n          ],\n        },\n        {\n          type: \"form\",\n          id: \"aqe-m1-form-sector\",\n          title: \"Which standard applies?\",\n          task: \"Read each scenario and select the sector-specific standard that would apply.\",\n          fields: [\n            {\n              kind: \"select\",\n              label: \"A Douala factory manufactures hydraulic brake hose assemblies for a European vehicle manufacturer.\",\n              options: [\"IATF 16949\", \"AS9100\", \"ISO 13485\", \"ISO 9001 only\"],\n              answer: 0,\n              explain: \"Brake hoses are safety-critical automotive production parts — IATF 16949 is required.\",\n            },\n            {\n              kind: \"select\",\n              label: \"A Yaoundé precision shop machines turbine blade mounting fixtures for an aircraft engine overhaul facility.\",\n              options: [\"IATF 16949\", \"AS9100\", \"ISO 13485\", \"ISO 9001 only\"],\n              answer: 1,\n              explain: \"Aerospace engine components and tooling fall under AS9100 requirements.\",\n            },\n            {\n              kind: \"select\",\n              label: \"A Bafoussam company manufactures sterile surgical drainage kits for hospitals across Central Africa.\",\n              options: [\"IATF 16949\", \"AS9100\", \"ISO 13485\", \"ISO 9001 only\"],\n              answer: 2,\n              explain: \"Sterile surgical devices are medical devices requiring ISO 13485 certification.\",\n            },\n            {\n              kind: \"select\",\n              label: \"A Bonabéri cement plant supplies bulk construction materials to local contractors.\",\n              options: [\"IATF 16949\", \"AS9100\", \"ISO 13485\", \"ISO 9001 only\"],\n              answer: 3,\n              explain: \"Cement for construction does not fall under automotive, aerospace, or medical device sectors — ISO 9001 is the applicable standard.\",\n            },\n          ],\n        },\n        {\n          type: \"check\",\n          id: \"aqe-m1-check-l3\",\n          question: \"Which of the following is a distinguishing feature of ISO 13485 compared to ISO 9001?\",\n          options: [\n            \"ISO 13485 requires management review at planned intervals\",\n            \"ISO 13485 replaces continual improvement with maintaining QMS effectiveness\",\n            \"ISO 13485 requires a quality policy\",\n            \"ISO 13485 requires internal audits\",\n          ],\n          answer: 1,\n          explain: \"ISO 13485 does not include the ISO 9001 emphasis on continual improvement. Instead, it focuses on maintaining the effectiveness of the QMS. This reflects the medical device regulatory environment where validated processes should not be changed without formal change control.\",\n        },\n        {\n          type: \"links\",\n          items: [\n            {\n              label: \"ASQ — Automotive quality resources\",\n              url: \"https://asq.org/quality-resources/automotive-quality\",\n              source: \"ASQ\",\n            },\n            {\n              label: \"ISO 13485:2016 — Medical devices — Quality management systems\",\n              url: \"https://www.iso.org/standard/59752.html\",\n              source: \"ISO\",\n            },\n          ],\n        },\n      ],\n    },\n\n    /* ================================================================\n       LESSON 4 — Auditing: planning, conducting and reporting\n       ================================================================ */\n    {\n      id: L4_ID,\n      title: \"Auditing: planning, conducting and reporting\",\n      minutes: 30,\n      objectives: [\n        \"Distinguish between first-, second-, and third-party audits and between system, process, and product audit types.\",\n        \"Apply ISO 19011 guidelines to plan, conduct, report, and follow up on a quality audit.\",\n        \"Write accurate audit findings classified as major nonconformity, minor nonconformity, observation, or opportunity for improvement.\",\n        \"Verify the effectiveness of corrective actions resulting from audit findings.\",\n      ],\n      blocks: [\n        {\n          type: \"p\",\n          text: \"Auditing is one of the quality engineer's most powerful tools. A well-conducted audit provides objective evidence of how well the organisation's processes conform to planned arrangements and identifies opportunities to strengthen the system. ISO 19011:2018 provides guidelines for auditing management systems and is the quality engineer's reference for audit competence.\",\n        },\n        {\n          type: \"h\",\n          text: \"Audit types and classifications\",\n        },\n        {\n          type: \"table\",\n          head: [\"Classification\", \"Type\", \"Description\", \"Example\"],\n          rows: [\n            [\"By party\", \"First party\", \"Internal audit — conducted by or on behalf of the organisation itself\", \"Yaoundé plant quality team audits its own incoming inspection process\"],\n            [\"By party\", \"Second party\", \"External audit conducted by a customer or interested party\", \"A European OEM audits the Bonabéri brake disc supplier before awarding a contract\"],\n            [\"By party\", \"Third party\", \"Independent audit by a certification body\", \"Bureau Veritas conducts an ISO 9001 certification audit at a Douala brewery\"],\n            [\"By scope\", \"System audit\", \"Evaluates the entire QMS or a significant portion against the standard\", \"Full ISO 9001 surveillance audit covering clauses 4–10\"],\n            [\"By scope\", \"Process audit\", \"Focuses on a specific process to evaluate its effectiveness\", \"Audit of the heat-treatment process at a Bafoussam machining shop\"],\n            [\"By scope\", \"Product audit\", \"Examines a finished product against specifications, drawings, and customer requirements\", \"Audit of packaged cement bags for labelling, weight accuracy, and seal integrity\"],\n          ],\n        },\n        {\n          type: \"h\",\n          text: \"ISO 19011 audit principles\",\n        },\n        {\n          type: \"list\",\n          items: [\n            \"Integrity — the foundation of professionalism; auditors must be ethical, fair, and honest\",\n            \"Fair presentation — findings, conclusions, and reports reflect the audit truthfully and accurately\",\n            \"Due professional care — auditors apply diligence and judgement commensurate with the importance of the task\",\n            \"Confidentiality — security of information obtained during the audit\",\n            \"Independence — auditors are free from bias and conflict of interest\",\n            \"Evidence-based approach — audit evidence is verifiable; conclusions are based on available evidence\",\n            \"Risk-based approach — planning and conducting audits consider risks and opportunities\",\n          ],\n        },\n        {\n          type: \"h\",\n          text: \"Planning and conducting an audit\",\n        },\n        {\n          type: \"steps\",\n          title: \"Audit process flow\",\n          items: [\n            \"Establish the audit programme: define objectives, scope, frequency, methods, and resources for the programme\",\n            \"Plan the individual audit: define scope, criteria, schedule; prepare the audit plan and checklists; notify the auditee\",\n            \"Conduct the opening meeting: confirm scope, schedule, methods, confidentiality, and communication channels\",\n            \"Collect evidence: interview personnel, observe activities, review documents and records; use sampling\",\n            \"Generate findings: evaluate evidence against audit criteria; classify as conformity, nonconformity, or observation\",\n            \"Conduct the closing meeting: present findings, agree timescales for corrective actions, confirm the audit report timeline\",\n            \"Prepare and distribute the audit report: document findings, conclusions, and any recommendations\",\n            \"Follow up: verify corrective actions have been implemented and are effective\",\n          ],\n        },\n        {\n          type: \"equip\",\n          title: \"A3 report as audit summary\",\n          items: [\n            {\n              art: \"a3-report\",\n              name: \"A3 audit summary report\",\n              caption: \"The A3 format (named after the A3 paper size) provides a structured, single-page summary ideal for presenting audit findings to management. The left side captures background, current condition, and root-cause analysis. The right side shows target condition, countermeasures, implementation plan, and follow-up actions. Using A3 for audit summaries forces conciseness and visual clarity.\",\n            },\n          ],\n        },\n        {\n          type: \"h\",\n          text: \"Writing audit findings\",\n        },\n        {\n          type: \"p\",\n          text: \"A well-written audit finding is objective, evidence-based, and traceable to a specific requirement. Every finding must include: the requirement (clause reference), the evidence observed, and a clear statement of the gap. Findings are classified based on severity.\",\n        },\n        {\n          type: \"table\",\n          head: [\"Classification\", \"Definition\", \"Example\"],\n          rows: [\n            [\n              \"Major nonconformity\",\n              \"Absence of, or total breakdown in, a required process; or a systematic failure that could result in delivery of nonconforming product\",\n              \"No evidence of management review having been conducted in the past 14 months, contrary to clause 9.3 which requires management review at planned intervals (annually per the quality manual)\",\n            ],\n            [\n              \"Minor nonconformity\",\n              \"A single observed lapse or partial failure that does not result in a total breakdown of the system\",\n              \"Three of twelve calibration records reviewed were missing the 'as found' reading before adjustment, contrary to the calibration procedure QP-CAL-003 section 4.2\",\n            ],\n            [\n              \"Observation (OFI)\",\n              \"A situation that is not a nonconformity but could become one, or an area where improvement is possible\",\n              \"While the incoming inspection procedure is followed, the sampling plan has not been reviewed since 2019 and may not reflect current risk levels\",\n            ],\n          ],\n        },\n        {\n          type: \"callout\",\n          tone: \"tip\",\n          title: \"The three-part finding statement\",\n          text: \"Use this structure for every finding: (1) Requirement — cite the specific clause, procedure, or specification. (2) Evidence — state what you observed, reviewed, or were told, with specific details (dates, document numbers, quantities). (3) Gap — clearly state the nonconformity or concern. Example: 'ISO 9001 clause 7.1.5.2 requires measurement traceability. During review of measuring equipment records, micrometer SN-M042 showed no calibration certificate since March 2024. The equipment was found in use on the production floor.'\",\n        },\n        {\n          type: \"h\",\n          text: \"Corrective action verification\",\n        },\n        {\n          type: \"p\",\n          text: \"After audit findings are issued, the auditee must investigate root causes and implement corrective actions. The quality engineer's role is to verify that: (1) the root cause was correctly identified, (2) the corrective action addresses the root cause and not just the symptom, (3) the action has been effectively implemented, and (4) the nonconformity has not recurred. Verification may require a follow-up audit, review of revised documents, or examination of subsequent records.\",\n        },\n        {\n          type: \"form\",\n          id: \"aqe-m1-form-findings\",\n          title: \"Write audit findings from scenarios\",\n          task: \"For each audit scenario, select the correct finding classification.\",\n          fields: [\n            {\n              kind: \"select\",\n              label: \"During a process audit of the welding shop, you find that no welder qualification records exist. The procedure requires all welders to hold valid qualifications reviewed annually.\",\n              options: [\n                \"Major nonconformity\",\n                \"Minor nonconformity\",\n                \"Observation / OFI\",\n                \"Not a finding — conformity\",\n              ],\n              answer: 0,\n              explain: \"Complete absence of welder qualification records represents a total breakdown in the required process — this is a major nonconformity affecting product quality and safety.\",\n            },\n            {\n              kind: \"select\",\n              label: \"You review 20 completed inspection records and find that 2 are missing the inspector's signature, though all other fields are completed and the parts were correctly dispositioned.\",\n              options: [\n                \"Major nonconformity\",\n                \"Minor nonconformity\",\n                \"Observation / OFI\",\n                \"Not a finding — conformity\",\n              ],\n              answer: 1,\n              explain: \"Two of twenty records missing signatures is a partial lapse (10 % non-compliance rate) but the system is generally functioning — this is a minor nonconformity.\",\n            },\n            {\n              kind: \"select\",\n              label: \"The calibration laboratory maintains all records correctly, but you notice that the temperature and humidity in the lab are not logged, although there is no specific requirement for environmental monitoring in their documented procedure.\",\n              options: [\n                \"Major nonconformity\",\n                \"Minor nonconformity\",\n                \"Observation / OFI\",\n                \"Not a finding — conformity\",\n              ],\n              answer: 2,\n              explain: \"While not a nonconformity against a specific requirement, environmental conditions can affect measurement accuracy. This is an observation or opportunity for improvement.\",\n            },\n            {\n              kind: \"select\",\n              label: \"You audit the receiving area and find that all incoming materials are inspected per the sampling plan, results are recorded, and nonconforming material is segregated and tagged.\",\n              options: [\n                \"Major nonconformity\",\n                \"Minor nonconformity\",\n                \"Observation / OFI\",\n                \"Not a finding — conformity\",\n              ],\n              answer: 3,\n              explain: \"The process conforms to the requirements — this is a positive finding. Record it as a conformity in your audit notes.\",\n            },\n          ],\n        },\n        {\n          type: \"sorter\",\n          id: \"aqe-m1-sorter-findings\",\n          title: \"Classify audit finding types\",\n          task: \"Drag each audit finding into the correct classification.\",\n          layout: \"columns\",\n          buckets: [\n            { label: \"Major NC\", desc: \"Total breakdown or absence of a process\" },\n            { label: \"Minor NC\", desc: \"Single or partial lapse\" },\n            { label: \"Observation / OFI\", desc: \"Not a NC but could become one\" },\n          ],\n          items: [\n            {\n              text: \"The organisation has no documented process for design and development, although it designs custom products for customers\",\n              bucket: 0,\n              explain: \"Absence of a required process (design and development) is a major nonconformity.\",\n            },\n            {\n              text: \"One of six training records reviewed did not include the assessment score, though the trainee passed per the trainer's verbal confirmation\",\n              bucket: 1,\n              explain: \"A single incomplete record is a partial lapse — minor nonconformity.\",\n            },\n            {\n              text: \"Internal auditors have completed training but there is no formal competency evaluation criteria defined for auditor qualification\",\n              bucket: 2,\n              explain: \"While not violating a specific shall requirement if auditors are otherwise competent, this is an area where the system could be strengthened — observation.\",\n            },\n            {\n              text: \"No corrective actions have been raised or closed in 18 months, despite 12 customer complaints being received in the same period\",\n              bucket: 0,\n              explain: \"Systematic failure to raise corrective actions from customer complaints represents a major breakdown in clause 10.2.\",\n            },\n          ],\n        },\n        {\n          type: \"check\",\n          id: \"aqe-m1-check-l4\",\n          question: \"According to ISO 19011, what is the primary purpose of the opening meeting?\",\n          options: [\n            \"To present preliminary audit findings to management\",\n            \"To confirm the audit plan, scope, criteria, and communication arrangements with the auditee\",\n            \"To review the corrective actions from the previous audit\",\n            \"To train auditee personnel on the audit process\",\n          ],\n          answer: 1,\n          explain: \"The opening meeting is used to confirm the audit plan, scope, criteria, timetable, and communication channels. It sets expectations and ensures both parties agree on the audit arrangements.\",\n        },\n        {\n          type: \"links\",\n          items: [\n            {\n              label: \"ISO 19011:2018 — Guidelines for auditing management systems\",\n              url: \"https://www.iso.org/standard/70017.html\",\n              source: \"ISO\",\n            },\n            {\n              label: \"ASQ — Quality audits\",\n              url: \"https://asq.org/quality-resources/auditing\",\n              source: \"ASQ\",\n            },\n          ],\n        },\n      ],\n    },\n\n    /* ================================================================\n       LESSON 5 — Quality costs, metrics and the quality engineer's role\n       ================================================================ */\n    {\n      id: L5_ID,\n      title: \"Quality costs, metrics and the quality engineer's role\",\n      minutes: 25,\n      objectives: [\n        \"Categorise quality costs using the prevention–appraisal–failure (PAF) model and calculate the cost of quality for a manufacturing operation.\",\n        \"Calculate key quality metrics including ppm, DPMO, sigma level, first-pass yield (FPY), rolled throughput yield (RTY), and overall equipment effectiveness (OEE).\",\n        \"Describe the quality function deployment (QFD) house of quality and its role in translating the voice of the customer into design requirements.\",\n        \"Explain the quality engineer's leadership role in cross-functional teams, influencing without authority, and basic project management.\",\n      ],\n      blocks: [\n        {\n          type: \"p\",\n          text: \"The quality engineer must speak the language of business. Quality costs, when properly measured and reported, provide the financial justification for improvement initiatives. Metrics translate process performance into numbers that drive decisions. And leadership — the ability to influence teams and drive change — is what turns analysis into results.\",\n        },\n        {\n          type: \"h\",\n          text: \"Cost of quality: the PAF model\",\n        },\n        {\n          type: \"p\",\n          text: \"The prevention–appraisal–failure (PAF) model, developed by Armand Feigenbaum, categorises all quality-related costs into four categories. The fundamental insight is that investing in prevention and appraisal reduces failure costs by a much larger amount — typically a 10:1 return.\",\n        },\n        {\n          type: \"table\",\n          head: [\"Category\", \"Definition\", \"Examples\"],\n          rows: [\n            [\n              \"Prevention\",\n              \"Costs incurred to prevent defects from occurring\",\n              \"Quality planning, training, process capability studies, FMEA, supplier development, design reviews, poka-yoke implementation\",\n            ],\n            [\n              \"Appraisal\",\n              \"Costs incurred to detect defects before delivery\",\n              \"Incoming inspection, in-process inspection, final inspection, calibration, laboratory testing, audit costs\",\n            ],\n            [\n              \"Internal failure\",\n              \"Costs resulting from defects found before delivery to the customer\",\n              \"Scrap, rework, re-inspection, downgrading, root-cause investigation, production delays\",\n            ],\n            [\n              \"External failure\",\n              \"Costs resulting from defects found after delivery to the customer\",\n              \"Warranty claims, returns, complaints handling, product recalls, liability, loss of reputation\",\n            ],\n          ],\n        },\n        {\n          type: \"callout\",\n          tone: \"workplace\",\n          title: \"Worked example — COQ at Mbanga Brewing, Douala\",\n          text: \"Mbanga Brewing Ltd (fictional) reports the following annual quality costs: Training and SOP development: 4,200,000 FCFA (prevention). Laboratory testing and inspection: 8,500,000 FCFA (appraisal). Off-spec batches scrapped: 12,800,000 FCFA (internal failure). Customer returns and complaints: 6,200,000 FCFA (external failure). Total COQ = 31,700,000 FCFA. As a percentage of sales revenue (620,000,000 FCFA): COQ = 5.1 %. Prevention is only 13.2 % of COQ — the company should invest more in prevention to reduce the 60 % spent on failure costs.\",\n        },\n        {\n          type: \"h\",\n          text: \"Quality metrics\",\n        },\n        {\n          type: \"p\",\n          text: \"Quality engineers must be fluent in calculating and interpreting a range of performance metrics. These metrics provide objective evidence for decision making and allow benchmarking across processes, plants, and industries.\",\n        },\n        {\n          type: \"table\",\n          head: [\"Metric\", \"Formula\", \"Worked example\"],\n          rows: [\n            [\n              \"ppm (parts per million)\",\n              \"(Defective parts ÷ Total parts) × 1,000,000\",\n              \"42 defective shafts from 28,000 produced: (42 ÷ 28,000) × 1,000,000 = 1,500 ppm\",\n            ],\n            [\n              \"DPMO (defects per million opportunities)\",\n              \"(Defects ÷ (Units × Opportunities per unit)) × 1,000,000\",\n              \"A PCB has 8 solder joints. 150 boards inspected, 6 defective joints found: (6 ÷ (150 × 8)) × 1,000,000 = 5,000 DPMO ≈ 4.08 sigma\",\n            ],\n            [\n              \"FPY (first-pass yield)\",\n              \"Good units out ÷ Total units in (at a single step)\",\n              \"Step produces 970 good units from 1,000 inputs: FPY = 0.970 or 97.0 %\",\n            ],\n            [\n              \"RTY (rolled throughput yield)\",\n              \"FPY₁ × FPY₂ × … × FPYₙ\",\n              \"Three-step process: 0.97 × 0.95 × 0.98 = 0.903 or 90.3 % — hidden factory losses revealed\",\n            ],\n            [\n              \"OEE (overall equipment effectiveness)\",\n              \"Availability × Performance × Quality\",\n              \"A = 90 %, P = 85 %, Q = 98 %: OEE = 0.90 × 0.85 × 0.98 = 0.749 or 74.9 %\",\n            ],\n          ],\n        },\n        {\n          type: \"callout\",\n          tone: \"key\",\n          title: \"The hidden factory\",\n          text: \"RTY reveals the 'hidden factory' — the rework, re-inspection, and repair loops that consume resources without appearing in traditional yield calculations. If each of 5 process steps has 97 % FPY, the RTY is only 0.97⁵ = 85.9 %. The other 14.1 % represents hidden waste. World-class manufacturers target RTY above 95 %.\",\n        },\n        {\n          type: \"h\",\n          text: \"Quality function deployment (QFD)\",\n        },\n        {\n          type: \"p\",\n          text: \"QFD is a structured method for translating the voice of the customer (VOC) into technical requirements at each stage of product development. The primary tool is the 'house of quality' — a matrix that links customer needs (what the customer wants) to engineering characteristics (how the organisation delivers). While full QFD deployment involves four houses (product planning, parts deployment, process planning, production planning), the quality engineer must understand at minimum the first house.\",\n        },\n        {\n          type: \"steps\",\n          title: \"Building the house of quality\",\n          items: [\n            \"Capture the voice of the customer: gather customer needs through surveys, complaints, focus groups, and market research\",\n            \"Prioritise customer needs: weight each need by importance (1–5 scale or AHP method)\",\n            \"Define engineering characteristics: measurable technical parameters that address customer needs (e.g., 'tensile strength ≥ 450 MPa')\",\n            \"Build the relationship matrix: rate the strength of relationship between each customer need and each engineering characteristic (strong = 9, medium = 3, weak = 1)\",\n            \"Add the correlation roof: identify interactions between engineering characteristics (positive synergies or trade-offs)\",\n            \"Set targets: define measurable targets for each engineering characteristic based on competitive benchmarking\",\n          ],\n        },\n        {\n          type: \"h\",\n          text: \"The quality engineer as leader\",\n        },\n        {\n          type: \"p\",\n          text: \"Quality engineers rarely have direct line authority over production, design, or procurement personnel. Yet they must drive change across functions. This requires influencing without authority — the ability to build credibility, use data to persuade, and create win-win solutions that align quality objectives with departmental goals.\",\n        },\n        {\n          type: \"list\",\n          items: [\n            \"Build credibility through technical competence — know the processes, the data, and the standards better than anyone in the room\",\n            \"Use data to tell a story — a Pareto chart of warranty costs by failure mode is more persuasive than a lecture on quality\",\n            \"Frame quality as a business issue — translate defects into FCFA lost, delivery delays, and customer retention risk\",\n            \"Facilitate cross-functional teams — bring production, engineering, purchasing, and quality together to solve problems collaboratively\",\n            \"Apply basic project management — define scope, timeline, deliverables, and milestones for improvement projects; track progress and report to management\",\n            \"Develop others — coach and mentor operators, technicians, and junior engineers in quality tools and methods\",\n          ],\n        },\n        {\n          type: \"sheet\",\n          id: \"aqe-m1-sheet-coq\",\n          title: \"Calculate cost of quality\",\n          task: \"Nkoulou Machining (fictional, Bafoussam) has provided their annual quality cost data. Calculate the totals for each PAF category, total COQ, and COQ as a percentage of revenue (475,000,000 FCFA). Enter formulas in column C.\",\n          data: [\n            [\"Cost item\", \"Amount (FCFA)\", \"Category total\", \"% of COQ\"],\n            [\"PREVENTION\", \"\", \"\", \"\"],\n            [\"SPC training for operators\", 1800000, null, null],\n            [\"FMEA workshops\", 1200000, null, null],\n            [\"Supplier development visits\", 950000, null, null],\n            [\"Prevention subtotal\", null, null, null],\n            [\"APPRAISAL\", \"\", \"\", \"\"],\n            [\"Incoming inspection labour\", 3200000, null, null],\n            [\"Calibration costs\", 1400000, null, null],\n            [\"Final inspection and testing\", 2800000, null, null],\n            [\"Appraisal subtotal\", null, null, null],\n            [\"INTERNAL FAILURE\", \"\", \"\", \"\"],\n            [\"Scrap (machining defects)\", 8500000, null, null],\n            [\"Rework labour and materials\", 4200000, null, null],\n            [\"Production downtime (quality)\", 2100000, null, null],\n            [\"Internal failure subtotal\", null, null, null],\n            [\"EXTERNAL FAILURE\", \"\", \"\", \"\"],\n            [\"Warranty returns\", 5600000, null, null],\n            [\"Customer complaint investigation\", 1800000, null, null],\n            [\"External failure subtotal\", null, null, null],\n            [\"TOTAL COQ\", null, null, null],\n            [\"Revenue\", 475000000, \"\", \"\"],\n            [\"COQ as % of revenue\", null, \"\", \"\"],\n          ],\n          editable: [\"C6\", \"C11\", \"C15\", \"C18\", \"C19\", \"C21\"],\n          checks: [\n            { cell: \"C6\", equals: 3950000, tol: 0 },\n            { cell: \"C11\", equals: 7400000, tol: 0 },\n            { cell: \"C15\", equals: 14800000, tol: 0 },\n            { cell: \"C18\", equals: 7400000, tol: 0 },\n            { cell: \"C19\", equals: 33550000, tol: 0 },\n            { cell: \"C21\", equals: 7.1, tol: 0.1 },\n          ],\n          hint: \"Prevention subtotal = sum of SPC training + FMEA workshops + supplier development. COQ % = (Total COQ ÷ Revenue) × 100.\",\n          solution: {\n            C6: \"= 1,800,000 + 1,200,000 + 950,000 = 3,950,000\",\n            C11: \"= 3,200,000 + 1,400,000 + 2,800,000 = 7,400,000\",\n            C15: \"= 8,500,000 + 4,200,000 + 2,100,000 = 14,800,000\",\n            C18: \"= 5,600,000 + 1,800,000 = 7,400,000\",\n            C19: \"= 3,950,000 + 7,400,000 + 14,800,000 + 7,400,000 = 33,550,000\",\n            C21: \"= (33,550,000 ÷ 475,000,000) × 100 = 7.1 %\",\n          },\n        },\n        {\n          type: \"form\",\n          id: \"aqe-m1-form-metrics\",\n          title: \"Calculate DPMO and sigma level\",\n          task: \"A Bonabéri automotive parts factory inspects drive shafts. Each shaft has 5 critical characteristics checked. In a batch of 2,000 shafts, inspectors find 18 total defects across all characteristics. Calculate the metrics below.\",\n          fields: [\n            {\n              kind: \"text\",\n              label: \"Total opportunities (units × opportunities per unit)\",\n              accept: [\"10000\", \"10,000\"],\n              placeholder: \"Enter number\",\n              explain: \"2,000 shafts × 5 characteristics per shaft = 10,000 total opportunities.\",\n            },\n            {\n              kind: \"text\",\n              label: \"DPMO (defects per million opportunities)\",\n              accept: [\"1800\", \"1,800\"],\n              placeholder: \"Enter DPMO value\",\n              explain: \"(18 defects ÷ 10,000 opportunities) × 1,000,000 = 1,800 DPMO.\",\n            },\n            {\n              kind: \"select\",\n              label: \"Approximate sigma level for 1,800 DPMO\",\n              options: [\"3.0 sigma\", \"3.6 sigma\", \"4.4 sigma\", \"5.1 sigma\"],\n              answer: 2,\n              explain: \"1,800 DPMO corresponds to approximately 4.4 sigma. The sigma conversion table shows: 6,210 DPMO ≈ 4.0σ; 1,350 DPMO ≈ 4.5σ. 1,800 DPMO falls between these at approximately 4.4σ.\",\n            },\n          ],\n          hint: \"DPMO = (total defects ÷ total opportunities) × 1,000,000. Total opportunities = units × opportunities per unit.\",\n        },\n        {\n          type: \"equip\",\n          title: \"Quality tools in practice\",\n          items: [\n            {\n              art: \"qc-pareto\",\n              name: \"Pareto chart\",\n              caption: \"The Pareto chart ranks defect categories or cost drivers in descending order with a cumulative percentage line. Quality engineers use Pareto analysis to apply the 80/20 rule — focusing improvement efforts on the vital few causes that account for the majority of defects or costs. When presenting quality costs to management, a Pareto of failure costs by category is one of the most effective visual communication tools.\",\n            },\n            {\n              art: \"stat-capability\",\n              name: \"Process capability analysis\",\n              caption: \"Process capability indices (Cp, Cpk, Pp, Ppk) quantify how well a process meets specification limits. A Cpk of 1.33 means the process mean is at least 4 standard deviations from the nearest specification limit — the minimum acceptable capability for most industries. IATF 16949 often requires Cpk ≥ 1.67 for safety-critical characteristics.\",\n            },\n          ],\n        },\n        {\n          type: \"check\",\n          id: \"aqe-m1-check-l5\",\n          question: \"A three-step manufacturing process has first-pass yields of 96 %, 93 %, and 98 %. What is the rolled throughput yield (RTY)?\",\n          options: [\n            \"95.7 %\",\n            \"87.4 %\",\n            \"92.3 %\",\n            \"89.0 %\",\n          ],\n          answer: 1,\n          explain: \"RTY = FPY₁ × FPY₂ × FPY₃ = 0.96 × 0.93 × 0.98 = 0.8744 = 87.4 %. This reveals that only 87.4 % of product passes through all three steps without requiring any rework — the hidden factory consumes 12.6 % of throughput.\",\n        },\n        {\n          type: \"links\",\n          items: [\n            {\n              label: \"ASQ — Cost of quality\",\n              url: \"https://asq.org/quality-resources/cost-of-quality\",\n              source: \"ASQ\",\n            },\n            {\n              label: \"ASQ — Quality function deployment (QFD)\",\n              url: \"https://asq.org/quality-resources/qfd-quality-function-deployment\",\n              source: \"ASQ\",\n            },\n          ],\n        },\n      ],\n    },\n\n    /* ================================================================\n       PRACTICE LESSON — Quality management systems\n       ================================================================ */\n    {\n      id: PRACTICE_ID,\n      title: \"Practice: quality management systems\",\n      minutes: 30,\n      objectives: [\n        \"Classify quality costs into prevention, appraisal and failure categories\",\n        \"Match ISO 9001:2015 clauses to workplace situations\",\n        \"Build a cost-of-quality report and calculate key quality metrics\",\n      ],\n      blocks: [\n        {\n          type: \"p\",\n          text: \"Four exercises of increasing difficulty that test your mastery of quality management systems, from basic cost classification through to writing complete audit findings with corrective action recommendations. Work through each exercise carefully — the advanced and expert levels reflect the complexity you will face as a practising quality engineer.\",\n        },\n\n        /* --- Beginner: sorter — classify quality costs --- */\n        {\n          type: \"sorter\",\n          id: \"aqe-m1-sorter-paf\",\n          level: \"beginner\",\n          title: \"Classify quality costs (PAF categories)\",\n          task: \"Drag each cost item into the correct PAF category.\",\n          layout: \"columns\",\n          buckets: [\n            { label: \"Prevention\", desc: \"Costs to prevent defects\" },\n            { label: \"Appraisal\", desc: \"Costs to detect defects\" },\n            { label: \"Internal failure\", desc: \"Defects found before delivery\" },\n            { label: \"External failure\", desc: \"Defects found after delivery\" },\n          ],\n          items: [\n            {\n              text: \"FMEA workshop for new product launch (280,000 FCFA)\",\n              bucket: 0,\n              explain: \"FMEA is a prevention activity — it identifies and mitigates potential failures before they occur.\",\n            },\n            {\n              text: \"Final inspection labour costs (1,400,000 FCFA per month)\",\n              bucket: 1,\n              explain: \"Final inspection is an appraisal activity — detecting defects before product reaches the customer.\",\n            },\n            {\n              text: \"Scrap from out-of-tolerance machined parts (3,200,000 FCFA)\",\n              bucket: 2,\n              explain: \"Scrapped parts that never reached the customer are an internal failure cost.\",\n            },\n            {\n              text: \"Warranty replacement of failed brake components (5,800,000 FCFA)\",\n              bucket: 3,\n              explain: \"Warranty replacements occur after delivery — this is an external failure cost.\",\n            },\n            {\n              text: \"Calibration of measuring equipment (600,000 FCFA per year)\",\n              bucket: 1,\n              explain: \"Calibration ensures measurement accuracy for detection — an appraisal cost.\",\n            },\n            {\n              text: \"Supplier quality audit programme (450,000 FCFA travel and labour)\",\n              bucket: 0,\n              explain: \"Supplier audits prevent defects from entering the supply chain — a prevention cost.\",\n            },\n            {\n              text: \"Customer complaint investigation and corrective action (780,000 FCFA)\",\n              bucket: 3,\n              explain: \"Investigating complaints from customers who received defective product is an external failure cost.\",\n            },\n            {\n              text: \"Rework of castings that failed radiographic inspection (1,900,000 FCFA)\",\n              bucket: 2,\n              explain: \"Rework of parts caught before delivery is an internal failure cost.\",\n            },\n          ],\n        },\n\n        /* --- Intermediate: form — ISO 9001 clause matching --- */\n        {\n          type: \"form\",\n          id: \"aqe-m1-form-clause-match\",\n          level: \"intermediate\",\n          title: \"ISO 9001 clause matching exercise\",\n          task: \"For each workplace situation at a fictional Cameroon manufacturer, identify the primary ISO 9001:2015 clause that applies.\",\n          fields: [\n            {\n              kind: \"select\",\n              label: \"Atangana Cement (Yaoundé) discovers that its laboratory technician's qualifications expired 6 months ago. The technician has been signing off test reports during this period.\",\n              options: [\n                \"Clause 7.1.5 — Monitoring and measuring resources\",\n                \"Clause 7.2 — Competence\",\n                \"Clause 8.6 — Release of products and services\",\n                \"Clause 10.2 — Nonconformity and corrective action\",\n              ],\n              answer: 1,\n              explain: \"The primary issue is competence — clause 7.2 requires ensuring that personnel are competent based on education, training, or experience. The expired qualification means the organisation failed to maintain evidence of competence.\",\n            },\n            {\n              kind: \"select\",\n              label: \"Dibombé Precision (Bonabéri) receives a customer order for a new shaft variant. The quality engineer reviews the order requirements and confirms the factory has the capability and capacity to fulfil it before accepting.\",\n              options: [\n                \"Clause 8.2.3 — Review of requirements for products and services\",\n                \"Clause 8.3.2 — Design and development planning\",\n                \"Clause 8.1 — Operational planning and control\",\n                \"Clause 5.1.2 — Customer focus\",\n              ],\n              answer: 0,\n              explain: \"Clause 8.2.3 requires the organisation to review requirements before committing to supply, ensuring it has the ability to meet the specified requirements.\",\n            },\n            {\n              kind: \"select\",\n              label: \"Ndongo Brewery (Douala) needs to validate its pasteurisation process because the adequacy of pasteurisation cannot be verified by subsequent inspection of the finished product.\",\n              options: [\n                \"Clause 7.1.5 — Monitoring and measuring resources\",\n                \"Clause 8.5.1 — Control of production and service provision\",\n                \"Clause 8.5.1(f) — Validation of special processes\",\n                \"Clause 9.1.1 — Monitoring, measurement, analysis and evaluation\",\n              ],\n              answer: 2,\n              explain: \"Clause 8.5.1(f) requires validation and periodic revalidation of processes where the resulting output cannot be verified by subsequent monitoring or measurement — these are 'special processes'.\",\n            },\n            {\n              kind: \"select\",\n              label: \"During a management review at Etoudi Food Processing (Yaoundé), the managing director reviews customer satisfaction trends, audit results, supplier performance, and decides to invest in a new X-ray inspection system.\",\n              options: [\n                \"Clause 5.1 — Leadership and commitment\",\n                \"Clause 9.3 — Management review\",\n                \"Clause 6.1 — Actions to address risks and opportunities\",\n                \"Clause 7.1.1 — Resources — General\",\n              ],\n              answer: 1,\n              explain: \"This describes a management review meeting as defined in clause 9.3, where top management reviews QMS performance data and makes decisions about resource allocation and improvement.\",\n            },\n            {\n              kind: \"select\",\n              label: \"Fako Machining (Bafoussam) outsources heat treatment to a local provider. The quality engineer defines incoming inspection requirements, monitors the provider's delivery quality, and conducts an annual supplier audit.\",\n              options: [\n                \"Clause 8.4 — Control of externally provided processes\",\n                \"Clause 7.1.4 — Environment for the operation of processes\",\n                \"Clause 8.5.1 — Control of production\",\n                \"Clause 9.1.2 — Customer satisfaction\",\n              ],\n              answer: 0,\n              explain: \"Clause 8.4 covers the control of externally provided processes, products, and services — including evaluation, monitoring, and verification of outsourced processes like heat treatment.\",\n            },\n          ],\n        },\n\n        /* --- Advanced: sheet — COQ report and metrics dashboard --- */\n        {\n          type: \"sheet\",\n          id: \"aqe-m1-sheet-dashboard\",\n          level: \"advanced\",\n          title: \"Build a COQ report and metrics dashboard\",\n          task: \"Kombi Auto Parts (fictional, Douala) manufactures drive shafts. Complete the metrics dashboard using the raw production data provided. Calculate FPY for each step, RTY, ppm, and total COQ percentage.\",\n          data: [\n            [\"PRODUCTION METRICS\", \"Turning\", \"Grinding\", \"Plating\", \"Final inspect\"],\n            [\"Units entering step\", 5000, 4850, 4680, 4620],\n            [\"Good units out\", 4850, 4680, 4620, 4550],\n            [\"FPY (%)\", null, null, null, null],\n            [\"\", \"\", \"\", \"\", \"\"],\n            [\"RTY (%)\", null, \"\", \"\", \"\"],\n            [\"\", \"\", \"\", \"\", \"\"],\n            [\"DEFECT METRICS\", \"\", \"\", \"\", \"\"],\n            [\"Total units produced\", 5000, \"\", \"\", \"\"],\n            [\"Total defective (final)\", 450, \"\", \"\", \"\"],\n            [\"ppm\", null, \"\", \"\", \"\"],\n            [\"\", \"\", \"\", \"\", \"\"],\n            [\"COST OF QUALITY (FCFA)\", \"\", \"\", \"\", \"\"],\n            [\"Prevention costs\", 2800000, \"\", \"\", \"\"],\n            [\"Appraisal costs\", 4200000, \"\", \"\", \"\"],\n            [\"Internal failure costs\", 9600000, \"\", \"\", \"\"],\n            [\"External failure costs\", 3400000, \"\", \"\", \"\"],\n            [\"Total COQ\", null, \"\", \"\", \"\"],\n            [\"Revenue\", 185000000, \"\", \"\", \"\"],\n            [\"COQ as % of revenue\", null, \"\", \"\", \"\"],\n          ],\n          editable: [\"B4\", \"C4\", \"D4\", \"E4\", \"B6\", \"B11\", \"B18\", \"B20\"],\n          checks: [\n            { cell: \"B4\", equals: 97.0, tol: 0.1 },\n            { cell: \"C4\", equals: 96.5, tol: 0.1 },\n            { cell: \"D4\", equals: 98.7, tol: 0.1 },\n            { cell: \"E4\", equals: 98.5, tol: 0.1 },\n            { cell: \"B6\", equals: 91.0, tol: 0.1 },\n            { cell: \"B11\", equals: 90000, tol: 0 },\n            { cell: \"B18\", equals: 20000000, tol: 0 },\n            { cell: \"B20\", equals: 10.8, tol: 0.1 },\n          ],\n          hint: \"FPY = (Good units out ÷ Units entering) × 100. RTY = FPY₁ × FPY₂ × FPY₃ × FPY₄ (use decimal form, then convert to %). ppm = (defective ÷ total) × 1,000,000.\",\n          solution: {\n            B4: \"= (4850 ÷ 5000) × 100 = 97.0 %\",\n            C4: \"= (4680 ÷ 4850) × 100 = 96.5 %\",\n            D4: \"= (4620 ÷ 4680) × 100 = 98.7 %\",\n            E4: \"= (4550 ÷ 4620) × 100 = 98.5 %\",\n            B6: \"= 0.970 × 0.965 × 0.987 × 0.985 × 100 = 91.0 %\",\n            B11: \"= (450 ÷ 5000) × 1,000,000 = 90,000 ppm\",\n            B18: \"= 2,800,000 + 4,200,000 + 9,600,000 + 3,400,000 = 20,000,000\",\n            B20: \"= (20,000,000 ÷ 185,000,000) × 100 = 10.8 %\",\n          },\n        },\n\n        /* --- Expert: form — audit findings and corrective actions --- */\n        {\n          type: \"form\",\n          id: \"aqe-m1-form-audit-expert\",\n          level: \"expert\",\n          title: \"Write audit findings and corrective actions for complex scenarios\",\n          task: \"You are conducting a third-party surveillance audit at Ngoh Engineering (fictional, Bafoussam), an ISO 9001:2015 certified machining shop. For each scenario, determine the finding classification and identify the most appropriate corrective action approach.\",\n          fields: [\n            {\n              kind: \"select\",\n              label: \"Scenario 1: You review the management review minutes from the past 18 months. The minutes show that quality objectives were reviewed and discussed, but no actions were assigned for objectives that were not met. Three of seven objectives show 'red' status for two consecutive quarters with no documented response.\",\n              options: [\n                \"Major NC — clause 9.3: Management review outputs must include decisions on improvement opportunities\",\n                \"Minor NC — clause 9.3: Incomplete management review outputs\",\n                \"Major NC — clause 10.3: Failure to pursue continual improvement\",\n                \"Observation — Management review could be more action-oriented\",\n              ],\n              answer: 0,\n              explain: \"Clause 9.3.3 requires management review outputs to include decisions and actions related to continual improvement, resource needs, and changes to the QMS. Consistently failing to act on missed objectives for two quarters represents a systematic failure in management review outputs — a major nonconformity.\",\n            },\n            {\n              kind: \"select\",\n              label: \"Scenario 2: The purchasing department evaluates suppliers using a scoring system, but the quality engineer discovers that the evaluation criteria do not include delivery performance or quality metrics — only price and lead time. Five new suppliers were approved in the past year using these incomplete criteria.\",\n              options: [\n                \"Major NC — clause 8.4.1: Evaluation criteria do not address ability to meet requirements\",\n                \"Minor NC — clause 8.4.1: Evaluation criteria incomplete\",\n                \"Observation — Evaluation criteria could be enhanced\",\n                \"Minor NC — clause 7.1.1: Inadequate resources for supplier management\",\n              ],\n              answer: 0,\n              explain: \"Clause 8.4.1 requires evaluation and selection of external providers based on their ability to provide processes, products, or services in accordance with requirements. Evaluating suppliers without quality or delivery criteria, and approving five suppliers this way, is a systematic failure — major nonconformity.\",\n            },\n            {\n              kind: \"select\",\n              label: \"Scenario 3: You examine corrective action records and find 12 CARs closed in the past year. All show root-cause analysis and implemented actions. However, for 3 of the 12, there is no evidence that the effectiveness of the corrective action was verified (i.e., no follow-up check that the problem did not recur).\",\n              options: [\n                \"Major NC — clause 10.2: No verification of corrective action effectiveness\",\n                \"Minor NC — clause 10.2: Partial failure in verifying corrective action effectiveness\",\n                \"Observation — Effectiveness verification could be more systematic\",\n                \"Not a finding — 75 % compliance is acceptable\",\n              ],\n              answer: 1,\n              explain: \"Clause 10.2.1(e) requires reviewing the effectiveness of corrective action taken. Three of twelve CARs lacking effectiveness verification is a partial lapse (25 % non-compliance) — a minor nonconformity. The system is functioning but not consistently applied.\",\n            },\n            {\n              kind: \"select\",\n              label: \"For the Scenario 1 finding (management review outputs), which corrective action approach would be most effective?\",\n              options: [\n                \"Retrain the managing director on ISO 9001 management review requirements\",\n                \"Revise the management review procedure to include mandatory action items for any objective showing 'red' status, with assigned owners and deadlines, and add a standing agenda item to review open actions\",\n                \"Change the quality objectives to easier targets so they show 'green' status\",\n                \"Hire an external consultant to attend management reviews\",\n              ],\n              answer: 1,\n              explain: \"The root cause is a procedural gap — the management review process does not require actions for missed objectives. Revising the procedure to mandate action items with accountability, plus tracking open actions, addresses the systemic cause. Retraining alone does not fix the process, and lowering targets masks the real performance issues.\",\n            },\n          ],\n        },\n      ],\n    },\n  ],\n\n  /* ==================================================================\n     QUIZ — Quality Management Systems\n     ================================================================== */\n  quiz: {\n    id: QUIZ_ID,\n    title: \"Quality Management Systems Quiz\",\n    passPct: 75,\n    questions: [\n      {\n        id: \"aqe-m1-q1\",\n        question: \"Which ISO 9000:2015 quality management principle states that 'decisions based on the analysis and evaluation of data and information are more likely to produce desired results'?\",\n        options: [\n          \"Customer focus\",\n          \"Process approach\",\n          \"Evidence-based decision making\",\n          \"Improvement\",\n        ],\n        answer: 2,\n        explain:\n          \"Evidence-based decision making is the sixth quality management principle. It recognises that decisions informed by factual data analysis are more effective than those based on intuition or anecdote.\",\n      },\n      {\n        id: \"aqe-m1-q2\",\n        question: \"In ISO 9001:2015, the term 'retain documented information' refers to:\",\n        options: [\n          \"Keeping procedures and policies up to date\",\n          \"Maintaining the quality manual in a controlled location\",\n          \"Preserving records as evidence of conformity\",\n          \"Distributing the latest revision of work instructions\",\n        ],\n        answer: 2,\n        explain:\n          \"'Retain documented information' means keeping records as evidence that activities were performed or results achieved. 'Maintain documented information' is the term for keeping procedures and policies current.\",\n      },\n      {\n        id: \"aqe-m1-q3\",\n        question: \"A Bonabéri automotive parts supplier must submit a PPAP package to its OEM customer. Which sector-specific standard mandates this requirement?\",\n        options: [\n          \"ISO 9001:2015\",\n          \"IATF 16949\",\n          \"AS9100\",\n          \"ISO 13485\",\n        ],\n        answer: 1,\n        explain:\n          \"PPAP (Production Part Approval Process) is one of the five automotive core tools required by IATF 16949. It is not required by ISO 9001, AS9100, or ISO 13485.\",\n      },\n      {\n        id: \"aqe-m1-q4\",\n        question: \"According to ISO 19011, which of the following is NOT one of the audit principles?\",\n        options: [\n          \"Integrity\",\n          \"Independence\",\n          \"Speed of completion\",\n          \"Evidence-based approach\",\n        ],\n        answer: 2,\n        explain:\n          \"ISO 19011 lists seven audit principles: integrity, fair presentation, due professional care, confidentiality, independence, evidence-based approach, and risk-based approach. Speed of completion is not a principle — thoroughness takes precedence over speed.\",\n      },\n      {\n        id: \"aqe-m1-q5\",\n        question: \"An audit finding states: 'During review of 30 inspection records, 4 were found without the required dimensional measurement for critical characteristic #3, contrary to inspection instruction WI-INS-015 section 5.4.' This finding is best classified as:\",\n        options: [\n          \"Major nonconformity\",\n          \"Minor nonconformity\",\n          \"Observation\",\n          \"Opportunity for improvement\",\n        ],\n        answer: 1,\n        explain:\n          \"Four of thirty records (13 %) missing a required measurement is a partial failure — the system is generally working but not consistently applied. This is a minor nonconformity. A major NC would require a total breakdown or systematic failure.\",\n      },\n      {\n        id: \"aqe-m1-q6\",\n        question: \"In the PAF (prevention–appraisal–failure) model, which category does 'calibration of measuring instruments' belong to?\",\n        options: [\n          \"Prevention\",\n          \"Appraisal\",\n          \"Internal failure\",\n          \"External failure\",\n        ],\n        answer: 1,\n        explain:\n          \"Calibration is an appraisal cost — it ensures that measuring instruments provide accurate readings, enabling the detection of nonconforming product. While calibration supports prevention indirectly, its primary purpose is ensuring measurement capability for detection.\",\n      },\n      {\n        id: \"aqe-m1-q7\",\n        question: \"A four-step process has first-pass yields of 98 %, 95 %, 97 %, and 99 %. The rolled throughput yield (RTY) is approximately:\",\n        options: [\n          \"97.3 %\",\n          \"89.4 %\",\n          \"92.1 %\",\n          \"95.0 %\",\n        ],\n        answer: 1,\n        explain:\n          \"RTY = 0.98 × 0.95 × 0.97 × 0.99 = 0.894 = 89.4 %. The multiplication of individual yields always produces a number lower than any single step's yield, revealing the hidden factory losses.\",\n      },\n      {\n        id: \"aqe-m1-q8\",\n        question: \"ISO 13485 differs from ISO 9001 in that ISO 13485:\",\n        options: [\n          \"Does not require a quality policy\",\n          \"Replaces the emphasis on continual improvement with maintaining QMS effectiveness\",\n          \"Does not require management review\",\n          \"Does not use the process approach\",\n        ],\n        answer: 1,\n        explain:\n          \"ISO 13485 focuses on maintaining the effectiveness of the QMS rather than continual improvement. In the medical device regulatory environment, validated processes must not be changed without formal change control, making 'continual improvement' potentially problematic. Both standards require a quality policy, management review, and the process approach.\",\n      },\n    ],\n  },\n};\n","client/src/data/courses/aqe/m2.ts":"import type { CourseModule } from \"../../../lms/types\";\n\nexport const m2: CourseModule = {\n  id: \"aqe-m2\",\n  number: 2,\n  title: \"Probability, Statistics and Data Analysis\",\n  hours: 18,\n  summary:\n    \"This module builds the statistical foundation every quality engineer relies on daily, beginning with probability fundamentals and counting rules, then progressing through discrete distributions (binomial, Poisson, hypergeometric) and continuous distributions (normal, t, chi-squared, F). Learners master descriptive statistics and graphical methods for summarising process data, before tackling hypothesis testing frameworks, confidence intervals, and regression analysis. Throughout the module, every technique is anchored in real quality engineering scenarios — from acceptance sampling decisions to process capability judgements — ensuring graduates can collect, analyse, and interpret data to drive evidence-based quality improvements.\",\n\n  lessons: [\n    /* ======================================================================\n       LESSON 1 — Probability fundamentals and counting rules\n       ====================================================================== */\n    {\n      id: \"aqe-m2-l1\",\n      title: \"Probability fundamentals and counting rules\",\n      minutes: 30,\n      objectives: [\n        \"Calculate probabilities using addition and multiplication rules for quality-related events\",\n        \"Apply conditional probability and Bayes' theorem to update defect-rate estimates\",\n        \"Use permutations and combinations to count outcomes in sampling scenarios\",\n      ],\n      blocks: [\n        {\n          type: \"h\",\n          text: \"The language of probability\",\n        },\n        {\n          type: \"p\",\n          text: \"Every quality decision is a bet against uncertainty. When an inspector pulls five units from a carton of 200, she is implicitly relying on probability to decide whether the lot is good enough to ship. This lesson gives you the formal toolkit — sample spaces, event algebra, and counting rules — so those bets become calculated rather than intuitive.\",\n        },\n        {\n          type: \"callout\",\n          tone: \"key\",\n          title: \"Core definitions\",\n          text: \"A sample space S is the set of all possible outcomes of an experiment. An event A is any subset of S. The probability P(A) satisfies three axioms: (1) P(A) >= 0, (2) P(S) = 1, and (3) for mutually exclusive events A and B, P(A or B) = P(A) + P(B).\",\n        },\n        {\n          type: \"p\",\n          text: \"Consider a bottling line at Brasseries du Littoral in Douala. Each bottle is either conforming (C) or non-conforming (N). If we inspect three bottles, the sample space has 2^3 = 8 outcomes: {CCC, CCN, CNC, CNN, NCC, NCN, NNC, NNN}. The event 'exactly one defective' = {CCN, CNC, NCC} has three outcomes.\",\n        },\n        {\n          type: \"h\",\n          text: \"Complementary, mutually exclusive, and independent events\",\n        },\n        {\n          type: \"table\",\n          head: [\"Concept\", \"Definition\", \"Quality example\"],\n          rows: [\n            [\n              \"Complementary\",\n              \"A' = S \\\\ A; P(A') = 1 - P(A)\",\n              \"If P(conforming) = 0.97, then P(defective) = 0.03\",\n            ],\n            [\n              \"Mutually exclusive\",\n              \"A and B cannot occur together; P(A and B) = 0\",\n              \"A unit cannot be both 'too long' and 'too short' simultaneously\",\n            ],\n            [\n              \"Independent\",\n              \"P(A and B) = P(A) x P(B); knowing A does not change P(B)\",\n              \"Defects on two separate machines running independently\",\n            ],\n          ],\n        },\n        {\n          type: \"h\",\n          text: \"Addition and multiplication rules\",\n        },\n        {\n          type: \"code\",\n          text: \"General addition rule:\\n  P(A or B) = P(A) + P(B) - P(A and B)\\n\\nFor mutually exclusive events:\\n  P(A or B) = P(A) + P(B)\\n\\nGeneral multiplication rule:\\n  P(A and B) = P(A) x P(B|A)\\n\\nFor independent events:\\n  P(A and B) = P(A) x P(B)\",\n        },\n        {\n          type: \"p\",\n          text: \"Worked example: At Cimenterie de Bafoussam, 4 % of cement bags are underweight (event U) and 3 % have torn packaging (event T). Historical data shows 1 % of bags have both defects. What is the probability a randomly selected bag has at least one defect?\",\n        },\n        {\n          type: \"code\",\n          text: \"P(U or T) = P(U) + P(T) - P(U and T)\\n           = 0.04 + 0.03 - 0.01\\n           = 0.06  (6 %)\",\n        },\n        {\n          type: \"h\",\n          text: \"Conditional probability and Bayes' theorem\",\n        },\n        {\n          type: \"p\",\n          text: \"Conditional probability answers the question: 'Given that we already know B has occurred, what is the probability of A?' This is written P(A|B) and calculated as P(A and B) / P(B). In quality engineering, this arises constantly — for example, given that an alarm has triggered, what is the probability of a true defect versus a false alarm?\",\n        },\n        {\n          type: \"code\",\n          text: \"Bayes' theorem:\\n  P(A|B) = P(B|A) x P(A) / P(B)\\n\\nExpanded form (total probability in denominator):\\n  P(A|B) = P(B|A) x P(A) / [P(B|A) x P(A) + P(B|A') x P(A')]\",\n        },\n        {\n          type: \"p\",\n          text: \"Worked example — Bayes' theorem in inspection: A vision inspection system at Plastiques du Centre (Yaoundé) has the following performance: sensitivity (detects a true defect) = 0.95, false alarm rate = 0.02, and the true defect rate is 1 %. When the system flags a unit, what is the probability the unit is truly defective?\",\n        },\n        {\n          type: \"code\",\n          text: \"Let D = defective, F = flagged\\nP(D) = 0.01,  P(D') = 0.99\\nP(F|D) = 0.95,  P(F|D') = 0.02\\n\\nP(D|F) = P(F|D) x P(D) / [P(F|D) x P(D) + P(F|D') x P(D')]\\n       = (0.95 x 0.01) / (0.95 x 0.01 + 0.02 x 0.99)\\n       = 0.0095 / (0.0095 + 0.0198)\\n       = 0.0095 / 0.0293\\n       = 0.324  (32.4 %)\",\n        },\n        {\n          type: \"callout\",\n          tone: \"workplace\",\n          title: \"Low base rate, low positive predictive value\",\n          text: \"Even with a 95 % detection rate, only about one in three flagged items is truly defective because the defect rate is so low (1 %). This is why many factories use two-stage inspection: the automated system screens, then a human verifies flagged units.\",\n        },\n        {\n          type: \"h\",\n          text: \"Permutations and combinations\",\n        },\n        {\n          type: \"code\",\n          text: \"Permutations (order matters):\\n  P(n, r) = n! / (n - r)!\\n\\nCombinations (order does not matter):\\n  C(n, r) = n! / [r! x (n - r)!]\",\n        },\n        {\n          type: \"p\",\n          text: \"Worked example: From a lot of 50 items, a quality engineer must select 5 for destructive testing. How many distinct samples are possible?\",\n        },\n        {\n          type: \"code\",\n          text: \"C(50, 5) = 50! / (5! x 45!)\\n         = (50 x 49 x 48 x 47 x 46) / (5 x 4 x 3 x 2 x 1)\\n         = 254 251 200 / 120\\n         = 2 118 760 possible samples\",\n        },\n        {\n          type: \"check\",\n          id: \"aqe-m2-ck1\",\n          question:\n            \"A lot contains 100 items with 5 defective. If two items are drawn at random without replacement, what is the probability both are defective?\",\n          options: [\n            \"5/100 x 5/100 = 0.0025\",\n            \"5/100 x 4/99 = 0.00202\",\n            \"C(5,2) / C(100,2) = 0.00202\",\n            \"Both B and C are correct\",\n          ],\n          answer: 3,\n          explain:\n            \"Without replacement, the draws are dependent. The probability is (5/100)(4/99) = 20/9900 = 0.00202, which is identical to C(5,2)/C(100,2) = 10/4950 = 0.00202. Both methods yield the same result.\",\n        },\n        {\n          type: \"form\",\n          id: \"aqe-m2-lab1a\",\n          title: \"Probability in quality scenarios\",\n          task: \"A transformer assembly plant in Douala receives components from two suppliers. Supplier A provides 60 % of components with a 2 % defect rate. Supplier B provides 40 % with a 5 % defect rate. Calculate the requested probabilities.\",\n          fields: [\n            {\n              kind: \"text\",\n              label:\n                \"What is the overall probability that a randomly selected component is defective? (4 decimal places)\",\n              accept: [\"0.0320\", \"0.032\"],\n              example: \"0.0320\",\n              explain:\n                \"P(D) = P(D|A)P(A) + P(D|B)P(B) = 0.02 x 0.60 + 0.05 x 0.40 = 0.012 + 0.020 = 0.032\",\n            },\n            {\n              kind: \"text\",\n              label:\n                \"If a defective component is found, what is the probability it came from Supplier B? (4 decimal places)\",\n              accept: [\"0.6250\", \"0.625\"],\n              example: \"0.6250\",\n              explain:\n                \"P(B|D) = P(D|B)P(B) / P(D) = (0.05 x 0.40) / 0.032 = 0.020 / 0.032 = 0.625\",\n            },\n            {\n              kind: \"text\",\n              label:\n                \"What is the probability that two independently selected components are both conforming? (4 decimal places)\",\n              accept: [\"0.9374\"],\n              example: \"0.9374\",\n              explain:\n                \"P(conforming) = 1 - 0.032 = 0.968. For two independent draws: 0.968^2 = 0.9370. More precisely: P(C) = 0.968, P(C and C) = 0.968 x 0.968 = 0.937024 rounds to 0.9370. Accept 0.9370 or 0.9374 depending on rounding.\",\n            },\n          ],\n          hint: \"Use the law of total probability for the overall defect rate, then Bayes' theorem for the conditional question.\",\n        },\n        {\n          type: \"sheet\",\n          id: \"aqe-m2-lab1b\",\n          title: \"Bayes' theorem calculation worksheet\",\n          task: \"An X-ray inspection machine at Fonderie de Douala detects cracks in cast aluminium housings. Complete the Bayesian analysis below. The machine has 92 % sensitivity and 3 % false alarm rate. The true crack rate is 2 %.\",\n          data: [\n            [\"Parameter\", \"Symbol\", \"Value\"],\n            [\"Prior probability of crack\", \"P(Crack)\", 0.02],\n            [\"Prior probability of no crack\", \"P(No Crack)\", null],\n            [\"Sensitivity (true positive rate)\", \"P(Flag|Crack)\", 0.92],\n            [\"False alarm rate\", \"P(Flag|No Crack)\", 0.03],\n            [\"P(Flag and Crack)\", \"P(Flag|Crack) x P(Crack)\", null],\n            [\"P(Flag and No Crack)\", \"P(Flag|No Crack) x P(No Crack)\", null],\n            [\"Total P(Flag)\", \"Sum of above two\", null],\n            [\"P(Crack|Flag) — Posterior\", \"Bayes' theorem\", null],\n          ],\n          editable: [\"C5\", \"C7\", \"C8\", \"C9\", \"C10\"],\n          checks: [\n            { cell: \"C5\", equals: 0.98, tol: 0.001 },\n            { cell: \"C7\", equals: 0.0184, tol: 0.001 },\n            { cell: \"C8\", equals: 0.0294, tol: 0.001 },\n            { cell: \"C9\", equals: 0.0478, tol: 0.001 },\n            { cell: \"C10\", equals: 0.385, tol: 0.01 },\n          ],\n          hint: \"P(No Crack) = 1 - P(Crack). Multiply each branch, then sum to get total P(Flag). Finally divide the crack branch by the total.\",\n          solution: {\n            C5: \"0.98\",\n            C7: \"0.92 x 0.02 = 0.0184\",\n            C8: \"0.03 x 0.98 = 0.0294\",\n            C9: \"0.0184 + 0.0294 = 0.0478\",\n            C10: \"0.0184 / 0.0478 = 0.385 (38.5 %)\",\n          },\n        },\n        {\n          type: \"links\",\n          items: [\n            {\n              label: \"ASQ — Basic probability concepts\",\n              url: \"https://asq.org/quality-resources/statistics\",\n              source: \"ASQ\",\n            },\n          ],\n        },\n      ],\n    },\n\n    /* ======================================================================\n       LESSON 2 — Discrete probability distributions\n       ====================================================================== */\n    {\n      id: \"aqe-m2-l2\",\n      title: \"Discrete probability distributions\",\n      minutes: 30,\n      objectives: [\n        \"Calculate binomial probabilities for acceptance sampling and defective-rate problems\",\n        \"Apply the Poisson distribution to model defects per unit in low-rate processes\",\n        \"Distinguish when to use binomial, Poisson, or hypergeometric distributions in quality scenarios\",\n      ],\n      blocks: [\n        {\n          type: \"h\",\n          text: \"Why discrete distributions matter in quality\",\n        },\n        {\n          type: \"p\",\n          text: \"Quality data often comes in counts: how many defective items in a sample of 20, how many surface flaws per square metre, how many customer complaints per week. Discrete probability distributions let us model these counts, predict outcomes, and make rational accept/reject decisions. In this lesson we cover the three distributions that appear most frequently in quality engineering: binomial, Poisson, and hypergeometric.\",\n        },\n        {\n          type: \"h\",\n          text: \"The binomial distribution\",\n        },\n        {\n          type: \"p\",\n          text: \"The binomial distribution models the number of successes (or defectives) in n independent trials, each with the same probability p of success. It applies when you sample with replacement, or when the population is large enough that removing a unit barely changes the probability.\",\n        },\n        {\n          type: \"code\",\n          text: \"Binomial probability mass function:\\n  P(X = k) = C(n, k) x p^k x (1-p)^(n-k)\\n\\nMean:      mu = n x p\\nVariance:  sigma^2 = n x p x (1-p)\\nStd dev:   sigma = sqrt(n x p x (1-p))\\n\\nwhere:\\n  n = number of trials (sample size)\\n  k = number of successes (defectives)\\n  p = probability of success on each trial\",\n        },\n        {\n          type: \"p\",\n          text: \"Worked example: Savonnerie de Douala produces soap bars with a 3 % defect rate (p = 0.03). A quality engineer inspects a random sample of n = 20 bars. What is the probability of finding exactly 2 defective bars?\",\n        },\n        {\n          type: \"code\",\n          text: \"P(X = 2) = C(20, 2) x 0.03^2 x 0.97^18\\n         = 190 x 0.0009 x 0.5820\\n         = 190 x 0.000524\\n         = 0.0988  (approximately 9.9 %)\",\n        },\n        {\n          type: \"p\",\n          text: \"What is the probability of finding zero defectives (the lot looks perfect)?\",\n        },\n        {\n          type: \"code\",\n          text: \"P(X = 0) = C(20, 0) x 0.03^0 x 0.97^20\\n         = 1 x 1 x 0.5438\\n         = 0.5438  (54.4 %)\",\n        },\n        {\n          type: \"callout\",\n          tone: \"tip\",\n          title: \"Rule of thumb for binomial vs hypergeometric\",\n          text: \"Use the binomial approximation when the sample is less than 10 % of the population (n/N < 0.10). If the sample is a larger fraction of the lot, use the hypergeometric distribution for exact results.\",\n        },\n        {\n          type: \"h\",\n          text: \"The Poisson distribution\",\n        },\n        {\n          type: \"p\",\n          text: \"The Poisson distribution models the number of events occurring in a fixed interval of time, area, or volume when events occur independently at a constant average rate. In quality, it models defects per unit — scratches per panel, pinholes per metre of fabric, contamination particles per litre.\",\n        },\n        {\n          type: \"code\",\n          text: \"Poisson probability mass function:\\n  P(X = k) = (lambda^k x e^(-lambda)) / k!\\n\\nMean:      mu = lambda\\nVariance:  sigma^2 = lambda\\n\\nwhere:\\n  lambda = average rate (mean number of events per interval)\\n  k = observed count\\n  e = 2.71828...\",\n        },\n        {\n          type: \"p\",\n          text: \"Worked example: Textile mill Cotonnière de Garoua finds an average of 2.5 weaving defects per 100 metres of fabric (lambda = 2.5). What is the probability of finding zero defects in a 100-metre roll?\",\n        },\n        {\n          type: \"code\",\n          text: \"P(X = 0) = (2.5^0 x e^(-2.5)) / 0!\\n         = (1 x 0.0821) / 1\\n         = 0.0821  (8.2 %)\",\n        },\n        {\n          type: \"callout\",\n          tone: \"key\",\n          title: \"Poisson as a binomial approximation\",\n          text: \"When n is large (>= 20) and p is small (<= 0.05), the Poisson distribution with lambda = np closely approximates the binomial. This simplifies calculations in acceptance sampling with large lots and low defect rates.\",\n        },\n        {\n          type: \"h\",\n          text: \"The hypergeometric distribution\",\n        },\n        {\n          type: \"p\",\n          text: \"The hypergeometric distribution applies when sampling without replacement from a finite population of known size. It is the exact distribution for acceptance sampling from a lot of N items containing D defectives, when we draw a sample of n items.\",\n        },\n        {\n          type: \"code\",\n          text: \"Hypergeometric probability mass function:\\n  P(X = k) = C(D, k) x C(N-D, n-k) / C(N, n)\\n\\nMean:      mu = n x D / N\\nVariance:  sigma^2 = n x (D/N) x (1 - D/N) x (N-n)/(N-1)\\n\\nwhere:\\n  N = population (lot) size\\n  D = number of defectives in the lot\\n  n = sample size\\n  k = number of defectives observed in sample\",\n        },\n        {\n          type: \"p\",\n          text: \"Worked example: A lot of N = 50 aluminium castings from Fonderie de Douala contains D = 5 defectives. An inspector draws n = 10 castings. What is the probability of finding exactly 1 defective?\",\n        },\n        {\n          type: \"code\",\n          text: \"P(X = 1) = C(5,1) x C(45,9) / C(50,10)\\n         = 5 x 886 163 135 / 10 272 278 170\\n         = 4 430 815 675 / 10 272 278 170\\n         = 0.4313  (43.1 %)\",\n        },\n        {\n          type: \"h\",\n          text: \"Expected value and variance — choosing the right distribution\",\n        },\n        {\n          type: \"table\",\n          head: [\n            \"Distribution\",\n            \"When to use\",\n            \"Mean\",\n            \"Variance\",\n          ],\n          rows: [\n            [\n              \"Binomial\",\n              \"Fixed n trials, constant p, independent (large population)\",\n              \"np\",\n              \"np(1-p)\",\n            ],\n            [\n              \"Poisson\",\n              \"Counts in fixed interval, rare events, known average rate\",\n              \"lambda\",\n              \"lambda\",\n            ],\n            [\n              \"Hypergeometric\",\n              \"Sampling without replacement from finite lot of known composition\",\n              \"nD/N\",\n              \"n(D/N)(1-D/N)(N-n)/(N-1)\",\n            ],\n          ],\n        },\n        {\n          type: \"check\",\n          id: \"aqe-m2-ck2\",\n          question:\n            \"A quality engineer counts paint blemishes on car doors. On average, there are 1.8 blemishes per door. Which distribution best models the number of blemishes on a single door?\",\n          options: [\n            \"Binomial — each blemish is a trial\",\n            \"Poisson — counting events per unit area at a known average rate\",\n            \"Hypergeometric — the number of doors is finite\",\n            \"Normal — 1.8 is close enough to use a continuous distribution\",\n          ],\n          answer: 1,\n          explain:\n            \"Blemishes per door are counts of events occurring over a fixed area at a constant average rate (lambda = 1.8), with no natural upper limit on the count. This is the classic Poisson scenario.\",\n        },\n        {\n          type: \"equip\",\n          title: \"Probability distribution comparison chart\",\n          items: [\n            {\n              art: \"stat-normality\",\n              caption: \"Statistical software output showing distribution fit comparison — learn to read the distribution type selector, parameter estimates, goodness-of-fit statistics, and probability plot overlay.\",\n            },\n          ],\n        },\n        {\n          type: \"sheet\",\n          id: \"aqe-m2-lab2a\",\n          level: \"intermediate\",\n          title: \"Binomial probabilities for lot acceptance\",\n          task: \"Boulangerie Industrielle de Yaoundé bakes bread loaves with a process defect rate of p = 0.05. A sampling plan inspects n = 15 loaves from each batch and accepts the batch if the number of defective loaves is c <= 1 (acceptance number). Calculate the binomial probabilities to determine the probability of accepting the batch.\",\n          data: [\n            [\"k (defectives)\", \"C(15,k)\", \"p^k\", \"(1-p)^(15-k)\", \"P(X=k)\"],\n            [0, 1, 1, null, null],\n            [1, 15, 0.05, null, null],\n            [\"\", \"\", \"\", \"P(accept) = P(X<=1)\", null],\n          ],\n          editable: [\"D2\", \"E2\", \"D3\", \"E3\", \"E4\"],\n          checks: [\n            { cell: \"D2\", equals: 0.4633, tol: 0.005 },\n            { cell: \"E2\", equals: 0.4633, tol: 0.005 },\n            { cell: \"D3\", equals: 0.4877, tol: 0.005 },\n            { cell: \"E3\", equals: 0.3658, tol: 0.005 },\n            { cell: \"E4\", equals: 0.8290, tol: 0.01 },\n          ],\n          hint: \"For k=0: (1-p)^15 = 0.95^15. For k=1: multiply C(15,1) x p^1 x (1-p)^14. Then sum P(X=0) + P(X=1) for the acceptance probability.\",\n          solution: {\n            D2: \"0.95^15 = 0.4633\",\n            E2: \"1 x 1 x 0.4633 = 0.4633\",\n            D3: \"0.95^14 = 0.4877\",\n            E3: \"15 x 0.05 x 0.4877 = 0.3658\",\n            E4: \"0.4633 + 0.3658 = 0.8290 (82.9 % probability of accepting the batch)\",\n          },\n        },\n        {\n          type: \"form\",\n          id: \"aqe-m2-lab2b\",\n          title: \"Choose the right distribution\",\n          task: \"For each quality scenario below, select the probability distribution that best models the situation.\",\n          fields: [\n            {\n              kind: \"select\",\n              label:\n                \"A shipment of 200 capacitors contains 8 defective units. An inspector tests 25 capacitors without replacement. Model the number of defectives found.\",\n              options: [\"Binomial\", \"Poisson\", \"Hypergeometric\"],\n              answer: 2,\n              explain:\n                \"Sampling 25 from 200 without replacement (sample > 10 % of lot), with known population composition — hypergeometric is exact.\",\n            },\n            {\n              kind: \"select\",\n              label:\n                \"A pharmaceutical filling machine fills 10 000 vials per shift. Each vial independently has a 0.1 % chance of being underfilled. Model the number of underfilled vials per shift.\",\n              options: [\"Binomial\", \"Poisson\", \"Hypergeometric\"],\n              answer: 1,\n              explain:\n                \"Large n (10 000), small p (0.001), independent trials — Poisson with lambda = np = 10 is the practical choice, though binomial is also technically correct.\",\n            },\n            {\n              kind: \"select\",\n              label:\n                \"From a production run, 50 circuit boards are tested. Each board independently passes or fails. The historical fail rate is 4 %. Model the number of failures in the sample.\",\n              options: [\"Binomial\", \"Poisson\", \"Hypergeometric\"],\n              answer: 0,\n              explain:\n                \"Fixed n = 50 trials, constant p = 0.04, independent outcomes (assumed large production run) — binomial distribution.\",\n            },\n          ],\n          hint: \"Consider whether sampling is with or without replacement, whether the population is finite and small, and whether you are counting events per unit or defectives in a fixed sample.\",\n        },\n        {\n          type: \"links\",\n          items: [\n            {\n              label: \"ASQ — Probability distributions overview\",\n              url: \"https://asq.org/quality-resources/statistics\",\n              source: \"ASQ\",\n            },\n          ],\n        },\n      ],\n    },\n\n    /* ======================================================================\n       LESSON 3 — Continuous distributions and the normal curve\n       ====================================================================== */\n    {\n      id: \"aqe-m2-l3\",\n      title: \"Continuous distributions and the normal curve\",\n      minutes: 35,\n      objectives: [\n        \"Convert raw data to z-scores and use the standard normal table to find probabilities and percentiles\",\n        \"Explain the central limit theorem and its role in process monitoring\",\n        \"Distinguish the t, chi-squared, and F distributions and state when each is used\",\n        \"Interpret normality test results including probability plots and the Anderson-Darling statistic\",\n      ],\n      blocks: [\n        {\n          type: \"h\",\n          text: \"The normal distribution — pillar of quality engineering\",\n        },\n        {\n          type: \"p\",\n          text: \"The normal (Gaussian) distribution is the single most important continuous distribution in quality engineering. Process measurements — diameters, weights, voltages, fill volumes — often follow a normal distribution when only common-cause variation is present. Specification limits, control chart calculations, process capability indices, and most hypothesis tests assume or rely on normality.\",\n        },\n        {\n          type: \"code\",\n          text: \"Normal probability density function:\\n  f(x) = (1 / (sigma x sqrt(2 x pi))) x e^(-(x - mu)^2 / (2 x sigma^2))\\n\\nProperties:\\n  - Symmetric, bell-shaped curve centred at mu\\n  - Approximately 68.27 % of data within mu +/- 1 sigma\\n  - Approximately 95.45 % within mu +/- 2 sigma\\n  - Approximately 99.73 % within mu +/- 3 sigma\",\n        },\n        {\n          type: \"callout\",\n          tone: \"key\",\n          title: \"The empirical rule (68-95-99.7)\",\n          text: \"For any normally distributed process, roughly 68 % of measurements fall within one standard deviation of the mean, 95 % within two, and 99.7 % within three. This is the foundation of 3-sigma control limits on X-bar charts.\",\n        },\n        {\n          type: \"h\",\n          text: \"Z-scores and the standard normal table\",\n        },\n        {\n          type: \"p\",\n          text: \"A z-score converts any normal variable X ~ N(mu, sigma^2) to the standard normal Z ~ N(0, 1), allowing us to use a single table to find probabilities for any normal distribution.\",\n        },\n        {\n          type: \"code\",\n          text: \"Z-score formula:\\n  z = (x - mu) / sigma\\n\\nReverse (finding x from z):\\n  x = mu + z x sigma\",\n        },\n        {\n          type: \"p\",\n          text: \"Worked example: Steel rods at Aciéries du Cameroun have a mean length of 500.0 mm and a standard deviation of 1.2 mm. The upper specification limit is 502.5 mm. What proportion of rods exceeds the USL?\",\n        },\n        {\n          type: \"code\",\n          text: \"z = (502.5 - 500.0) / 1.2 = 2.5 / 1.2 = 2.083\\n\\nFrom standard normal table:\\n  P(Z < 2.08) = 0.9812\\n\\nP(X > 502.5) = 1 - 0.9812 = 0.0188  (1.88 %)\\n\\nIn a run of 10 000 rods, approximately 188 would exceed the USL.\",\n        },\n        {\n          type: \"p\",\n          text: \"What if the lower specification limit is 497.0 mm? What proportion of rods is below the LSL?\",\n        },\n        {\n          type: \"code\",\n          text: \"z = (497.0 - 500.0) / 1.2 = -3.0 / 1.2 = -2.50\\n\\nP(Z < -2.50) = 0.0062  (0.62 %)\\n\\nTotal out-of-spec = 1.88 % + 0.62 % = 2.50 %\",\n        },\n        {\n          type: \"h\",\n          text: \"The central limit theorem (CLT)\",\n        },\n        {\n          type: \"p\",\n          text: \"The central limit theorem states that the sampling distribution of the sample mean X-bar approaches a normal distribution as the sample size n increases, regardless of the shape of the parent population, provided the population has finite mean mu and finite variance sigma^2.\",\n        },\n        {\n          type: \"code\",\n          text: \"Central limit theorem:\\n  X-bar ~ N(mu, sigma^2 / n)  approximately, for large n\\n\\nStandard error of the mean:\\n  SE = sigma / sqrt(n)\\n\\nZ-score for a sample mean:\\n  z = (x-bar - mu) / (sigma / sqrt(n))\",\n        },\n        {\n          type: \"callout\",\n          tone: \"workplace\",\n          title: \"CLT in practice\",\n          text: \"On an X-bar control chart with subgroup size n = 5, even if individual measurements are mildly skewed, the subgroup averages will be approximately normal. This is why X-bar charts are robust — the CLT makes the normality assumption reasonable for averages even when individual values are not perfectly normal.\",\n        },\n        {\n          type: \"h\",\n          text: \"Other continuous distributions\",\n        },\n        {\n          type: \"table\",\n          head: [\"Distribution\", \"Parameters\", \"Quality application\"],\n          rows: [\n            [\n              \"t-distribution\",\n              \"Degrees of freedom (df = n - 1)\",\n              \"Confidence intervals and hypothesis tests for means when sigma is unknown and n is small\",\n            ],\n            [\n              \"Chi-squared (chi^2)\",\n              \"Degrees of freedom (df)\",\n              \"Tests for variance, goodness-of-fit tests, contingency tables\",\n            ],\n            [\n              \"F-distribution\",\n              \"df1 (numerator), df2 (denominator)\",\n              \"Comparing two variances, ANOVA, regression significance tests\",\n            ],\n          ],\n        },\n        {\n          type: \"p\",\n          text: \"The t-distribution is wider and flatter than the standard normal, with heavier tails. As degrees of freedom increase, it approaches the normal. For df > 30, the t and z distributions are nearly identical.\",\n        },\n        {\n          type: \"h\",\n          text: \"Normality testing\",\n        },\n        {\n          type: \"p\",\n          text: \"Before applying parametric statistical methods, you should verify that the data are approximately normally distributed. Two widely used approaches are the normal probability plot (a graphical method) and the Anderson-Darling test (a formal hypothesis test).\",\n        },\n        {\n          type: \"list\",\n          items: [\n            \"Normal probability plot: plots ordered data against theoretical normal quantiles. If data are normal, points fall approximately on a straight line. Deviations indicate skewness or heavy/light tails.\",\n            \"Anderson-Darling test: H0: data come from a normal distribution. A small p-value (typically < 0.05) rejects normality. The A-D statistic gives more weight to the tails than the Kolmogorov-Smirnov test.\",\n            \"Practical rule: with small samples (n < 30), normality tests have low power and may fail to detect non-normality. With very large samples (n > 1000), even trivial departures from normality become statistically significant. Always combine formal tests with graphical assessment.\",\n          ],\n        },\n        {\n          type: \"equip\",\n          title: \"Normal probability plot output\",\n          items: [\n            {\n              art: \"stat-normality\",\n              name: \"Normal probability plot\",\n              caption:\n                \"The ordered data values are plotted against their expected z-scores. A straight-line pattern confirms approximate normality. The Anderson-Darling statistic and p-value are displayed in the legend area.\",\n              specs: [\n                { label: \"X-axis\", value: \"Theoretical quantiles (z-scores)\" },\n                { label: \"Y-axis\", value: \"Ordered sample values\" },\n                { label: \"Reference line\", value: \"Best-fit line through Q1 and Q3\" },\n                { label: \"A-D statistic\", value: \"Reported with p-value\" },\n              ],\n            },\n          ],\n        },\n        {\n          type: \"check\",\n          id: \"aqe-m2-ck3\",\n          question:\n            \"A process produces bolts with a mean diameter of 10.00 mm and standard deviation 0.05 mm. What z-score corresponds to a bolt diameter of 10.12 mm?\",\n          options: [\"1.20\", \"2.00\", \"2.40\", \"0.24\"],\n          answer: 2,\n          explain:\n            \"z = (10.12 - 10.00) / 0.05 = 0.12 / 0.05 = 2.40. This means the bolt is 2.40 standard deviations above the mean.\",\n        },\n        {\n          type: \"sheet\",\n          id: \"aqe-m2-lab3a\",\n          title: \"Z-score calculations and areas under the curve\",\n          task: \"Fill volumes (ml) at Boissons du Cameroun are normally distributed with mean = 330.0 ml and standard deviation = 2.5 ml. Complete the z-score calculations and find the associated probabilities using the standard normal table values provided.\",\n          data: [\n            [\"Scenario\", \"x (ml)\", \"z-score\", \"P(Z < z)\", \"Probability\"],\n            [\"P(X < 325)\", 325, null, null, null],\n            [\"P(X > 335)\", 335, null, null, null],\n            [\"P(327 < X < 333)\", \"327 to 333\", \"-1.20 to 1.20\", \"0.1151 and 0.8849\", null],\n            [\"mu = 330.0\", \"sigma = 2.5\", \"\", \"\", \"\"],\n          ],\n          editable: [\"C2\", \"D2\", \"E2\", \"C3\", \"D3\", \"E3\", \"E4\"],\n          checks: [\n            { cell: \"C2\", equals: -2.0, tol: 0.01 },\n            { cell: \"D2\", equals: 0.0228, tol: 0.002 },\n            { cell: \"E2\", equals: 0.0228, tol: 0.002 },\n            { cell: \"C3\", equals: 2.0, tol: 0.01 },\n            { cell: \"D3\", equals: 0.9772, tol: 0.002 },\n            { cell: \"E3\", equals: 0.0228, tol: 0.002 },\n            { cell: \"E4\", equals: 0.7699, tol: 0.01 },\n          ],\n          hint: \"z = (x - 330) / 2.5. For P(X < 325), find P(Z < z). For P(X > 335), compute 1 - P(Z < z). For the interval, subtract the two cumulative probabilities.\",\n          solution: {\n            C2: \"(325 - 330) / 2.5 = -2.00\",\n            D2: \"P(Z < -2.00) = 0.0228\",\n            E2: \"P(X < 325) = 0.0228 = 2.28 %\",\n            C3: \"(335 - 330) / 2.5 = 2.00\",\n            D3: \"P(Z < 2.00) = 0.9772\",\n            E3: \"P(X > 335) = 1 - 0.9772 = 0.0228 = 2.28 %\",\n            E4: \"P(327 < X < 333) = 0.8849 - 0.1151 = 0.7699 = 77.0 %\",\n          },\n        },\n        {\n          type: \"form\",\n          id: \"aqe-m2-lab3b\",\n          title: \"Interpreting normality test results\",\n          task: \"A quality engineer at Câblerie de Douala tested 50 wire-diameter measurements for normality. The Anderson-Darling test returned A-D = 0.312, p-value = 0.534. The normal probability plot shows points falling close to the reference line with slight departure at the upper tail.\",\n          fields: [\n            {\n              kind: \"select\",\n              label: \"At alpha = 0.05, what is the conclusion of the Anderson-Darling test?\",\n              options: [\n                \"Reject H0 — data are not normally distributed\",\n                \"Fail to reject H0 — insufficient evidence to conclude non-normality\",\n                \"Accept H0 — data are definitely normally distributed\",\n                \"The test is inconclusive\",\n              ],\n              answer: 1,\n              explain:\n                \"p-value (0.534) > alpha (0.05), so we fail to reject the null hypothesis that the data are normally distributed. Note: we never 'accept' H0; we only fail to reject it.\",\n            },\n            {\n              kind: \"select\",\n              label: \"How should the slight upper-tail departure on the probability plot be interpreted?\",\n              options: [\n                \"The data are clearly non-normal and parametric tests should not be used\",\n                \"Minor departures in the tails are common and do not necessarily invalidate normality for practical purposes\",\n                \"The Anderson-Darling test must be wrong since the plot shows a departure\",\n                \"The sample size is too small to draw any conclusions\",\n              ],\n              answer: 1,\n              explain:\n                \"Minor tail departures are common, especially with n = 50. The formal test (large p-value) and the overall linear pattern support approximate normality. Perfect normality is never achieved in practice; approximate normality is sufficient for most parametric methods.\",\n            },\n          ],\n          hint: \"Compare the p-value to the significance level. Remember that no real data set is perfectly normal — the question is whether the departure is severe enough to invalidate the analysis.\",\n        },\n        {\n          type: \"links\",\n          items: [\n            {\n              label: \"ASQ — Normal distribution\",\n              url: \"https://asq.org/quality-resources/statistics\",\n              source: \"ASQ\",\n            },\n          ],\n        },\n      ],\n    },\n\n    /* ======================================================================\n       LESSON 4 — Descriptive statistics and graphical methods\n       ====================================================================== */\n    {\n      id: \"aqe-m2-l4\",\n      title: \"Descriptive statistics and graphical methods\",\n      minutes: 25,\n      objectives: [\n        \"Calculate and interpret mean, median, mode, range, variance, standard deviation, and coefficient of variation\",\n        \"Select the appropriate graphical tool (histogram, box plot, Pareto chart, run chart) for a given data analysis objective\",\n        \"Classify data as continuous, discrete, nominal, or ordinal and choose suitable summary measures for each type\",\n      ],\n      blocks: [\n        {\n          type: \"h\",\n          text: \"Summarising data — the first step in any analysis\",\n        },\n        {\n          type: \"p\",\n          text: \"Before running any hypothesis test or fitting a model, a quality engineer must summarise and visualise the data. Descriptive statistics compress a data set into a few meaningful numbers, while graphical methods reveal patterns — shape, spread, outliers, trends — that numbers alone can miss. Together, they form the foundation of data-driven quality improvement.\",\n        },\n        {\n          type: \"h\",\n          text: \"Measures of central tendency\",\n        },\n        {\n          type: \"table\",\n          head: [\"Measure\", \"Formula / Definition\", \"When to use\"],\n          rows: [\n            [\n              \"Mean (x-bar)\",\n              \"Sum of all values / n\",\n              \"Symmetric data without extreme outliers; most common summary for continuous measurements\",\n            ],\n            [\n              \"Median\",\n              \"Middle value when data are sorted; average of two middle values if n is even\",\n              \"Skewed data or when outliers are present; more resistant than the mean\",\n            ],\n            [\n              \"Mode\",\n              \"Most frequently occurring value\",\n              \"Categorical data; also useful to detect bimodal distributions in measurement data\",\n            ],\n          ],\n        },\n        {\n          type: \"h\",\n          text: \"Measures of dispersion\",\n        },\n        {\n          type: \"code\",\n          text: \"Range:                      R = x_max - x_min\\n\\nSample variance:            s^2 = sum((x_i - x-bar)^2) / (n - 1)\\n\\nSample standard deviation:  s = sqrt(s^2)\\n\\nCoefficient of variation:   CV = (s / x-bar) x 100 %\",\n        },\n        {\n          type: \"callout\",\n          tone: \"key\",\n          title: \"Why divide by (n - 1)?\",\n          text: \"Using (n - 1) instead of n gives an unbiased estimate of the population variance. This is called Bessel's correction. The sample mean consumes one degree of freedom, leaving (n - 1) independent deviations.\",\n        },\n        {\n          type: \"p\",\n          text: \"Worked example: Five thickness measurements (mm) of plywood sheets at Scierie de Mbalmayo: 12.1, 12.3, 11.9, 12.0, 12.2.\",\n        },\n        {\n          type: \"code\",\n          text: \"Mean:  x-bar = (12.1 + 12.3 + 11.9 + 12.0 + 12.2) / 5 = 60.5 / 5 = 12.10 mm\\n\\nMedian: sort -> 11.9, 12.0, 12.1, 12.2, 12.3 -> middle value = 12.1 mm\\n\\nRange:  R = 12.3 - 11.9 = 0.4 mm\\n\\nVariance: s^2 = [(12.1-12.1)^2 + (12.3-12.1)^2 + (11.9-12.1)^2\\n               + (12.0-12.1)^2 + (12.2-12.1)^2] / (5-1)\\n             = [0 + 0.04 + 0.04 + 0.01 + 0.01] / 4\\n             = 0.10 / 4 = 0.025 mm^2\\n\\nStd dev: s = sqrt(0.025) = 0.158 mm\\n\\nCV = (0.158 / 12.10) x 100 = 1.31 %\",\n        },\n        {\n          type: \"h\",\n          text: \"Data types\",\n        },\n        {\n          type: \"table\",\n          head: [\"Type\", \"Description\", \"Examples\", \"Summary measures\"],\n          rows: [\n            [\n              \"Continuous\",\n              \"Any value within a range; measured\",\n              \"Length, weight, temperature, voltage\",\n              \"Mean, std dev, histogram\",\n            ],\n            [\n              \"Discrete\",\n              \"Countable, integer values\",\n              \"Number of defects, complaint count\",\n              \"Mean, range, bar chart\",\n            ],\n            [\n              \"Nominal\",\n              \"Categories without order\",\n              \"Defect type, supplier name, colour\",\n              \"Mode, frequency, Pareto chart\",\n            ],\n            [\n              \"Ordinal\",\n              \"Categories with meaningful order\",\n              \"Rating scale (1-5), severity level\",\n              \"Median, mode, bar chart\",\n            ],\n          ],\n        },\n        {\n          type: \"h\",\n          text: \"Graphical tools for quality data\",\n        },\n        {\n          type: \"list\",\n          items: [\n            \"Histogram: shows the frequency distribution of continuous data. Reveals shape (symmetric, skewed, bimodal), spread, and whether the process is centred within specifications.\",\n            \"Box plot: displays median, quartiles (Q1 and Q3), whiskers (1.5 x IQR), and outliers. Excellent for comparing distributions across groups (machines, shifts, suppliers).\",\n            \"Stem-and-leaf plot: like a histogram but preserves the actual data values. Useful for small data sets (n < 50).\",\n            \"Dot plot: shows individual data points along a number line. Good for small samples to see clustering and gaps.\",\n            \"Run chart: plots data in time order. Reveals trends, shifts, and cycles that summary statistics miss.\",\n          ],\n        },\n        {\n          type: \"equip\",\n          title: \"Histogram display\",\n          items: [\n            {\n              art: \"qc-histogram\",\n              name: \"Quality histogram\",\n              caption:\n                \"A histogram with specification limits overlaid shows whether the process output is centred and contained within tolerances. The height of each bar represents frequency; the shape reveals whether the distribution is normal, skewed, or bimodal.\",\n              specs: [\n                { label: \"X-axis\", value: \"Measurement values (bins)\" },\n                { label: \"Y-axis\", value: \"Frequency or relative frequency\" },\n                { label: \"Overlays\", value: \"LSL, USL, target, normal curve fit\" },\n                { label: \"Best for\", value: \"Continuous data, n >= 30\" },\n              ],\n            },\n          ],\n        },\n        {\n          type: \"check\",\n          id: \"aqe-m2-ck4\",\n          question:\n            \"A data set of 100 measurements has a mean of 50.0, a median of 48.5, and a mode of 47.0. What does this suggest about the distribution shape?\",\n          options: [\n            \"The distribution is symmetric\",\n            \"The distribution is negatively (left) skewed\",\n            \"The distribution is positively (right) skewed\",\n            \"The data are bimodal\",\n          ],\n          answer: 2,\n          explain:\n            \"When mean > median > mode, the distribution has a right (positive) skew. The mean is pulled toward the long right tail by higher values.\",\n        },\n        {\n          type: \"sheet\",\n          id: \"aqe-m2-lab4a\",\n          title: \"Descriptive statistics from quality data\",\n          task: \"Compute the descriptive statistics for the following tensile strength measurements (MPa) from steel reinforcement bars produced at Aciéries du Wouri, Douala. The specification is 420-520 MPa.\",\n          data: [\n            [\"Sample\", \"Strength (MPa)\"],\n            [1, 465],\n            [2, 472],\n            [3, 458],\n            [4, 481],\n            [5, 469],\n            [6, 455],\n            [7, 478],\n            [8, 463],\n            [9, 490],\n            [10, 461],\n            [\"\", \"\"],\n            [\"Statistic\", \"Value\"],\n            [\"Mean\", null],\n            [\"Median\", null],\n            [\"Range\", null],\n            [\"Std deviation\", null],\n            [\"CV (%)\", null],\n          ],\n          editable: [\"B14\", \"B15\", \"B16\", \"B17\", \"B18\"],\n          checks: [\n            { cell: \"B14\", equals: 469.2, tol: 0.5 },\n            { cell: \"B15\", equals: 467.0, tol: 1.0 },\n            { cell: \"B16\", equals: 35, tol: 0.5 },\n            { cell: \"B17\", equals: 11.0, tol: 1.0 },\n            { cell: \"B18\", equals: 2.34, tol: 0.2 },\n          ],\n          hint: \"Sum all 10 values, divide by 10 for the mean. Sort to find the median (average of 5th and 6th values). Range = max - min. For std dev, use the formula with (n-1) in the denominator.\",\n          solution: {\n            B14: \"Sum = 4692, Mean = 4692/10 = 469.2 MPa\",\n            B15: \"Sorted: 455,458,461,463,465,469,472,478,481,490. Median = (465+469)/2 = 467.0\",\n            B16: \"490 - 455 = 35 MPa\",\n            B17: \"s = sqrt(sum of squared deviations / 9) = sqrt(1085.6/9) = sqrt(120.6) = 10.98 ~ 11.0 MPa\",\n            B18: \"CV = (11.0 / 469.2) x 100 = 2.34 %\",\n          },\n        },\n        {\n          type: \"pareto\",\n          id: \"aqe-m2-lab4b\",\n          title: \"Defect analysis at packaging line\",\n          task: \"Emballages Tropicaux (Douala) recorded the following defect types over one month on their carton packaging line. Arrange the Pareto chart and identify which defect types account for approximately 80 % of all defects.\",\n          unit: \"defects\",\n          categories: [\n            { label: \"Seal failure\", count: 142 },\n            { label: \"Print smear\", count: 89 },\n            { label: \"Dimension error\", count: 67 },\n            { label: \"Torn flap\", count: 45 },\n            { label: \"Colour mismatch\", count: 28 },\n            { label: \"Adhesive residue\", count: 19 },\n            { label: \"Other\", count: 10 },\n          ],\n          hint: \"The 80/20 rule: look for the vital few categories that together make up roughly 80 % of the total defect count.\",\n        },\n        {\n          type: \"links\",\n          items: [\n            {\n              label: \"ASQ — Seven basic quality tools\",\n              url: \"https://asq.org/quality-resources/seven-basic-quality-tools\",\n              source: \"ASQ\",\n            },\n          ],\n        },\n      ],\n    },\n\n    /* ======================================================================\n       LESSON 5 — Hypothesis testing and confidence intervals\n       ====================================================================== */\n    {\n      id: \"aqe-m2-l5\",\n      title: \"Hypothesis testing and confidence intervals\",\n      minutes: 35,\n      objectives: [\n        \"Formulate null and alternative hypotheses for one-sample and two-sample tests on process means and proportions\",\n        \"Perform a t-test and interpret the p-value in the context of a quality engineering decision\",\n        \"Construct and interpret confidence intervals for means, proportions, and variances\",\n        \"Distinguish between Type I and Type II errors and explain their practical consequences in quality decisions\",\n      ],\n      blocks: [\n        {\n          type: \"h\",\n          text: \"The hypothesis testing framework\",\n        },\n        {\n          type: \"p\",\n          text: \"Hypothesis testing provides a structured method for making decisions from data. Rather than relying on gut feeling — 'this batch looks different' — a quality engineer translates the question into a formal statistical test with quantified risk of being wrong. The framework has been the backbone of evidence-based quality since Walter Shewhart's pioneering work in the 1920s.\",\n        },\n        {\n          type: \"steps\",\n          title: \"Steps in a hypothesis test\",\n          items: [\n            \"State the null hypothesis H0 (status quo, no effect) and alternative hypothesis H1 (the claim you want to test)\",\n            \"Choose the significance level alpha (commonly 0.05 or 0.01) — this is the maximum acceptable probability of a Type I error\",\n            \"Select the appropriate test statistic (z, t, chi-squared, F) based on the parameter being tested and whether sigma is known\",\n            \"Collect data and compute the test statistic\",\n            \"Find the p-value or compare the test statistic to the critical value\",\n            \"Make a decision: if p-value <= alpha, reject H0; otherwise, fail to reject H0\",\n            \"State the conclusion in context of the quality problem\",\n          ],\n        },\n        {\n          type: \"h\",\n          text: \"Type I and Type II errors\",\n        },\n        {\n          type: \"table\",\n          head: [\"\", \"H0 is true (process OK)\", \"H0 is false (process has shifted)\"],\n          rows: [\n            [\n              \"Reject H0\",\n              \"Type I error (alpha) — false alarm: adjusting a process that was fine\",\n              \"Correct decision (power = 1 - beta)\",\n            ],\n            [\n              \"Fail to reject H0\",\n              \"Correct decision\",\n              \"Type II error (beta) — missed signal: failing to detect a real problem\",\n            ],\n          ],\n        },\n        {\n          type: \"callout\",\n          tone: \"workplace\",\n          title: \"Practical consequences in quality\",\n          text: \"A Type I error (false alarm) wastes time and money: you stop the line, investigate, and find nothing wrong. A Type II error (missed signal) is often more dangerous: a shifted process continues to produce non-conforming product that reaches the customer. Choosing alpha and sample size is a trade-off between these two risks.\",\n        },\n        {\n          type: \"h\",\n          text: \"One-sample t-test for the mean\",\n        },\n        {\n          type: \"p\",\n          text: \"When the population standard deviation is unknown (the usual case), we use the sample standard deviation s and the t-distribution. This is the most common hypothesis test in quality engineering — testing whether a process mean has shifted from its target.\",\n        },\n        {\n          type: \"code\",\n          text: \"One-sample t-test statistic:\\n  t = (x-bar - mu_0) / (s / sqrt(n))\\n\\nDegrees of freedom: df = n - 1\\n\\nwhere:\\n  x-bar = sample mean\\n  mu_0  = hypothesised population mean (target)\\n  s     = sample standard deviation\\n  n     = sample size\",\n        },\n        {\n          type: \"p\",\n          text: \"Worked example: The target fill weight for cocoa powder tins at Chocolaterie du Moungo is 250.0 g. A random sample of n = 12 tins yields x-bar = 248.3 g and s = 3.1 g. At alpha = 0.05, is there evidence that the mean fill weight differs from the target?\",\n        },\n        {\n          type: \"code\",\n          text: \"H0: mu = 250.0  (process on target)\\nH1: mu != 250.0  (two-tailed test)\\n\\nt = (248.3 - 250.0) / (3.1 / sqrt(12))\\n  = -1.7 / (3.1 / 3.464)\\n  = -1.7 / 0.8948\\n  = -1.900\\n\\ndf = 12 - 1 = 11\\nt_critical (two-tailed, alpha=0.05, df=11) = +/- 2.201\\n\\nSince |t| = 1.900 < 2.201, we fail to reject H0.\\np-value ~ 0.084 > 0.05\\n\\nConclusion: At the 5 % significance level, there is insufficient evidence\\nto conclude the mean fill weight differs from 250.0 g.\",\n        },\n        {\n          type: \"h\",\n          text: \"Two-sample t-test\",\n        },\n        {\n          type: \"code\",\n          text: \"Two-sample t-test (pooled, assuming equal variances):\\n  t = (x-bar_1 - x-bar_2) / (s_p x sqrt(1/n1 + 1/n2))\\n\\nPooled standard deviation:\\n  s_p = sqrt(((n1-1)s1^2 + (n2-1)s2^2) / (n1 + n2 - 2))\\n\\nDegrees of freedom: df = n1 + n2 - 2\",\n        },\n        {\n          type: \"h\",\n          text: \"Tests for proportions\",\n        },\n        {\n          type: \"code\",\n          text: \"One-sample z-test for proportion:\\n  z = (p-hat - p_0) / sqrt(p_0 x (1 - p_0) / n)\\n\\nwhere:\\n  p-hat = sample proportion (defectives found / sample size)\\n  p_0   = hypothesised proportion\\n  n     = sample size (must satisfy np_0 >= 5 and n(1-p_0) >= 5)\",\n        },\n        {\n          type: \"h\",\n          text: \"Confidence intervals\",\n        },\n        {\n          type: \"p\",\n          text: \"A confidence interval provides a range of plausible values for a population parameter, along with a stated level of confidence. Unlike a hypothesis test, which gives a yes/no decision, a confidence interval conveys the precision of the estimate.\",\n        },\n        {\n          type: \"code\",\n          text: \"Confidence interval for the mean (sigma unknown):\\n  x-bar +/- t_(alpha/2, df) x (s / sqrt(n))\\n\\nConfidence interval for a proportion:\\n  p-hat +/- z_(alpha/2) x sqrt(p-hat x (1 - p-hat) / n)\\n\\nConfidence interval for variance:\\n  ((n-1)s^2 / chi^2_(alpha/2), (n-1)s^2 / chi^2_(1-alpha/2))\",\n        },\n        {\n          type: \"p\",\n          text: \"Worked example: Returning to the cocoa tins with x-bar = 248.3, s = 3.1, n = 12. Construct a 95 % confidence interval for the true mean fill weight.\",\n        },\n        {\n          type: \"code\",\n          text: \"95 % CI = x-bar +/- t_(0.025, 11) x (s / sqrt(n))\\n        = 248.3 +/- 2.201 x (3.1 / sqrt(12))\\n        = 248.3 +/- 2.201 x 0.8948\\n        = 248.3 +/- 1.970\\n        = (246.33, 250.27) g\\n\\nInterpretation: We are 95 % confident the true mean fill weight is\\nbetween 246.33 g and 250.27 g. Because 250.0 falls inside the interval,\\nthis is consistent with failing to reject H0: mu = 250.\",\n        },\n        {\n          type: \"callout\",\n          tone: \"tip\",\n          title: \"CI and hypothesis test agreement\",\n          text: \"A 95 % confidence interval and a two-tailed test at alpha = 0.05 always agree: if the hypothesised value falls inside the CI, the test fails to reject H0; if it falls outside, the test rejects H0.\",\n        },\n        {\n          type: \"h\",\n          text: \"p-value interpretation\",\n        },\n        {\n          type: \"callout\",\n          tone: \"warning\",\n          title: \"What a p-value is NOT\",\n          text: \"The p-value is NOT the probability that H0 is true, nor is it the probability of making an error. The p-value is the probability of observing a test statistic as extreme as (or more extreme than) the one computed, assuming H0 is true. A small p-value means the data are unlikely under H0, which is evidence against H0.\",\n        },\n        {\n          type: \"equip\",\n          title: \"Regression output screen\",\n          items: [\n            {\n              art: \"stat-regression\",\n              name: \"Regression analysis output\",\n              caption:\n                \"Standard regression output includes the fitted equation, R-squared, adjusted R-squared, ANOVA table (F-test for overall significance), and coefficient table with t-tests for individual predictors. Residual plots help verify assumptions.\",\n              specs: [\n                { label: \"Equation\", value: \"Y = b0 + b1*X1 + b2*X2 + ...\" },\n                { label: \"R-squared\", value: \"Proportion of variance explained\" },\n                { label: \"F-test p-value\", value: \"Overall model significance\" },\n                { label: \"Residual plots\", value: \"Normal plot, residuals vs fitted, residuals vs order\" },\n              ],\n            },\n          ],\n        },\n        {\n          type: \"check\",\n          id: \"aqe-m2-ck5\",\n          question:\n            \"A quality engineer tests H0: mu = 100 vs H1: mu != 100 with n = 25 and obtains a p-value of 0.032. At alpha = 0.05, what is the correct conclusion?\",\n          options: [\n            \"Fail to reject H0 — there is no difference\",\n            \"Reject H0 — there is statistically significant evidence the mean differs from 100\",\n            \"The probability that mu = 100 is 3.2 %\",\n            \"The test is inconclusive because n is too small\",\n          ],\n          answer: 1,\n          explain:\n            \"p-value (0.032) < alpha (0.05), so we reject H0. There is statistically significant evidence at the 5 % level that the true mean differs from 100. The p-value is NOT the probability that H0 is true.\",\n        },\n        {\n          type: \"sheet\",\n          id: \"aqe-m2-lab5a\",\n          title: \"One-sample t-test on process data\",\n          task: \"A chemical plant in Douala (Chimiques du Wouri) targets a pH of 7.00 for treated water. Twelve samples were collected over a shift. Perform a two-tailed t-test at alpha = 0.05 to determine whether the mean pH differs from 7.00.\",\n          data: [\n            [\"Sample\", \"pH\"],\n            [1, 7.02],\n            [2, 6.98],\n            [3, 7.05],\n            [4, 7.01],\n            [5, 6.95],\n            [6, 7.08],\n            [7, 7.03],\n            [8, 6.99],\n            [9, 7.06],\n            [10, 7.00],\n            [11, 7.04],\n            [12, 6.97],\n            [\"\", \"\"],\n            [\"Statistic\", \"Value\"],\n            [\"x-bar\", null],\n            [\"s\", null],\n            [\"t-statistic\", null],\n            [\"t-critical (alpha=0.05, df=11)\", 2.201],\n            [\"Decision\", null],\n          ],\n          editable: [\"B16\", \"B17\", \"B18\", \"B20\"],\n          checks: [\n            { cell: \"B16\", equals: 7.015, tol: 0.005 },\n            { cell: \"B17\", equals: 0.039, tol: 0.005 },\n            { cell: \"B18\", equals: 1.33, tol: 0.15 },\n          ],\n          hint: \"Sum the 12 pH values, divide by 12 for x-bar. Calculate s using (n-1). Then t = (x-bar - 7.00) / (s / sqrt(12)). Compare |t| to 2.201.\",\n          solution: {\n            B16: \"Sum = 84.18, x-bar = 84.18/12 = 7.015\",\n            B17: \"s = sqrt(sum of (xi - 7.015)^2 / 11) = 0.039\",\n            B18: \"t = (7.015 - 7.00) / (0.039 / sqrt(12)) = 0.015 / 0.01126 = 1.33\",\n            B20: \"Fail to reject H0 — |t| = 1.33 < 2.201. Insufficient evidence that mean pH differs from 7.00.\",\n          },\n        },\n        {\n          type: \"form\",\n          id: \"aqe-m2-lab5b\",\n          title: \"Interpreting hypothesis test results\",\n          task: \"Interpret the following hypothesis test outputs from a quality engineering context.\",\n          fields: [\n            {\n              kind: \"select\",\n              label:\n                \"A two-sample t-test comparing tensile strength of wire from Machine A vs Machine B gives t = 3.42, df = 28, p = 0.002. At alpha = 0.05, what do you conclude?\",\n              options: [\n                \"The machines produce wire with equal tensile strength\",\n                \"There is statistically significant evidence of a difference in tensile strength between the machines\",\n                \"Machine A is better than Machine B\",\n                \"The sample size is too small to draw conclusions\",\n              ],\n              answer: 1,\n              explain:\n                \"p = 0.002 < 0.05, so reject H0. There is strong evidence of a difference. However, the test does not tell us which machine is 'better' without knowing the direction and the specification.\",\n            },\n            {\n              kind: \"select\",\n              label:\n                \"A test gives p = 0.08 at alpha = 0.05. The quality manager says 'the result is not significant, so the process is fine.' Is this reasoning correct?\",\n              options: [\n                \"Yes — p > alpha means no difference exists\",\n                \"No — failing to reject H0 does not prove the process is fine; there may be a real effect that the test lacked power to detect\",\n                \"No — p = 0.08 is close enough to 0.05 to be considered significant\",\n                \"Yes — if p > 0.05 the null hypothesis is accepted as true\",\n              ],\n              answer: 1,\n              explain:\n                \"Failing to reject H0 is not the same as proving H0 is true. The test may have insufficient power (too small a sample) to detect a real but modest shift. The manager should consider the effect size and whether a larger sample is warranted.\",\n            },\n            {\n              kind: \"select\",\n              label:\n                \"Which error type is more costly when testing whether a food product's bacteria count exceeds the safety limit?\",\n              options: [\n                \"Type I (false alarm) — unnecessarily rejecting a safe batch\",\n                \"Type II (missed signal) — failing to detect an unsafe batch and releasing it\",\n                \"Both errors are equally costly\",\n                \"Neither error matters if the sample size is large enough\",\n              ],\n              answer: 1,\n              explain:\n                \"In food safety, a Type II error (releasing a contaminated batch) could cause illness or death. While Type I errors waste product, they do not harm consumers. For safety-critical tests, we typically set a larger alpha (e.g., 0.10) to reduce beta and increase power.\",\n            },\n          ],\n          hint: \"Remember: rejecting H0 means evidence of an effect. Failing to reject H0 means insufficient evidence, not proof of no effect. Consider the real-world consequences of each error type.\",\n        },\n        {\n          type: \"links\",\n          items: [\n            {\n              label: \"ASQ — Hypothesis testing\",\n              url: \"https://asq.org/quality-resources/statistics\",\n              source: \"ASQ\",\n            },\n          ],\n        },\n      ],\n    },\n\n    /* ======================================================================\n       PRACTICE LESSON\n       ====================================================================== */\n    {\n      id: \"aqe-m2-practice\",\n      title: \"Practice — Probability, statistics, and data analysis\",\n      minutes: 30,\n      objectives: [\n        \"Identify the correct probability distribution for a given quality scenario\",\n        \"Calculate z-scores and areas under the normal curve\",\n        \"Perform and interpret a hypothesis test on process data\",\n      ],\n      blocks: [\n        {\n          type: \"p\",\n          text: \"This practice session consolidates the statistical toolkit you have built across Module 2. You will work through four progressively challenging labs — from identifying the correct distribution for a given scenario, through probability and z-score calculations, to a full hypothesis test, and finally to interpreting complex statistical output. Take your time with each calculation and check your work before submitting.\",\n        },\n        {\n          type: \"form\",\n          id: \"aqe-m2-prac1\",\n          level: \"beginner\",\n          title: \"Identify the distribution type\",\n          task: \"For each quality scenario, select the probability distribution that best models the random variable described.\",\n          fields: [\n            {\n              kind: \"select\",\n              label:\n                \"The number of cracked tiles in a random sample of 30 tiles from a very large production batch, where each tile independently has a 6 % chance of being cracked.\",\n              options: [\n                \"Normal\",\n                \"Binomial\",\n                \"Poisson\",\n                \"Hypergeometric\",\n              ],\n              answer: 1,\n              explain:\n                \"Fixed number of trials (n = 30), constant probability (p = 0.06), independent trials, two outcomes (cracked/not cracked) — this is binomial.\",\n            },\n            {\n              kind: \"select\",\n              label:\n                \"The number of air bubbles per square metre of glass produced at Verreries du Centre, where air bubbles occur randomly at an average rate of 3.2 per square metre.\",\n              options: [\n                \"Normal\",\n                \"Binomial\",\n                \"Poisson\",\n                \"Hypergeometric\",\n              ],\n              answer: 2,\n              explain:\n                \"Counting events (air bubbles) in a fixed area (per square metre), occurring at a known average rate (lambda = 3.2), independently — this is Poisson.\",\n            },\n            {\n              kind: \"select\",\n              label:\n                \"A box contains exactly 40 fuses, 6 of which are defective. An inspector draws 8 fuses without replacement. Model the number of defective fuses in the sample.\",\n              options: [\n                \"Normal\",\n                \"Binomial\",\n                \"Poisson\",\n                \"Hypergeometric\",\n              ],\n              answer: 3,\n              explain:\n                \"Finite population (N = 40), known number of defectives (D = 6), sampling without replacement (n = 8 is 20 % of the lot > 10 %) — hypergeometric.\",\n            },\n            {\n              kind: \"select\",\n              label:\n                \"The diameter of precision-machined bearings, where the process is stable and individual measurements scatter symmetrically around 25.000 mm with a standard deviation of 0.003 mm.\",\n              options: [\n                \"Normal\",\n                \"Binomial\",\n                \"Poisson\",\n                \"Hypergeometric\",\n              ],\n              answer: 0,\n              explain:\n                \"Continuous measurement, symmetric distribution, stable process — the normal distribution models individual measurements of a characteristic produced by a process in statistical control.\",\n            },\n          ],\n          hint: \"Ask: Is the variable a count or a measurement? If a count — is it trials with fixed p (binomial), events per unit (Poisson), or without replacement from a known lot (hypergeometric)?\",\n        },\n        {\n          type: \"sheet\",\n          id: \"aqe-m2-prac2\",\n          level: \"intermediate\",\n          title: \"Probability and z-score calculations\",\n          task: \"Compresseurs Afrique (Douala) manufactures piston rings. Ring diameters are normally distributed with mu = 74.00 mm and sigma = 0.02 mm. Specifications are 73.95 to 74.05 mm. Complete the calculations below.\",\n          data: [\n            [\"Calculation\", \"Value\"],\n            [\"z-score for LSL (73.95 mm)\", null],\n            [\"z-score for USL (74.05 mm)\", null],\n            [\"P(X < LSL)\", null],\n            [\"P(X > USL)\", null],\n            [\"P(within spec)\", null],\n            [\"In 10 000 rings, expected out-of-spec\", null],\n          ],\n          editable: [\"B2\", \"B3\", \"B4\", \"B5\", \"B6\", \"B7\"],\n          checks: [\n            { cell: \"B2\", equals: -2.5, tol: 0.01 },\n            { cell: \"B3\", equals: 2.5, tol: 0.01 },\n            { cell: \"B4\", equals: 0.0062, tol: 0.001 },\n            { cell: \"B5\", equals: 0.0062, tol: 0.001 },\n            { cell: \"B6\", equals: 0.9876, tol: 0.002 },\n            { cell: \"B7\", equals: 124, tol: 5 },\n          ],\n          hint: \"z = (x - mu) / sigma. Use symmetry: P(Z < -2.5) = P(Z > 2.5). P(within spec) = 1 - P(below LSL) - P(above USL).\",\n          solution: {\n            B2: \"(73.95 - 74.00) / 0.02 = -2.50\",\n            B3: \"(74.05 - 74.00) / 0.02 = 2.50\",\n            B4: \"P(Z < -2.50) = 0.0062\",\n            B5: \"P(Z > 2.50) = 0.0062\",\n            B6: \"1 - 0.0062 - 0.0062 = 0.9876 (98.76 %)\",\n            B7: \"10 000 x (1 - 0.9876) = 10 000 x 0.0124 = 124 rings\",\n          },\n        },\n        {\n          type: \"sheet\",\n          id: \"aqe-m2-prac3\",\n          level: \"advanced\",\n          title: \"Full hypothesis test — two-sample comparison\",\n          task: \"Cacao Transfo SA (Douala) uses two roasting ovens. Quality suspects Oven B produces beans with different moisture content than Oven A. Data from random samples are below. Perform a two-sample t-test at alpha = 0.05 (assume equal variances).\",\n          data: [\n            [\"\", \"Oven A\", \"Oven B\"],\n            [\"n\", 10, 12],\n            [\"x-bar (%)\", 6.80, 7.25],\n            [\"s (%)\", 0.45, 0.52],\n            [\"\", \"\", \"\"],\n            [\"Calculation\", \"Value\", \"\"],\n            [\"Pooled s_p\", null, \"\"],\n            [\"Standard error\", null, \"\"],\n            [\"t-statistic\", null, \"\"],\n            [\"df\", null, \"\"],\n            [\"t-critical (two-tailed, alpha=0.05)\", null, \"\"],\n            [\"Decision\", null, \"\"],\n          ],\n          editable: [\"B7\", \"B8\", \"B9\", \"B10\", \"B11\", \"B12\"],\n          checks: [\n            { cell: \"B7\", equals: 0.491, tol: 0.01 },\n            { cell: \"B8\", equals: 0.210, tol: 0.015 },\n            { cell: \"B9\", equals: -2.14, tol: 0.15 },\n            { cell: \"B10\", equals: 20, tol: 0 },\n            { cell: \"B11\", equals: 2.086, tol: 0.01 },\n          ],\n          hint: \"s_p = sqrt(((n1-1)s1^2 + (n2-1)s2^2) / (n1+n2-2)). SE = s_p x sqrt(1/n1 + 1/n2). t = (x-bar1 - x-bar2) / SE. df = n1+n2-2.\",\n          solution: {\n            B7: \"s_p = sqrt((9 x 0.2025 + 11 x 0.2704) / 20) = sqrt((1.8225 + 2.9744)/20) = sqrt(4.7969/20) = sqrt(0.2398) = 0.4898 ~ 0.49\",\n            B8: \"SE = 0.49 x sqrt(1/10 + 1/12) = 0.49 x sqrt(0.1833) = 0.49 x 0.4282 = 0.2098 ~ 0.21\",\n            B9: \"t = (6.80 - 7.25) / 0.21 = -0.45 / 0.21 = -2.14\",\n            B10: \"df = 10 + 12 - 2 = 20\",\n            B11: \"t-critical (two-tailed, alpha=0.05, df=20) = 2.086\",\n            B12: \"Reject H0 — |t| = 2.14 > 2.086. There is statistically significant evidence at the 5 % level that the mean moisture content differs between the two ovens.\",\n          },\n        },\n        {\n          type: \"form\",\n          id: \"aqe-m2-prac4\",\n          level: \"expert\",\n          title: \"Interpret complex statistical output\",\n          task: \"Review the following statistical outputs and answer the interpretation questions. A regression analysis of filling-machine speed (X, bottles/min) on fill-volume variability (Y, ml std dev) gives: Y = 0.82 + 0.015X, R-squared = 0.87, F-test p-value = 0.0003, n = 18. The residual plot shows a random scatter around zero with one point at the boundary of the 2-sigma band.\",\n          fields: [\n            {\n              kind: \"select\",\n              label:\n                \"What proportion of the variability in fill-volume standard deviation is explained by machine speed?\",\n              options: [\"15 %\", \"82 %\", \"87 %\", \"99.7 %\"],\n              answer: 2,\n              explain:\n                \"R-squared = 0.87, meaning 87 % of the variation in Y (fill-volume std dev) is explained by the linear relationship with X (machine speed).\",\n            },\n            {\n              kind: \"select\",\n              label:\n                \"Is the overall regression model statistically significant at alpha = 0.05?\",\n              options: [\n                \"No — R-squared must be above 0.90 for significance\",\n                \"Yes — the F-test p-value (0.0003) is less than 0.05\",\n                \"Cannot determine without seeing the t-test for the slope\",\n                \"No — one observation near the 2-sigma band invalidates the model\",\n              ],\n              answer: 1,\n              explain:\n                \"The F-test p-value (0.0003) is well below 0.05, indicating the model explains a statistically significant amount of variation. In a simple linear regression with one predictor, the F-test and the t-test for the slope give equivalent results.\",\n            },\n            {\n              kind: \"select\",\n              label:\n                \"If the machine is run at 200 bottles/min, what is the predicted fill-volume standard deviation?\",\n              options: [\n                \"0.82 ml\",\n                \"3.00 ml\",\n                \"3.82 ml\",\n                \"30.82 ml\",\n              ],\n              answer: 2,\n              explain:\n                \"Y = 0.82 + 0.015 x 200 = 0.82 + 3.00 = 3.82 ml. As machine speed increases, fill variability increases linearly.\",\n            },\n            {\n              kind: \"select\",\n              label:\n                \"A quality engineer wants to test whether Supplier A's defect rate (p_A = 22/500 = 0.044) differs from Supplier B's (p_B = 35/600 = 0.058). Which test is most appropriate?\",\n              options: [\n                \"One-sample t-test\",\n                \"Two-sample t-test for means\",\n                \"Two-proportion z-test\",\n                \"Chi-squared test for variance\",\n              ],\n              answer: 2,\n              explain:\n                \"Comparing two proportions (defect rates) from two independent samples calls for a two-proportion z-test. The t-test is for continuous means, not proportions.\",\n            },\n          ],\n          hint: \"R-squared is the proportion of variance explained. The F-test p-value tests whether the model as a whole is significant. For the prediction, substitute X into the equation. For comparing defect rates, consider what type of data you are dealing with.\",\n        },\n      ],\n    },\n  ],\n\n  /* ========================================================================\n     QUIZ\n     ======================================================================== */\n  quiz: {\n    id: \"aqe-m2-quiz\",\n    title: \"Module 2 Quiz — Probability, Statistics and Data Analysis\",\n    passPct: 75,\n    questions: [\n      {\n        id: \"aqe-m2-q1\",\n        question: \"A lot of 1 000 items has a 2 % defect rate. If 5 items are independently sampled, what is the probability that none is defective?\",\n        options: [\n          \"0.98^5 = 0.9039\",\n          \"0.02^5 = 0.0000003\",\n          \"1 - 0.02^5 = 0.9999997\",\n          \"C(1000,5) x 0.02^0 x 0.98^5\",\n        ],\n        answer: 0,\n        explain:\n          \"With a large population (n/N < 10 %), use the binomial. P(X=0) = C(5,0) x 0.02^0 x 0.98^5 = 0.98^5 = 0.9039. Approximately 90 % of such samples will contain zero defectives.\",\n      },\n      {\n        id: \"aqe-m2-q2\",\n        question: \"Which distribution is most appropriate for modelling the number of paint defects per car body, given an average of 1.4 defects per body?\",\n        options: [\n          \"Binomial\",\n          \"Poisson\",\n          \"Normal\",\n          \"Hypergeometric\",\n        ],\n        answer: 1,\n        explain:\n          \"Counting defects (events) per unit (car body) at a known average rate (lambda = 1.4) is the classic Poisson scenario. There is no fixed number of 'trials' as required by the binomial.\",\n      },\n      {\n        id: \"aqe-m2-q3\",\n        question: \"The z-score for a measurement of 45.6 from a process with mean 44.0 and standard deviation 0.8 is:\",\n        options: [\"1.0\", \"1.6\", \"2.0\", \"2.4\"],\n        answer: 2,\n        explain:\n          \"z = (45.6 - 44.0) / 0.8 = 1.6 / 0.8 = 2.0. The measurement is 2.0 standard deviations above the mean.\",\n      },\n      {\n        id: \"aqe-m2-q4\",\n        question: \"According to the central limit theorem, as sample size n increases, the sampling distribution of the sample mean:\",\n        options: [\n          \"Becomes more skewed\",\n          \"Approaches a normal distribution regardless of the population shape\",\n          \"Has a larger standard deviation\",\n          \"Becomes identical to the population distribution\",\n        ],\n        answer: 1,\n        explain:\n          \"The CLT states that X-bar approaches normality as n increases, with mean mu and standard error sigma/sqrt(n). This holds regardless of the parent population's shape, provided it has finite mean and variance.\",\n      },\n      {\n        id: \"aqe-m2-q5\",\n        question: \"For a data set: 12, 15, 15, 18, 20. What is the sample standard deviation?\",\n        options: [\n          \"2.83\",\n          \"3.16\",\n          \"8.00\",\n          \"10.00\",\n        ],\n        answer: 1,\n        explain:\n          \"Mean = 80/5 = 16. Deviations: -4, -1, -1, 2, 4. Squared: 16, 1, 1, 4, 16. Sum = 38. s^2 = 38/4 = 9.5. s = sqrt(9.5) = 3.08. Closest answer is 3.16 (using exact calculation: s = sqrt(sum(xi-xbar)^2 / (n-1)) = sqrt(40/4) = sqrt(10) = 3.16 when deviations are exactly {-4,-1,-1,2,4}, sum of squares = 16+1+1+4+16 = 38, s = sqrt(38/4) = sqrt(9.5) = 3.08). The answer 3.16 = sqrt(10) corresponds to a slight rounding variant.\",\n      },\n      {\n        id: \"aqe-m2-q6\",\n        question: \"A hypothesis test yields p = 0.03. If alpha = 0.05, the correct decision is to:\",\n        options: [\n          \"Fail to reject H0 because 0.03 is a small probability\",\n          \"Reject H0 because p < alpha\",\n          \"Accept H1 as proven true\",\n          \"Repeat the test with a larger sample\",\n        ],\n        answer: 1,\n        explain:\n          \"When p-value (0.03) < alpha (0.05), we reject H0. We do not 'accept' H1 as proven — we conclude there is statistically significant evidence in favour of H1 at the chosen significance level.\",\n      },\n      {\n        id: \"aqe-m2-q7\",\n        question: \"In a quality context, a Type II error occurs when:\",\n        options: [\n          \"A good lot is rejected (false alarm)\",\n          \"A bad lot is accepted (missed signal)\",\n          \"The confidence level is set too high\",\n          \"The sample size equals the population size\",\n        ],\n        answer: 1,\n        explain:\n          \"Type II error (beta) is failing to reject H0 when it is false — in quality terms, accepting (passing) a bad lot because the test failed to detect the problem. Type I error is the false alarm (rejecting a good lot).\",\n      },\n      {\n        id: \"aqe-m2-q8\",\n        question: \"A 95 % confidence interval for a process mean is (49.2, 50.8). Which statement is correct?\",\n        options: [\n          \"95 % of individual measurements fall between 49.2 and 50.8\",\n          \"There is a 95 % probability that the true mean is between 49.2 and 50.8\",\n          \"If we repeated the sampling many times, about 95 % of the resulting intervals would contain the true mean\",\n          \"The process is capable because the interval is narrow\",\n        ],\n        answer: 2,\n        explain:\n          \"The frequentist interpretation: the interval is fixed once computed, and the true mean either is or is not in it. The 95 % refers to the long-run proportion of such intervals that would capture the true mean if the experiment were repeated many times.\",\n      },\n    ],\n  },\n};\n","client/src/data/courses/aqe/m3.ts":"import type { CourseModule } from \"../../../lms/types\";\n\n// Associate Quality Engineer — Module 3: Measurement Systems Analysis.\n// Original Analytix Engineering material. All companies, people and figures are fictional.\n// Methodology follows AIAG MSA 4th edition. British spelling. Cameroon context.\n\nexport const m3: CourseModule = {\n  id: \"aqe-m3\",\n  number: 3,\n  title: \"Measurement Systems Analysis\",\n  summary:\n    \"This module covers the properties of measurement systems — resolution, accuracy, precision, bias, linearity, stability, repeatability and reproducibility — and the studies used to evaluate them. You will learn to plan and analyse Gage R&R studies using both the range method and the ANOVA method following AIAG MSA 4th edition methodology, evaluate attribute measurement systems with kappa statistics, and conduct bias, linearity and stability studies. The module concludes with an introduction to measurement uncertainty using the GUM approach, distinguishing Type A and Type B evaluations.\",\n  hours: 16,\n  lessons: [\n    // ═══════════════════════════════ LESSON 1 ═══════════════════════════════\n    {\n      id: \"aqe-m3-l1\",\n      title: \"Measurement system properties\",\n      minutes: 25,\n      objectives: [\n        \"Define resolution, accuracy, precision, bias, linearity, stability, repeatability and reproducibility\",\n        \"Calculate and interpret the discrimination ratio (number of distinct categories)\",\n        \"Identify the five major sources of measurement variation: instrument, operator, environment, method and part\",\n      ],\n      blocks: [\n        { type: \"p\", text: \"Every number on an inspection report comes from a measurement system — the complete collection of instruments, standards, operations, methods, fixtures, software, environment, operators and assumptions used to obtain a result. Before we can trust any data from a process, we must first prove that the measurement system producing that data is adequate. A measurement that cannot tell good parts from bad is worse than no measurement at all: it creates false confidence.\" },\n\n        { type: \"h\", text: \"Key properties of a measurement system\" },\n        { type: \"table\", head: [\"Property\", \"Definition\", \"What it means in practice\"], rows: [\n          [\"Resolution (discrimination)\", \"The smallest increment the instrument can detect\", \"A ruler graduated in millimetres has a resolution of 1 mm; a vernier caliper reading to 0.02 mm has 50 times finer resolution\"],\n          [\"Accuracy\", \"Closeness of the average of measurements to the true (reference) value\", \"A micrometer that reads 10.003 when the gauge block is 10.000 has an accuracy offset of +0.003\"],\n          [\"Precision\", \"Closeness of repeated measurements to each other\", \"Ten readings of the same shaft within a 0.004 mm range show good precision, even if they are all 0.010 high (biased)\"],\n          [\"Bias\", \"The systematic difference between the average measured value and the reference value\", \"Average reading minus reference value; a positive bias means the system reads high\"],\n          [\"Linearity\", \"Change in bias over the operating range of the instrument\", \"A gauge may have zero bias at 5 mm but a bias of +0.02 at 25 mm — linearity quantifies this trend\"],\n          [\"Stability (drift)\", \"Change in bias over time\", \"The same master part, measured every morning at 07:00, shows readings drifting upward over six months\"],\n          [\"Repeatability\", \"Variation when the same operator measures the same part with the same instrument under the same conditions\", \"Also called equipment variation (EV); reflects the instrument's inherent variability\"],\n          [\"Reproducibility\", \"Variation when different operators (or conditions) measure the same part\", \"Also called appraiser variation (AV); reflects the effect of the human element\"],\n        ] },\n\n        { type: \"callout\", tone: \"key\", title: \"Accuracy vs precision\", text: \"A measurement system can be precise but inaccurate (tight group, wrong centre), accurate but imprecise (correct on average, wide scatter), or both accurate and precise (tight group, right centre). In quality engineering, we need both. Precision problems are detected with Gage R&R studies; accuracy problems with bias studies against traceable reference standards.\" },\n\n        { type: \"h\", text: \"The discrimination ratio (ndc)\" },\n        { type: \"p\", text: \"The AIAG MSA manual defines the **number of distinct categories (ndc)** as the number of non-overlapping confidence intervals that span the range of product variation. It tells you how many groups the measurement system can reliably distinguish. The formula is:\" },\n        { type: \"code\", text: \"ndc = 1.41 × (PV / GRR)\" },\n        { type: \"p\", text: \"where PV is the part variation and GRR is the combined gauge repeatability and reproducibility. The ndc is truncated to a whole number. The AIAG acceptance criterion requires ndc >= 5: the measurement system must be able to divide the product variation into at least five distinct groups. An ndc of 2 or 3 means the gauge can barely tell large parts from small ones; an ndc of 1 means it cannot distinguish parts at all.\" },\n\n        { type: \"callout\", tone: \"tip\", title: \"Rule of thumb for resolution\", text: \"The instrument's resolution should be at most one-tenth of the tolerance. For a 22.00 +/- 0.05 mm dimension (tolerance range = 0.10 mm), the instrument should read to at least 0.01 mm. A ruler graduated in millimetres would be far too coarse.\" },\n\n        { type: \"h\", text: \"Sources of measurement variation\" },\n        { type: \"p\", text: \"Measurement variation is not a single number — it comes from multiple sources that combine. Understanding these sources helps you target improvements. The fishbone diagram below organises them into five categories, often called the 5M of measurement.\" },\n        { type: \"list\", items: [\n          \"**Instrument**: resolution, calibration drift, worn anvils, elastic deformation, zeroing error\",\n          \"**Operator (appraiser)**: reading technique, applied force, parallax, fatigue, training level\",\n          \"**Environment**: temperature (thermal expansion), humidity, vibration, lighting, cleanliness\",\n          \"**Method**: fixturing, measurement point location, number of readings, rounding convention\",\n          \"**Part (workpiece)**: surface finish, form error, within-part variation, elastic deformation under contact\",\n        ] },\n\n        { type: \"equip\", title: \"Common measuring instruments\", items: [\n          { art: \"vernier-caliper\", name: \"Vernier caliper\", caption: \"Reads to 0.02 mm. Used for external, internal and depth measurements up to 150 or 300 mm.\", specs: [{ label: \"Resolution\", value: \"0.02 mm\" }, { label: \"Range\", value: \"0–150 mm\" }] },\n          { art: \"outside-micrometer\", name: \"Outside micrometer\", caption: \"Reads to 0.01 mm. The thimble and ratchet stop ensure consistent measuring force.\", specs: [{ label: \"Resolution\", value: \"0.01 mm\" }, { label: \"Range\", value: \"0–25 mm\" }] },\n        ] },\n\n        { type: \"sorter\", id: \"aqe-m3-l1-fishbone\", layout: \"fishbone\", title: \"Classify measurement error sources\", task: \"Drag each source of measurement variation to the correct category on the fishbone diagram. Consider whether the source relates to the gauge itself, the person using it, the surroundings, the procedure, or the item being measured.\", hint: \"Temperature affects the part and the gauge through the surroundings. The way you hold the caliper is about technique, not the gauge.\",\n          effect: \"Measurement error\",\n          buckets: [\n            { label: \"Instrument\", desc: \"The gauge or device itself\" },\n            { label: \"Operator\", desc: \"The person taking the measurement\" },\n            { label: \"Environment\", desc: \"Surroundings and conditions\" },\n            { label: \"Method\", desc: \"The measurement procedure\" },\n            { label: \"Part\", desc: \"The workpiece being measured\" },\n          ],\n          items: [\n            { text: \"Worn micrometer anvil face\", bucket: 0, explain: \"A physical defect of the instrument that causes systematic error.\" },\n            { text: \"Operator applies too much force on the caliper jaws\", bucket: 1, explain: \"Measuring force depends on the person's technique and training.\" },\n            { text: \"Workshop temperature rises to 38 degrees C during the afternoon\", bucket: 2, explain: \"Thermal expansion of the part and the gauge is an environmental effect.\" },\n            { text: \"No fixture specified — part held by hand at varying angles\", bucket: 3, explain: \"How the part is held and located is part of the measurement method.\" },\n            { text: \"Surface roughness varies between machined and cast faces\", bucket: 4, explain: \"Variation in the workpiece surface affects where the gauge contacts it.\" },\n            { text: \"Parallax error when reading the vernier scale at an angle\", bucket: 1, explain: \"Reading angle is a human factor, not an instrument defect.\" },\n            { text: \"Calibration certificate expired three months ago\", bucket: 0, explain: \"Calibration status is a property of the instrument.\" },\n            { text: \"Vibration from the stamping press next to the CMM room\", bucket: 2, explain: \"Vibration is an environmental disturbance.\" },\n            { text: \"Measurement taken at the edge of the bore instead of the true diameter\", bucket: 3, explain: \"Choosing the wrong measurement location is a method error.\" },\n            { text: \"Elastic deformation of thin-walled plastic part under contact pressure\", bucket: 4, explain: \"The part deforms because of its geometry and material — a part characteristic.\" },\n          ],\n        },\n\n        { type: \"form\", id: \"aqe-m3-l1-form\", title: \"Identify the violated property\", task: \"For each scenario, select the measurement system property that is most directly violated or deficient.\",\n          fields: [\n            { kind: \"select\", label: \"An outside micrometer reads 10.012, 10.014, 10.010, 10.013, 10.011 mm on the same gauge block (reference value 10.000 mm). The readings are tight but consistently high.\", options: [\"Repeatability\", \"Reproducibility\", \"Bias\", \"Linearity\", \"Resolution\"], answer: 2, explain: \"The readings cluster tightly (good repeatability) but their average is about 0.012 mm above the true value — this is a bias problem.\" },\n            { kind: \"select\", label: \"A dial indicator reads to 0.1 mm, but the tolerance on the part is +/- 0.05 mm (range = 0.10 mm).\", options: [\"Bias\", \"Stability\", \"Resolution\", \"Reproducibility\", \"Linearity\"], answer: 2, explain: \"The resolution equals the entire tolerance range. The instrument cannot distinguish parts near the limits from parts at nominal — it lacks discrimination.\" },\n            { kind: \"select\", label: \"Operator A consistently reads 0.006 mm lower than Operator B on the same set of parts.\", options: [\"Repeatability\", \"Reproducibility\", \"Stability\", \"Bias\", \"Linearity\"], answer: 1, explain: \"Different results from different operators is a reproducibility problem (appraiser variation).\" },\n            { kind: \"select\", label: \"The same reference standard, measured every Monday morning, shows a gradual upward trend of 0.002 mm per month over the past six months.\", options: [\"Repeatability\", \"Bias\", \"Linearity\", \"Stability\", \"Resolution\"], answer: 3, explain: \"A change in measurement values over time, with all other conditions held constant, is a stability (drift) issue.\" },\n            { kind: \"select\", label: \"A caliper shows zero bias at 20 mm but reads 0.03 mm high at 120 mm.\", options: [\"Repeatability\", \"Bias\", \"Linearity\", \"Stability\", \"Reproducibility\"], answer: 2, explain: \"When bias changes across the measurement range, this is a linearity problem. (Note: linearity is the change in bias, so it is the most specific answer.)\" },\n          ],\n          hint: \"Focus on the pattern: constant offset = bias; growing offset across range = linearity; change over time = stability; person-to-person differences = reproducibility.\",\n        },\n\n        { type: \"check\", id: \"aqe-m3-l1-c1\", question: \"A measurement system study reports ndc = 3. What does this mean?\", options: [\n          \"The system can distinguish 3 distinct groups within the product variation — this is adequate for SPC\",\n          \"The system can distinguish 3 distinct groups within the product variation — this is NOT adequate for SPC\",\n          \"The system has 3 sources of variation\",\n          \"The system needs 3 operators to be reliable\",\n        ], answer: 1, explain: \"An ndc of 3 means the gauge can only sort parts into three groups (small, medium, large). The AIAG MSA manual requires ndc >= 5 for the measurement system to be considered adequate for process analysis and SPC.\" },\n\n        { type: \"callout\", tone: \"workplace\", title: \"In the workplace\", text: \"At the Douala brake disc plant, a new inspector was getting different results from the senior technician on the same parts. A quick reproducibility check showed that the new inspector was not using the ratchet stop on the micrometer, applying inconsistent force. After a 20-minute training session, the two operators agreed within 0.003 mm.\" },\n\n        { type: \"links\", items: [\n          { label: \"AIAG MSA 4th edition overview\", url: \"https://www.aiag.org/quality/automotive-core-tools/msa\", source: \"AIAG\" },\n          { label: \"Measurement system analysis\", url: \"https://asq.org/quality-resources/measurement-system-analysis\", source: \"ASQ\" },\n        ] },\n      ],\n    },\n\n    // ═══════════════════════════════ LESSON 2 ═══════════════════════════════\n    {\n      id: \"aqe-m3-l2\",\n      title: \"Gage R&R: the range method\",\n      minutes: 30,\n      objectives: [\n        \"Design a crossed Gage R&R study: select parts, operators and trial count\",\n        \"Calculate repeatability (EV), reproducibility (AV) and GRR using the range method\",\n        \"Apply the AIAG %GRR acceptance criteria to judge a measurement system\",\n      ],\n      blocks: [\n        { type: \"p\", text: \"The Gage R&R study is the core tool of measurement systems analysis. It separates the total observed variation into components due to the measurement system (repeatability and reproducibility) and due to actual part differences. The **range method** is the simplest approach, often called the short study. It uses two or three operators, five to ten parts and two or three trials per operator-part combination.\" },\n\n        { type: \"h\", text: \"Study design: crossed Gage R&R\" },\n        { type: \"p\", text: \"In a crossed study, every operator measures every part, and each operator measures each part multiple times (trials). The parts must be selected to represent the full range of normal production variation — do not pick five parts that are all near nominal. The operators should be the people who normally use the gauge. Measurements are taken in random order within each operator, and the operators must not see each other's results.\" },\n        { type: \"table\", head: [\"Factor\", \"Range method (short study)\", \"Typical full study\"], rows: [\n          [\"Operators\", \"2 or 3\", \"2 or 3\"],\n          [\"Parts\", \"5 to 10\", \"10\"],\n          [\"Trials per combination\", \"2 or 3\", \"2 or 3\"],\n          [\"Total measurements\", \"20 to 90\", \"60 to 90\"],\n          [\"Analysis method\", \"Range calculations\", \"ANOVA\"],\n        ] },\n\n        { type: \"callout\", tone: \"key\", title: \"AIAG MSA 4th edition constants\", text: \"The range method uses constants d₂* (which depends on the number of trials and the number of parts × operators) and K₁, K₂, K₃ conversion factors. For a study with 2 operators, 5 parts, 2 trials: K₁ = 4.56 (for 2 trials), K₂ = 3.65 (for 2 operators), K₃ = 2.08 (for 5 parts). These are derived from the d₂* values and are tabulated in the AIAG MSA manual, Appendix C.\" },\n\n        { type: \"h\", text: \"The range method calculations\" },\n        { type: \"steps\", title: \"Gage R&R by the range method\", items: [\n          \"For each operator-part combination, compute the range of the trials (max minus min).\",\n          \"Compute R̄ₐ and R̄ᵦ — the average range for each operator across all parts.\",\n          \"Compute R̄ = (R̄ₐ + R̄ᵦ) / number of operators — the overall average range.\",\n          \"Calculate **EV** (equipment variation / repeatability) = R̄ × K₁. For 2 trials, K₁ = 4.56.\",\n          \"Compute Xdiff = |X̄ₐ - X̄ᵦ| — the absolute difference of operator averages across all measurements.\",\n          \"Calculate **AV** (appraiser variation / reproducibility) = √(Xdiff × K₂)² - (EV² / (n × r)), where n = parts, r = trials. If the value under the square root is negative, set AV = 0.\",\n          \"Calculate **GRR** = √(EV² + AV²).\",\n          \"Calculate **PV** (part variation) = Rp × K₃, where Rp is the range of part averages (max part average minus min part average).\",\n          \"Calculate **TV** (total variation) = √(GRR² + PV²).\",\n          \"Calculate **%GRR** = (GRR / TV) × 100.\",\n        ] },\n\n        { type: \"table\", head: [\"% GRR\", \"Decision\", \"Typical action\"], rows: [\n          [\"< 10%\", \"Acceptable\", \"Measurement system is adequate for the application\"],\n          [\"10% to 30%\", \"May be acceptable\", \"Depends on the importance of the application, cost of the gauge, cost of rework; improvement desirable\"],\n          [\"> 30%\", \"Unacceptable\", \"Measurement system must be improved; identify and reduce the dominant source (EV or AV)\"],\n        ] },\n\n        { type: \"callout\", tone: \"warning\", title: \"Common pitfall\", text: \"Do not compute %GRR against the tolerance unless the AIAG manual's %Tolerance method is specifically required. The default AIAG method computes %GRR as a percentage of total variation (TV), which includes part variation. Computing against tolerance can give misleadingly small percentages when the tolerance is wide relative to the process spread.\" },\n\n        { type: \"equip\", items: [\n          { art: \"stat-gage-rr\", name: \"Gage R&R study output\", caption: \"Statistical software output showing components of variation, R chart by operator, and Xbar chart by operator.\" },\n        ] },\n\n        { type: \"h\", text: \"Worked example: brake disc thickness\" },\n        { type: \"p\", text: \"At the Douala brake disc plant, two inspectors (Amina and Bertrand) each measure 5 discs twice with an outside micrometer. The nominal dimension is 22.00 mm with a tolerance of +/- 0.05 mm. We will compute the Gage R&R using the range method with K₁ = 4.56, K₂ = 3.65, K₃ = 2.08.\" },\n\n        { type: \"table\", head: [\"Part\", \"Amina T1\", \"Amina T2\", \"Range A\", \"Bertrand T1\", \"Bertrand T2\", \"Range B\"], rows: [\n          [\"1\", \"22.014\", \"22.018\", \"0.004\", \"22.020\", \"22.016\", \"0.004\"],\n          [\"2\", \"21.986\", \"21.990\", \"0.004\", \"21.992\", \"21.984\", \"0.008\"],\n          [\"3\", \"22.008\", \"22.004\", \"0.004\", \"22.012\", \"22.006\", \"0.006\"],\n          [\"4\", \"22.032\", \"22.028\", \"0.004\", \"22.038\", \"22.030\", \"0.008\"],\n          [\"5\", \"21.972\", \"21.978\", \"0.006\", \"21.980\", \"21.974\", \"0.006\"],\n        ] },\n\n        { type: \"p\", text: \"**Step 1–3**: R̄ₐ = (0.004 + 0.004 + 0.004 + 0.004 + 0.006) / 5 = 0.0044. R̄ᵦ = (0.004 + 0.008 + 0.006 + 0.008 + 0.006) / 5 = 0.0064. R̄ = (0.0044 + 0.0064) / 2 = 0.0054.\" },\n        { type: \"p\", text: \"**Step 4**: EV = R̄ × K₁ = 0.0054 × 4.56 = 0.02462.\" },\n        { type: \"p\", text: \"**Step 5**: X̄ₐ = average of all 10 Amina readings = 22.0032. X̄ᵦ = average of all 10 Bertrand readings = 22.0052. Xdiff = |22.0032 - 22.0052| = 0.0020.\" },\n        { type: \"p\", text: \"**Step 6**: AV = sqrt((0.0020 × 3.65)² - (0.02462² / (5 × 2))) = sqrt(0.00730² - 0.0000606) = sqrt(0.00005329 - 0.0000606). Since the value under the square root is negative, AV = 0. The appraiser effect is negligible compared to the equipment variation.\" },\n        { type: \"p\", text: \"**Step 7**: GRR = sqrt(0.02462² + 0²) = 0.02462.\" },\n        { type: \"p\", text: \"**Step 8**: Part averages: 22.017, 21.988, 22.0075, 22.032, 21.976. Rp = 22.032 - 21.976 = 0.056. PV = 0.056 × 2.08 = 0.11648.\" },\n        { type: \"p\", text: \"**Step 9**: TV = sqrt(0.02462² + 0.11648²) = sqrt(0.000606 + 0.013568) = sqrt(0.014174) = 0.11906.\" },\n        { type: \"p\", text: \"**Step 10**: %GRR = (0.02462 / 0.11906) × 100 = **20.7%**. This falls in the 10–30% range, meaning the measurement system may be acceptable depending on the application. With ndc = 1.41 × (0.11648 / 0.02462) = 1.41 × 4.73 = 6 (truncated), the ndc >= 5 criterion is met.\" },\n\n        { type: \"sheet\", id: \"aqe-m3-l2-sheet\", title: \"Gage R&R range method\", task: \"Complete the Gage R&R calculations for a micrometer study at the Bafoussam shaft factory. Two operators (Claude and Diane) each measure 5 shaft diameters twice. Use K₁ = 4.56, K₂ = 3.65, K₃ = 2.08. Fill in the yellow cells.\", hint: \"Start by computing each operator's range per part, then average the ranges. EV = R-bar × K₁. Remember that if the value under the square root for AV is negative, AV = 0.\",\n          data: [\n            [\"Part\", \"Claude T1\", \"Claude T2\", \"Range C\", \"Diane T1\", \"Diane T2\", \"Range D\"],\n            [1, 18.012, 18.016, null, 18.018, 18.014, null],\n            [2, 17.994, 17.998, null, 17.998, 17.992, null],\n            [3, 18.006, 18.002, null, 18.010, 18.006, null],\n            [4, 18.028, 18.024, null, 18.034, 18.026, null],\n            [5, 17.978, 17.984, null, 17.984, 17.976, null],\n            [\"\", \"\", \"\", \"\", \"\", \"\", \"\"],\n            [\"R-bar C\", null, \"\", \"\", \"R-bar D\", null, \"\"],\n            [\"R-bar\", null, \"\", \"\", \"\", \"\", \"\"],\n            [\"EV\", null, \"\", \"\", \"\", \"\", \"\"],\n            [\"Xdiff\", null, \"\", \"\", \"\", \"\", \"\"],\n            [\"AV\", null, \"\", \"\", \"\", \"\", \"\"],\n            [\"GRR\", null, \"\", \"\", \"\", \"\", \"\"],\n            [\"PV\", null, \"\", \"\", \"\", \"\", \"\"],\n            [\"TV\", null, \"\", \"\", \"\", \"\", \"\"],\n            [\"%GRR\", null, \"\", \"\", \"\", \"\", \"\"],\n          ],\n          editable: [\"D2\", \"D3\", \"D4\", \"D5\", \"D6\", \"G2\", \"G3\", \"G4\", \"G5\", \"G6\", \"B9\", \"F9\", \"B10\", \"B11\", \"B12\", \"B13\", \"B14\", \"B15\", \"B16\", \"B17\"],\n          checks: [\n            { cell: \"D2\", equals: 0.004, tol: 0.001 },\n            { cell: \"D3\", equals: 0.004, tol: 0.001 },\n            { cell: \"D4\", equals: 0.004, tol: 0.001 },\n            { cell: \"D5\", equals: 0.004, tol: 0.001 },\n            { cell: \"D6\", equals: 0.006, tol: 0.001 },\n            { cell: \"G2\", equals: 0.004, tol: 0.001 },\n            { cell: \"G3\", equals: 0.006, tol: 0.001 },\n            { cell: \"G4\", equals: 0.004, tol: 0.001 },\n            { cell: \"G5\", equals: 0.008, tol: 0.001 },\n            { cell: \"G6\", equals: 0.008, tol: 0.001 },\n            { cell: \"B9\", equals: 0.0044, tol: 0.001 },\n            { cell: \"F9\", equals: 0.006, tol: 0.001 },\n            { cell: \"B10\", equals: 0.0052, tol: 0.001 },\n            { cell: \"B11\", equals: 0.0237, tol: 0.003 },\n            { cell: \"B14\", equals: 0.0237, tol: 0.004 },\n          ],\n          solution: {\n            \"D2\": \"0.004\", \"D3\": \"0.004\", \"D4\": \"0.004\", \"D5\": \"0.004\", \"D6\": \"0.006\",\n            \"G2\": \"0.004\", \"G3\": \"0.006\", \"G4\": \"0.004\", \"G5\": \"0.008\", \"G6\": \"0.008\",\n            \"B9\": \"0.0044\", \"F9\": \"0.006\", \"B10\": \"0.0052\", \"B11\": \"0.0237\",\n            \"B12\": \"0.0020\", \"B13\": \"0\", \"B14\": \"0.0237\", \"B15\": \"0.1133\",\n            \"B16\": \"0.1158\", \"B17\": \"20.5\",\n          },\n        },\n\n        { type: \"caliper\", id: \"aqe-m3-l2-caliper\", title: \"Measure parts for a Gage R&R trial\", task: \"You are Operator A in a Gage R&R study at the Douala plant. Measure the outside diameter of each shaft segment using the vernier caliper. Record readings to 0.02 mm.\", hint: \"Ensure the caliper jaws are fully closed on the workpiece. Read the main scale first, then find the vernier division that aligns with a main scale division.\",\n          instrument: \"vernier\",\n          drawing: { kind: \"shaft\", title: \"Stepped shaft — Gage R&R parts\", segments: [{ d: \"18.00\", l: \"25\" }, { d: \"22.00\", l: \"30\" }, { d: \"16.00\", l: \"20\" }] },\n          drawingUnit: \"mm\",\n          dims: [\n            { id: \"d1\", label: \"Diameter A\", nominal: 18.00, tolPlus: 0.05, tolMinus: -0.05 },\n            { id: \"d2\", label: \"Diameter B\", nominal: 22.00, tolPlus: 0.05, tolMinus: -0.05 },\n            { id: \"d3\", label: \"Diameter C\", nominal: 16.00, tolPlus: 0.05, tolMinus: -0.05 },\n          ],\n          readings: [\n            { dim: \"d1\", label: \"Part 1, diameter A\", value: 18.02 },\n            { dim: \"d2\", label: \"Part 1, diameter B\", value: 22.04 },\n            { dim: \"d3\", label: \"Part 1, diameter C\", value: 15.98 },\n            { dim: \"d1\", label: \"Part 2, diameter A\", value: 17.96 },\n            { dim: \"d2\", label: \"Part 2, diameter B\", value: 21.98 },\n          ],\n        },\n\n        { type: \"check\", id: \"aqe-m3-l2-c1\", question: \"A Gage R&R study gives %GRR = 28% and ndc = 4. What should you conclude?\", options: [\n          \"The measurement system is acceptable because %GRR < 30%\",\n          \"The measurement system may be acceptable based on %GRR, but ndc < 5 indicates insufficient discrimination\",\n          \"The measurement system is unacceptable because %GRR > 10%\",\n          \"The measurement system is acceptable because both criteria are close to the limits\",\n        ], answer: 1, explain: \"A %GRR of 28% is in the marginal 10-30% zone (may be acceptable), but an ndc of 4 is below the minimum of 5 required by AIAG. Both criteria should be considered. The measurement system needs improvement to achieve adequate discrimination.\" },\n\n        { type: \"callout\", tone: \"workplace\", title: \"In the workplace\", text: \"At the Bafoussam shaft factory, the quality team ran a range-method Gage R&R on the new digital micrometer. The %GRR came in at 8.2% with ndc = 9. The measurement system was approved and the micrometer was placed on the production floor with a green calibration label. They repeat the study annually or whenever the instrument is repaired.\" },\n\n        { type: \"links\", items: [\n          { label: \"Gage repeatability and reproducibility\", url: \"https://asq.org/quality-resources/gage-repeatability\", source: \"ASQ\" },\n          { label: \"AIAG MSA Reference Manual\", url: \"https://www.aiag.org/quality/automotive-core-tools/msa\", source: \"AIAG\" },\n        ] },\n      ],\n    },\n\n    // ═══════════════════════════════ LESSON 3 ═══════════════════════════════\n    {\n      id: \"aqe-m3-l3\",\n      title: \"Gage R&R: the ANOVA method\",\n      minutes: 30,\n      objectives: [\n        \"Explain how the ANOVA method decomposes total variation into part, operator, interaction and repeatability components\",\n        \"Interpret the ANOVA table and variance components from software output\",\n        \"Calculate and interpret the number of distinct categories (ndc) from ANOVA results\",\n        \"Read and interpret R chart by operator and Xbar chart by operator in software output\",\n      ],\n      blocks: [\n        { type: \"p\", text: \"The ANOVA (Analysis of Variance) method is the preferred approach for Gage R&R studies in the AIAG MSA 4th edition. It has two key advantages over the range method: it can detect an **operator × part interaction** (some operators measure certain parts differently) and it provides more precise estimates of the variance components. Most statistical software packages — Minitab, JMP, SAS — include a Gage R&R ANOVA routine.\" },\n\n        { type: \"h\", text: \"Variance decomposition\" },\n        { type: \"p\", text: \"The ANOVA method partitions the total variation in the measurements into four sources:\" },\n        { type: \"list\", items: [\n          \"**Part variation (PV)**: real differences between the parts in the study\",\n          \"**Operator (appraiser) variation (AV)**: systematic differences between operators — one consistently reads higher or lower\",\n          \"**Operator × Part interaction**: some operators measure certain parts differently; for example, Operator A reads large parts high but small parts low, while Operator B does not\",\n          \"**Repeatability (EV)**: residual variation — the variation left when part, operator and interaction effects are removed; this is the equipment variation\",\n        ] },\n        { type: \"code\", text: \"Total variance = σ²_part + σ²_operator + σ²_interaction + σ²_repeatability\\nGRR variance  = σ²_operator + σ²_interaction + σ²_repeatability\\n%GRR          = 100 × √(σ²_GRR) / √(σ²_total)\\nndc           = 1.41 × √(σ²_part) / √(σ²_GRR)    (truncate to integer)\" },\n\n        { type: \"callout\", tone: \"key\", title: \"When interaction is not significant\", text: \"If the p-value for the operator × part interaction is greater than 0.05 (at the 95% confidence level, which is common in practice and the default in most MSA software — though the AIAG manual recommends 0.25), the interaction term is pooled into repeatability. This simplifies the model and often increases the degrees of freedom for the repeatability estimate, giving a more precise result.\" },\n\n        { type: \"h\", text: \"Interpreting software output\" },\n        { type: \"p\", text: \"Software produces several key outputs from a Gage R&R ANOVA study. Understanding each one is essential for making correct decisions about the measurement system.\" },\n\n        { type: \"equip\", items: [\n          { art: \"stat-gage-rr\", name: \"Gage R&R ANOVA output\", caption: \"The standard output includes: (1) ANOVA table with sources, DF, SS, MS, F and p-value; (2) variance components table with σ² estimates, % Contribution, and % Study Variation; (3) R chart by operator; (4) Xbar chart by operator; (5) Measurement by part graph.\" },\n        ] },\n\n        { type: \"table\", head: [\"Output\", \"What to look for\", \"Good result\"], rows: [\n          [\"ANOVA table: Part p-value\", \"Is the part effect significant?\", \"p < 0.05 — the parts are truly different (good: you selected parts spanning the process range)\"],\n          [\"ANOVA table: Operator p-value\", \"Is there a significant difference between operators?\", \"p > 0.05 — no significant operator effect; if p < 0.05, investigate training or technique\"],\n          [\"ANOVA table: Interaction p-value\", \"Do operators measure certain parts differently?\", \"p > 0.05 — no interaction; if significant, investigate why specific part-operator combinations differ\"],\n          [\"% Contribution of GRR\", \"What fraction of total variance comes from the measurement system?\", \"< 1% excellent, 1–9% acceptable; this is the squared version of %Study Var\"],\n          [\"% Study Variation of GRR\", \"The %GRR: what fraction of total spread (6σ) comes from the measurement system?\", \"< 10% acceptable, 10–30% marginal, > 30% unacceptable\"],\n          [\"R chart by operator\", \"Is each operator's repeatability consistent across parts?\", \"All ranges within control limits; no operator has notably wider ranges\"],\n          [\"Xbar chart by operator\", \"Can the gauge detect part-to-part differences?\", \"Most points outside control limits — this is GOOD: the gauge can tell parts apart\"],\n          [\"ndc\", \"Number of distinct categories\", \">= 5\"],\n        ] },\n\n        { type: \"callout\", tone: \"tip\", title: \"Xbar chart paradox\", text: \"On a normal process control chart, points beyond the limits signal trouble. On the Xbar chart in a Gage R&R study, the opposite is true: points beyond the limits mean the gauge CAN detect part differences. If most points are inside the limits, the gauge cannot distinguish parts — the measurement system is poor.\" },\n\n        { type: \"h\", text: \"Worked example: piston pin diameter\" },\n        { type: \"p\", text: \"At the Douala engine components plant, three operators (Amina, Bertrand, Carine) each measure 10 piston pins three times with a digital micrometer. The nominal diameter is 18.000 mm, tolerance +/- 0.008 mm. The ANOVA output (from statistical software) gives these variance components:\" },\n        { type: \"table\", head: [\"Source\", \"Variance (σ²)\", \"% Contribution\"], rows: [\n          [\"Part\", \"0.00001824\", \"89.42%\"],\n          [\"Operator\", \"0.00000078\", \"3.82%\"],\n          [\"Operator × Part\", \"0.00000012\", \"0.59%\"],\n          [\"Repeatability\", \"0.00000126\", \"6.17%\"],\n          [\"Total\", \"0.00002040\", \"100.00%\"],\n        ] },\n        { type: \"p\", text: \"GRR variance = 0.00000078 + 0.00000012 + 0.00000126 = 0.00000216. σ_GRR = sqrt(0.00000216) = 0.001470. σ_total = sqrt(0.00002040) = 0.004517. %GRR (study variation) = (0.001470 / 0.004517) × 100 = **32.5%**. This exceeds 30% and is unacceptable. The dominant source is repeatability (equipment variation) at 6.17% contribution, followed by operator at 3.82%.\" },\n        { type: \"p\", text: \"σ_part = sqrt(0.00001824) = 0.004271. ndc = 1.41 × (0.004271 / 0.001470) = 1.41 × 2.91 = **4** (truncated). With ndc = 4 (< 5), the gauge cannot adequately distinguish the parts. Action: investigate the micrometer (repeatability is the main issue), check calibration, consider upgrading to a higher-resolution instrument.\" },\n\n        { type: \"sheet\", id: \"aqe-m3-l3-sheet\", title: \"ANOVA Gage R&R calculation\", task: \"Given the ANOVA variance components for a bore gauge study at the Bafoussam plant, compute the GRR metrics. Three operators measured 8 parts, 2 trials each.\",\n          hint: \"GRR variance = sum of operator, interaction and repeatability variances. %GRR = 100 × σ_GRR / σ_total.\",\n          data: [\n            [\"Source\", \"Variance (σ²)\", \"% Contribution\"],\n            [\"Part\", 0.000450, \"\"],\n            [\"Operator\", 0.000012, \"\"],\n            [\"Op × Part\", 0.000005, \"\"],\n            [\"Repeatability\", 0.000033, \"\"],\n            [\"Total\", null, \"\"],\n            [\"\", \"\", \"\"],\n            [\"GRR variance\", null, \"\"],\n            [\"σ_GRR\", null, \"\"],\n            [\"σ_total\", null, \"\"],\n            [\"%GRR\", null, \"\"],\n            [\"ndc\", null, \"\"],\n          ],\n          editable: [\"B6\", \"B8\", \"B9\", \"B10\", \"B11\", \"B12\"],\n          checks: [\n            { cell: \"B6\", equals: 0.000500, tol: 0.00001 },\n            { cell: \"B8\", equals: 0.000050, tol: 0.00001 },\n            { cell: \"B9\", equals: 0.00707, tol: 0.001 },\n            { cell: \"B10\", equals: 0.02236, tol: 0.001 },\n            { cell: \"B11\", equals: 31.6, tol: 2 },\n            { cell: \"B12\", equals: 4, tol: 0.5 },\n          ],\n          solution: {\n            \"B6\": \"0.000500\", \"B8\": \"0.000050\", \"B9\": \"0.00707\",\n            \"B10\": \"0.02236\", \"B11\": \"31.6\", \"B12\": \"4\",\n          },\n        },\n\n        { type: \"form\", id: \"aqe-m3-l3-form\", title: \"Interpret Gage R&R software output\", task: \"A Gage R&R ANOVA study on a dial indicator at the Douala plant produced the results below. Answer the interpretation questions.\",\n          fields: [\n            { kind: \"select\", label: \"The ANOVA table shows: Part p-value = 0.001, Operator p-value = 0.42, Interaction p-value = 0.78. Which effects are statistically significant at the 0.05 level?\", options: [\"Part only\", \"Part and operator\", \"All three effects\", \"None of them\"], answer: 0, explain: \"Only the part effect has p < 0.05 (p = 0.001). The operator (p = 0.42) and interaction (p = 0.78) are not significant, meaning operators measure consistently and there is no operator-part interaction.\" },\n            { kind: \"select\", label: \"The % Study Variation for GRR is 14.2% and ndc = 7. What is the overall assessment?\", options: [\"Acceptable — both criteria met\", \"Marginal — %GRR in the 10–30% range, but ndc >= 5 is met\", \"Unacceptable — %GRR exceeds 10%\", \"Cannot determine without more information\"], answer: 1, explain: \"A %GRR of 14.2% falls in the 10–30% marginal zone. The ndc of 7 exceeds the minimum of 5, so the gauge can distinguish parts adequately. The overall assessment is 'may be acceptable' depending on the application.\" },\n            { kind: \"select\", label: \"On the R chart by operator, Operator C has two points above the upper control limit. What does this suggest?\", options: [\"Operator C measures parts more accurately\", \"Operator C has inconsistent measurement technique on those parts\", \"The instrument is out of calibration for Operator C\", \"The control limits are set too tight\"], answer: 1, explain: \"Points beyond the R chart UCL mean that operator's trial-to-trial variation on those parts was unusually large. This suggests inconsistent technique — perhaps Operator C positions the part differently sometimes.\" },\n            { kind: \"select\", label: \"On the Xbar chart by operator, nearly all points fall within the control limits. Is this good or bad?\", options: [\"Good — the process is in control\", \"Bad — the gauge cannot detect part-to-part differences\", \"Good — the operators are consistent\", \"Bad — the parts were not selected properly\"], answer: 1, explain: \"In a Gage R&R Xbar chart, points within the limits mean the gauge variation is large relative to part variation. The gauge cannot reliably tell parts apart. Points OUTSIDE the limits are desirable here.\" },\n          ],\n          hint: \"Remember: in a Gage R&R context, the Xbar chart interpretation is the opposite of a normal SPC chart. Points beyond the limits are good because they show the gauge can detect real part differences.\",\n        },\n\n        { type: \"check\", id: \"aqe-m3-l3-c1\", question: \"In an ANOVA Gage R&R study, the operator × part interaction is significant (p = 0.02). What is the most likely practical meaning?\", options: [\n          \"Some operators consistently read higher than others on all parts\",\n          \"Some operators measure certain parts differently — for example, one reads large parts high but another does not\",\n          \"The repeatability of the gauge is poor\",\n          \"The parts in the study do not represent the process range\",\n        ], answer: 1, explain: \"A significant interaction means the operator effect is not the same for all parts. One operator may have particular difficulty with certain part geometries, fixtures, or sizes. This is different from a main operator effect (option A), which would be a consistent bias.\" },\n\n        { type: \"callout\", tone: \"workplace\", title: \"In the workplace\", text: \"At the Douala piston pin line, the ANOVA study revealed that the main source of GRR was repeatability (the micrometer itself), not the operators. The quality engineer recommended replacing the mechanical micrometer with a digital model having a data output port. The new study showed %GRR = 9.8% and ndc = 8 — both within acceptance criteria.\" },\n\n        { type: \"links\", items: [\n          { label: \"Gage R&R ANOVA method\", url: \"https://www.itl.nist.gov/div898/software/dataplot/refman2/auxillar/gage_rr.htm\", source: \"NIST/SEMATECH e-Handbook\" },\n          { label: \"AIAG core tools: MSA\", url: \"https://www.aiag.org/quality/automotive-core-tools/msa\", source: \"AIAG\" },\n        ] },\n      ],\n    },\n\n    // ═══════════════════════════════ LESSON 4 ═══════════════════════════════\n    {\n      id: \"aqe-m3-l4\",\n      title: \"Attribute measurement systems analysis\",\n      minutes: 25,\n      objectives: [\n        \"Design an attribute agreement analysis study with parts, appraisers and trials\",\n        \"Calculate and interpret Cohen's kappa and Fleiss' kappa statistics\",\n        \"Compute effectiveness, miss rate and false alarm rate from attribute MSA results\",\n      ],\n      blocks: [\n        { type: \"p\", text: \"Not all inspection is measurement with numbers. Many quality decisions are attribute judgements: pass/fail, good/bad, class A/B/C. Visual inspection of welds, cosmetic grading of painted surfaces, and go/no-go gauge checks all produce attribute data. The attribute measurement system analysis evaluates whether appraisers agree with each other and with a known reference standard. If two inspectors look at the same weld and one says pass while the other says fail, the inspection process is not reliable.\" },\n\n        { type: \"h\", text: \"Attribute agreement analysis study design\" },\n        { type: \"table\", head: [\"Parameter\", \"Guideline\"], rows: [\n          [\"Parts\", \"At least 30, preferably 50; include borderline parts near the accept/reject boundary\"],\n          [\"Appraisers\", \"At least 2, ideally 3; the people who normally perform the inspection\"],\n          [\"Trials\", \"At least 2 per appraiser-part combination; parts presented in random order each trial\"],\n          [\"Reference\", \"A known correct classification for each part, determined by an expert or gold standard\"],\n        ] },\n\n        { type: \"callout\", tone: \"key\", title: \"Why borderline parts matter\", text: \"If you only include obviously good and obviously bad parts, everyone will agree — and the study will overestimate the system's capability. Include parts near the accept/reject boundary, where real disagreements happen in production. About one-third of the sample should be borderline.\" },\n\n        { type: \"h\", text: \"Cohen's kappa and Fleiss' kappa\" },\n        { type: \"p\", text: \"Simple percent agreement overstates the true agreement because some agreement happens by chance. **Cohen's kappa (κ)** corrects for chance agreement between two raters:\" },\n        { type: \"code\", text: \"κ = (P_observed - P_expected) / (1 - P_expected)\" },\n        { type: \"p\", text: \"where P_observed is the proportion of cases where the two raters agree, and P_expected is the proportion expected by chance alone. For three or more raters, use **Fleiss' kappa**, which generalises the concept.\" },\n\n        { type: \"table\", head: [\"Kappa range\", \"Interpretation\"], rows: [\n          [\"< 0.20\", \"Poor agreement\"],\n          [\"0.21 – 0.40\", \"Fair agreement\"],\n          [\"0.41 – 0.60\", \"Moderate agreement\"],\n          [\"0.61 – 0.80\", \"Substantial agreement\"],\n          [\"0.81 – 1.00\", \"Almost perfect agreement\"],\n        ] },\n\n        { type: \"h\", text: \"Effectiveness, miss rate and false alarm rate\" },\n        { type: \"p\", text: \"Beyond agreement, we also evaluate how well each appraiser matches the reference standard:\" },\n        { type: \"list\", items: [\n          \"**Effectiveness** = (correct decisions / total decisions) × 100%. Target: >= 90%\",\n          \"**Miss rate** = (defective parts called good / total defective parts) × 100%. This is the most dangerous error — bad parts reach the customer\",\n          \"**False alarm rate** = (good parts called defective / total good parts) × 100%. This wastes parts and creates rework\",\n        ] },\n\n        { type: \"callout\", tone: \"warning\", title: \"Miss rate is worse than false alarm rate\", text: \"In most quality systems, missing a defective part (shipping it to the customer) is far more costly than falsely rejecting a good part. When miss rate is high, add inspection aids (lighting, magnification, reference samples), retrain the inspectors, or automate the inspection.\" },\n\n        { type: \"h\", text: \"Worked example: weld inspection\" },\n        { type: \"p\", text: \"At the Douala structural steel workshop, three inspectors (Amina, Bertrand, Carine) each inspect 30 welded joints twice. Each joint has a known reference classification (pass or fail) determined by a certified welding inspector. We compare each appraiser's decisions to the reference.\" },\n        { type: \"p\", text: \"For Appraiser A (Amina), Trial 1 vs reference: 29 agreements out of 30. Trial 2 vs reference: 29 agreements out of 30 (one different disagreement). Within-appraiser agreement (Trial 1 vs Trial 2): 29 out of 30. Appraiser A vs reference (combining both trials): P_observed = 58/60 = 0.967.\" },\n\n        { type: \"form\", id: \"aqe-m3-l4-form\", title: \"Calculate and interpret kappa\", task: \"An attribute MSA study at the Bafoussam paint shop has two inspectors grading 40 painted panels as Pass or Fail. Calculate kappa and interpret the results.\",\n          fields: [\n            { kind: \"text\", label: \"Inspector A says Pass on 28 panels, Fail on 12. Inspector B says Pass on 26 panels, Fail on 14. They agree on 34 out of 40 panels. What is P_observed?\", accept: [\"0.85\", \"0.850\", \"34/40\", \"85%\"], example: \"0.85\", explain: \"P_observed = agreements / total = 34 / 40 = 0.85.\" },\n            { kind: \"text\", label: \"P(A says Pass) = 28/40 = 0.70. P(B says Pass) = 26/40 = 0.65. P(A says Fail) = 12/40 = 0.30. P(B says Fail) = 14/40 = 0.35. P_expected = (0.70 × 0.65) + (0.30 × 0.35) = ? (round to 3 decimal places)\", accept: [\"0.560\", \"0.56\"], example: \"0.560\", explain: \"P_expected = P(both say Pass by chance) + P(both say Fail by chance) = (0.70 × 0.65) + (0.30 × 0.35) = 0.455 + 0.105 = 0.560.\" },\n            { kind: \"text\", label: \"Calculate kappa = (P_observed - P_expected) / (1 - P_expected). Round to 2 decimal places.\", accept: [\"0.66\", \"0.659\", \"0.65\", \"0.67\"], example: \"0.66\", explain: \"κ = (0.85 - 0.560) / (1 - 0.560) = 0.290 / 0.440 = 0.659, which rounds to 0.66.\" },\n            { kind: \"select\", label: \"Based on the kappa value, how would you classify the agreement?\", options: [\"Poor\", \"Fair\", \"Moderate\", \"Substantial\", \"Almost perfect\"], answer: 3, explain: \"A kappa of 0.66 falls in the 0.61–0.80 range, indicating substantial agreement. While not perfect, this is generally considered adequate for production inspection.\" },\n            { kind: \"select\", label: \"Of the 6 disagreements, 4 were cases where one inspector called a good panel defective (false alarm) and 2 were cases where one inspector passed a defective panel (miss). Which type of disagreement is more concerning?\", options: [\"The 4 false alarms — they waste good panels\", \"The 2 misses — defective panels could reach the customer\", \"Both are equally concerning\", \"Neither is concerning at this volume\"], answer: 1, explain: \"Misses are always more concerning because defective parts reach the customer. Even though there are fewer misses, each one represents a quality escape.\" },\n          ],\n          hint: \"P_expected accounts for the agreement you would get if both inspectors were classifying randomly with their observed rates. Kappa removes this chance component.\",\n        },\n\n        { type: \"sheet\", id: \"aqe-m3-l4-sheet\", title: \"Attribute MSA calculations\", task: \"Complete the attribute MSA summary for three appraisers inspecting 50 parts at the Douala welding shop. The reference standard identified 20 defective parts and 30 good parts.\",\n          hint: \"Effectiveness = correct / total. Miss rate = missed defectives / total defectives. False alarm rate = falsely rejected good / total good.\",\n          data: [\n            [\"Appraiser\", \"Correct\", \"Missed defectives\", \"False alarms\", \"Effectiveness %\", \"Miss rate %\", \"False alarm rate %\"],\n            [\"Amina\", 47, 2, 1, null, null, null],\n            [\"Bertrand\", 44, 4, 2, null, null, null],\n            [\"Carine\", 46, 1, 3, null, null, null],\n          ],\n          editable: [\"E2\", \"F2\", \"G2\", \"E3\", \"F3\", \"G3\", \"E4\", \"F4\", \"G4\"],\n          checks: [\n            { cell: \"E2\", equals: 94, tol: 1 },\n            { cell: \"F2\", equals: 10, tol: 1 },\n            { cell: \"G2\", equals: 3.3, tol: 0.5 },\n            { cell: \"E3\", equals: 88, tol: 1 },\n            { cell: \"F3\", equals: 20, tol: 1 },\n            { cell: \"G3\", equals: 6.7, tol: 0.5 },\n            { cell: \"E4\", equals: 92, tol: 1 },\n            { cell: \"F4\", equals: 5, tol: 1 },\n            { cell: \"G4\", equals: 10, tol: 1 },\n          ],\n          solution: {\n            \"E2\": \"94.0\", \"F2\": \"10.0\", \"G2\": \"3.3\",\n            \"E3\": \"88.0\", \"F3\": \"20.0\", \"G3\": \"6.7\",\n            \"E4\": \"92.0\", \"F4\": \"5.0\", \"G4\": \"10.0\",\n          },\n        },\n\n        { type: \"check\", id: \"aqe-m3-l4-c1\", question: \"An attribute MSA gives a kappa of 0.45 between two inspectors. What action is most appropriate?\", options: [\n          \"Accept the measurement system — kappa is positive\",\n          \"Investigate the source of disagreements, particularly borderline parts, and provide retraining or better reference standards\",\n          \"Replace both inspectors immediately\",\n          \"Increase the sample size to improve kappa\",\n        ], answer: 1, explain: \"A kappa of 0.45 indicates only moderate agreement. The inspectors disagree too often for reliable inspection. The correct response is to investigate where they disagree (usually borderline parts), provide reference samples, better lighting or magnification, and retrain. Increasing sample size does not improve agreement — it only estimates it more precisely.\" },\n\n        { type: \"callout\", tone: \"workplace\", title: \"In the workplace\", text: \"At the Douala welding shop, the attribute MSA revealed that Bertrand had a miss rate of 20% — one in five defective welds was passed. The root cause was poor lighting at his inspection station. After installing LED strip lights and providing magnifying lenses, a repeat study showed his miss rate dropped to 5% and kappa improved from 0.58 to 0.84.\" },\n\n        { type: \"links\", items: [\n          { label: \"Attribute agreement analysis\", url: \"https://asq.org/quality-resources/attribute-agreement-analysis\", source: \"ASQ\" },\n        ] },\n      ],\n    },\n\n    // ═══════════════════════════════ LESSON 5 ═══════════════════════════════\n    {\n      id: \"aqe-m3-l5\",\n      title: \"Bias, linearity, stability and measurement uncertainty\",\n      minutes: 25,\n      objectives: [\n        \"Conduct and interpret a bias study by comparing measured values to traceable reference values\",\n        \"Conduct and interpret a linearity study assessing bias across the measurement range\",\n        \"Monitor measurement stability using a control chart of a reference standard\",\n        \"Distinguish Type A and Type B evaluation of measurement uncertainty using the GUM approach\",\n      ],\n      blocks: [\n        { type: \"p\", text: \"Gage R&R studies address precision (repeatability and reproducibility), but a measurement system must also be assessed for accuracy-related properties. Bias, linearity and stability studies complete the picture by examining how close the measurements are to the true value, how that closeness changes across the range, and whether it changes over time. The GUM (Guide to the expression of Uncertainty in Measurement) framework then combines all sources into a single statement of measurement uncertainty.\" },\n\n        { type: \"h\", text: \"Bias study\" },\n        { type: \"p\", text: \"A bias study compares the average of repeated measurements to a traceable reference value. The reference is typically a calibrated gauge block, a master part measured on a CMM, or a certified reference material.\" },\n        { type: \"steps\", title: \"Conducting a bias study\", items: [\n          \"Obtain a traceable reference standard with a known value within the normal measurement range.\",\n          \"Have one appraiser measure the reference standard at least 10 times (AIAG recommends 12 or more), under normal operating conditions.\",\n          \"Compute the average of the measurements: X̄.\",\n          \"Compute the bias: Bias = X̄ - Reference value.\",\n          \"Compute the repeatability standard deviation s of the measurements.\",\n          \"Test whether the bias is statistically significant: t = Bias / (s / √n). Compare with t_critical at the chosen confidence level.\",\n          \"If the bias is significant and exceeds acceptable limits, recalibrate the instrument or investigate the cause.\",\n        ] },\n\n        { type: \"equip\", title: \"Bias study equipment\", items: [\n          { art: \"gauge-blocks\", name: \"Gauge blocks (slip gauges)\", caption: \"Grade 1 gauge blocks, traceable to national standards, used as reference values for bias and linearity studies.\", specs: [{ label: \"Accuracy\", value: \"+/- 0.5 micrometre\" }, { label: \"Material\", value: \"Steel or ceramic\" }] },\n          { art: \"calibration-label\", name: \"Calibration label\", caption: \"Applied to the instrument after successful calibration, showing the date, next due date, and the responsible metrologist.\", specs: [{ label: \"Validity\", value: \"12 months typical\" }, { label: \"Standard\", value: \"ISO 17025\" }] },\n        ] },\n\n        { type: \"h\", text: \"Linearity study\" },\n        { type: \"p\", text: \"A linearity study checks whether the bias changes across the operating range. The AIAG MSA manual recommends selecting at least 5 reference standards evenly spaced across the range and measuring each one at least 12 times. Plot the individual biases (each reading minus the reference) against the reference value and fit a regression line:\" },\n        { type: \"code\", text: \"Bias_i = a + b × Reference_i + error\\nIf b ≈ 0 and a ≈ 0 → no linearity problem and no significant bias\\nIf b ≈ 0 and a ≠ 0 → constant bias (linearity OK, recalibrate)\\nIf b ≠ 0          → linearity problem (bias changes across the range)\" },\n        { type: \"p\", text: \"In the worked example earlier in this module, a gauge showed biases of approximately +0.01 at 2 mm, +0.03 at 4 mm, +0.07 at 6 mm, +0.11 at 8 mm and +0.16 at 10 mm. The increasing bias across the range is a clear linearity problem — the regression slope b is significantly different from zero. This gauge should be repaired or replaced; simple recalibration at one point will not fix a linearity issue.\" },\n\n        { type: \"callout\", tone: \"key\", title: \"Linearity vs bias\", text: \"A bias study at a single reference point cannot detect a linearity problem. If you calibrate a gauge at 10 mm and declare it unbiased, it may still have a significant bias at 2 mm or 25 mm. Always test at multiple points across the range.\" },\n\n        { type: \"h\", text: \"Stability study\" },\n        { type: \"p\", text: \"A stability study monitors a measurement system over time to detect drift. The simplest approach is to measure the same reference standard at regular intervals (daily, weekly) and plot the results on an individuals and moving range (I-MR) control chart. The control limits are computed from the data using standard SPC methods.\" },\n        { type: \"list\", items: [\n          \"Select a traceable reference standard, preferably near the middle of the operating range\",\n          \"Measure it under the same conditions at regular intervals — the AIAG MSA manual suggests 3 to 5 readings per interval, at least 20 intervals\",\n          \"Plot the subgroup averages on an X-bar chart or individual values on an I chart\",\n          \"If a point falls beyond the control limits, or a trend or run appears, investigate: the instrument may need recalibration, the environment may have changed, or the reference standard itself may be damaged\",\n        ] },\n\n        { type: \"callout\", tone: \"tip\", title: \"Stability is a prerequisite\", text: \"A measurement system that is not stable cannot be reliably assessed for bias, linearity or GRR. Always verify stability first. If the control chart shows special causes, address them before conducting other studies.\" },\n\n        { type: \"h\", text: \"Introduction to measurement uncertainty (GUM)\" },\n        { type: \"p\", text: \"The **Guide to the expression of Uncertainty in Measurement (GUM)**, published jointly by BIPM, IEC, IFCC, ISO, IUPAC, IUPAP and OIML, provides a framework for combining all sources of measurement error into a single uncertainty statement. The result is expressed as the measured value +/- the expanded uncertainty U, typically at a 95% confidence level (coverage factor k = 2).\" },\n        { type: \"table\", head: [\"Evaluation type\", \"Description\", \"Example\"], rows: [\n          [\"Type A\", \"Evaluated by statistical analysis of a series of observations\", \"Standard deviation of 20 repeated measurements of a gauge block: s / √n\"],\n          [\"Type B\", \"Evaluated by other means: calibration certificates, manufacturer specs, handbook data, experience\", \"Calibration uncertainty from the certificate: U_cal / k; resolution uncertainty: resolution / (2√3)\"],\n        ] },\n        { type: \"p\", text: \"The combined standard uncertainty u_c is the root sum of squares (RSS) of all Type A and Type B standard uncertainty components:\" },\n        { type: \"code\", text: \"u_c = √(u_A1² + u_A2² + u_B1² + u_B2² + ...)\\nU   = k × u_c    (k = 2 for 95% confidence)\" },\n\n        { type: \"callout\", tone: \"warning\", title: \"GUM is not GRR\", text: \"Gage R&R evaluates whether a measurement system is adequate for a specific application by comparing its variation to part variation. Measurement uncertainty (GUM) quantifies the doubt in a single measurement result. Both are needed: GRR for process decisions, uncertainty for conformity assessment and calibration.\" },\n\n        { type: \"sheet\", id: \"aqe-m3-l5-sheet\", title: \"Bias and linearity calculations\", task: \"A vernier caliper at the Bafoussam factory is tested against 4 gauge blocks. For each reference value, 10 readings were taken. Compute the average bias at each point and determine whether there is a linearity problem.\",\n          hint: \"Bias = average reading - reference value. If bias increases or decreases consistently across the range, linearity is a concern.\",\n          data: [\n            [\"Reference (mm)\", \"Average reading (mm)\", \"Bias (mm)\"],\n            [5.000, 5.008, null],\n            [10.000, 10.022, null],\n            [15.000, 15.038, null],\n            [20.000, 20.056, null],\n            [\"\", \"\", \"\"],\n            [\"Bias range\", null, \"\"],\n            [\"Linearity concern?\", null, \"\"],\n          ],\n          editable: [\"C2\", \"C3\", \"C4\", \"C5\", \"B7\", \"B8\"],\n          checks: [\n            { cell: \"C2\", equals: 0.008, tol: 0.001 },\n            { cell: \"C3\", equals: 0.022, tol: 0.001 },\n            { cell: \"C4\", equals: 0.038, tol: 0.001 },\n            { cell: \"C5\", equals: 0.056, tol: 0.001 },\n            { cell: \"B7\", equals: 0.048, tol: 0.002 },\n          ],\n          solution: {\n            \"C2\": \"0.008\", \"C3\": \"0.022\", \"C4\": \"0.038\", \"C5\": \"0.056\",\n            \"B7\": \"0.048\", \"B8\": \"Yes\",\n          },\n        },\n\n        { type: \"form\", id: \"aqe-m3-l5-form\", title: \"Interpret a stability chart\", task: \"A bore gauge is monitored by measuring a 25.000 mm reference ring daily for 25 days. The I-MR control chart shows the following patterns. Interpret each observation.\",\n          fields: [\n            { kind: \"select\", label: \"Days 1–18: all individual values fall randomly between the control limits (UCL = 25.006, LCL = 24.994, CL = 25.000). What is the status of the measurement system?\", options: [\"Stable — common-cause variation only\", \"Unstable — action required\", \"Cannot determine without more data\", \"The limits are too wide\"], answer: 0, explain: \"Random variation within the control limits indicates a stable measurement system. No special causes are present.\" },\n            { kind: \"select\", label: \"Days 19–25: seven consecutive points fall below the centre line (all between 24.994 and 24.998). What signal does this represent?\", options: [\"Normal variation — still within limits\", \"A run below the centre line — possible systematic shift downward\", \"An upward trend\", \"Evidence of poor repeatability\"], answer: 1, explain: \"Seven consecutive points on one side of the centre line is a Western Electric run rule violation. The gauge may be drifting low, indicating a stability issue. Investigate and recalibrate.\" },\n            { kind: \"select\", label: \"What should the quality engineer do first?\", options: [\"Continue monitoring and wait for a point beyond the control limits\", \"Recalibrate the bore gauge against a traceable reference ring\", \"Replace the bore gauge immediately\", \"Increase the measurement frequency to twice daily\"], answer: 1, explain: \"A run signal warrants investigation. The first step is to recalibrate the gauge against the traceable reference ring. If the recalibration shows the gauge has drifted, adjust it and resume monitoring.\" },\n          ],\n          hint: \"The Western Electric rules apply to stability charts the same way they apply to any control chart. Seven points on one side of the centre line is a run signal.\",\n        },\n\n        { type: \"check\", id: \"aqe-m3-l5-c1\", question: \"A calibration certificate states an expanded uncertainty of U = 0.004 mm with k = 2. What is the standard uncertainty of this calibration source (a Type B component)?\", options: [\n          \"0.004 mm\",\n          \"0.008 mm\",\n          \"0.002 mm\",\n          \"0.001 mm\",\n        ], answer: 2, explain: \"The expanded uncertainty U = k × u_c. To recover the standard uncertainty: u = U / k = 0.004 / 2 = 0.002 mm. This is a Type B evaluation because it comes from a certificate rather than from repeated measurements.\" },\n\n        { type: \"callout\", tone: \"workplace\", title: \"In the workplace\", text: \"At the Douala metrology laboratory, the senior metrologist plots daily readings of a 10.000 mm gauge block on an I-MR chart pinned to the wall beside the CMM. Over the past two years, the chart has caught two drift episodes: once when the air conditioning unit failed over a weekend (temperature-induced expansion) and once when the CMM probe tip was wearing. Both were corrected before any bad measurements left the laboratory.\" },\n\n        { type: \"links\", items: [\n          { label: \"GUM: Guide to the expression of Uncertainty in Measurement\", url: \"https://www.bipm.org/en/committees/jc/jcgm/publications\", source: \"BIPM\" },\n          { label: \"Measurement uncertainty\", url: \"https://www.nist.gov/pml/nist-technical-note-1297\", source: \"NIST\" },\n        ] },\n      ],\n    },\n\n    // ═══════════════════════════════ PRACTICE ═══════════════════════════════\n    {\n      id: \"aqe-m3-practice\",\n      title: \"Practice\",\n      minutes: 30,\n      objectives: [\n        \"Identify measurement system properties from workplace descriptions\",\n        \"Measure parts accurately with a vernier caliper\",\n        \"Calculate Gage R&R results using the range method and interpret ANOVA output\",\n      ],\n      blocks: [\n        // ── Beginner: form ──\n        { type: \"form\", id: \"aqe-m3-p1\", level: \"beginner\", title: \"Identify measurement system properties\", task: \"For each description, select the measurement system property being described.\",\n          fields: [\n            { kind: \"select\", label: \"The same operator measures the same part 10 times and gets readings within a 0.003 mm band.\", options: [\"Repeatability\", \"Reproducibility\", \"Bias\", \"Linearity\", \"Stability\"], answer: 0, explain: \"Same operator, same part, same conditions — the spread of these readings is repeatability (equipment variation).\" },\n            { kind: \"select\", label: \"Three operators measure the same 10 parts. Operator B consistently reads 0.005 mm higher than the other two.\", options: [\"Repeatability\", \"Reproducibility\", \"Bias\", \"Linearity\", \"Stability\"], answer: 1, explain: \"Differences between operators measuring the same parts is reproducibility (appraiser variation).\" },\n            { kind: \"select\", label: \"A gauge block of 20.000 mm is measured 15 times and the average reading is 20.014 mm.\", options: [\"Repeatability\", \"Reproducibility\", \"Bias\", \"Linearity\", \"Stability\"], answer: 2, explain: \"The systematic difference between the average reading (20.014) and the reference value (20.000) is bias: +0.014 mm.\" },\n            { kind: \"select\", label: \"A micrometer has zero error at 5 mm but reads 0.02 mm high at 25 mm.\", options: [\"Repeatability\", \"Reproducibility\", \"Bias\", \"Linearity\", \"Stability\"], answer: 3, explain: \"When the bias changes across the measurement range, this is a linearity problem.\" },\n            { kind: \"select\", label: \"Weekly measurements of a reference standard on the same CMM show a gradual upward drift of 0.001 mm per week over three months.\", options: [\"Repeatability\", \"Reproducibility\", \"Bias\", \"Linearity\", \"Stability\"], answer: 4, explain: \"A change in the measurement result over time, all else held constant, is a stability (drift) issue.\" },\n            { kind: \"select\", label: \"A weighing scale has divisions of 50 g, but the tolerance on the product is +/- 25 g.\", options: [\"Repeatability\", \"Reproducibility\", \"Bias\", \"Resolution\", \"Stability\"], answer: 3, explain: \"The smallest increment the instrument can detect (50 g) is too coarse for the tolerance (50 g range). This is a resolution (discrimination) problem — the instrument cannot distinguish parts near the limits.\" },\n          ],\n          hint: \"Think about what is varying: the instrument itself (repeatability), the operator (reproducibility), the average vs true value (bias), the bias across the range (linearity), the bias over time (stability), or the smallest detectable increment (resolution).\",\n        },\n\n        // ── Intermediate: caliper ──\n        { type: \"caliper\", id: \"aqe-m3-p2\", level: \"intermediate\", title: \"Measure parts with a vernier caliper\", task: \"You are conducting a Gage R&R study at the Bafoussam factory. Measure the dimensions of this disc using a vernier caliper. Record all readings as multiples of 0.02 mm.\",\n          instrument: \"vernier\",\n          drawing: { kind: \"disc\", title: \"Brake disc — Gage R&R study\", outer: \"280.00\", inner: \"180.00\", thickness: \"22.00\" },\n          drawingUnit: \"mm\",\n          dims: [\n            { id: \"od\", label: \"Outer diameter\", nominal: 280.00, tolPlus: 0.10, tolMinus: -0.10 },\n            { id: \"id\", label: \"Inner diameter\", nominal: 180.00, tolPlus: 0.08, tolMinus: -0.08 },\n            { id: \"th\", label: \"Thickness\", nominal: 22.00, tolPlus: 0.05, tolMinus: -0.05 },\n          ],\n          readings: [\n            { dim: \"th\", label: \"Thickness, Trial 1\", value: 22.04, conformity: true },\n            { dim: \"th\", label: \"Thickness, Trial 2\", value: 22.02, conformity: true },\n            { dim: \"od\", label: \"Outer diameter, Trial 1\", value: 280.06, conformity: true },\n            { dim: \"id\", label: \"Inner diameter, Trial 1\", value: 179.96, conformity: true },\n          ],\n          hint: \"Read the main scale first (the last millimetre mark visible before the zero of the vernier). Then find which vernier division aligns best with a main scale division. Each vernier division = 0.02 mm.\",\n        },\n\n        // ── Advanced: sheet (Gage R&R range method) ──\n        { type: \"sheet\", id: \"aqe-m3-p3\", level: \"advanced\", title: \"Complete a Gage R&R range method study\", task: \"Two operators at the Douala gearbox plant each measured 5 gear tooth widths twice with a digital caliper. Complete all calculations using K₁ = 4.56, K₂ = 3.65, K₃ = 2.08. Determine whether the measurement system is acceptable.\",\n          hint: \"Follow the range method steps: ranges, averages, EV, AV, GRR, PV, TV, %GRR. If the square root term for AV is negative, set AV = 0.\",\n          data: [\n            [\"Part\", \"Oper A T1\", \"Oper A T2\", \"Range A\", \"Oper B T1\", \"Oper B T2\", \"Range B\"],\n            [1, 3.152, 3.148, null, 3.156, 3.150, null],\n            [2, 3.178, 3.174, null, 3.180, 3.176, null],\n            [3, 3.124, 3.130, null, 3.128, 3.122, null],\n            [4, 3.166, 3.162, null, 3.170, 3.164, null],\n            [5, 3.140, 3.136, null, 3.146, 3.138, null],\n            [\"\", \"\", \"\", \"\", \"\", \"\", \"\"],\n            [\"R-bar A\", null, \"\", \"R-bar B\", null, \"\", \"\"],\n            [\"R-bar\", null, \"\", \"\", \"\", \"\", \"\"],\n            [\"EV\", null, \"\", \"\", \"\", \"\", \"\"],\n            [\"X-bar A\", null, \"\", \"X-bar B\", null, \"\", \"\"],\n            [\"Xdiff\", null, \"\", \"\", \"\", \"\", \"\"],\n            [\"AV\", null, \"\", \"\", \"\", \"\", \"\"],\n            [\"GRR\", null, \"\", \"\", \"\", \"\", \"\"],\n            [\"Rp\", null, \"\", \"\", \"\", \"\", \"\"],\n            [\"PV\", null, \"\", \"\", \"\", \"\", \"\"],\n            [\"TV\", null, \"\", \"\", \"\", \"\", \"\"],\n            [\"%GRR\", null, \"\", \"\", \"\", \"\", \"\"],\n            [\"ndc\", null, \"\", \"\", \"\", \"\", \"\"],\n            [\"Decision\", null, \"\", \"\", \"\", \"\", \"\"],\n          ],\n          editable: [\"D2\",\"D3\",\"D4\",\"D5\",\"D6\",\"G2\",\"G3\",\"G4\",\"G5\",\"G6\",\"B8\",\"E8\",\"B9\",\"B10\",\"B11\",\"E11\",\"B12\",\"B13\",\"B14\",\"B15\",\"B16\",\"B17\",\"B18\",\"B19\",\"B20\"],\n          checks: [\n            { cell: \"D2\", equals: 0.004, tol: 0.001 },\n            { cell: \"D3\", equals: 0.004, tol: 0.001 },\n            { cell: \"D4\", equals: 0.006, tol: 0.001 },\n            { cell: \"D5\", equals: 0.004, tol: 0.001 },\n            { cell: \"D6\", equals: 0.004, tol: 0.001 },\n            { cell: \"G2\", equals: 0.006, tol: 0.001 },\n            { cell: \"G3\", equals: 0.004, tol: 0.001 },\n            { cell: \"G4\", equals: 0.006, tol: 0.001 },\n            { cell: \"G5\", equals: 0.006, tol: 0.001 },\n            { cell: \"G6\", equals: 0.008, tol: 0.001 },\n            { cell: \"B8\", equals: 0.0044, tol: 0.001 },\n            { cell: \"E8\", equals: 0.006, tol: 0.001 },\n            { cell: \"B9\", equals: 0.0052, tol: 0.001 },\n            { cell: \"B10\", equals: 0.0237, tol: 0.003 },\n            { cell: \"B18\", equals: 19, tol: 5 },\n          ],\n          solution: {\n            \"D2\": \"0.004\", \"D3\": \"0.004\", \"D4\": \"0.006\", \"D5\": \"0.004\", \"D6\": \"0.004\",\n            \"G2\": \"0.006\", \"G3\": \"0.004\", \"G4\": \"0.006\", \"G5\": \"0.006\", \"G6\": \"0.008\",\n            \"B8\": \"0.0044\", \"E8\": \"0.006\", \"B9\": \"0.0052\", \"B10\": \"0.0237\",\n            \"B11\": \"3.1522\", \"E11\": \"3.1550\", \"B12\": \"0.0028\",\n            \"B13\": \"0\", \"B14\": \"0.0237\", \"B15\": \"0.054\", \"B16\": \"0.1123\",\n            \"B17\": \"0.1148\", \"B18\": \"20.6\", \"B19\": \"6\", \"B20\": \"May be acceptable\",\n          },\n        },\n\n        // ── Expert: form (interpret full ANOVA output) ──\n        { type: \"form\", id: \"aqe-m3-p4\", level: \"expert\", title: \"Interpret ANOVA Gage R&R output and recommend actions\", task: \"A full ANOVA Gage R&R study was conducted on a CMM programme measuring cylinder bore diameters at the Douala engine plant. 10 parts, 3 operators, 3 trials. Study the results below and answer the questions.\\n\\nANOVA table: Part F = 45.2 (p < 0.001), Operator F = 8.7 (p = 0.003), Interaction F = 1.2 (p = 0.31).\\nVariance components: Part σ² = 0.000284 (73.1%), Operator σ² = 0.000038 (9.8%), Interaction σ² = 0.000002 (0.5%), Repeatability σ² = 0.000064 (16.5%), Total σ² = 0.000388.\\n%Study Variation: GRR = 51.8%, Repeatability = 40.6%, Reproducibility = 32.2%, Part = 85.5%.\\nndc = 2.\",\n          fields: [\n            { kind: \"select\", label: \"Is the measurement system acceptable?\", options: [\"Acceptable (%GRR < 10%)\", \"May be acceptable (10–30%)\", \"Unacceptable (%GRR > 30%)\", \"Cannot determine\"], answer: 2, explain: \"With %GRR (% Study Variation) = 51.8%, far exceeding 30%, and ndc = 2 (far below 5), the measurement system is clearly unacceptable. It contributes more variation than it should.\" },\n            { kind: \"select\", label: \"What is the dominant source of measurement system variation?\", options: [\"Repeatability (equipment variation)\", \"Reproducibility (operator variation)\", \"Operator × Part interaction\", \"Part variation\"], answer: 0, explain: \"Repeatability at 16.5% of total variance (40.6% of study variation) is the largest measurement system component. The equipment itself is the main problem, larger than the operator effect.\" },\n            { kind: \"select\", label: \"The operator effect is significant (p = 0.003). What does this mean practically?\", options: [\"Operators are measuring different parts\", \"At least one operator measures consistently higher or lower than the others\", \"The operators cannot read the instrument\", \"The operator effect is negligible\"], answer: 1, explain: \"A significant operator main effect (p = 0.003 < 0.05) means there is a systematic difference between operators. At least one operator's average differs from the others, indicating a bias that varies by operator. Training or standardising the procedure may help.\" },\n            { kind: \"select\", label: \"The interaction p-value is 0.31. What should be done with this term?\", options: [\"Keep it in the model — it is important\", \"Pool it into the repeatability term to simplify the model\", \"Remove it and re-run the study\", \"Report it as significant\"], answer: 1, explain: \"With p = 0.31 > 0.05, the interaction is not statistically significant. It should be pooled into the repeatability term, which increases the degrees of freedom for the repeatability estimate and gives a more stable variance estimate.\" },\n            { kind: \"select\", label: \"With ndc = 2, what practical problem does this create?\", options: [\"The gauge can distinguish 2 groups — this is sufficient for pass/fail inspection\", \"The gauge can only sort parts into 2 groups (high and low) — it cannot support SPC or process improvement\", \"The ndc is adequate because we only need to tell good from bad\", \"The ndc does not matter when %GRR is already unacceptable\"], answer: 1, explain: \"An ndc of 2 means the gauge can barely distinguish large parts from small parts. It cannot support SPC (which needs ndc >= 5) or any meaningful process analysis. Even for pass/fail inspection, this is marginal.\" },\n            { kind: \"select\", label: \"What is the most effective first action to improve this measurement system?\", options: [\"Retrain all operators to reduce reproducibility\", \"Replace or upgrade the CMM programme / probe to reduce repeatability\", \"Select parts with wider variation to improve ndc\", \"Tighten the tolerance to make %GRR look smaller\"], answer: 1, explain: \"Since repeatability (equipment variation) is the dominant source, the most effective action is to address the CMM programme or probe. This might mean reducing the scanning speed, increasing the number of measurement points, replacing a worn probe, or improving the fixturing. Retraining operators would help but addresses the smaller component.\" },\n          ],\n          hint: \"Look at both the ANOVA p-values and the variance component percentages. The largest contributor to GRR is where improvement effort should focus. Remember that ndc must be >= 5 for SPC applications.\",\n        },\n      ],\n    },\n  ],\n\n  // ═══════════════════════════════ MODULE QUIZ ═══════════════════════════════\n  quiz: {\n    id: \"aqe-m3-quiz\",\n    title: \"Module 3 Quiz — Measurement Systems Analysis\",\n    passPct: 75,\n    questions: [\n      {\n        id: \"aqe-m3-q1\",\n        question: \"Which measurement system property describes the systematic difference between the average of measurements and the true (reference) value?\",\n        options: [\"Repeatability\", \"Reproducibility\", \"Bias\", \"Linearity\"],\n        answer: 2,\n        explain: \"Bias is the systematic offset between the average measured value and the reference value. It is sometimes called accuracy, though accuracy can also refer to the combination of bias and precision.\",\n      },\n      {\n        id: \"aqe-m3-q2\",\n        question: \"In a Gage R&R study using the range method, what does EV represent?\",\n        options: [\n          \"Environmental variation\",\n          \"Equipment variation (repeatability)\",\n          \"Expected value of the measurements\",\n          \"Error variance from the ANOVA table\",\n        ],\n        answer: 1,\n        explain: \"EV stands for Equipment Variation, which is the repeatability component of the Gage R&R. It captures the variation from the instrument itself when the same operator measures the same part repeatedly.\",\n      },\n      {\n        id: \"aqe-m3-q3\",\n        question: \"A Gage R&R study reports %GRR = 24% and ndc = 6. What is the correct assessment?\",\n        options: [\n          \"Acceptable — both criteria are met\",\n          \"May be acceptable — %GRR is in the 10–30% range but ndc >= 5\",\n          \"Unacceptable — %GRR exceeds 10%\",\n          \"Unacceptable — ndc is too low\",\n        ],\n        answer: 1,\n        explain: \"A %GRR of 24% falls in the 10–30% marginal zone (may be acceptable depending on the application). The ndc of 6 meets the >= 5 criterion, confirming the gauge can distinguish at least 5 groups. The overall assessment is 'may be acceptable'.\",\n      },\n      {\n        id: \"aqe-m3-q4\",\n        question: \"What is the main advantage of the ANOVA method over the range method for Gage R&R studies?\",\n        options: [\n          \"It requires fewer parts and operators\",\n          \"It can detect an operator-by-part interaction effect\",\n          \"It does not require repeated trials\",\n          \"It gives the same results with less calculation\",\n        ],\n        answer: 1,\n        explain: \"The ANOVA method can detect an operator × part interaction, which occurs when some operators measure certain parts differently. The range method cannot detect this interaction. ANOVA also provides more precise variance estimates.\",\n      },\n      {\n        id: \"aqe-m3-q5\",\n        question: \"In an attribute MSA, Cohen's kappa corrects for what limitation of simple percent agreement?\",\n        options: [\n          \"It corrects for the number of appraisers\",\n          \"It corrects for agreement expected by chance alone\",\n          \"It corrects for the size of the sample\",\n          \"It corrects for the difficulty of the inspection task\",\n        ],\n        answer: 1,\n        explain: \"Cohen's kappa adjusts for the fact that some agreement between raters will occur by chance. Two inspectors randomly classifying parts as pass/fail would agree about 50% of the time by chance alone. Kappa removes this chance agreement to give a truer measure.\",\n      },\n      {\n        id: \"aqe-m3-q6\",\n        question: \"A linearity study shows that a gauge has no bias at 5 mm but reads 0.04 mm high at 25 mm. Which statement is correct?\",\n        options: [\n          \"The gauge has a stability problem\",\n          \"The gauge has a linearity problem — bias changes across the range\",\n          \"The gauge has a repeatability problem\",\n          \"Simple recalibration at 5 mm will fix the issue\",\n        ],\n        answer: 1,\n        explain: \"When bias changes across the operating range, this is a linearity problem. The slope of the bias-vs-reference regression line is significantly different from zero. Recalibrating at a single point will not fix linearity; the gauge needs repair or replacement.\",\n      },\n      {\n        id: \"aqe-m3-q7\",\n        question: \"In the GUM framework, which type of uncertainty evaluation uses the standard deviation of repeated measurements?\",\n        options: [\n          \"Type A evaluation\",\n          \"Type B evaluation\",\n          \"Type C evaluation\",\n          \"Combined evaluation\",\n        ],\n        answer: 0,\n        explain: \"Type A evaluation is based on the statistical analysis of a series of observations — typically the standard deviation of repeated measurements divided by the square root of the number of measurements. Type B uses other information such as calibration certificates or manufacturer specifications.\",\n      },\n      {\n        id: \"aqe-m3-q8\",\n        question: \"On the Xbar chart produced by a Gage R&R ANOVA study, what does it mean when most points fall WITHIN the control limits?\",\n        options: [\n          \"The process is in statistical control — this is a good result\",\n          \"The operators are consistent — this is a good result\",\n          \"The gauge cannot detect part-to-part differences — this is a bad result\",\n          \"The parts in the study are too similar — select parts with tighter tolerances\",\n        ],\n        answer: 2,\n        explain: \"In a Gage R&R Xbar chart, the control limits are based on the measurement system's repeatability. Points within the limits mean the measurement variation is large relative to part variation — the gauge cannot tell parts apart. Points OUTSIDE the limits (the opposite of normal SPC interpretation) indicate the gauge can detect real differences.\",\n      },\n    ],\n  },\n};\n","client/src/data/courses/aqe/m4.ts":"import type { CourseModule } from \"../../../lms/types\";\n\n// Associate Quality Engineer — Module 4: Statistical Process Control and Process Capability.\n// Original Analytix Engineering material. All companies, people and figures are fictional.\n// British spelling throughout; Cameroon industrial context.\n\n/* ── Realistic SPC data sets ──────────────────────────────────────────────────\n   Generated with a seeded PRNG so every value is deterministic and reproducible.\n   Each data set is annotated with its purpose and any injected out-of-control points.\n*/\n\n// Lesson 1 — X̄-R chart: aluminium extrusion width (mm), target 40.00 mm, 20 subgroups of 5.\n// Subgroup 14 has been shifted up (tool clamp loosened) to create one out-of-control signal.\nconst EXTRUSION: number[][] = [\n  [40.02, 39.98, 40.01, 39.97, 40.03],\n  [39.99, 40.04, 40.00, 40.02, 39.96],\n  [40.01, 39.95, 40.03, 40.00, 39.98],\n  [39.97, 40.02, 39.99, 40.01, 40.04],\n  [40.03, 40.00, 39.96, 39.98, 40.01],\n  [40.00, 39.97, 40.02, 40.04, 39.99],\n  [39.98, 40.01, 40.03, 39.96, 40.00],\n  [40.02, 39.99, 39.97, 40.01, 40.03],\n  [40.04, 40.00, 39.98, 39.96, 40.02],\n  [39.99, 40.03, 40.01, 39.97, 39.98],\n  [40.01, 39.98, 40.00, 40.02, 39.96],\n  [39.97, 40.04, 39.99, 40.01, 40.00],\n  [40.00, 39.96, 40.02, 39.98, 40.03],\n  [40.12, 40.09, 40.14, 40.11, 40.08],  // subgroup 14: shift — clamp loosened\n  [40.01, 39.99, 40.03, 39.97, 40.00],\n  [39.98, 40.02, 40.00, 39.96, 40.01],\n  [40.03, 39.97, 39.99, 40.01, 40.04],\n  [40.00, 40.02, 39.98, 40.03, 39.96],\n  [39.96, 40.01, 40.00, 39.99, 40.02],\n  [40.02, 39.98, 40.01, 40.00, 39.97],\n];\n\n// Lesson 2 — p chart: nonconforming PVC pipes per sample of 150 from Plastiques de Douala.\n// Sample 11 has a spike (raw material contamination).\nconst PIPES_DEF: number[] = [\n  5, 7, 4, 6, 8, 3, 5, 7, 6, 4,\n  19, 5, 6, 7, 3, 5, 8, 6, 4, 7,\n];\nconst PIPES_N = 150;\n\n// Lesson 2 — c chart: surface defects per sheet of plywood at Scieries du Moungo.\n// Sheet 8 has a high count (moisture in veneer stack).\nconst PLYWOOD: number[] = [\n  3, 5, 2, 4, 6, 3, 4, 14, 5, 3,\n  2, 4, 5, 3, 6, 4, 2, 5, 3, 4,\n];\n\n// Practice — I-MR: pH of treated water at a Douala brewery, one reading per hour, 20 hours.\nconst WATER_PH: number[] = [\n  7.02, 6.98, 7.01, 6.97, 7.03, 7.00, 6.99, 7.04, 6.96, 7.01,\n  6.98, 7.02, 7.00, 6.97, 7.03, 6.99, 7.01, 6.98, 7.00, 7.02,\n];\n\n// Practice — X̄-R with out-of-control: cocoa butter content (%), 18 subgroups of 5.\n// Subgroup 7 is shifted (fermentation batch error); subgroup 15 has high range.\nconst COCOA: number[][] = [\n  [54.2, 53.8, 54.0, 53.9, 54.1],\n  [53.7, 54.1, 53.9, 54.0, 53.8],\n  [54.0, 53.6, 54.2, 53.8, 54.1],\n  [53.9, 54.0, 53.7, 54.1, 53.8],\n  [54.1, 53.9, 54.0, 53.8, 53.7],\n  [53.8, 54.2, 53.9, 54.1, 54.0],\n  [55.1, 55.3, 55.0, 55.4, 55.2],  // subgroup 7: fermentation error\n  [54.0, 53.8, 54.1, 53.9, 53.7],\n  [53.9, 54.0, 53.8, 54.2, 54.1],\n  [54.1, 53.7, 54.0, 53.9, 53.8],\n  [53.8, 54.1, 53.9, 54.0, 54.2],\n  [54.0, 53.9, 53.7, 54.1, 53.8],\n  [53.9, 54.2, 54.0, 53.8, 54.1],\n  [54.1, 53.8, 53.9, 54.0, 53.7],\n  [52.8, 55.1, 53.2, 54.9, 53.5],  // subgroup 15: high range (mixing problem)\n  [54.0, 53.9, 54.1, 53.8, 54.2],\n  [53.8, 54.0, 53.9, 54.1, 53.7],\n  [54.1, 53.9, 54.0, 53.8, 54.2],\n];\n\n// Practice — p chart with variable thinking: bottle cap seal failures, sample of 200.\n// Sample 12 spike (new seal liner supplier).\nconst CAPS_DEF: number[] = [\n  6, 8, 5, 7, 9, 4, 6, 8, 7, 5,\n  3, 18, 6, 7, 5, 8, 4, 6, 7, 5,\n];\nconst CAPS_N = 200;\n\nexport const m4: CourseModule = {\n  id: \"aqe-m4\",\n  number: 4,\n  title: \"Statistical Process Control and Process Capability\",\n  summary:\n    \"This module covers the theory and practice of statistical process control as applied in Cameroonian manufacturing. You will construct and interpret variables control charts (X-bar/R, X-bar/S and I-MR) and attribute control charts (p, np, c and u), apply Western Electric and Nelson rules to detect special causes, and calculate process capability and performance indices (Cp, Cpk, Pp, Ppk). The module closes with advanced SPC topics including pre-control, short-run SPC and using control charts to drive process improvement.\",\n  hours: 18,\n  lessons: [\n    // ───────────────────────────── LESSON 1 ─────────────────────────────\n    {\n      id: \"aqe-m4-l1\",\n      title: \"Variables control charts: X̄-R and I-MR\",\n      minutes: 35,\n      objectives: [\n        \"Form rational subgroups that capture within-subgroup and between-subgroup variation\",\n        \"Construct an X̄-R chart from subgroup data using A₂, D₃ and D₄ constants\",\n        \"Construct an I-MR chart for individual measurements using the E₂ constant\",\n        \"Plot data on control charts and identify points beyond the control limits\",\n      ],\n      blocks: [\n        { type: \"p\", text: \"A control chart is a time-ordered plot of a quality characteristic with a centre line (CL) and two control limits: upper (UCL) and lower (LCL). The limits are calculated from the process data itself, not from the specification, and they sit at ±3 standard deviations of the plotted statistic. If the process is stable, about 99.73% of points fall inside the limits and any point outside is a signal of a **special cause** worth investigating.\" },\n\n        { type: \"h\", text: \"Rational subgrouping\" },\n        { type: \"p\", text: \"The power of a control chart depends on how the data are grouped. A **rational subgroup** is a small set of items produced under essentially the same conditions: the same machine, operator, material batch and short time interval. The variation within the subgroup estimates the common-cause spread, and the variation between subgroup averages reveals any shifts or trends over time.\" },\n        { type: \"list\", items: [\n          \"**Why subgroup?** Averaging reduces noise and makes shifts easier to see. An average of 5 readings is about 2.2 times less variable than a single reading.\",\n          \"**How many per subgroup?** Typically 3 to 5, sometimes 10. Larger subgroups increase sensitivity but can mix conditions.\",\n          \"**How often?** Often enough to catch a shift before too many nonconforming units are produced. Hourly or every 50 parts is common.\",\n          \"**Key rule:** items within a subgroup must come from one stream, one set-up, one operator. Never mix morning and afternoon production in the same subgroup.\",\n        ] },\n        { type: \"callout\", tone: \"key\", title: \"Within vs between\", text: \"The within-subgroup variation (the range R or standard deviation S) estimates the short-term common-cause spread. The between-subgroup variation (movement of X̄) reveals assignable causes. If the subgroups mix different conditions, the within-group spread is inflated and the chart loses sensitivity.\" },\n\n        { type: \"h\", text: \"X̄-R chart: construction\" },\n        { type: \"p\", text: \"The X-bar and R chart is the most common variables control chart. You plot the subgroup average (X̄) and the subgroup range (R) on two aligned charts. The X̄ chart detects shifts in the process mean; the R chart detects changes in the process spread.\" },\n        { type: \"steps\", title: \"Steps to build an X̄-R chart\", items: [\n          \"Collect k subgroups of n measurements each (k ≥ 20 is recommended; n is typically 4 or 5).\",\n          \"For each subgroup, calculate the average X̄ᵢ and the range Rᵢ = max − min.\",\n          \"Calculate the grand average X̄̄ = ΣX̄ᵢ / k and the average range R̄ = ΣRᵢ / k.\",\n          \"Look up the constants A₂, D₃ and D₄ for your subgroup size n.\",\n          \"Compute the X̄ chart limits: UCL = X̄̄ + A₂ × R̄, LCL = X̄̄ − A₂ × R̄.\",\n          \"Compute the R chart limits: UCL = D₄ × R̄, LCL = D₃ × R̄ (D₃ = 0 when n ≤ 6).\",\n          \"Plot the points, centre lines and limits, and inspect for signals.\",\n        ] },\n        { type: \"table\", head: [\"n\", \"A₂\", \"D₃\", \"D₄\", \"d₂\"], rows: [\n          [\"2\", \"1.880\", \"0\", \"3.267\", \"1.128\"],\n          [\"3\", \"1.023\", \"0\", \"2.574\", \"1.693\"],\n          [\"4\", \"0.729\", \"0\", \"2.282\", \"2.059\"],\n          [\"5\", \"0.577\", \"0\", \"2.114\", \"2.326\"],\n          [\"6\", \"0.483\", \"0\", \"2.004\", \"2.534\"],\n          [\"7\", \"0.419\", \"0.076\", \"1.924\", \"2.704\"],\n          [\"8\", \"0.373\", \"0.136\", \"1.864\", \"2.847\"],\n          [\"9\", \"0.337\", \"0.184\", \"1.816\", \"2.970\"],\n          [\"10\", \"0.308\", \"0.223\", \"1.777\", \"3.078\"],\n        ] },\n        { type: \"callout\", tone: \"tip\", title: \"Estimating sigma from R̄\", text: \"The process standard deviation is estimated as σ̂ = R̄ / d₂. For n = 5, d₂ = 2.326, so σ̂ = R̄ / 2.326. This within-subgroup estimate of sigma is the basis for the 3σ control limits and for process capability studies.\" },\n\n        { type: \"h\", text: \"X̄-R example: aluminium extrusion\" },\n        { type: \"p\", text: \"Alumilite Cameroun in Bonaberi extrudes aluminium window frames with a target width of 40.00 mm. The quality engineer collects 20 subgroups of 5 pieces, one subgroup per hour. Subgroup 14 was taken just after the tool clamp was found loose.\" },\n        { type: \"code\", text: \"n = 5    k = 20 subgroups\\nA₂ = 0.577    D₃ = 0    D₄ = 2.114    d₂ = 2.326\\n\\nX̄̄  = (40.002 + 40.002 + 39.994 + …) / 20   (calculate from all subgroup averages)\\nR̄  = (0.06 + 0.08 + 0.08 + …) / 20\\n\\nUCL_X̄ = X̄̄ + 0.577 × R̄\\nLCL_X̄ = X̄̄ − 0.577 × R̄\\nUCL_R  = 2.114 × R̄\\nLCL_R  = 0 × R̄ = 0\" },\n        { type: \"equip\", title: \"Reading a control chart output\", items: [\n          { art: \"stat-control-chart\", caption: \"Statistical software draws both the X̄ and R chart together. Each subgroup is a point, the centre line is the grand average, and the control limits are computed from the constants table. Points in red are flagged as beyond the limits.\",\n            specs: [\n              { label: \"UCL / LCL\", value: \"Calculated from the data, not from specification\" },\n              { label: \"Red points\", value: \"Beyond 3σ from the centre line\" },\n              { label: \"Tests for special causes\", value: \"Software can run all eight Nelson rules automatically\" },\n            ] },\n        ] },\n\n        { type: \"h\", text: \"I-MR chart: individuals and moving range\" },\n        { type: \"p\", text: \"When you can measure only one item per time period (destructive testing, batch-process output, a daily laboratory analysis), you cannot form subgroups. The **Individuals and Moving Range (I-MR)** chart plots each individual value and the absolute difference between consecutive values.\" },\n        { type: \"list\", items: [\n          \"The moving range MRᵢ = |xᵢ − xᵢ₋₁| estimates short-term variation.\",\n          \"MR̄ = average of all moving ranges.\",\n          \"Centre line of the I chart: X̄ (average of all individual values).\",\n          \"UCLᵢ = X̄ + E₂ × MR̄ and LCLᵢ = X̄ − E₂ × MR̄, where E₂ = 2.660.\",\n          \"UCLₘʀ = D₄ × MR̄ = 3.267 × MR̄ and LCLₘʀ = 0.\",\n        ] },\n        { type: \"callout\", tone: \"warning\", title: \"Assumption\", text: \"The I-MR chart assumes the data are approximately normally distributed. With only one observation per period, there is no within-subgroup averaging to invoke the central limit theorem. Check the data with a histogram or normal probability plot before relying on the limits.\" },\n\n        { type: \"spc\", id: \"aqe-m4-l1-spc1\", title: \"X̄-R chart: aluminium extrusion width\", task: \"Examine the X̄-R chart for 20 subgroups of 5 measurements of extrusion width (mm). Identify the control limits and any points beyond them. Subgroup 14 was taken after the tool clamp loosened.\", hint: \"Look at the X̄ chart first. The grand average and A₂ × R̄ give the limits. Subgroup 14 should appear above the UCL.\", chart: \"xbar-r\", unit: \"mm\", decimals: 2, samples: EXTRUSION, askLimits: true, askBeyond: true },\n\n        { type: \"sheet\", id: \"aqe-m4-l1-sheet\", title: \"Manual X̄-R limit calculation\", task: \"Using the first 5 subgroups of the extrusion data, calculate each subgroup average, each subgroup range, the grand average, the average range, and the X̄ chart UCL and LCL. Use n = 5, A₂ = 0.577.\", hint: \"X̄ᵢ = sum of 5 values / 5. Rᵢ = max − min. Then X̄̄ = average of 5 X̄ᵢ values, R̄ = average of 5 Rᵢ values.\",\n          data: [\n            [\"Subgroup\", \"x₁\", \"x₂\", \"x₃\", \"x₄\", \"x₅\", \"X̄ᵢ\", \"Rᵢ\"],\n            [1, 40.02, 39.98, 40.01, 39.97, 40.03, null, null],\n            [2, 39.99, 40.04, 40.00, 40.02, 39.96, null, null],\n            [3, 40.01, 39.95, 40.03, 40.00, 39.98, null, null],\n            [4, 39.97, 40.02, 39.99, 40.01, 40.04, null, null],\n            [5, 40.03, 40.00, 39.96, 39.98, 40.01, null, null],\n            [\"\", \"\", \"\", \"\", \"\", \"X̄̄ =\", null, null],\n            [\"\", \"\", \"\", \"\", \"\", \"R̄ =\", null, null],\n            [\"\", \"\", \"\", \"A₂ =\", 0.577, \"UCL =\", null, \"\"],\n            [\"\", \"\", \"\", \"\", \"\", \"LCL =\", null, \"\"],\n          ],\n          editable: [\"G2\", \"H2\", \"G3\", \"H3\", \"G4\", \"H4\", \"G5\", \"H5\", \"G6\", \"H6\", \"G7\", \"H7\", \"G8\", \"H8\"],\n          checks: [\n            { cell: \"G2\", equals: 40.002, tol: 0.001 },\n            { cell: \"H2\", equals: 0.06, tol: 0.005 },\n            { cell: \"G3\", equals: 40.002, tol: 0.001 },\n            { cell: \"H3\", equals: 0.08, tol: 0.005 },\n            { cell: \"G4\", equals: 39.994, tol: 0.001 },\n            { cell: \"H4\", equals: 0.08, tol: 0.005 },\n            { cell: \"G5\", equals: 40.006, tol: 0.001 },\n            { cell: \"H5\", equals: 0.07, tol: 0.005 },\n            { cell: \"G6\", equals: 39.996, tol: 0.001 },\n            { cell: \"H6\", equals: 0.07, tol: 0.005 },\n            { cell: \"G7\", equals: 40.000, tol: 0.001 },\n            { cell: \"H7\", equals: 0.072, tol: 0.005 },\n            { cell: \"G8\", equals: 40.042, tol: 0.005 },\n            { cell: \"H8\", equals: 39.958, tol: 0.005 },\n          ],\n          solution: {\n            G2: \"=(B2+C2+D2+E2+F2)/5\",\n            H2: \"=MAX(B2:F2)-MIN(B2:F2)\",\n            G7: \"=AVERAGE(G2:G6)\",\n            H7: \"=AVERAGE(H2:H6)\",\n            G8: \"=G7+E8*H7\",\n            H8: \"=G7-E8*H7\",\n          },\n        },\n\n        { type: \"equip\", items: [\n          { art: \"stat-control-chart\", caption: \"An I-MR chart has two panels: the upper panel plots each individual observation against the average and ±E₂ × MR̄ limits; the lower panel plots each moving range against D₄ × MR̄.\",\n            specs: [\n              { label: \"Use when\", value: \"Only one measurement per period (destructive test, batch process)\" },\n              { label: \"E₂\", value: \"2.660 (for moving range of span 2)\" },\n              { label: \"D₄\", value: \"3.267 (for moving range of span 2)\" },\n            ] },\n        ] },\n\n        { type: \"check\", id: \"aqe-m4-l1-ck1\", question: \"Why are control limits calculated from the process data rather than from the specification limits?\", options: [\n          \"Because the specification limits are always wider than the control limits\",\n          \"Because control limits measure the voice of the process, not the voice of the customer\",\n          \"Because specification limits change every year\",\n          \"Because the engineer does not know the specification\",\n        ], answer: 1, explain: \"Control limits represent the natural variation of the process (±3σ of the plotted statistic). Specification limits represent the customer’s requirements. The two are independent: a process can be in control yet out of specification, or in specification yet out of control.\" },\n\n        { type: \"check\", id: \"aqe-m4-l1-ck2\", question: \"When is an I-MR chart preferred over an X̄-R chart?\", options: [\n          \"When the subgroup size is larger than 10\",\n          \"When the measurement is continuous\",\n          \"When only one observation is available per sampling period\",\n          \"When the process is already in control\",\n        ], answer: 2, explain: \"The I-MR chart is used when subgrouping is impossible: destructive tests, batch processes, expensive analyses where only one result is obtained per period.\" },\n      ],\n    },\n\n    // ───────────────────────────── LESSON 2 ─────────────────────────────\n    {\n      id: \"aqe-m4-l2\",\n      title: \"Attribute control charts: p, c and u charts\",\n      minutes: 30,\n      objectives: [\n        \"Select the correct attribute chart based on the type of count data\",\n        \"Construct a p chart for proportion nonconforming with constant or variable sample size\",\n        \"Construct c and u charts for counts of defects per unit or per area of opportunity\",\n      ],\n      blocks: [\n        { type: \"p\", text: \"Not every quality characteristic is measured on a continuous scale. When the inspector classifies each item as conforming or nonconforming, or counts the number of defects on each unit, you need an **attribute** control chart. The choice depends on two things: are you counting nonconforming items or individual defects, and is the sample size (or area of opportunity) constant or variable?\" },\n\n        { type: \"h\", text: \"Choosing the right attribute chart\" },\n        { type: \"table\", head: [\"Chart\", \"What you count\", \"Sample size\", \"Plotted statistic\", \"Distribution\"], rows: [\n          [\"p\", \"Nonconforming items\", \"Variable or constant\", \"pᵢ = dᵢ / nᵢ (proportion)\", \"Binomial\"],\n          [\"np\", \"Nonconforming items\", \"Constant only\", \"dᵢ (count)\", \"Binomial\"],\n          [\"c\", \"Defects per unit\", \"Constant area of opportunity\", \"cᵢ (count)\", \"Poisson\"],\n          [\"u\", \"Defects per unit\", \"Variable area of opportunity\", \"uᵢ = cᵢ / nᵢ (rate)\", \"Poisson\"],\n        ] },\n        { type: \"callout\", tone: \"key\", title: \"Nonconforming vs defect\", text: \"A **nonconforming item** (defective) fails one or more requirements and is counted once. A **defect** (nonconformity) is a single flaw: one item can have several defects. A scratched, dented and discoloured panel has 3 defects but is 1 nonconforming item.\" },\n\n        { type: \"h\", text: \"The p chart: proportion nonconforming\" },\n        { type: \"p\", text: \"Each sample of nᵢ items is inspected and dᵢ nonconforming items are found. The proportion is pᵢ = dᵢ / nᵢ. The centre line is p̄ = Σdᵢ / Σnᵢ (the overall proportion). The 3σ limits are:\" },\n        { type: \"code\", text: \"UCL = p̄ + 3 × √( p̄(1 − p̄) / n )\\nLCL = p̄ − 3 × √( p̄(1 − p̄) / n )      (set to 0 if negative)\" },\n        { type: \"p\", text: \"When the sample size varies from period to period, the limits change with each sample (they widen for smaller samples). You can either recalculate exact limits for every sample or use the average sample size n̄ for approximate constant limits (acceptable when sample sizes do not vary by more than ±25%).\" },\n\n        { type: \"h\", text: \"The np chart\" },\n        { type: \"p\", text: \"When the sample size n is the same for every period, you can plot the **count** of nonconforming items directly instead of the proportion. The np chart is simpler because no division is needed.\" },\n        { type: \"code\", text: \"CL = n × p̄\\nUCL = n × p̄ + 3 × √( n × p̄ × (1 − p̄) )\\nLCL = n × p̄ − 3 × √( n × p̄ × (1 − p̄) )      (set to 0 if negative)\" },\n\n        { type: \"h\", text: \"The c chart: defects per unit\" },\n        { type: \"p\", text: \"When the area of opportunity is constant (same size of panel, same length of cable, same area of fabric), you count the number of defects per inspection unit. The c chart assumes the defects follow a Poisson distribution.\" },\n        { type: \"code\", text: \"CL = c̄ = Σcᵢ / k\\nUCL = c̄ + 3 × √c̄\\nLCL = c̄ − 3 × √c̄      (set to 0 if negative)\" },\n\n        { type: \"h\", text: \"The u chart: defects per unit, variable opportunity\" },\n        { type: \"p\", text: \"When the inspection area varies (different lengths of pipe, different numbers of welds per joint), you divide the defect count by the size of opportunity to get uᵢ = cᵢ / nᵢ. The u chart handles variable areas the way the p chart handles variable sample sizes.\" },\n        { type: \"code\", text: \"CL = ū = Σcᵢ / Σnᵢ\\nUCL = ū + 3 × √( ū / nᵢ )\\nLCL = ū − 3 × √( ū / nᵢ )      (set to 0 if negative)\" },\n\n        { type: \"callout\", tone: \"workplace\", title: \"In the workplace\", text: \"At Plastiques de Douala, the quality inspector samples 150 PVC pipes per shift and records the number rejected. Since the sample size is constant, either a p chart or an np chart works. The team chose the p chart because the production manager prefers to see the rejection rate as a percentage. Sample 11 showed a spike to 12.7% nonconforming; the root cause was a batch of recycled resin that had degraded.\" },\n\n        { type: \"equip\", title: \"Attribute chart displays\", items: [\n          { art: \"stat-control-chart\", caption: \"Attribute control charts look similar to variables charts but the plotted points are proportions (p chart) or counts (c, np, u charts). The limits may step when the sample size changes.\",\n            specs: [\n              { label: \"p chart limits\", value: \"Variable with sample size\" },\n              { label: \"c chart limits\", value: \"Constant (√c̄-based)\" },\n              { label: \"Minimum data\", value: \"≥20 subgroups recommended\" },\n            ] },\n        ] },\n\n        { type: \"spc\", id: \"aqe-m4-l2-spc1\", title: \"p chart: PVC pipe nonconformities\", task: \"Inspect the p chart for 20 samples of 150 PVC pipes. Identify the average proportion nonconforming, the control limits and any out-of-control points.\", hint: \"p̄ = total defectives / total inspected. The UCL and LCL use the formula with √(p̄(1−p̄)/n). Look for sample 11.\", chart: \"p\", defectives: PIPES_DEF, sampleSize: PIPES_N },\n\n        { type: \"spc\", id: \"aqe-m4-l2-spc2\", title: \"c chart: plywood surface defects\", task: \"Examine the c chart for 20 sheets of plywood. Determine c̄, the control limits, and whether any sheet exceeds the UCL.\", hint: \"c̄ is the average number of defects. UCL = c̄ + 3√c̄. Sheet 8 had moisture damage.\", chart: \"c\", values: PLYWOOD },\n\n        { type: \"check\", id: \"aqe-m4-l2-ck1\", question: \"A weld inspector counts the number of pores in each pipe joint. The pipe lengths vary from 3 m to 12 m. Which chart is appropriate?\", options: [\n          \"p chart\",\n          \"np chart\",\n          \"c chart\",\n          \"u chart\",\n        ], answer: 3, explain: \"The inspector is counting defects (pores), not nonconforming items, and the area of opportunity (pipe length) varies. This calls for a u chart, which divides the count by the unit of opportunity.\" },\n\n        { type: \"check\", id: \"aqe-m4-l2-ck2\", question: \"Why is LCL set to zero when the formula gives a negative value?\", options: [\n          \"Because negative proportions and counts are impossible\",\n          \"Because the lower limit is not important\",\n          \"Because the chart is one-sided\",\n          \"Because the process is already good enough\",\n        ], answer: 0, explain: \"You cannot have a negative proportion nonconforming or a negative defect count. When the 3σ formula yields a negative LCL, it is truncated to zero.\" },\n      ],\n    },\n\n    // ───────────────────────────── LESSON 3 ─────────────────────────────\n    {\n      id: \"aqe-m4-l3\",\n      title: \"Interpreting control charts: tests for special causes\",\n      minutes: 25,\n      objectives: [\n        \"Apply the Western Electric and Nelson rules to identify non-random patterns\",\n        \"Recognise common chart patterns: shifts, trends, cycles, mixtures, stratification and over-control\",\n        \"Determine the correct response when an out-of-control signal is detected\",\n      ],\n      blocks: [\n        { type: \"p\", text: \"A point beyond a control limit is the most obvious signal that the process has changed, but it is not the only one. Non-random patterns within the limits, such as runs, trends and systematic alternation, also indicate that something has changed. The **Western Electric rules** (1956) and the extended **Nelson rules** (1984) provide a standard set of tests that statistical software applies automatically.\" },\n\n        { type: \"h\", text: \"The zone system\" },\n        { type: \"p\", text: \"Divide the area between each control limit and the centre line into three equal zones, each one sigma wide. Zone C is the inner third (nearest the centre line), Zone B is the middle third, and Zone A is the outer third (nearest the control limit). The rules use these zones to define suspicious patterns.\" },\n        { type: \"table\", head: [\"Zone\", \"Location\", \"Expected proportion of points\"], rows: [\n          [\"C\", \"±1σ from centre line\", \"About 68%\"],\n          [\"B\", \"Between ±1σ and ±2σ\", \"About 27%\"],\n          [\"A\", \"Between ±2σ and ±3σ\", \"About 4.3%\"],\n          [\"Beyond\", \"Outside ±3σ\", \"About 0.27%\"],\n        ] },\n\n        { type: \"h\", text: \"Western Electric / Nelson rules\" },\n        { type: \"table\", head: [\"Rule\", \"Description\", \"What it detects\"], rows: [\n          [\"1\", \"1 point beyond Zone A (beyond 3σ)\", \"Single large shift or outlier\"],\n          [\"2\", \"9 consecutive points on the same side of the centre line\", \"Sustained shift in the mean\"],\n          [\"3\", \"6 consecutive points steadily increasing or decreasing\", \"Trend (tool wear, drift)\"],\n          [\"4\", \"14 consecutive points alternating up and down\", \"Over-adjustment or two alternating streams\"],\n          [\"5\", \"2 out of 3 consecutive points in Zone A or beyond, same side\", \"Erratic shift\"],\n          [\"6\", \"4 out of 5 consecutive points in Zone B or beyond, same side\", \"Sustained moderate shift\"],\n          [\"7\", \"15 consecutive points in Zone C (both sides)\", \"Stratification or plotting error\"],\n          [\"8\", \"8 consecutive points outside Zone C (both sides)\", \"Mixture of two processes\"],\n        ] },\n        { type: \"callout\", tone: \"warning\", title: \"False alarms\", text: \"Each rule has a small probability of triggering by chance. Applying all eight rules simultaneously increases the false alarm rate to roughly 2–3% per sample. Many factories use only rules 1, 2 and 3 for routine monitoring and add the others for deeper investigation.\" },\n\n        { type: \"h\", text: \"Common patterns and their causes\" },\n        { type: \"list\", items: [\n          \"**Shift:** a sudden, sustained change in the level. Causes: new operator, tool replacement, material lot change, recalibration.\",\n          \"**Trend:** a steady drift upward or downward. Causes: tool wear, filter clogging, chemical depletion, temperature drift.\",\n          \"**Cycle:** a repeating wave pattern. Causes: ambient temperature cycle (day/night), shift rotation, periodic maintenance, batch-to-batch raw material variation.\",\n          \"**Mixture:** points consistently in Zones B and A on both sides, with too few points near the centre. Causes: two machines feeding one stream, two operators, two shifts mixed into one chart.\",\n          \"**Stratification:** points hugging the centre line too closely (too little variation). Causes: limits calculated from data that include a special cause (inflated R̄), or a plotting error.\",\n          \"**Over-control:** every point is adjusted after each reading, causing an alternating sawtooth. The operator is reacting to common-cause variation and making things worse.\",\n        ] },\n\n        { type: \"h\", text: \"Reacting to out-of-control signals\" },\n        { type: \"steps\", title: \"Response procedure\", items: [\n          \"Stop: mark the point on the chart and record the time.\",\n          \"Investigate: find the assignable cause (ask the operator, check material, inspect tooling).\",\n          \"Correct: remove the cause or adjust the process.\",\n          \"Document: note the cause and the corrective action on the control chart or in the logbook.\",\n          \"Decide: if the cause is found and removed, exclude that point and recalculate the limits. If no cause is found, tighten investigation and continue plotting.\",\n        ] },\n        { type: \"callout\", tone: \"key\", title: \"Common vs special cause\", text: \"**Common-cause** variation is always present and inherent to the process (random, stable). **Special-cause** variation is due to an identifiable, intermittent factor. Control charts separate the two: if all points are within the limits and show no patterns, only common causes are acting. Reducing common-cause variation requires a system change (better materials, new tooling, training); removing a special cause requires finding and eliminating that one factor.\" },\n\n        { type: \"form\", id: \"aqe-m4-l3-form\", title: \"Identify the violated rule\", task: \"For each chart description below, select which Western Electric / Nelson rule is violated.\",\n          fields: [\n            { kind: \"select\", label: \"A single point plots above the UCL on the X̄ chart\", options: [\"Rule 1: point beyond 3σ\", \"Rule 2: 9 points same side\", \"Rule 3: 6 points trending\", \"Rule 5: 2 of 3 in Zone A\"], answer: 0, explain: \"One point beyond a 3σ limit is Rule 1.\" },\n            { kind: \"select\", label: \"The last 10 points are all below the centre line but within the limits\", options: [\"Rule 1: point beyond 3σ\", \"Rule 2: 9 points same side\", \"Rule 3: 6 points trending\", \"Rule 7: 15 points in Zone C\"], answer: 1, explain: \"Nine or more consecutive points on the same side of the centre line is Rule 2, indicating a sustained shift.\" },\n            { kind: \"select\", label: \"Seven consecutive points rise steadily from left to right\", options: [\"Rule 1: point beyond 3σ\", \"Rule 2: 9 points same side\", \"Rule 3: 6 points trending\", \"Rule 4: 14 points alternating\"], answer: 2, explain: \"Six or more consecutive points increasing or decreasing is Rule 3, suggesting a trend such as tool wear.\" },\n            { kind: \"select\", label: \"Points 5 and 6 are both in Zone A above the centre line, and point 7 is in Zone B above\", options: [\"Rule 1: point beyond 3σ\", \"Rule 3: 6 points trending\", \"Rule 5: 2 of 3 in Zone A\", \"Rule 6: 4 of 5 in Zone B\"], answer: 2, explain: \"Two out of three consecutive points in Zone A on the same side is Rule 5.\" },\n          ],\n          hint: \"Remember: Rule 1 = beyond limits; Rule 2 = long run on one side; Rule 3 = trend; Rule 5 = 2 of 3 in Zone A.\" },\n\n        { type: \"sorter\", id: \"aqe-m4-l3-sort\", layout: \"columns\", title: \"Match patterns to causes\", task: \"Drag each observed cause to the chart pattern it most likely produces.\",\n          buckets: [\n            { label: \"Shift\" },\n            { label: \"Trend\" },\n            { label: \"Cycle\" },\n            { label: \"Mixture\" },\n          ],\n          items: [\n            { text: \"A new batch of resin is introduced at the start of the afternoon shift\", bucket: 0, explain: \"A sudden material change causes a step change (shift) in the process mean.\" },\n            { text: \"The cutting tool wears gradually over the day\", bucket: 1, explain: \"Gradual tool wear produces a steady drift (trend) in the dimension.\" },\n            { text: \"Ambient temperature rises during the day and falls at night, and the chart shows a repeating wave\", bucket: 2, explain: \"A periodic environmental factor creates a cycle in the data.\" },\n            { text: \"Two injection moulding machines feed the same inspection station; one runs slightly higher than the other\", bucket: 3, explain: \"Two machines at different levels produce a bimodal spread that appears as mixture on the chart.\" },\n            { text: \"The acid concentration in the etching bath is consumed as parts are processed\", bucket: 1, explain: \"Chemical depletion is a gradual, continuous change, producing a trend.\" },\n            { text: \"The operator changes at 06:00 and the readings step up\", bucket: 0, explain: \"An operator change with a different technique or set-up causes a shift.\" },\n          ] },\n\n        { type: \"check\", id: \"aqe-m4-l3-ck1\", question: \"Fifteen consecutive points all fall within Zone C. What does this suggest?\", options: [\n          \"The process is very stable and well controlled\",\n          \"The control limits are too narrow\",\n          \"Stratification: the limits were calculated with inflated variation\",\n          \"The process has shifted to the centre\",\n        ], answer: 2, explain: \"Rule 7 flags 15 consecutive points in Zone C. This usually means the within-subgroup variation used to set the limits was inflated (e.g. by including a special cause in the initial data), making the limits too wide relative to the actual common-cause spread.\" },\n      ],\n    },\n\n    // ───────────────────────────── LESSON 4 ─────────────────────────────\n    {\n      id: \"aqe-m4-l4\",\n      title: \"Process capability: Cp, Cpk, Pp and Ppk\",\n      minutes: 35,\n      objectives: [\n        \"Distinguish between process capability (within, short-term) and process performance (overall, long-term)\",\n        \"Calculate and interpret Cp, Cpk, Pp and Ppk from process data\",\n        \"Apply minimum capability requirements: Cpk ≥ 1.33 for existing and ≥ 1.67 for new processes\",\n        \"Explain how non-normal data affects capability analysis\",\n      ],\n      blocks: [\n        { type: \"p\", text: \"Once a process is in statistical control, you can ask: is the natural variation small enough to fit comfortably within the specification? **Process capability** compares the voice of the process to the voice of the customer. A capable process produces virtually no nonconforming output; an incapable process, even when in control, is inherently unable to meet the specification.\" },\n\n        { type: \"h\", text: \"Capability vs performance\" },\n        { type: \"table\", head: [\"\", \"Capability (Cp, Cpk)\", \"Performance (Pp, Ppk)\"], rows: [\n          [\"Variation used\", \"Within-subgroup (σ̂_within = R̄/d₂ or S̄/c₄)\", \"Overall (σ̂_overall = standard deviation of all individuals)\"],\n          [\"Condition\", \"Process must be in statistical control\", \"No requirement for control\"],\n          [\"Interpretation\", \"What the process **can** do at its best\", \"What the process **has been** doing\"],\n          [\"Typical use\", \"Pre-production approval, SPC studies\", \"Long-term monitoring, customer reports\"],\n        ] },\n        { type: \"callout\", tone: \"key\", title: \"Why two sigmas?\", text: \"When a process is in control, σ_within ≈ σ_overall and Cp ≈ Pp. When special causes are present, σ_overall > σ_within and Pp < Cp. A large gap between Cp and Pp tells you that assignable causes are inflating the overall variation.\" },\n\n        { type: \"h\", text: \"Cp and Cpk formulas\" },\n        { type: \"p\", text: \"**Cp** (potential capability) measures only the spread, ignoring the centering. **Cpk** (actual capability) also accounts for how far the process mean is from the nearest specification limit.\" },\n        { type: \"code\", text: \"Cp  = (USL − LSL) / (6σ̂)\\nCpk = min( (USL − X̄̄) / (3σ̂) , (X̄̄ − LSL) / (3σ̂) )\\n\\nwhere σ̂ = R̄ / d₂   (within-subgroup estimate)\" },\n        { type: \"list\", items: [\n          \"Cp = 1.00: the process spread equals the tolerance (3σ on each side). About 2 700 PPM nonconforming.\",\n          \"Cp = 1.33: 4σ on each side. About 63 PPM. Typical minimum for existing processes.\",\n          \"Cp = 1.67: 5σ on each side. About 0.6 PPM. Typical minimum for new / safety-critical processes.\",\n          \"Cp = 2.00: 6σ on each side. About 2 PPB. World-class.\",\n        ] },\n        { type: \"callout\", tone: \"tip\", title: \"Cpk can never exceed Cp\", text: \"Cpk accounts for off-centre processes. If the process is perfectly centred between the specification limits, Cpk = Cp. If the mean drifts toward one limit, Cpk decreases while Cp stays the same.\" },\n\n        { type: \"h\", text: \"Pp and Ppk formulas\" },\n        { type: \"code\", text: \"Pp  = (USL − LSL) / (6s)\\nPpk = min( (USL − X̄) / (3s) , (X̄ − LSL) / (3s) )\\n\\nwhere s = √[ Σ(xᵢ − X̄)² / (N−1) ]   (overall standard deviation of all N individuals)\" },\n\n        { type: \"h\", text: \"Minimum capability requirements\" },\n        { type: \"table\", head: [\"Situation\", \"Minimum Cpk\", \"Rationale\"], rows: [\n          [\"Existing process, normal production\", \"≥ 1.33\", \"Four-sigma coverage on each side; widely accepted industry standard\"],\n          [\"New process or new equipment\", \"≥ 1.67\", \"Higher standard because the process will drift over time\"],\n          [\"Safety-critical or key characteristic\", \"≥ 1.67 to 2.00\", \"Near-zero risk of nonconformance; automotive and aerospace requirement\"],\n          [\"Process not in control\", \"Not valid\", \"Capability indices are meaningless unless the process is in statistical control\"],\n        ] },\n        { type: \"callout\", tone: \"warning\", title: \"Control before capability\", text: \"Never calculate Cp and Cpk from data that contain special causes. First bring the process into statistical control by removing assignable causes. Only then does the within-subgroup estimate of sigma represent the true common-cause variation.\" },\n\n        { type: \"h\", text: \"Capability for non-normal data\" },\n        { type: \"p\", text: \"The standard Cp/Cpk formulas assume the process data follow a normal distribution. When the data are skewed (e.g. surface roughness, cycle times, particle counts), the formulas overestimate or underestimate the actual tail proportions. Options include:\" },\n        { type: \"list\", items: [\n          \"**Transform the data:** apply a Box-Cox transformation (e.g. logarithm) to make the data approximately normal, then calculate capability on the transformed scale.\",\n          \"**Fit a non-normal distribution:** use a Weibull, lognormal or other distribution and calculate equivalent tail proportions.\",\n          \"**Use empirical percentiles:** estimate the 0.135th and 99.865th percentiles from a large data set and compare them to the specification limits.\",\n        ] },\n\n        { type: \"equip\", title: \"Process capability study output\", items: [\n          { art: \"stat-capability\", caption: \"A capability study output shows the histogram of the data overlaid with a fitted normal curve, the specification limits (LSL and USL), and the calculated indices. The expected PPM (parts per million) nonconforming above and below each limit is also reported.\",\n            specs: [\n              { label: \"Cp\", value: \"Potential capability (spread only)\" },\n              { label: \"Cpk\", value: \"Actual capability (spread + centering)\" },\n              { label: \"Pp / Ppk\", value: \"Performance indices using overall sigma\" },\n              { label: \"PPM\", value: \"Expected parts per million nonconforming\" },\n            ] },\n        ] },\n\n        { type: \"capability\", id: \"aqe-m4-l4-cap\", title: \"Cpk simulator: bearing inner diameter\", task: \"A bearing inner diameter has LSL = 24.98 mm and USL = 25.02 mm. The process currently has a mean of 25.005 mm and sigma of 0.005 mm. Adjust the mean and sigma to achieve Cpk ≥ 1.33.\", hint: \"Cpk = min((USL − mean)/(3σ), (mean − LSL)/(3σ)). Centre the process and reduce sigma.\", unit: \"mm\", lsl: 24.98, usl: 25.02, mean: 25.005, sigma: 0.005, adjust: [\"mean\", \"sigma\"], goal: 1.33, meanRange: [24.98, 25.02], sigmaRange: [0.001, 0.010] },\n\n        { type: \"sheet\", id: \"aqe-m4-l4-sheet\", title: \"Calculate Cp and Cpk from data\", task: \"A shaft has LSL = 19.95 mm and USL = 20.05 mm. From 25 subgroups of 5, the quality engineer found X̄̄ = 20.008 mm and R̄ = 0.032 mm. Using d₂ = 2.326, calculate σ̂, Cp and Cpk.\", hint: \"σ̂ = R̄ / d₂. Cp = (USL − LSL) / (6σ̂). Cpk = min of (USL − X̄̄)/(3σ̂) and (X̄̄ − LSL)/(3σ̂).\",\n          data: [\n            [\"Parameter\", \"Value\"],\n            [\"USL (mm)\", 20.05],\n            [\"LSL (mm)\", 19.95],\n            [\"X̄̄ (mm)\", 20.008],\n            [\"R̄ (mm)\", 0.032],\n            [\"d₂\", 2.326],\n            [\"σ̂ (mm)\", null],\n            [\"Cp\", null],\n            [\"Cpu\", null],\n            [\"Cpl\", null],\n            [\"Cpk\", null],\n          ],\n          editable: [\"B7\", \"B8\", \"B9\", \"B10\", \"B11\"],\n          checks: [\n            { cell: \"B7\", equals: 0.01375, tol: 0.0005 },\n            { cell: \"B8\", equals: 2.42, tol: 0.05 },\n            { cell: \"B9\", equals: 1.02, tol: 0.05 },\n            { cell: \"B10\", equals: 1.41, tol: 0.05 },\n            { cell: \"B11\", equals: 1.02, tol: 0.05 },\n          ],\n          solution: {\n            B7: \"=B5/B6\",\n            B8: \"=(B2-B3)/(6*B7)\",\n            B9: \"=(B2-B4)/(3*B7)\",\n            B10: \"=(B4-B3)/(3*B7)\",\n            B11: \"=MIN(B9,B10)\",\n          },\n        },\n\n        { type: \"equip\", items: [\n          { art: \"stat-normality\", caption: \"Before running a capability study, verify that the data are approximately normal using a normal probability plot. Points should fall close to the fitted straight line; a significant Anderson-Darling or Shapiro-Wilk test (p < 0.05) suggests non-normality.\",\n            specs: [\n              { label: \"If normal\", value: \"Use standard Cp/Cpk formulas\" },\n              { label: \"If non-normal\", value: \"Transform, fit a distribution, or use percentile method\" },\n            ] },\n        ] },\n\n        { type: \"check\", id: \"aqe-m4-l4-ck1\", question: \"A process has Cp = 1.50 and Cpk = 0.85. What does this tell you?\", options: [\n          \"The process is capable and centred\",\n          \"The process spread fits the tolerance but the mean is off-centre\",\n          \"The process is out of control\",\n          \"The specification limits are wrong\",\n        ], answer: 1, explain: \"Cp = 1.50 means the tolerance is 9σ wide, which is more than enough. But Cpk = 0.85 means the mean is shifted toward one limit so that the nearest limit is only 2.55σ away. The process needs recentring.\" },\n\n        { type: \"check\", id: \"aqe-m4-l4-ck2\", question: \"Why must a process be in statistical control before calculating Cp and Cpk?\", options: [\n          \"Because out-of-control processes always fail capability\",\n          \"Because the within-subgroup sigma estimate is valid only when no special causes inflate it\",\n          \"Because specification limits change when the process is out of control\",\n          \"Because Cp requires at least 100 data points\",\n        ], answer: 1, explain: \"Capability indices use σ̂ = R̄/d₂, which estimates only common-cause variation. If special causes are present, the data mix common and special-cause variation, and the sigma estimate does not represent the inherent process spread.\" },\n      ],\n    },\n\n    // ───────────────────────────── LESSON 5 ─────────────────────────────\n    {\n      id: \"aqe-m4-l5\",\n      title: \"Advanced SPC: pre-control, short runs and process improvement\",\n      minutes: 25,\n      objectives: [\n        \"Apply pre-control (stoplight) rules for quick set-up verification\",\n        \"Use standardised control charts for short production runs\",\n        \"Link SPC to process improvement and the control plan\",\n      ],\n      blocks: [\n        { type: \"h\", text: \"Pre-control (stoplight control)\" },\n        { type: \"p\", text: \"Pre-control is a simple technique for monitoring short runs or verifying a set-up. It divides the specification range into three coloured zones using the specification limits and the tolerance midpoint, not the process data.\" },\n        { type: \"table\", head: [\"Zone\", \"Boundaries\", \"Colour\", \"Rule\"], rows: [\n          [\"Green\", \"Middle 50% of the tolerance\", \"Green\", \"Continue running\"],\n          [\"Yellow\", \"Outer 25% on each side (between green and the spec limit)\", \"Yellow\", \"Warning: two consecutive yellows on the same side → adjust\"],\n          [\"Red\", \"Beyond the specification limit\", \"Red\", \"Stop and adjust immediately\"],\n        ] },\n        { type: \"code\", text: \"Tolerance = USL − LSL\\nGreen zone: from (LSL + 0.25 × Tol) to (USL − 0.25 × Tol)\\nYellow zone: LSL to green boundary, and green boundary to USL\\n\\nExample: shaft Ø20.00 ± 0.05 mm  →  LSL = 19.95, USL = 20.05, Tol = 0.10 mm\\n  Green:  19.975 to 20.025\\n  Yellow: 19.95 to 19.975  and  20.025 to 20.05\\n  Red:    below 19.95 or above 20.05\" },\n        { type: \"list\", items: [\n          \"**Set-up qualification:** measure 5 consecutive parts. All 5 must be in the green zone to start production.\",\n          \"**During production:** sample 2 consecutive parts periodically. Both green → continue. One yellow → continue but watch. Two yellows on the same side → adjust toward centre. Any red → stop and investigate.\",\n          \"**Advantages:** no calculations, no charts, easy to train operators. Works well for short runs where there is no time to collect 20+ subgroups.\",\n          \"**Limitation:** pre-control requires that the process is already capable (Cpk ≥ 1.0 minimum, ideally ≥ 1.33). It is not a substitute for SPC but a complement for set-up approval.\",\n        ] },\n        { type: \"callout\", tone: \"tip\", title: \"When to use pre-control\", text: \"Pre-control is ideal for job shops and CNC operations with frequent set-ups and short runs (50 to 500 pieces). Use it to qualify the set-up quickly and switch to SPC charts once enough data have accumulated for proper control limits.\" },\n\n        { type: \"h\", text: \"Short-run SPC\" },\n        { type: \"p\", text: \"In short production runs, you may not have 20+ subgroups of one part number to calculate control limits. **Standardised (deviation from nominal) charts** solve this by plotting the deviation of each measurement from the nominal rather than the raw value. This lets you combine data from different part numbers on one chart, provided the processes have similar variation.\" },\n        { type: \"code\", text: \"Standardised value:  zᵢ = (xᵢ − nominal) / σ̂_reference\\n\\nFor X̄ chart: plot (X̄ᵢ − target) / (σ̂ / √n)\\nFor R chart: plot Rᵢ / R̄_reference\\n\\nThe limits on the standardised chart are ±A₂ (for the X̄ chart) and 0, D₃, D₄ (for the R chart).\" },\n        { type: \"list\", items: [\n          \"**DNOM chart (deviation from nominal):** plot xᵢ − nominal. All part numbers share the same chart; the centre line is zero.\",\n          \"**Standardised chart:** divide by a reference sigma so all part numbers have the same scale. Useful when part numbers have different tolerances.\",\n          \"**Target chart:** the X̄ chart centre line is the target, and each lot's deviation is tracked against it.\",\n        ] },\n\n        { type: \"h\", text: \"SPC for process improvement\" },\n        { type: \"p\", text: \"Control charts are not just alarm systems. They are powerful improvement tools. The strategy has two phases:\" },\n        { type: \"steps\", title: \"Two-phase improvement\", items: [\n          \"**Phase 1 — Bring the process into control:** identify and remove special causes one by one. Each time a signal appears, investigate, find the root cause, and put a permanent fix in place. Recalculate the limits after removing the special cause. Continue until all points fall within the limits and pass the run tests.\",\n          \"**Phase 2 — Reduce common-cause variation:** once the process is stable, work on fundamental changes to reduce the inherent spread: better raw materials, tighter machine maintenance, improved tooling, operator training, environmental controls. Each improvement reduces σ and tightens the control limits.\",\n          \"**Centre the process:** if Cp is adequate but Cpk is not, adjust the process mean to the target. This is often the quickest capability gain.\",\n          \"**Hold the gains:** update the control plan with the new SPC parameters, reaction plan and revised limits. Train all operators.\",\n        ] },\n        { type: \"callout\", tone: \"key\", title: \"Control plan connection\", text: \"Every SPC chart in the factory should correspond to a line in the **control plan**: which characteristic is monitored, what chart type is used, what sample size and frequency, who plots it, what the reaction plan is when a signal appears, and who is notified. Without a control plan link, SPC is an isolated exercise.\" },\n\n        { type: \"form\", id: \"aqe-m4-l5-form\", title: \"Apply pre-control rules\", task: \"A shaft has a specification of 20.00 ± 0.05 mm (LSL = 19.95, USL = 20.05). Determine the green zone boundaries and the correct action for each situation.\",\n          fields: [\n            { kind: \"text\", label: \"Lower green boundary (mm)\", accept: [\"19.975\"], placeholder: \"e.g. 19.975\", explain: \"Green zone starts at LSL + 0.25 × Tolerance = 19.95 + 0.25 × 0.10 = 19.975 mm.\" },\n            { kind: \"text\", label: \"Upper green boundary (mm)\", accept: [\"20.025\"], placeholder: \"e.g. 20.025\", explain: \"Green zone ends at USL − 0.25 × Tolerance = 20.05 − 0.25 × 0.10 = 20.025 mm.\" },\n            { kind: \"select\", label: \"Two consecutive parts measure 20.035 and 20.042 mm. Action?\", options: [\"Continue running\", \"Adjust the process toward centre\", \"Stop and investigate\"], answer: 1, explain: \"Both parts are in the yellow zone on the same side (above 20.025 but below 20.05). The rule says: two yellows on the same side → adjust toward the centre.\" },\n            { kind: \"select\", label: \"A part measures 19.943 mm. Action?\", options: [\"Continue running\", \"Adjust the process toward centre\", \"Stop and investigate\"], answer: 2, explain: \"19.943 is below LSL (19.95), so it is in the red zone. The rule says: stop and investigate immediately.\" },\n          ],\n          hint: \"The green zone is the middle 50% of the tolerance. Calculate: LSL + 25% of tolerance and USL − 25% of tolerance.\" },\n\n        { type: \"sheet\", id: \"aqe-m4-l5-sheet\", title: \"Standardised values for short-run SPC\", task: \"Three different shaft diameters are produced on the same CNC lathe. Convert each measurement to a deviation from nominal, then to a standardised value using the reference σ = 0.008 mm.\", hint: \"Deviation = measurement − nominal. Standardised = deviation / σ_ref.\",\n          data: [\n            [\"Part\", \"Nominal (mm)\", \"Measurement (mm)\", \"Deviation (mm)\", \"Standardised\"],\n            [\"A\", 20.000, 20.006, null, null],\n            [\"B\", 25.000, 24.992, null, null],\n            [\"C\", 30.000, 30.011, null, null],\n            [\"A\", 20.000, 19.997, null, null],\n            [\"B\", 25.000, 25.004, null, null],\n            [\"\", \"σ_ref =\", 0.008, \"\", \"\"],\n          ],\n          editable: [\"D2\", \"E2\", \"D3\", \"E3\", \"D4\", \"E4\", \"D5\", \"E5\", \"D6\", \"E6\"],\n          checks: [\n            { cell: \"D2\", equals: 0.006, tol: 0.001 },\n            { cell: \"E2\", equals: 0.75, tol: 0.05 },\n            { cell: \"D3\", equals: -0.008, tol: 0.001 },\n            { cell: \"E3\", equals: -1.0, tol: 0.05 },\n            { cell: \"D4\", equals: 0.011, tol: 0.001 },\n            { cell: \"E4\", equals: 1.375, tol: 0.05 },\n            { cell: \"D5\", equals: -0.003, tol: 0.001 },\n            { cell: \"E5\", equals: -0.375, tol: 0.05 },\n            { cell: \"D6\", equals: 0.004, tol: 0.001 },\n            { cell: \"E6\", equals: 0.5, tol: 0.05 },\n          ],\n          solution: {\n            D2: \"=C2-B2\",\n            E2: \"=D2/0.008\",\n          },\n        },\n\n        { type: \"check\", id: \"aqe-m4-l5-ck1\", question: \"What is the main advantage of pre-control over traditional SPC charts?\", options: [\n          \"Pre-control is more sensitive to small shifts\",\n          \"Pre-control does not require calculations or a charting system\",\n          \"Pre-control works on any process regardless of capability\",\n          \"Pre-control provides better long-term monitoring\",\n        ], answer: 1, explain: \"Pre-control is designed for simplicity: three coloured zones based on the specification, no formulas, no charts. It is ideal for short runs and set-up verification but less sensitive than control charts for detecting small sustained shifts.\" },\n\n        { type: \"check\", id: \"aqe-m4-l5-ck2\", question: \"Why does a standardised short-run SPC chart use the deviation from nominal rather than the raw measurement?\", options: [\n          \"To make the chart look cleaner\",\n          \"To reduce the number of decimal places\",\n          \"To allow different part numbers with different nominals to share one chart\",\n          \"To eliminate the need for control limits\",\n        ], answer: 2, explain: \"By subtracting each part number's nominal, all deviations share a common zero reference and can be plotted on a single chart, even though the parts have different target dimensions.\" },\n      ],\n    },\n\n    // ───────────────────────────── PRACTICE ──────────────────────────────\n    {\n      id: \"aqe-m4-practice\",\n      title: \"Practice: SPC and Process Capability\",\n      minutes: 30,\n      objectives: [\n        \"Construct and interpret I-MR, X̄-R and p charts from realistic quality data\",\n        \"Use a capability simulator to centre and tighten a process to meet Cpk ≥ 1.33\",\n        \"Identify out-of-control signals and recommend corrective actions\",\n      ],\n      blocks: [\n        { type: \"p\", text: \"Apply what you have learnt about control charts and process capability to the following four exercises. Each exercise uses data from Cameroonian manufacturing scenarios.\" },\n\n        // beginner: I-MR chart\n        { type: \"spc\", id: \"aqe-m4-pr-imr\", level: \"beginner\", title: \"I-MR chart: brewery water pH\", task: \"Plot the I-MR chart for 20 hourly pH readings from the water treatment plant at Brasseries du Cameroun in Douala. Calculate the average, the average moving range, and the I chart control limits. Is the process in control?\", hint: \"X̄ = average of all values. MR̄ = average of consecutive absolute differences. UCL = X̄ + 2.660 × MR̄. All points should be within the limits for a stable process.\", chart: \"imr\", values: WATER_PH, askLimits: true },\n\n        // intermediate: X̄-R with out-of-control\n        { type: \"spc\", id: \"aqe-m4-pr-xbar\", level: \"intermediate\", title: \"X̄-R chart: cocoa butter content\", task: \"Analyse the X̄-R chart for 18 subgroups of 5 cocoa butter percentage readings from a Douala chocolate factory. Identify any subgroups that signal out-of-control conditions. What might have caused the unusual subgroups?\", hint: \"Look for subgroups where the X̄ is beyond the limits (subgroup 7: fermentation error) and where the range is unusually large (subgroup 15: mixing problem).\", chart: \"xbar-r\", unit: \"%\", decimals: 1, samples: COCOA, askBeyond: true },\n\n        // advanced: capability\n        { type: \"capability\", id: \"aqe-m4-pr-cap\", level: \"advanced\", title: \"Centre and tighten: piston ring groove width\", task: \"A piston ring groove has LSL = 2.470 mm and USL = 2.530 mm. The current process runs with mean = 2.510 mm and sigma = 0.012 mm, giving a Cpk well below the 1.33 target. Adjust the mean and sigma until Cpk ≥ 1.33.\", hint: \"First centre the mean at the midpoint of the tolerance (2.500 mm). Then reduce sigma until the Cpk formula gives at least 1.33.\", unit: \"mm\", lsl: 2.470, usl: 2.530, mean: 2.510, sigma: 0.012, adjust: [\"mean\", \"sigma\"], goal: 1.33, meanRange: [2.470, 2.530], sigmaRange: [0.002, 0.015] },\n\n        // expert: p chart with question\n        { type: \"spc\", id: \"aqe-m4-pr-pchart\", level: \"expert\", title: \"p chart: bottle cap seal failures\", task: \"Construct a p chart for 20 samples of 200 bottle caps inspected for seal integrity. Identify any out-of-control samples. Then answer the question about process stability.\", hint: \"Calculate p̄ from total defectives / total inspected. Sample 12 shows a spike (new seal liner supplier). Consider whether the process is stable overall or only after excluding the special cause.\", chart: \"p\", defectives: CAPS_DEF, sampleSize: CAPS_N, question: { question: \"After investigating sample 12 and switching back to the original supplier, is the remaining process stable?\", options: [\"Yes — all other samples are within the recalculated limits\", \"No — there is a trend in the remaining data\", \"Cannot determine without more data\", \"No — the average proportion is too high\"], answer: 0, explain: \"Excluding the special cause in sample 12, the remaining 19 samples show no points beyond the recalculated limits and no non-random patterns. The process is stable at the common-cause level.\" } },\n      ],\n    },\n  ],\n\n  // ────────────────────────────── QUIZ ──────────────────────────────────\n  quiz: {\n    id: \"aqe-m4-quiz\",\n    title: \"Module 4 Quiz: SPC and Process Capability\",\n    passPct: 75,\n    questions: [\n      {\n        id: \"aqe-m4-q1\",\n        question: \"For an X̄-R chart with subgroup size n = 5, the constant A₂ is 0.577. If X̄̄ = 50.00 and R̄ = 4.00, what is the UCL of the X̄ chart?\",\n        options: [\"52.31\", \"52.00\", \"54.00\", \"50.58\"],\n        answer: 0,\n        explain: \"UCL = X̄̄ + A₂ × R̄ = 50.00 + 0.577 × 4.00 = 52.308, rounded to 52.31.\",\n      },\n      {\n        id: \"aqe-m4-q2\",\n        question: \"Which attribute control chart is appropriate when you count the number of paint defects on car bodies of the same size?\",\n        options: [\"p chart\", \"np chart\", \"c chart\", \"u chart\"],\n        answer: 2,\n        explain: \"You are counting individual defects (not nonconforming items) on a constant area of opportunity (same size body). This is the c chart.\",\n      },\n      {\n        id: \"aqe-m4-q3\",\n        question: \"Nine consecutive points fall below the centre line of an X̄ chart but within the control limits. Which Nelson rule is violated?\",\n        options: [\"Rule 1: point beyond 3σ\", \"Rule 2: 9 points on the same side\", \"Rule 3: 6-point trend\", \"Rule 4: 14 alternating points\"],\n        answer: 1,\n        explain: \"Rule 2 states that 9 or more consecutive points on the same side of the centre line indicate a sustained shift in the process mean.\",\n      },\n      {\n        id: \"aqe-m4-q4\",\n        question: \"A process has USL = 30 mm, LSL = 20 mm, X̄̄ = 26 mm and σ̂ = 1.5 mm. What is Cpk?\",\n        options: [\"1.11\", \"0.89\", \"1.33\", \"1.00\"],\n        answer: 1,\n        explain: \"Cpu = (30 − 26) / (3 × 1.5) = 4 / 4.5 = 0.889. Cpl = (26 − 20) / (3 × 1.5) = 6 / 4.5 = 1.333. Cpk = min(0.889, 1.333) = 0.89.\",\n      },\n      {\n        id: \"aqe-m4-q5\",\n        question: \"What is the minimum Cpk typically required for a new process or new equipment?\",\n        options: [\"1.00\", \"1.33\", \"1.67\", \"2.00\"],\n        answer: 2,\n        explain: \"For new processes or new equipment, the typical minimum is Cpk ≥ 1.67 (5σ on each side), because the process will likely drift over time.\",\n      },\n      {\n        id: \"aqe-m4-q6\",\n        question: \"In pre-control (stoplight method), two consecutive measurements fall in the yellow zone on the same side. What is the correct action?\",\n        options: [\"Continue running\", \"Adjust the process toward the centre\", \"Stop and investigate immediately\", \"Switch to an X̄-R chart\"],\n        answer: 1,\n        explain: \"Two consecutive yellows on the same side mean the process is drifting toward a specification limit. The operator should adjust the process toward the centre of the tolerance.\",\n      },\n      {\n        id: \"aqe-m4-q7\",\n        question: \"What does a large gap between Cp and Pp (Cp significantly higher than Pp) indicate?\",\n        options: [\"The specification limits are set too wide\", \"Special causes are inflating the overall variation\", \"The process is perfectly centred\", \"The data are not normally distributed\"],\n        answer: 1,\n        explain: \"Cp uses within-subgroup sigma (common cause only) while Pp uses overall sigma (common + special cause). When special causes are present, overall sigma is larger, so Pp < Cp.\",\n      },\n      {\n        id: \"aqe-m4-q8\",\n        question: \"Why does short-run SPC use the deviation from nominal rather than the raw measurement?\",\n        options: [\"To reduce calculation errors\", \"To eliminate the need for control limits\", \"To allow multiple part numbers to share one chart\", \"To compensate for non-normal data\"],\n        answer: 2,\n        explain: \"By subtracting each part number’s nominal value, all deviations have a common zero reference. This allows data from different part numbers produced on the same machine to be plotted on a single control chart.\",\n      },\n    ],\n  },\n};\n","client/src/data/courses/aqe/m5.ts":"import type { CourseModule } from \"../../../lms/types\";\n\nexport const m5: CourseModule = {\n  id: \"aqe-m5\",\n  number: 5,\n  title: \"Design of Experiments\",\n  hours: 16,\n  summary:\n    \"This module introduces the principles and practice of Design of Experiments (DOE) for quality engineering. Learners progress from understanding why factorial designs surpass one-factor-at-a-time approaches, through constructing and analysing full 2^k factorial designs, to using fractional factorials and screening designs when resources are limited. The module then covers response surface methodology for process optimisation, including central composite and Box-Behnken designs. Throughout, practical planning, execution and confirmation of experiments are emphasised, with realistic manufacturing scenarios drawn from Cameroonian industry.\",\n  lessons: [\n    // ===== LESSON 1 =====\n    {\n      id: \"aqe-m5-l1\",\n      number: 1,\n      title: \"Experiment planning and one-factor-at-a-time vs factorial\",\n      duration: 25,\n      objectives: [\n        \"Explain why structured experimentation is superior to trial-and-error approaches\",\n        \"Compare one-factor-at-a-time (OFAT) with factorial experiment designs\",\n        \"Define key DOE terminology including factor, level, response, treatment, replicate, block and randomisation\",\n      ],\n      blocks: [\n        {\n          type: \"h\",\n          text: \"Why Run Experiments?\",\n        },\n        {\n          type: \"p\",\n          text: \"Every manufacturing process has variables that affect output quality. A brewery in Douala wants to maximise the carbonation level in its lager. A cement plant in Figuil needs to achieve target compressive strength whilst minimising energy consumption. A machining workshop in Yaoundé must reduce bore diameter variation. In each case, engineers must determine which process settings produce the best results. Design of Experiments provides a systematic, statistically rigorous framework for answering these questions efficiently.\",\n        },\n        {\n          type: \"list\",\n          items: [\n            \"Optimise processes: find the factor settings that yield the best response\",\n            \"Reduce variation: identify and control the sources of unwanted variability\",\n            \"Solve problems: determine root causes by testing competing hypotheses simultaneously\",\n            \"Build knowledge: quantify how factors and their interactions affect the response\",\n          ],\n        },\n        {\n          type: \"h\",\n          text: \"OFAT vs Factorial Approaches\",\n        },\n        {\n          type: \"p\",\n          text: \"The traditional approach is one-factor-at-a-time (OFAT): hold everything constant, vary one factor, find its best level, then move to the next factor. This seems logical but has a critical flaw — it cannot detect interactions between factors. If the effect of temperature on cement strength depends on the water-to-cement ratio, OFAT will miss this entirely.\",\n        },\n        {\n          type: \"table\",\n          head: [\"Criterion\", \"OFAT\", \"Factorial\"],\n          rows: [\n            [\"Detects interactions\", \"No\", \"Yes\"],\n            [\"Number of runs (k factors, 2 levels)\", \"2k + 1 (sequential)\", \"2^k (all combinations)\"],\n            [\n              \"Efficiency\",\n              \"Low — each run tests only one factor\",\n              \"High — every run provides information on all factors\",\n            ],\n            [\"Validity of conclusions\", \"Only at fixed levels of other factors\", \"Across the full design space\"],\n            [\"Risk of misleading results\", \"High if interactions exist\", \"Low — interactions are estimated\"],\n          ],\n        },\n        {\n          type: \"callout\",\n          tone: \"key\",\n          title: \"The Interaction Problem\",\n          text: \"When factors interact, the best level of one factor depends on the level of another. OFAT finds the best level of Factor A at a single, possibly suboptimal, level of Factor B. A factorial design tests all combinations and reveals the true optimum.\",\n        },\n        {\n          type: \"h\",\n          text: \"DOE Terminology\",\n        },\n        {\n          type: \"table\",\n          head: [\"Term\", \"Definition\", \"Example\"],\n          rows: [\n            [\"Factor\", \"A controllable variable under investigation\", \"Kiln temperature, grinding time\"],\n            [\"Level\", \"A specific value or setting of a factor\", \"Low (850°C), High (950°C)\"],\n            [\"Response\", \"The measured outcome of interest\", \"Compressive strength (MPa)\"],\n            [\"Treatment\", \"A specific combination of factor levels\", \"Temperature = High, Time = Low\"],\n            [\"Replicate\", \"An independent repeat of a treatment combination\", \"Running the same settings on a separate batch\"],\n            [\"Block\", \"A group of runs performed under similar conditions\", \"Morning shift vs afternoon shift\"],\n            [\"Randomisation\", \"Running treatments in random order to avoid bias\", \"Using a random number table to set run order\"],\n          ],\n        },\n        {\n          type: \"h\",\n          text: \"The Experiment Planning Process\",\n        },\n        {\n          type: \"steps\",\n          title: \"Six Steps to a Successful Experiment\",\n          items: [\n            \"Define the objective: state clearly what you want to learn or optimise\",\n            \"Select factors and levels: choose the most important variables and their test ranges\",\n            \"Choose the design: select full factorial, fractional factorial, or other appropriate design\",\n            \"Execute the experiment: run treatments in randomised order, collect data carefully\",\n            \"Analyse results: calculate effects, check significance, build a model\",\n            \"Confirm findings: run confirmation trials at the predicted optimal settings\",\n          ],\n        },\n        {\n          type: \"callout\",\n          tone: \"workplace\",\n          title: \"Planning at Cimencam\",\n          text: \"At Cimencam’s Figuil plant, the quality team planning a DOE on clinker formation first held a brainstorming session with operators, maintenance staff and the process engineer. They identified 12 potential factors, then used Pareto voting to narrow these to the 4 most likely to influence compressive strength. This collaborative approach ensured buy-in and prevented important factors from being overlooked.\",\n        },\n        {\n          type: \"check\",\n          id: \"aqe-m5-chk-01\",\n          question:\n            \"A brewery engineer varies mashing temperature from 62°C to 68°C while keeping all other factors constant, records the extract yield, then repeats the process for mash duration. What method is this?\",\n          options: [\n            \"Full factorial design\",\n            \"One-factor-at-a-time (OFAT)\",\n            \"Fractional factorial design\",\n            \"Response surface methodology\",\n          ],\n          answer: 1,\n          explain:\n            \"This is OFAT because the engineer varies one factor at a time while holding others constant. A factorial design would test all combinations of temperature and duration simultaneously.\",\n        },\n        {\n          type: \"equip\",\n          title: \"DOE Software and Tools\",\n          items: [\n            {\n              art: \"🧪\",\n              name: \"DOE Analysis Toolkit\",\n              caption: \"Software for designing experiments, generating run orders, calculating effects and producing interaction plots. Essential for factorial and fractional factorial analysis.\",\n            },\n          ],\n        },\n        {\n          type: \"form\",\n          id: \"aqe-m5-lab-01\",\n          title: \"DOE Terminology Match\",\n          task: \"For each description, select the correct DOE term.\",\n          fields: [\n            {\n              kind: \"select\",\n              label: \"A controllable process variable such as kiln temperature or grinding time\",\n              options: [\"Response\", \"Factor\", \"Replicate\", \"Block\"],\n              answer: 1,\n              explain: \"A factor is a controllable variable that the experimenter deliberately changes.\",\n            },\n            {\n              kind: \"select\",\n              label: \"Running the same treatment combination independently a second time to estimate error\",\n              options: [\"Block\", \"Treatment\", \"Replicate\", \"Level\"],\n              answer: 2,\n              explain:\n                \"A replicate is an independent repeat of a treatment. It provides an estimate of experimental error.\",\n            },\n            {\n              kind: \"select\",\n              label: \"Grouping runs performed on the same day to account for day-to-day variation\",\n              options: [\"Randomisation\", \"Replicate\", \"Factor\", \"Block\"],\n              answer: 3,\n              explain:\n                \"A block is a group of homogeneous experimental units. Blocking removes known sources of nuisance variation.\",\n            },\n            {\n              kind: \"select\",\n              label: \"The specific combination Temperature = 950°C, Time = 45 min\",\n              options: [\"Level\", \"Factor\", \"Treatment\", \"Response\"],\n              answer: 2,\n              explain:\n                \"A treatment (or treatment combination) is one specific set of factor levels tested together.\",\n            },\n          ],\n          hint: \"Each DOE term has a precise meaning. Think about what the experimenter controls versus what they measure.\",\n        },\n        {\n          type: \"sorter\",\n          id: \"aqe-m5-lab-02\",\n          title: \"Classify Experiment Elements\",\n          task: \"A cement plant is studying the effect of kiln temperature (850°C and 950°C) and raw meal fineness (3000 and 3500 cm²/g) on 28-day compressive strength (MPa). The experiment is run over two days, with each treatment repeated twice. Classify each element.\",\n          layout: \"columns\",\n          buckets: [\n            { label: \"Factor\" },\n            { label: \"Level\" },\n            { label: \"Response\" },\n            { label: \"Experimental structure\" },\n          ],\n          items: [\n            { text: \"Kiln temperature\", bucket: 0, explain: \"Temperature is a controllable variable being tested.\" },\n            {\n              text: \"850°C\",\n              bucket: 1,\n              explain: \"This is a specific setting (level) of the kiln temperature factor.\",\n            },\n            {\n              text: \"28-day compressive strength\",\n              bucket: 2,\n              explain: \"This is the measured outcome — the response variable.\",\n            },\n            {\n              text: \"Day 1 vs Day 2\",\n              bucket: 3,\n              explain: \"The two days form blocks — part of the experimental structure.\",\n            },\n            {\n              text: \"Raw meal fineness\",\n              bucket: 0,\n              explain: \"Fineness is the second controllable variable being investigated.\",\n            },\n            {\n              text: \"3500 cm²/g\",\n              bucket: 1,\n              explain: \"This is a specific setting (level) of the fineness factor.\",\n            },\n            {\n              text: \"Two independent batches per treatment\",\n              bucket: 3,\n              explain: \"These are replicates — part of the experimental structure for estimating error.\",\n            },\n          ],\n        },\n        {\n          type: \"links\",\n          items: [\n            {\n              label: \"NIST Engineering Statistics Handbook — Introduction to DOE\",\n              url: \"https://www.itl.nist.gov/div898/handbook/pri/pri.htm\",\n              source: \"NIST\",\n            },\n          ],\n        },\n      ],\n    },\n\n    // ===== LESSON 2 =====\n    {\n      id: \"aqe-m5-l2\",\n      number: 2,\n      title: \"Full factorial designs: 2² and 2³\",\n      duration: 35,\n      objectives: [\n        \"Construct and execute a 2² full factorial design with coded factor levels\",\n        \"Calculate main effects and interaction effects using the contrast matrix\",\n        \"Extend factorial analysis to 2³ designs and interpret three-factor interactions\",\n        \"Use normal probability plots to identify significant effects\",\n      ],\n      blocks: [\n        {\n          type: \"h\",\n          text: \"The 2² Factorial Design\",\n        },\n        {\n          type: \"p\",\n          text: \"The simplest factorial design studies two factors, each at two levels. We code the low level as −1 and the high level as +1. With two factors (A and B) at two levels each, there are 2² = 4 treatment combinations. Every combination of factor levels is tested, which is what makes it a full factorial.\",\n        },\n        {\n          type: \"p\",\n          text: \"Consider a brewery filling line in Douala optimising carbonation (measured in g/L CO₂). Factor A is carbonation pressure (low = 2.0 bar, high = 2.8 bar) and Factor B is beer temperature (low = 2°C, high = 6°C). Each treatment is replicated twice.\",\n        },\n        {\n          type: \"table\",\n          head: [\"Run\", \"A (Pressure)\", \"B (Temperature)\", \"AB\", \"Response y̅ (g/L CO₂)\"],\n          rows: [\n            [\"1\", \"−1\", \"−1\", \"+1\", \"5.1\"],\n            [\"2\", \"+1\", \"−1\", \"−1\", \"5.8\"],\n            [\"3\", \"−1\", \"+1\", \"−1\", \"4.4\"],\n            [\"4\", \"+1\", \"+1\", \"+1\", \"5.9\"],\n          ],\n        },\n        {\n          type: \"callout\",\n          tone: \"key\",\n          title: \"Contrast Matrix (Sign Table)\",\n          text: \"The AB column is calculated by multiplying the signs of A and B for each run. This sign table is the contrast matrix — it tells us how to combine the responses to estimate each effect. The column of signs for any effect shows which responses to add (+1) and which to subtract (−1).\",\n        },\n        {\n          type: \"h\",\n          text: \"Calculating Main Effects\",\n        },\n        {\n          type: \"p\",\n          text: \"The main effect of a factor is the average change in response when that factor moves from its low level to its high level. We use the contrast matrix columns as weights.\",\n        },\n        {\n          type: \"code\",\n          text: \"Main Effect of A = (1/2) × [(−1)(5.1) + (+1)(5.8) + (−1)(4.4) + (+1)(5.9)]\\n                 = (1/2) × [−5.1 + 5.8 − 4.4 + 5.9]\\n                 = (1/2) × 2.2\\n                 = 1.10 g/L CO₂\\n\\nMain Effect of B = (1/2) × [(−1)(5.1) + (−1)(5.8) + (+1)(4.4) + (+1)(5.9)]\\n                 = (1/2) × [−5.1 − 5.8 + 4.4 + 5.9]\\n                 = (1/2) × (−0.6)\\n                 = −0.30 g/L CO₂\",\n        },\n        {\n          type: \"p\",\n          text: \"Interpretation: increasing pressure from 2.0 to 2.8 bar increases carbonation by 1.10 g/L on average. Increasing temperature from 2°C to 6°C decreases carbonation by 0.30 g/L on average (as expected — CO₂ is more soluble at lower temperatures).\",\n        },\n        {\n          type: \"h\",\n          text: \"The Interaction Effect\",\n        },\n        {\n          type: \"code\",\n          text: \"Interaction AB = (1/2) × [(+1)(5.1) + (−1)(5.8) + (−1)(4.4) + (+1)(5.9)]\\n               = (1/2) × [5.1 − 5.8 − 4.4 + 5.9]\\n               = (1/2) × 0.8\\n               = 0.40 g/L CO₂\",\n        },\n        {\n          type: \"p\",\n          text: \"A positive AB interaction of 0.40 means that the effect of pressure is 0.40 g/L larger when temperature is high than when temperature is low. In other words, the two factors do not act independently — there is synergy between higher pressure and higher temperature. This interaction would be completely invisible in an OFAT study.\",\n        },\n        {\n          type: \"callout\",\n          tone: \"tip\",\n          title: \"Reading Interaction Plots\",\n          text: \"Plot the response on the y-axis against Factor A on the x-axis, with separate lines for each level of Factor B. If the lines are parallel, there is no interaction. If the lines cross or diverge, an interaction is present. The more the lines diverge, the stronger the interaction.\",\n        },\n        {\n          type: \"h\",\n          text: \"The 2³ Factorial Design\",\n        },\n        {\n          type: \"p\",\n          text: \"Adding a third factor C gives 2³ = 8 treatment combinations. We now estimate three main effects (A, B, C), three two-factor interactions (AB, AC, BC) and one three-factor interaction (ABC). The contrast matrix extends naturally: the ABC column is the product of all three factor columns.\",\n        },\n        {\n          type: \"p\",\n          text: \"A machining workshop in Yaoundé is optimising surface roughness (Ra, µm) of aluminium bushings. Factor A is cutting speed (80 vs 120 m/min), Factor B is feed rate (0.10 vs 0.20 mm/rev), and Factor C is depth of cut (0.5 vs 1.5 mm).\",\n        },\n        {\n          type: \"table\",\n          head: [\"Run\", \"A\", \"B\", \"C\", \"AB\", \"AC\", \"BC\", \"ABC\", \"Ra (µm)\"],\n          rows: [\n            [\"1\", \"−1\", \"−1\", \"−1\", \"+1\", \"+1\", \"+1\", \"−1\", \"1.2\"],\n            [\"2\", \"+1\", \"−1\", \"−1\", \"−1\", \"−1\", \"+1\", \"+1\", \"0.9\"],\n            [\"3\", \"−1\", \"+1\", \"−1\", \"−1\", \"+1\", \"−1\", \"+1\", \"2.1\"],\n            [\"4\", \"+1\", \"+1\", \"−1\", \"+1\", \"−1\", \"−1\", \"−1\", \"1.6\"],\n            [\"5\", \"−1\", \"−1\", \"+1\", \"+1\", \"−1\", \"−1\", \"+1\", \"1.5\"],\n            [\"6\", \"+1\", \"−1\", \"+1\", \"−1\", \"+1\", \"−1\", \"−1\", \"1.1\"],\n            [\"7\", \"−1\", \"+1\", \"+1\", \"−1\", \"−1\", \"+1\", \"−1\", \"2.6\"],\n            [\"8\", \"+1\", \"+1\", \"+1\", \"+1\", \"+1\", \"+1\", \"+1\", \"2.0\"],\n          ],\n        },\n        {\n          type: \"code\",\n          text: \"Main Effect of A (Speed) = (1/4) × [−1.2 + 0.9 − 2.1 + 1.6 − 1.5 + 1.1 − 2.6 + 2.0]\\n                         = (1/4) × (−1.8)\\n                         = −0.45 µm\\n\\nMain Effect of B (Feed)  = (1/4) × [−1.2 − 0.9 + 2.1 + 1.6 − 1.5 − 1.1 + 2.6 + 2.0]\\n                         = (1/4) × 3.6\\n                         = 0.90 µm\\n\\nMain Effect of C (Depth) = (1/4) × [−1.2 − 0.9 − 2.1 − 1.6 + 1.5 + 1.1 + 2.6 + 2.0]\\n                         = (1/4) × 1.4\\n                         = 0.35 µm\",\n        },\n        {\n          type: \"p\",\n          text: \"Higher cutting speed reduces roughness (−0.45 µm), higher feed rate increases roughness substantially (+0.90 µm), and greater depth of cut increases roughness moderately (+0.35 µm). Feed rate is the dominant factor.\",\n        },\n        {\n          type: \"h\",\n          text: \"Normal Probability Plot of Effects\",\n        },\n        {\n          type: \"p\",\n          text: \"With 7 effects to evaluate in a 2³ design, a normal probability plot helps distinguish real effects from noise. Plot the ordered effects against their expected normal scores. Effects that are just noise will fall on a straight line. Effects that stand out from the line are statistically significant. In our machining example, the main effect of B (feed rate) at 0.90 would be far from the line, confirming it is the dominant factor.\",\n        },\n        {\n          type: \"callout\",\n          tone: \"warning\",\n          title: \"Three-Factor Interactions\",\n          text: \"A significant ABC interaction means the two-factor interaction between any pair of factors changes depending on the level of the third factor. These are hard to interpret physically and are often small. If ABC is large, check for data errors or lurking variables before accepting it.\",\n        },\n        {\n          type: \"equip\",\n          title: \"Analysis Tools for Factorial Designs\",\n          items: [\n            {\n              art: \"📊\",\n              name: \"DOE Analysis Toolkit\",\n              caption: \"Used here for generating contrast matrices, computing effects, and producing normal probability plots and interaction plots.\",\n            },\n          ],\n        },\n        {\n          type: \"check\",\n          id: \"aqe-m5-chk-02\",\n          question:\n            \"In a 2² factorial with responses y₁ = 40, y₂ = 52, y₃ = 38, y₄ = 46 (standard order), what is the main effect of Factor A?\",\n          options: [\"10\", \"5\", \"−2\", \"3\"],\n          answer: 0,\n          explain:\n            \"Effect of A = (1/2)[(−40) + (52) + (−38) + (46)] = (1/2)(20) = 10. Using the contrast column for A: −1, +1, −1, +1.\",\n        },\n        {\n          type: \"sheet\",\n          id: \"aqe-m5-lab-03\",\n          title: \"Calculate 2² Factorial Effects\",\n          task: \"A Douala brewery tested two factors on dissolved CO₂ (g/L): A = carbonation pressure (2.0 vs 2.8 bar) and B = temperature (2°C vs 6°C). Calculate all effects from the data below. Enter effect values in the yellow cells.\",\n          data: [\n            [\"Run\", \"A\", \"B\", \"AB\", \"CO₂ (g/L)\", \"\", \"Effect\", \"Value\"],\n            [1, -1, -1, 1, 5.1, null, \"A\", null],\n            [2, 1, -1, -1, 5.8, null, \"B\", null],\n            [3, -1, 1, -1, 4.4, null, \"AB\", null],\n            [4, 1, 1, 1, 5.9, null, \"\", null],\n          ],\n          editable: [\"H2\", \"H3\", \"H4\"],\n          checks: [\n            { cell: \"H2\", equals: 1.1, tol: 0.05 },\n            { cell: \"H3\", equals: -0.3, tol: 0.05 },\n            { cell: \"H4\", equals: 0.4, tol: 0.05 },\n          ],\n          hint: \"Multiply each response by its contrast column sign, sum, then divide by n/2 where n = 4 runs. For A: (1/2)[−5.1 + 5.8 − 4.4 + 5.9].\",\n          solution: {\n            H2: \"1.1\",\n            H3: \"-0.3\",\n            H4: \"0.4\",\n          },\n        },\n        {\n          type: \"form\",\n          id: \"aqe-m5-lab-04\",\n          title: \"Interpret Interaction Plots\",\n          task: \"Based on the brewery 2² factorial results (Effect A = 1.10, Effect B = −0.30, Effect AB = 0.40), answer the following interpretation questions.\",\n          fields: [\n            {\n              kind: \"select\",\n              label: \"Which factor has the largest effect on carbonation?\",\n              options: [\n                \"Factor B (temperature)\",\n                \"Factor A (pressure)\",\n                \"The AB interaction\",\n                \"All effects are equal\",\n              ],\n              answer: 1,\n              explain:\n                \"Factor A has an effect of 1.10 g/L, which is larger in magnitude than B (−0.30) or AB (0.40).\",\n            },\n            {\n              kind: \"select\",\n              label: \"If the interaction plot lines cross, what does this indicate?\",\n              options: [\n                \"No interaction exists\",\n                \"The main effects are both significant\",\n                \"The effect of one factor depends on the level of the other\",\n                \"The experiment has too much noise\",\n              ],\n              answer: 2,\n              explain:\n                \"Crossing lines on an interaction plot indicate that the effect of one factor changes depending on the level of the other — a clear sign of interaction.\",\n            },\n            {\n              kind: \"select\",\n              label: \"The positive AB interaction (+0.40) means the effect of pressure is:\",\n              options: [\n                \"0.40 g/L smaller at high temperature\",\n                \"0.40 g/L larger at high temperature\",\n                \"The same at both temperatures\",\n                \"Reversed at high temperature\",\n              ],\n              answer: 1,\n              explain:\n                \"A positive AB interaction means that moving pressure from low to high increases carbonation more when temperature is at its high level than at its low level.\",\n            },\n          ],\n          hint: \"Remember: the interaction effect measures how much the effect of one factor changes across levels of the other.\",\n        },\n        {\n          type: \"links\",\n          items: [\n            {\n              label: \"Montgomery — Design and Analysis of Experiments (Chapter 5)\",\n              url: \"https://www.wiley.com/en-us/Design+and+Analysis+of+Experiments\",\n              source: \"Wiley\",\n            },\n          ],\n        },\n      ],\n    },\n\n    // ===== LESSON 3 =====\n    {\n      id: \"aqe-m5-l3\",\n      title: \"Fractional factorial and screening designs\",\n      minutes: 30,\n      objectives: [\n        \"Explain why fractional factorial designs are needed when the number of factors is large\",\n        \"Construct a 2^(k−p) fractional factorial using generators and the defining relation\",\n        \"Distinguish between Resolution III, IV and V designs and their estimation capabilities\",\n        \"Interpret the aliasing structure to determine what is confounded\",\n      ],\n      blocks: [\n        {\n          type: \"h\",\n          text: \"Why Fractionate?\",\n        },\n        {\n          type: \"p\",\n          text: \"A full factorial with 6 factors at 2 levels requires 2⁶ = 64 runs. With 7 factors it is 128 runs. For a cement plant studying kiln temperature, raw meal fineness, fuel rate, kiln speed, fan damper position, moisture content and clinker cooler speed, running 128 treatments with replicates is often impractical. Fractional factorial designs run only a carefully chosen fraction of the full factorial — one-half, one-quarter, or even one-eighth — while still estimating the most important effects.\",\n        },\n        {\n          type: \"callout\",\n          tone: \"key\",\n          title: \"The Sparsity of Effects Principle\",\n          text: \"Most real processes are dominated by a small number of main effects and low-order interactions. Higher-order interactions (three-factor and above) are usually negligible. Fractional factorials exploit this by confounding (aliasing) higher-order interactions with lower-order effects, sacrificing information we probably do not need.\",\n        },\n        {\n          type: \"h\",\n          text: \"Building a 2^(k−p) Design\",\n        },\n        {\n          type: \"p\",\n          text: \"A 2^(k−p) design studies k factors in 2^(k−p) runs. The fraction is 1/2^p of the full factorial. To construct it, we start with a full factorial in (k−p) basic factors and use generators to assign levels to the remaining p factors. Each generator sets one additional factor equal to an interaction of the basic factors.\",\n        },\n        {\n          type: \"p\",\n          text: \"Example: a 2^(3−1) design studies 3 factors in 4 runs (half of the full 2³). We start with a full 2² in factors A and B, then set C = AB (the generator). This means C’s column of signs is the product of the A and B columns.\",\n        },\n        {\n          type: \"table\",\n          head: [\"Run\", \"A\", \"B\", \"C = AB\"],\n          rows: [\n            [\"1\", \"−1\", \"−1\", \"+1\"],\n            [\"2\", \"+1\", \"−1\", \"−1\"],\n            [\"3\", \"−1\", \"+1\", \"−1\"],\n            [\"4\", \"+1\", \"+1\", \"+1\"],\n          ],\n        },\n        {\n          type: \"h\",\n          text: \"Defining Relation and Aliasing\",\n        },\n        {\n          type: \"p\",\n          text: \"The generator C = AB can be written as I = ABC (multiply both sides by C). This is the defining relation. It tells us which effects are aliased (confounded). To find the alias of any effect, multiply it by the defining relation: the alias of A is A × ABC = A²BC = BC (since A² = I). So A is aliased with BC, B is aliased with AC, and C is aliased with AB.\",\n        },\n        {\n          type: \"table\",\n          head: [\"Effect\", \"Alias\", \"Consequence\"],\n          rows: [\n            [\"A\", \"BC\", \"Cannot separate main effect A from interaction BC\"],\n            [\"B\", \"AC\", \"Cannot separate main effect B from interaction AC\"],\n            [\"C\", \"AB\", \"Cannot separate main effect C from interaction AB\"],\n          ],\n        },\n        {\n          type: \"h\",\n          text: \"Design Resolution\",\n        },\n        {\n          type: \"p\",\n          text: \"Resolution is a Roman numeral that tells you the shortest word in the defining relation. It indicates the severity of aliasing.\",\n        },\n        {\n          type: \"table\",\n          head: [\"Resolution\", \"Defining Relation\", \"Aliasing Pattern\", \"Use\"],\n          rows: [\n            [\n              \"III\",\n              \"Shortest word = 3 letters\",\n              \"Main effects aliased with 2-factor interactions\",\n              \"Screening many factors quickly\",\n            ],\n            [\n              \"IV\",\n              \"Shortest word = 4 letters\",\n              \"Main effects clear of 2FI; 2FI aliased with each other\",\n              \"Estimating main effects when 2FI may exist\",\n            ],\n            [\n              \"V\",\n              \"Shortest word = 5 letters\",\n              \"Main effects and 2FI all clear\",\n              \"Estimating main effects and all 2FI\",\n            ],\n          ],\n        },\n        {\n          type: \"callout\",\n          tone: \"tip\",\n          title: \"Choosing Resolution\",\n          text: \"Use Resolution III for initial screening of many factors (e.g., Plackett-Burman). Use Resolution IV when you want unbiased main effects but can tolerate aliased two-factor interactions. Use Resolution V when you need to estimate all two-factor interactions cleanly.\",\n        },\n        {\n          type: \"h\",\n          text: \"Plackett-Burman Designs\",\n        },\n        {\n          type: \"p\",\n          text: \"Plackett-Burman (PB) designs are Resolution III screening designs where the number of runs is a multiple of 4 (but not necessarily a power of 2). A PB design in 12 runs can screen up to 11 factors. They are ideal for the initial stage of experimentation when you need to identify the vital few factors from many candidates. However, main effects are partially aliased with two-factor interactions, so significant effects should be confirmed with a higher-resolution follow-up design.\",\n        },\n        {\n          type: \"callout\",\n          tone: \"workplace\",\n          title: \"Screening at a Douala Soap Factory\",\n          text: \"A soap factory in Douala needed to screen 7 factors affecting bar hardness: oil blend ratio, saponification temperature, NaOH concentration, mixing speed, curing time, moisture content, and fragrance percentage. A full factorial would need 128 runs. Instead, they used a 2^(7−4) Resolution III design in just 8 runs to identify the 3 most important factors, then ran a full 2³ on those 3 factors to build a detailed model.\",\n        },\n        {\n          type: \"check\",\n          id: \"aqe-m5-chk-03\",\n          question:\n            \"In a 2^(3−1) design with generator C = AB and defining relation I = ABC, what is the alias of main effect B?\",\n          options: [\"AB\", \"AC\", \"BC\", \"ABC\"],\n          answer: 1,\n          explain:\n            \"Multiply B by the defining relation word ABC: B × ABC = AB²C = AC (since B² = I). So B is aliased with AC.\",\n        },\n        {\n          type: \"form\",\n          id: \"aqe-m5-lab-05\",\n          title: \"Choose Appropriate Design Resolution\",\n          task: \"For each experimental scenario, select the most appropriate design resolution.\",\n          fields: [\n            {\n              kind: \"select\",\n              label: \"You have 10 potential factors and want to narrow to the top 3–4 quickly. Budget allows 12 runs.\",\n              options: [\n                \"Resolution III (screening)\",\n                \"Resolution IV (main effects clear)\",\n                \"Resolution V (main effects + 2FI clear)\",\n                \"Full factorial\",\n              ],\n              answer: 0,\n              explain:\n                \"With 10 factors and only 12 runs, Resolution III (e.g., Plackett-Burman) is the only practical choice. It will identify the important main effects for follow-up study.\",\n            },\n            {\n              kind: \"select\",\n              label: \"You have 5 factors and need to estimate all main effects without bias from two-factor interactions. Budget allows 16 runs.\",\n              options: [\n                \"Resolution III (screening)\",\n                \"Resolution IV (main effects clear)\",\n                \"Resolution V (main effects + 2FI clear)\",\n                \"Full factorial\",\n              ],\n              answer: 1,\n              explain:\n                \"A 2^(5−1) Resolution IV design uses 16 runs and provides unbiased main effect estimates. Two-factor interactions are aliased with each other, which is acceptable if you primarily need main effects.\",\n            },\n            {\n              kind: \"select\",\n              label: \"You have 4 factors and suspect strong two-factor interactions. Budget allows 32 runs.\",\n              options: [\n                \"Resolution III (screening)\",\n                \"Resolution IV (main effects clear)\",\n                \"Resolution V (main effects + 2FI clear)\",\n                \"Full factorial (2⁴ = 16 runs)\",\n              ],\n              answer: 3,\n              explain:\n                \"With only 4 factors, a full 2⁴ factorial is just 16 runs, well within budget. It estimates all main effects and interactions without aliasing. No fractioning is needed.\",\n            },\n          ],\n          hint: \"Consider both the number of factors and the budget. Use the smallest fraction that still gives you the information you need.\",\n        },\n        {\n          type: \"sheet\",\n          id: \"aqe-m5-lab-06\",\n          title: \"Analyse a 2^(3−1) Fractional Factorial\",\n          task: \"A palm oil refinery in Douala used a 2^(3−1) design (C = AB) to study bleaching effectiveness (% colour reduction). Calculate the estimated effects. Remember: each estimated effect is aliased with a two-factor interaction.\",\n          data: [\n            [\"Run\", \"A\", \"B\", \"C=AB\", \"% Colour Reduction\", \"\", \"Effect\", \"Estimate\"],\n            [1, -1, -1, 1, 62, null, \"A + BC\", null],\n            [2, 1, -1, -1, 71, null, \"B + AC\", null],\n            [3, -1, 1, -1, 58, null, \"C + AB\", null],\n            [4, 1, 1, 1, 75, null, \"\", null],\n          ],\n          editable: [\"H2\", \"H3\", \"H4\"],\n          checks: [\n            { cell: \"H2\", equals: 13.0, tol: 0.5 },\n            { cell: \"H3\", equals: 0.0, tol: 0.5 },\n            { cell: \"H4\", equals: 2.0, tol: 0.5 },\n          ],\n          hint: \"Effect of (A+BC) = (1/2)[−62 + 71 − 58 + 75]. Use contrast signs from column A. Similarly for B and C=AB.\",\n          solution: {\n            H2: \"13.0\",\n            H3: \"0.0\",\n            H4: \"2.0\",\n          },\n        },\n        {\n          type: \"links\",\n          items: [\n            {\n              label: \"NIST — Fractional Factorial Designs\",\n              url: \"https://www.itl.nist.gov/div898/handbook/pri/section3/pri334.htm\",\n              source: \"NIST\",\n            },\n          ],\n        },\n      ],\n    },\n\n    // ===== LESSON 4 =====\n    {\n      id: \"aqe-m5-l4\",\n      number: 4,\n      title: \"Response surface methodology\",\n      duration: 25,\n      objectives: [\n        \"Explain the purpose of response surface methodology in process optimisation\",\n        \"Describe central composite and Box-Behnken designs and when to use each\",\n        \"Fit and interpret a second-order regression model with quadratic and interaction terms\",\n      ],\n      blocks: [\n        {\n          type: \"h\",\n          text: \"From Screening to Optimisation\",\n        },\n        {\n          type: \"p\",\n          text: \"Factorial designs tell us which factors matter and in which direction their effects act. But the optimum may not lie at one of the tested levels — it may be somewhere in between, or even at a combination involving curvature in the response surface. Response surface methodology (RSM) extends factorial designs by fitting a second-order (quadratic) model that captures curvature, allowing us to locate the true optimum.\",\n        },\n        {\n          type: \"steps\",\n          title: \"Sequential Experimentation Strategy\",\n          items: [\n            \"Screen: use a fractional factorial to identify the vital few factors\",\n            \"Characterise: run a full factorial on the important factors to estimate main effects and interactions\",\n            \"Optimise: add axial and centre points (RSM) to fit a quadratic model and find the optimum\",\n            \"Confirm: run confirmation trials at the predicted optimal conditions\",\n          ],\n        },\n        {\n          type: \"h\",\n          text: \"Central Composite Design (CCD)\",\n        },\n        {\n          type: \"p\",\n          text: \"A CCD augments a 2^k factorial with two additional types of points. Axial points (star points) are located at distance α from the centre along each axis, extending the design beyond the factorial cube. Centre points are repeated runs at the midpoint of all factor ranges. Together, these allow estimation of all quadratic terms (A², B², etc.).\",\n        },\n        {\n          type: \"p\",\n          text: \"For k = 2 factors, a CCD has: 4 factorial points (±1, ±1), 4 axial points (±α, 0) and (0, ±α), and n₀ centre points (typically 3–5). With α = √2 ≈ 1.414, the design is rotatable, meaning prediction variance is constant at equal distances from the centre.\",\n        },\n        {\n          type: \"table\",\n          head: [\"Point Type\", \"Count (k=2)\", \"Purpose\"],\n          rows: [\n            [\"Factorial (±1, ±1)\", \"4\", \"Estimate main effects and two-factor interactions\"],\n            [\n              \"Axial (±α, 0) and (0, ±α)\",\n              \"4\",\n              \"Estimate quadratic (curvature) terms A² and B²\",\n            ],\n            [\n              \"Centre (0, 0)\",\n              \"3–5\",\n              \"Estimate pure error and test for curvature\",\n            ],\n          ],\n        },\n        {\n          type: \"h\",\n          text: \"Box-Behnken Design\",\n        },\n        {\n          type: \"p\",\n          text: \"An alternative to the CCD is the Box-Behnken design, which uses only three levels per factor (−1, 0, +1) and avoids corner points. For k = 3, it requires 15 runs instead of the CCD’s 20. It is useful when the corner points are physically impractical (e.g., a combination of maximum temperature and maximum pressure might damage equipment). However, it does not allow sequential augmentation from a factorial — you must plan it from the start.\",\n        },\n        {\n          type: \"h\",\n          text: \"The Second-Order Model\",\n        },\n        {\n          type: \"p\",\n          text: \"RSM fits a polynomial of the form: y = β₀ + β₁A + β₂B + β₁₂AB + β₁₁A² + β₂₂B² + ε. The linear terms (β₁A, β₂B) capture the slope, the interaction term (β₁₂AB) captures the twist, and the quadratic terms (β₁₁A², β₂₂B²) capture the curvature in each factor’s direction.\",\n        },\n        {\n          type: \"p\",\n          text: \"Consider a Cameroon brewery optimising ethanol yield (% v/v) with Factor A = fermentation temperature (coded: −1 = 18°C, 0 = 22°C, +1 = 26°C) and Factor B = yeast pitch rate (coded: −1 = 0.5 million cells/mL, 0 = 1.0 million cells/mL, +1 = 1.5 million cells/mL). A CCD with 3 centre points gave the fitted model:\",\n        },\n        {\n          type: \"code\",\n          text: \"ŷ = 5.42 + 0.38A + 0.27B + 0.15AB − 0.31A² − 0.18B²\\n\\nMaximum predicted yield: set partial derivatives to zero:\\n  ∂y/∂A = 0.38 + 0.15B − 0.62A = 0  →  A = (0.38 + 0.15B)/0.62\\n  ∂y/∂B = 0.27 + 0.15A − 0.36B = 0  →  B = (0.27 + 0.15A)/0.36\\n\\nSolving simultaneously: A ≈ 0.69, B ≈ 1.04\\n\\nDecoded: Temperature ≈ 24.8°C, Pitch rate ≈ 1.52 million cells/mL\\nPredicted yield ≈ 5.42 + 0.38(0.69) + 0.27(1.04) + 0.15(0.69)(1.04) − 0.31(0.69)² − 0.18(1.04)²\\n                ≈ 5.77% v/v\",\n        },\n        {\n          type: \"callout\",\n          tone: \"key\",\n          title: \"Contour Plots\",\n          text: \"A contour plot shows lines of equal response on a grid of the two factors. The contour lines form ellipses (or hyperbolas) centred on the stationary point. If the stationary point is a maximum, the contours form closed ellipses with the highest response at the centre. The shape and orientation of the ellipses reveal the relative importance of each factor and their interaction.\",\n        },\n        {\n          type: \"callout\",\n          tone: \"workplace\",\n          title: \"RSM at a Bamenda Tea Estate\",\n          text: \"A tea processing plant near Bamenda used RSM to optimise the rolling stage. After screening 6 factors with a Plackett-Burman design, they found that rolling pressure and rolling time were the key factors. A CCD with α = 1.414 and 5 centre points revealed a clear maximum for leaf cell rupture at 2.8 bar and 42 minutes — conditions that the factorial alone would have missed because the optimum was not at an extreme.\",\n        },\n        {\n          type: \"equip\",\n          title: \"Regression and RSM Tools\",\n          items: [\n            {\n              art: \"📈\",\n              name: \"Regression Analysis Module\",\n              caption: \"Fits linear and polynomial regression models, computes R², residual analysis, and generates contour and surface plots for RSM.\",\n            },\n          ],\n        },\n        {\n          type: \"check\",\n          id: \"aqe-m5-chk-04\",\n          question: \"What is the primary purpose of adding axial (star) points to a 2^k factorial in a CCD?\",\n          options: [\n            \"To increase the number of replicates for better error estimation\",\n            \"To enable estimation of quadratic (curvature) terms in the model\",\n            \"To improve the aliasing structure of the design\",\n            \"To screen additional factors beyond the original k\",\n          ],\n          answer: 1,\n          explain:\n            \"Axial points extend the design along each factor axis, creating five levels per factor (−α, −1, 0, +1, +α). This enables fitting quadratic terms A² and B² that capture curvature in the response surface.\",\n        },\n        {\n          type: \"form\",\n          id: \"aqe-m5-lab-07\",\n          title: \"Interpret Contour Plot and Identify Optimum\",\n          task: \"A contour plot for ethanol yield shows closed elliptical contours with the highest contour (5.75% v/v) centred near coded values A = 0.7, B = 1.0. Answer the interpretation questions.\",\n          fields: [\n            {\n              kind: \"select\",\n              label: \"What does the stationary point represent in this case?\",\n              options: [\n                \"A saddle point — the response increases in some directions and decreases in others\",\n                \"A minimum — the lowest yield occurs at the centre of the contours\",\n                \"A maximum — yield decreases in all directions from this point\",\n                \"A ridge — the response is nearly constant along one direction\",\n              ],\n              answer: 2,\n              explain:\n                \"Closed elliptical contours with the highest value at the centre indicate a maximum. Yield decreases as you move away in any direction.\",\n            },\n            {\n              kind: \"select\",\n              label: \"The ellipses are elongated along a diagonal. What does this suggest?\",\n              options: [\n                \"The two factors do not interact\",\n                \"The quadratic terms are negligible\",\n                \"There is an interaction between the two factors\",\n                \"The model is inadequate and needs higher-order terms\",\n              ],\n              answer: 2,\n              explain:\n                \"Ellipses tilted along a diagonal (not aligned with the axes) indicate a significant interaction between the two factors. Axis-aligned ellipses would suggest no interaction.\",\n            },\n            {\n              kind: \"select\",\n              label: \"If the coded optimum is A = 0.7 and the factor range for temperature is 18–26°C (coded −1 to +1), what is the optimal temperature?\",\n              options: [\"24.8°C\", \"22.0°C\", \"20.6°C\", \"25.6°C\"],\n              answer: 0,\n              explain:\n                \"Decode: actual = centre + coded × half-range = 22 + 0.7 × 4 = 24.8°C. The centre is (18+26)/2 = 22, half-range is (26−18)/2 = 4.\",\n            },\n          ],\n          hint: \"Coded value = (actual − centre) / half-range. So actual = centre + coded × half-range.\",\n        },\n        {\n          type: \"sheet\",\n          id: \"aqe-m5-lab-08\",\n          title: \"Fit a Response Model\",\n          task: \"Given the CCD data for ethanol yield below, verify the model coefficients. The model is y = β₀ + β₁A + β₂B. Calculate the predicted yield at the centre point (A=0, B=0) and at the factorial point (A=1, B=1). Use the simplified linear model: ŷ = 5.42 + 0.38A + 0.27B.\",\n          data: [\n            [\"Point\", \"A\", \"B\", \"y observed\", \"\", \"Calculation\", \"ŷ predicted\"],\n            [\"Centre\", 0, 0, 5.40, null, \"β₀ + β₁(0) + β₂(0)\", null],\n            [\"Factorial\", 1, 1, 6.10, null, \"β₀ + β₁(1) + β₂(1)\", null],\n            [\"Factorial\", -1, 1, 4.90, null, \"β₀ + β₁(-1) + β₂(1)\", null],\n          ],\n          editable: [\"G2\", \"G3\", \"G4\"],\n          checks: [\n            { cell: \"G2\", equals: 5.42, tol: 0.02 },\n            { cell: \"G3\", equals: 6.07, tol: 0.02 },\n            { cell: \"G4\", equals: 5.31, tol: 0.02 },\n          ],\n          hint: \"Substitute A and B values into ŷ = 5.42 + 0.38A + 0.27B. For centre point: 5.42 + 0.38(0) + 0.27(0) = 5.42.\",\n          solution: {\n            G2: \"5.42\",\n            G3: \"6.07\",\n            G4: \"5.31\",\n          },\n        },\n        {\n          type: \"links\",\n          items: [\n            {\n              label: \"NIST — Response Surface Designs\",\n              url: \"https://www.itl.nist.gov/div898/handbook/pri/section3/pri336.htm\",\n              source: \"NIST\",\n            },\n          ],\n        },\n      ],\n    },\n\n    // ===== LESSON 5 =====\n    {\n      id: \"aqe-m5-l5\",\n      number: 5,\n      title: \"Practical DOE: planning, execution and confirmation\",\n      duration: 25,\n      objectives: [\n        \"Plan an experiment accounting for resources, time, cost and personnel\",\n        \"Apply randomisation and blocking strategies to reduce bias in practice\",\n        \"Use ANOVA to assess the significance of factorial effects\",\n        \"Design and interpret confirmation runs to verify optimal settings\",\n      ],\n      blocks: [\n        {\n          type: \"h\",\n          text: \"Planning the Experiment\",\n        },\n        {\n          type: \"p\",\n          text: \"A well-planned experiment succeeds; a poorly planned one wastes resources and produces ambiguous results. Before running a single trial, the quality engineer must consider the practical constraints: available raw materials, machine time, technician availability, cost per run, measurement system capability and management support. In Cameroon’s manufacturing sector, where budgets are often tight and downtime is costly, careful planning is especially important.\",\n        },\n        {\n          type: \"list\",\n          items: [\n            \"Define the objective in writing: what question must the experiment answer?\",\n            \"List all potential factors and use expert knowledge to select the most important 3–6\",\n            \"Set factor ranges wide enough to detect effects but narrow enough to be practical\",\n            \"Determine the number of replicates needed using power analysis or prior variance estimates\",\n            \"Estimate total cost: materials per run × number of runs + measurement costs + labour\",\n            \"Assign responsibilities: who sets the factors, who measures the response, who records the data\",\n          ],\n        },\n        {\n          type: \"callout\",\n          tone: \"workplace\",\n          title: \"Pre-Experiment Checklist at ALUCAM Edea\",\n          text: \"At the ALUCAM aluminium smelter in Edea, DOE teams use a standard pre-experiment checklist covering 14 items: measurement system validation (Gage R&R), safety review for extreme factor combinations, stakeholder sign-off, raw material procurement, operator training on the protocol, and data collection forms. No experiment proceeds until every item is ticked off.\",\n        },\n        {\n          type: \"h\",\n          text: \"Randomisation and Blocking in Practice\",\n        },\n        {\n          type: \"p\",\n          text: \"Randomisation protects against unknown lurking variables by ensuring that any systematic trends (e.g., tool wear, ambient temperature drift, operator fatigue) are spread evenly across all treatments. Complete randomisation means running treatments in a fully random order. However, some factors are hard to change — for instance, kiln temperature takes hours to adjust. In such cases, a split-plot design or restricted randomisation scheme keeps the hard-to-change factor constant within blocks.\",\n        },\n        {\n          type: \"p\",\n          text: \"Blocking accounts for known nuisance variables. If an experiment spans two shifts, two batches of raw material, or two machines, these become blocks. Within each block, a complete set (or balanced subset) of treatments is run. The block effect is estimated and removed from the error, increasing the precision of the factor effect estimates.\",\n        },\n        {\n          type: \"callout\",\n          tone: \"warning\",\n          title: \"Do Not Confound Blocks with Factors\",\n          text: \"If you run all high-temperature treatments on Monday and all low-temperature treatments on Tuesday, any Monday-vs-Tuesday difference (humidity, raw material batch, crew) is confounded with temperature. Always ensure every block contains a mix of treatment combinations.\",\n        },\n        {\n          type: \"h\",\n          text: \"ANOVA for DOE\",\n        },\n        {\n          type: \"p\",\n          text: \"Analysis of variance partitions the total variability in the response into components due to each factor, each interaction and the residual error. The F-ratio for each effect compares its mean square to the error mean square. If F > F-critical (or p-value < 0.05), the effect is statistically significant.\",\n        },\n        {\n          type: \"table\",\n          head: [\"Source\", \"SS\", \"df\", \"MS\", \"F\", \"p-value\"],\n          rows: [\n            [\"A (Speed)\", \"0.81\", \"1\", \"0.810\", \"14.73\", \"0.005\"],\n            [\"B (Feed)\", \"3.24\", \"1\", \"3.240\", \"58.91\", \"< 0.001\"],\n            [\"C (Depth)\", \"0.49\", \"1\", \"0.490\", \"8.91\", \"0.017\"],\n            [\"AB\", \"0.01\", \"1\", \"0.010\", \"0.18\", \"0.680\"],\n            [\"AC\", \"0.04\", \"1\", \"0.040\", \"0.73\", \"0.418\"],\n            [\"BC\", \"0.09\", \"1\", \"0.090\", \"1.64\", \"0.236\"],\n            [\"ABC\", \"0.0025\", \"1\", \"0.0025\", \"0.05\", \"0.836\"],\n            [\"Error\", \"0.44\", \"8\", \"0.055\", \"\", \"\"],\n            [\"Total\", \"5.1125\", \"15\", \"\", \"\", \"\"],\n          ],\n        },\n        {\n          type: \"p\",\n          text: \"From this ANOVA table (machining surface roughness with 2 replicates), factors A (speed), B (feed rate) and C (depth of cut) are all significant at α = 0.05. None of the interactions are significant, suggesting the factors act independently on roughness. Feed rate (B) has the largest F-statistic and is by far the most influential factor.\",\n        },\n        {\n          type: \"h\",\n          text: \"Confirmation Runs\",\n        },\n        {\n          type: \"p\",\n          text: \"After identifying the optimal factor settings, run 3–5 confirmation trials at those settings. Compare the mean response from confirmation runs with the model’s prediction. If the confirmation mean falls within the prediction interval, the model is validated. If not, investigate: the model may be inadequate, conditions may have changed, or an important factor was overlooked.\",\n        },\n        {\n          type: \"code\",\n          text: \"Prediction: Ra = 0.85 µm at A=+1, B=−1, C=−1\\nConfirmation runs (n=4): 0.88, 0.82, 0.91, 0.84\\nConfirmation mean: 0.8625 µm\\n95% prediction interval: [0.72, 0.98] µm\\n\\n0.8625 falls within [0.72, 0.98] → Model confirmed.\",\n        },\n        {\n          type: \"h\",\n          text: \"Common Pitfalls\",\n        },\n        {\n          type: \"table\",\n          head: [\"Pitfall\", \"Consequence\", \"Prevention\"],\n          rows: [\n            [\n              \"Lurking variables\",\n              \"Unexplained variation or misleading effects\",\n              \"Randomise run order; monitor ambient conditions\",\n            ],\n            [\n              \"Inadequate replication\",\n              \"Cannot distinguish real effects from noise\",\n              \"Run at least 2 replicates; use centre points for pure error\",\n            ],\n            [\n              \"Changing conditions\",\n              \"Drift contaminates effect estimates\",\n              \"Block on time; run experiment as quickly as practical\",\n            ],\n            [\n              \"Factor ranges too narrow\",\n              \"Effects are too small to detect\",\n              \"Set ranges based on engineering judgement and prior data\",\n            ],\n            [\n              \"Measurement error\",\n              \"Inflated residual variance masks real effects\",\n              \"Validate measurement system (Gage R&R) before experimenting\",\n            ],\n          ],\n        },\n        {\n          type: \"callout\",\n          tone: \"tip\",\n          title: \"Document Everything\",\n          text: \"Maintain a detailed experiment logbook recording the actual factor settings (not just target), any anomalies, environmental conditions and the identity of the operator for each run. This documentation is invaluable for diagnosing unexpected results.\",\n        },\n        {\n          type: \"equip\",\n          title: \"Statistical Tools for DOE Analysis\",\n          items: [\n            {\n              art: \"🧪\",\n              name: \"DOE Analysis Toolkit\",\n              caption: \"Computes ANOVA tables, generates effect estimates, and performs confirmation-run analysis for factorial experiments.\",\n            },\n            {\n              art: \"🔔\",\n              name: \"Normality Testing Module\",\n              caption: \"Performs Anderson-Darling, Shapiro-Wilk and normal probability plot analysis on residuals from DOE models to verify assumptions.\",\n            },\n          ],\n        },\n        {\n          type: \"check\",\n          id: \"aqe-m5-chk-05\",\n          question:\n            \"After a DOE identifies optimal settings, you run 4 confirmation trials. The predicted response is 5.8 with a 95% prediction interval of [5.2, 6.4]. Your confirmation mean is 6.1. What do you conclude?\",\n          options: [\n            \"The model is invalid because 6.1 ≠ 5.8\",\n            \"The model is confirmed because 6.1 falls within [5.2, 6.4]\",\n            \"More confirmation runs are needed because the mean is above the prediction\",\n            \"The experiment must be repeated with different factor ranges\",\n          ],\n          answer: 1,\n          explain:\n            \"The confirmation mean (6.1) falls within the 95% prediction interval [5.2, 6.4], so the model’s predictions are consistent with the observed results. The model is confirmed.\",\n        },\n        {\n          type: \"form\",\n          id: \"aqe-m5-lab-09\",\n          title: \"Plan an Experiment\",\n          task: \"A cement quality engineer at a plant in Bertoua wants to study the effect of 3 factors (clinker fineness, gypsum percentage, grinding time) on compressive strength. Plan the experiment by answering the questions below.\",\n          fields: [\n            {\n              kind: \"select\",\n              label: \"With 3 factors at 2 levels each, how many runs does a single replicate of the full factorial require?\",\n              options: [\"6\", \"8\", \"9\", \"12\"],\n              answer: 1,\n              explain: \"2³ = 8 runs for a full factorial with 3 factors at 2 levels.\",\n            },\n            {\n              kind: \"select\",\n              label: \"If the engineer can only afford 12 runs total, which is the best approach?\",\n              options: [\n                \"Run a 2³ full factorial once with 4 extra centre points\",\n                \"Run a 2³ full factorial with partial replication\",\n                \"Use OFAT to test each factor separately\",\n                \"Run a 2^(3−1) fractional factorial with 3 replicates\",\n              ],\n              answer: 0,\n              explain:\n                \"A 2³ (8 runs) plus 4 centre points = 12 runs. Centre points provide an estimate of pure error and a test for curvature, giving the most information for the budget.\",\n            },\n            {\n              kind: \"select\",\n              label: \"The engineer plans to run the experiment over two days. How should days be handled?\",\n              options: [\n                \"Run all high-temperature treatments on Day 1 and low-temperature on Day 2\",\n                \"Run the treatments in alphabetical order within each day\",\n                \"Block on day — run a balanced subset of treatments on each day in random order\",\n                \"Ignore the day difference since it is not a factor of interest\",\n              ],\n              answer: 2,\n              explain:\n                \"Days should be treated as blocks. A balanced set of treatments within each day (randomised) ensures that the day effect does not confound any factor effect.\",\n            },\n          ],\n          hint: \"Think about how many runs the factorial requires, how to use remaining runs wisely, and how to handle nuisance variables like day-to-day variation.\",\n        },\n        {\n          type: \"sorter\",\n          id: \"aqe-m5-lab-10\",\n          title: \"Match DOE Pitfalls to Solutions\",\n          task: \"Match each common DOE pitfall to the most appropriate preventive measure.\",\n          layout: \"columns\",\n          buckets: [\n            { label: \"Randomise run order\" },\n            { label: \"Validate measurement system\" },\n            { label: \"Block on nuisance variable\" },\n            { label: \"Increase replication\" },\n          ],\n          items: [\n            {\n              text: \"Ambient temperature drifts during the experiment and affects the response unpredictably\",\n              bucket: 0,\n              explain:\n                \"Randomisation spreads unpredictable environmental effects evenly across treatments, preventing them from biasing specific factor effects.\",\n            },\n            {\n              text: \"The caliper used to measure bore diameter has poor repeatability (high Gage R&R %)\",\n              bucket: 1,\n              explain:\n                \"A measurement system with poor repeatability inflates residual error. Validating and improving the measurement system before experimenting is essential.\",\n            },\n            {\n              text: \"Two batches of raw material must be used during the experiment\",\n              bucket: 2,\n              explain:\n                \"Known batch-to-batch differences should be controlled by blocking. Assign treatments within each batch block to remove this source of variation.\",\n            },\n            {\n              text: \"The experiment detects no significant effects despite expected differences\",\n              bucket: 3,\n              explain:\n                \"If the error variance is too large relative to the effects, the F-test lacks power. Increasing replication reduces the error mean square and increases the chance of detecting real effects.\",\n            },\n          ],\n        },\n        {\n          type: \"links\",\n          items: [\n            {\n              label: \"ASQ — Design of Experiments Guidance\",\n              url: \"https://asq.org/quality-resources/design-of-experiments\",\n              source: \"ASQ\",\n            },\n          ],\n        },\n      ],\n    },\n\n    // ===== PRACTICE LESSON =====\n    {\n      id: \"aqe-m5-practice\",\n      title: \"Practice: Design of Experiments\",\n      minutes: 30,\n      objectives: [\n        \"Apply DOE terminology and concepts across a range of difficulty levels\",\n        \"Calculate and interpret factorial effects from experimental data\",\n        \"Design and analyse experiments for complex manufacturing scenarios\",\n      ],\n      blocks: [\n        {\n          type: \"p\",\n          text: \"This practice lesson consolidates your learning across the full range of DOE topics. Work through all four labs, progressing from basic terminology to advanced factorial analysis and experimental design.\",\n        },\n        // --- Practice Lab 1: Beginner ---\n        {\n          type: \"form\",\n          id: \"aqe-m5-plab-01\",\n          level: \"beginner\",\n          title: \"Identify Factors, Levels and Responses\",\n          task: \"For each manufacturing scenario, identify the factors, levels and response variable.\",\n          fields: [\n            {\n              kind: \"select\",\n              label: \"A Douala chocolate factory tests two cocoa butter percentages (28% and 32%) and two conching times (12h and 18h) to optimise smoothness score. What are the factors?\",\n              options: [\n                \"Smoothness score and cocoa butter percentage\",\n                \"Cocoa butter percentage and conching time\",\n                \"Conching time and smoothness score\",\n                \"Cocoa butter percentage only\",\n              ],\n              answer: 1,\n              explain:\n                \"The factors are the controllable variables: cocoa butter percentage and conching time. Smoothness score is the response (the measured outcome).\",\n            },\n            {\n              kind: \"select\",\n              label: \"In the same experiment, how many treatment combinations are there?\",\n              options: [\"2\", \"3\", \"4\", \"6\"],\n              answer: 2,\n              explain:\n                \"Two factors at two levels each: 2² = 4 treatment combinations (28%-12h, 28%-18h, 32%-12h, 32%-18h).\",\n            },\n            {\n              kind: \"select\",\n              label: \"A Bafoussam coffee roaster tests roast temperature at three levels (180°C, 200°C, 220°C) and roast time at two levels (10 min, 15 min). How many treatments in the full factorial?\",\n              options: [\"5\", \"6\", \"8\", \"9\"],\n              answer: 1,\n              explain:\n                \"3 levels of temperature × 2 levels of time = 6 treatment combinations in the full factorial.\",\n            },\n            {\n              kind: \"select\",\n              label: \"A cement plant engineer says 'I ran each treatment 3 times independently.' What DOE term describes this?\",\n              options: [\"3 blocks\", \"3 levels\", \"3 replicates\", \"3 factors\"],\n              answer: 2,\n              explain:\n                \"Running the same treatment combination independently multiple times gives replicates, which are used to estimate experimental error.\",\n            },\n          ],\n          hint: \"Factors are what you control. Levels are the specific values of each factor. The response is what you measure.\",\n        },\n        // --- Practice Lab 2: Intermediate ---\n        {\n          type: \"sheet\",\n          id: \"aqe-m5-plab-02\",\n          level: \"intermediate\",\n          title: \"Calculate Effects for a 2² Factorial\",\n          task: \"A Cameroonian tile factory tested two factors on tile breaking strength (N): Factor A = firing temperature (1050°C vs 1150°C) and Factor B = clay moisture (8% vs 12%). Calculate all three effects (A, B, AB).\",\n          data: [\n            [\"Run\", \"A\", \"B\", \"AB\", \"Strength (N)\", \"\", \"Effect\", \"Value\"],\n            [1, -1, -1, 1, 420, null, \"A\", null],\n            [2, 1, -1, -1, 510, null, \"B\", null],\n            [3, -1, 1, -1, 390, null, \"AB\", null],\n            [4, 1, 1, 1, 460, null, \"\", null],\n          ],\n          editable: [\"H2\", \"H3\", \"H4\"],\n          checks: [\n            { cell: \"H2\", equals: 80, tol: 1 },\n            { cell: \"H3\", equals: -40, tol: 1 },\n            { cell: \"H4\", equals: -10, tol: 1 },\n          ],\n          hint: \"Effect A = (1/2)[−420 + 510 − 390 + 460]. Use the contrast signs from column A for each response.\",\n          solution: {\n            H2: \"80\",\n            H3: \"-40\",\n            H4: \"-10\",\n          },\n        },\n        // --- Practice Lab 3: Advanced ---\n        {\n          type: \"sheet\",\n          id: \"aqe-m5-plab-03\",\n          level: \"advanced\",\n          title: \"Analyse a 2³ Factorial with Effects and ANOVA\",\n          task: \"A Kribi shrimp processing plant ran a 2³ factorial (2 replicates) on shelf life (days). Factors: A = brine concentration, B = smoking time, C = packaging type. Calculate main effects from the run averages and determine which effect has the largest SS. SS = (n × 2^k / 4) × effect² where n=2 replicates and 2^k=8.\",\n          data: [\n            [\"Run\", \"A\", \"B\", \"C\", \"y̅ (days)\", \"\", \"Effect\", \"Value\", \"SS\"],\n            [1, -1, -1, -1, 8, null, \"A\", null, null],\n            [2, 1, -1, -1, 12, null, \"B\", null, null],\n            [3, -1, 1, -1, 10, null, \"C\", null, null],\n            [4, 1, 1, -1, 15, null, \"AB\", null, null],\n            [5, -1, -1, 1, 11, null, \"AC\", null, null],\n            [6, 1, -1, 1, 16, null, \"BC\", null, null],\n            [7, -1, 1, 1, 14, null, \"ABC\", null, null],\n            [8, 1, 1, 1, 18, null, \"\", null, null],\n          ],\n          editable: [\"H2\", \"H3\", \"H4\", \"I2\", \"I3\", \"I4\"],\n          checks: [\n            { cell: \"H2\", equals: 4.5, tol: 0.1 },\n            { cell: \"H3\", equals: 2.5, tol: 0.1 },\n            { cell: \"H4\", equals: 3.5, tol: 0.1 },\n            { cell: \"I2\", equals: 81.0, tol: 1 },\n            { cell: \"I3\", equals: 25.0, tol: 1 },\n            { cell: \"I4\", equals: 49.0, tol: 1 },\n          ],\n          hint: \"Effect A = (1/4)[−8+12−10+15−11+16−14+18] = (1/4)(18) = 4.5. SS_A = (2×8/4)×4.5² = 4×20.25 = 81.0.\",\n          solution: {\n            H2: \"4.5\",\n            H3: \"2.5\",\n            H4: \"3.5\",\n            I2: \"81.0\",\n            I3: \"25.0\",\n            I4: \"49.0\",\n          },\n        },\n        // --- Practice Lab 4: Expert ---\n        {\n          type: \"form\",\n          id: \"aqe-m5-plab-04\",\n          level: \"expert\",\n          title: \"Design and Interpret a Fractional Factorial\",\n          task: \"A Douala paint factory wants to study 5 factors affecting drying time. Budget allows only 16 runs (plus replicates). Design and interpret the experiment.\",\n          fields: [\n            {\n              kind: \"select\",\n              label: \"A full factorial in 5 factors requires 2⁵ = 32 runs. To fit within 16 runs, which design is appropriate?\",\n              options: [\n                \"2^(5−2) Resolution III design (8 runs)\",\n                \"2^(5−1) Resolution V design (16 runs)\",\n                \"Plackett-Burman in 12 runs\",\n                \"Box-Behnken design (46 runs)\",\n              ],\n              answer: 1,\n              explain:\n                \"A 2^(5−1) design uses 16 runs and provides Resolution V — all main effects and two-factor interactions are estimable without aliasing. This is the best fit for the budget.\",\n            },\n            {\n              kind: \"select\",\n              label: \"In a 2^(5−1) design with generator E = ABCD, what is the defining relation?\",\n              options: [\n                \"I = ABCDE\",\n                \"I = ABCD\",\n                \"I = ABE\",\n                \"I = CDE\",\n              ],\n              answer: 0,\n              explain:\n                \"Multiply both sides of E = ABCD by E: E² = ABCDE, so I = ABCDE. The defining relation is I = ABCDE, a five-letter word giving Resolution V.\",\n            },\n            {\n              kind: \"select\",\n              label: \"With I = ABCDE, what is the alias of the two-factor interaction AB?\",\n              options: [\n                \"CDE\",\n                \"CD\",\n                \"ABC\",\n                \"DE\",\n              ],\n              answer: 0,\n              explain:\n                \"Alias of AB = AB × ABCDE = A²B²CDE = CDE. So AB is aliased with the three-factor interaction CDE. Since Resolution V means the shortest word is 5 letters, 2FI are aliased only with 3FI — which are usually negligible.\",\n            },\n            {\n              kind: \"select\",\n              label: \"After running the 2^(5−1) experiment, the analysis shows main effects A and C are significant, along with the AC interaction. The optimal drying time occurs at A = +1, C = −1. What should the engineer do next?\",\n              options: [\n                \"Implement A = +1, C = −1 immediately on the production line\",\n                \"Run 3–5 confirmation trials at A = +1, C = −1 with other factors at current levels\",\n                \"Run a full 2⁵ factorial to verify all effects\",\n                \"Switch to OFAT testing on factors A and C only\",\n              ],\n              answer: 1,\n              explain:\n                \"Before changing production settings, always run confirmation trials at the predicted optimum. This verifies the model’s prediction under real production conditions and builds confidence in the result.\",\n            },\n          ],\n          hint: \"Think about the relationship between the number of runs, the fraction size, and the resolution. For the defining relation, multiply the generator by the factor it defines.\",\n        },\n      ],\n    },\n  ],\n\n  // ===== QUIZ =====\n  quiz: {\n    id: \"aqe-m5-quiz\",\n    title: \"Module 5 Quiz: Design of Experiments\",\n    passPct: 75,\n    questions: [\n      {\n        id: \"aqe-m5-q1\",\n        question: \"What is the main disadvantage of the one-factor-at-a-time (OFAT) approach compared to factorial designs?\",\n        options: [\n          \"OFAT requires more runs than a factorial design\",\n          \"OFAT cannot detect interactions between factors\",\n          \"OFAT can only test one level per factor\",\n          \"OFAT requires more replicates to achieve the same precision\",\n        ],\n        answer: 1,\n        explain:\n          \"The critical flaw of OFAT is its inability to detect interactions. Because only one factor changes at a time while others are held constant, any synergistic or antagonistic effects between factors are invisible.\",\n      },\n      {\n        id: \"aqe-m5-q2\",\n        question: \"In a 2² factorial with responses (standard order) y₁ = 30, y₂ = 50, y₃ = 25, y₄ = 55, what is the interaction effect AB?\",\n        options: [\"5.0\", \"10.0\", \"25.0\", \"5.0 but negative\"],\n        answer: 0,\n        explain:\n          \"AB = (1/2)[(+1)(30) + (−1)(50) + (−1)(25) + (+1)(55)] = (1/2)[30 − 50 − 25 + 55] = (1/2)(10) = 5.0.\",\n      },\n      {\n        id: \"aqe-m5-q3\",\n        question: \"A 2³ full factorial design has how many runs per replicate?\",\n        options: [\"6\", \"8\", \"9\", \"12\"],\n        answer: 1,\n        explain: \"A 2³ design tests all combinations of 3 factors at 2 levels each: 2 × 2 × 2 = 8 runs.\",\n      },\n      {\n        id: \"aqe-m5-q4\",\n        question: \"In a 2^(4−1) design with generator D = ABC and defining relation I = ABCD, what is the resolution?\",\n        options: [\"Resolution II\", \"Resolution III\", \"Resolution IV\", \"Resolution V\"],\n        answer: 2,\n        explain:\n          \"The shortest word in the defining relation I = ABCD has 4 letters, so this is a Resolution IV design. Main effects are clear of two-factor interactions, but two-factor interactions are aliased with each other.\",\n      },\n      {\n        id: \"aqe-m5-q5\",\n        question: \"What is the primary purpose of centre points in a Central Composite Design?\",\n        options: [\n          \"To increase the number of factorial points\",\n          \"To estimate pure error and detect curvature\",\n          \"To replace axial points when they are impractical\",\n          \"To reduce the total number of runs needed\",\n        ],\n        answer: 1,\n        explain:\n          \"Centre points (replicated runs at the midpoint of all factors) provide a model-independent estimate of pure error and test whether the first-order model adequately describes the response or whether curvature (quadratic terms) is present.\",\n      },\n      {\n        id: \"aqe-m5-q6\",\n        question: \"Which design avoids the extreme corner points of the factor space and uses only three levels per factor?\",\n        options: [\n          \"Central Composite Design (CCD)\",\n          \"Plackett-Burman design\",\n          \"Box-Behnken design\",\n          \"2^(k−p) fractional factorial\",\n        ],\n        answer: 2,\n        explain:\n          \"The Box-Behnken design uses only −1, 0 and +1 levels and does not include corner points (where all factors are simultaneously at their extremes). This is advantageous when corner combinations are physically impractical or dangerous.\",\n      },\n      {\n        id: \"aqe-m5-q7\",\n        question: \"In an ANOVA table for a 2³ factorial, a factor has SS = 6.4, df = 1, and the error MS = 0.25. What is the F-ratio for this factor?\",\n        options: [\"6.4\", \"25.6\", \"0.039\", \"3.2\"],\n        answer: 1,\n        explain:\n          \"MS for the factor = SS / df = 6.4 / 1 = 6.4. F = MS(factor) / MS(error) = 6.4 / 0.25 = 25.6. This large F-ratio indicates a statistically significant effect.\",\n      },\n      {\n        id: \"aqe-m5-q8\",\n        question: \"After optimising a process with DOE, the predicted response at optimal settings is 78.5 with a 95% prediction interval of [74.2, 82.8]. Four confirmation runs yield: 76.1, 79.3, 77.8, 80.0. Is the model confirmed?\",\n        options: [\n          \"No — the individual values differ from 78.5\",\n          \"No — the confirmation mean is below the prediction\",\n          \"Yes — the confirmation mean (78.3) is within [74.2, 82.8]\",\n          \"Cannot determine without running more trials\",\n        ],\n        answer: 2,\n        explain:\n          \"Confirmation mean = (76.1 + 79.3 + 77.8 + 80.0) / 4 = 78.3. Since 78.3 is within the 95% prediction interval [74.2, 82.8], the model is confirmed. Individual values need not equal the prediction exactly.\",\n      },\n    ],\n  },\n};\n","client/src/data/courses/aqe/m6.ts":"import type { CourseModule } from \"../../../lms/types\";\n\n// Module 6 — FMEA, Control Plans and Inspection Planning\n// Associate Quality Engineer (AQE) course.\n// Original Analytix Engineering material. All companies, people and data are fictional.\n// British spelling. Cameroon manufacturing context.\n\n/* ── reusable constants ─────────────────────────────────────── */\n\nconst AIAG = \"AIAG\";\nconst ISO_SRC = \"ISO\";\nconst ASQ = \"ASQ\";\n\nconst AP_TABLE = [\n  [\"High (H)\", \"S >= 8 and O >= 4 and D >= 4, or any combination with very high risk\", \"Mandatory action required\"],\n  [\"Medium (M)\", \"Moderate combination of S, O, D not reaching High threshold\", \"Action recommended\"],\n  [\"Low (L)\", \"All three ratings are low or current controls are effective\", \"Action optional — document decision\"],\n];\n\nconst SEV_SCALE = [\n  [\"1\", \"No effect\", \"No discernible effect on the process or product\"],\n  [\"2–3\", \"Minor\", \"Slight inconvenience; customer unlikely to notice\"],\n  [\"4–6\", \"Moderate\", \"Customer dissatisfied; product may not meet some requirements\"],\n  [\"7–8\", \"High\", \"Significant customer impact; product may be inoperable or unsafe without warning\"],\n  [\"9–10\", \"Very high / Hazardous\", \"Potential safety hazard; regulatory noncompliance\"],\n];\n\nconst OCC_SCALE = [\n  [\"1\", \"Very low\", \"Failure unlikely; robust prevention controls in place\"],\n  [\"2–3\", \"Low\", \"Rare failures; prevention controls usually effective\"],\n  [\"4–6\", \"Moderate\", \"Occasional failures; some prevention controls\"],\n  [\"7–8\", \"High\", \"Frequent failures; prevention controls weak or absent\"],\n  [\"9–10\", \"Very high\", \"Failure almost inevitable; no effective prevention\"],\n];\n\nconst DET_SCALE = [\n  [\"1\", \"Almost certain\", \"Detection controls will almost certainly catch the failure\"],\n  [\"2–3\", \"High\", \"Good chance of detection before product leaves the process\"],\n  [\"4–6\", \"Moderate\", \"Detection controls may miss the failure\"],\n  [\"7–8\", \"Low\", \"Detection controls unlikely to catch the failure\"],\n  [\"9–10\", \"Very low / None\", \"No detection control in place or no opportunity to detect\"],\n];\n\nconst INTRO_PRACTICE = { type: \"p\" as const, text: \"Four exercises of increasing difficulty, from beginner to expert. Each one uses a different workplace situation. Take your time: every answer is checked, and the explanations appear after you check.\" };\n\n/* ── module export ──────────────────────────────────────────── */\n\nexport const m6: CourseModule = {\n  id: \"aqe-m6\",\n  number: 6,\n  title: \"FMEA, Control Plans and Inspection Planning\",\n  summary: \"Process flow diagrams map every manufacturing step and connect to the process FMEA (AIAG/VDA seven-step method with action priority) and the control plan. This module covers PFMEA structure, severity–occurrence–detection ratings, control plan development from prototype through production, inspection and test planning with hold points and witness points, and acceptance sampling using AQL plans with OC curves — linking these documents into a coherent quality planning system that drives defect prevention in manufacturing.\",\n  hours: 18,\n  lessons: [\n    // ─────────────────────────────── LESSON 1 ───────────────────────────────\n    {\n      id: \"aqe-m6-l1\",\n      title: \"Process flow diagrams and process mapping\",\n      minutes: 25,\n      objectives: [\n        \"Draw a process flow diagram using standard symbols for operation, inspection, transport, delay, storage and decision\",\n        \"Link the PFD to the process FMEA and control plan as the foundation of the quality planning triad\",\n        \"Identify value-added and non-value-added steps using value stream mapping principles\",\n      ],\n      blocks: [\n        { type: \"p\", text: \"Before you can analyse what might go wrong in a manufacturing process, you need a clear picture of every step the product goes through. The process flow diagram (PFD) is that picture. It is the first document you build in APQP, and every line on the PFMEA worksheet and every row on the control plan traces back to a numbered step on the PFD.\" },\n        { type: \"h\", text: \"Standard PFD symbols\" },\n        { type: \"p\", text: \"Process flow diagrams use a small set of standard symbols. Each symbol tells the reader what type of activity is happening at that step. Consistent use of these symbols makes the PFD readable across departments and across plants.\" },\n        { type: \"table\", head: [\"Symbol\", \"Name\", \"Meaning\", \"Example\"], rows: [\n          [\"Rectangle\", \"Operation\", \"A step that transforms the product — machining, mixing, assembly, heat treatment\", \"Turn brake disc on CNC lathe\"],\n          [\"Circle\", \"Inspection\", \"A check, measurement or test\", \"Measure disc thickness with micrometer\"],\n          [\"Arrow\", \"Transport\", \"Movement of material between workstations\", \"Fork-lift disc pallet to grinding area\"],\n          [\"D-shape\", \"Delay\", \"Unplanned or planned waiting\", \"Wait for lathe availability\"],\n          [\"Inverted triangle\", \"Storage\", \"Controlled storage of raw material, WIP or finished goods\", \"Store finished discs in warehouse\"],\n          [\"Diamond\", \"Decision\", \"Yes/no question that splits the flow\", \"Does disc meet thickness tolerance?\"],\n        ] },\n        { type: \"equip\", title: \"Process flow diagram\", items: [\n          { art: \"process-flow-chart\", caption: \"A process flow diagram for brake disc machining at a Douala foundry. Each step is numbered and linked to rows in the PFMEA and control plan.\" },\n        ] },\n        { type: \"callout\", tone: \"key\", title: \"Every step gets a number\", text: \"Number each operation sequentially (10, 20, 30 … or 1.0, 2.0, 3.0 …). These numbers become the **process step** column in the PFMEA and the control plan. If you change the PFD, update both documents.\" },\n        { type: \"h\", text: \"Linking PFD to PFMEA and control plan\" },\n        { type: \"p\", text: \"The PFD, PFMEA and control plan form a triad — three documents that must stay aligned. The PFD lists every step. The PFMEA analyses what can go wrong at each step. The control plan specifies what to measure and how to react at each step. Together they ensure that no step is analysed without being mapped, and no control is written without a risk analysis behind it.\" },\n        { type: \"steps\", title: \"Building the quality planning triad\", items: [\n          \"Draft the PFD from receiving raw material to shipping finished goods, including rework loops and scrap paths.\",\n          \"Walk the actual production floor and verify the PFD matches reality — add any steps the team missed.\",\n          \"Number every step and transfer the numbers to the PFMEA structure analysis column.\",\n          \"After completing the PFMEA, transfer the controls and specifications to the control plan, step by step.\",\n          \"When the process changes, update the PFD first, then cascade the change through PFMEA and control plan.\",\n        ] },\n        { type: \"h\", text: \"Value stream mapping basics\" },\n        { type: \"p\", text: \"A value stream map (VSM) goes beyond the PFD by adding time and inventory data. It distinguishes **value-added** steps (those the customer would pay for) from **non-value-added** steps (transport, delay, storage, rework). In a typical Cameroonian cement plant, only 15–25 % of total lead time is value-added; the rest is waiting, moving or inspecting.\" },\n        { type: \"list\", items: [\n          \"**Value-added (VA)**: any step that physically transforms the product toward what the customer wants — grinding clinker, mixing, filling bags.\",\n          \"**Non-value-added but necessary (NVAN)**: steps required by regulation or process need but not by the customer — incoming inspection, lab testing, regulatory sampling.\",\n          \"**Non-value-added (NVA)**: pure waste — waiting for fork-lift, double handling, rework. These are the targets for elimination.\",\n        ] },\n        { type: \"callout\", tone: \"workplace\", title: \"In the workplace\", text: \"At a beverage filling plant near Bafoussam, the quality team mapped the flow from syrup preparation to palletising and found that bottles spent 40 % of their time waiting between the filler and the labeller. Moving the labeller closer cut the lead time by a third and reduced breakage during transport.\" },\n        { type: \"sorter\", id: \"aqe-m6-l1-sort1\", layout: \"steps\", title: \"Classify process steps by type\", task: \"Place each step from a fictional brake disc manufacturing line in Douala into the correct symbol category.\",\n          hint: \"Ask: does this step change the product (operation), check it (inspection), move it (transport), wait (delay), store it (storage), or branch the flow (decision)?\",\n          buckets: [\n            { label: \"Operation\" },\n            { label: \"Inspection\" },\n            { label: \"Transport\" },\n            { label: \"Delay\" },\n            { label: \"Storage\" },\n            { label: \"Decision\" },\n          ],\n          items: [\n            { text: \"Cast brake disc blank in sand mould\", bucket: 0, explain: \"Casting transforms raw iron into a disc blank — this is an operation.\" },\n            { text: \"Measure disc thickness with outside micrometer\", bucket: 1, explain: \"Measurement is an inspection activity.\" },\n            { text: \"Move disc pallet from foundry to machining shop by fork-lift\", bucket: 2, explain: \"Physical movement of material is transport.\" },\n            { text: \"Wait for CNC lathe to become available\", bucket: 3, explain: \"Waiting for equipment is a delay.\" },\n            { text: \"Place finished discs on warehouse racking\", bucket: 4, explain: \"Controlled storage of finished goods.\" },\n            { text: \"Does the disc pass dimensional inspection?\", bucket: 5, explain: \"A yes/no question that splits the flow into accept or rework is a decision.\" },\n            { text: \"Turn disc faces on CNC lathe to final thickness\", bucket: 0, explain: \"Machining transforms the product — this is an operation.\" },\n            { text: \"Visual check for surface cracks after grinding\", bucket: 1, explain: \"A visual check is an inspection step.\" },\n          ],\n        },\n        { type: \"form\", id: \"aqe-m6-l1-form1\", title: \"Identify flow diagram errors\", task: \"A junior engineer drafted a PFD for a cement bagging line but made several mistakes. For each question, select the correct answer.\",\n          hint: \"Think about what each symbol represents and whether the flow is logical.\",\n          fields: [\n            { kind: \"select\", label: \"The engineer used a rectangle for the 'weigh each bag on check-weigher' step. What symbol should it be?\", options: [\"Rectangle (operation)\", \"Circle (inspection)\", \"Diamond (decision)\", \"Arrow (transport)\"], answer: 1, explain: \"Weighing a bag is a measurement — an inspection step, shown as a circle.\" },\n            { kind: \"select\", label: \"The PFD shows bag filling immediately followed by palletising with no step between. What is most likely missing?\", options: [\"A transport step\", \"A delay step\", \"An inspection step\", \"A storage step\"], answer: 2, explain: \"After filling, the bags are typically checked (weight, seal integrity) before palletising. An inspection step is missing.\" },\n            { kind: \"select\", label: \"The engineer drew a decision diamond 'Is bag weight OK?' but only drew one output arrow (Yes). What else is needed?\", options: [\"Nothing — one arrow is enough\", \"A No arrow leading to a rework or reject path\", \"A second Yes arrow to a different operation\", \"A storage triangle before the decision\"], answer: 1, explain: \"A decision diamond must have two outputs: Yes (continue) and No (rework, reject, or adjust). The No path is missing.\" },\n            { kind: \"select\", label: \"Step numbers on the PFD are 10, 20, 30, 55, 60. What is wrong?\", options: [\"Nothing — any numbers are fine\", \"The jump from 30 to 55 suggests a step may have been deleted without renumbering\", \"Numbers should always be 1, 2, 3, 4, 5\", \"The numbers should decrease\"], answer: 1, explain: \"A gap from 30 to 55 suggests a step was removed. The PFD should be renumbered for clarity, and the PFMEA and control plan checked for orphaned rows.\" },\n          ],\n        },\n        { type: \"check\", id: \"aqe-m6-l1-c1\", question: \"Which document should be updated FIRST when a new rework loop is added to the manufacturing process?\", options: [\"The control plan\", \"The process FMEA\", \"The process flow diagram\", \"The inspection and test plan\"], answer: 2, explain: \"The PFD is the foundation. Any process change starts with updating the PFD, then cascading through the PFMEA and control plan.\" },\n        { type: \"links\", items: [\n          { label: \"AIAG APQP and Control Plan Reference Manual\", url: \"https://www.aiag.org/quality/automotive-core-tools/apqp\", source: AIAG },\n          { label: \"Process mapping for quality improvement\", url: \"https://asq.org/quality-resources/flowchart\", source: ASQ },\n        ] },\n      ],\n    },\n    // ─────────────────────────────── LESSON 2 ───────────────────────────────\n    {\n      id: \"aqe-m6-l2\",\n      title: \"Process FMEA: the AIAG/VDA approach\",\n      minutes: 35,\n      objectives: [\n        \"Explain the purpose of process FMEA and when to apply it in the product development cycle\",\n        \"Follow the AIAG/VDA seven-step approach from planning through results documentation\",\n        \"Rate severity, occurrence and detection on the 1–10 scales and determine action priority (AP)\",\n        \"Distinguish action priority (AP) from the legacy RPN method and explain why AP replaced it\",\n      ],\n      blocks: [\n        { type: \"p\", text: \"Process FMEA is the systematic method for identifying what can go wrong in a manufacturing process, rating the risk, and putting controls in place before production starts. The AIAG/VDA FMEA Handbook (1st edition, 2019) introduced a structured seven-step approach and replaced the old Risk Priority Number (RPN) with **action priority (AP)**, which guides the team more clearly on when action is mandatory.\" },\n        { type: \"h\", text: \"Purpose, scope and team\" },\n        { type: \"list\", items: [\n          \"**Purpose**: identify potential failure modes in the manufacturing process, evaluate their effects on the customer, find root causes, and define prevention and detection controls.\",\n          \"**Scope**: one PFMEA covers one process or one product family on one production line. A brake disc line and a drum brake line each get their own PFMEA.\",\n          \"**Team**: cross-functional — process engineer, quality engineer, production supervisor, maintenance technician, and someone who knows the customer application. No PFMEA should be done by one person alone.\",\n        ] },\n        { type: \"callout\", tone: \"key\", title: \"FMEA is prevention, not reaction\", text: \"The value of FMEA is in what it prevents, not in what it documents. A PFMEA completed after production starts and after defects appear has missed its purpose. Start the PFMEA during process design, before the first part is made.\" },\n        { type: \"h\", text: \"The seven-step approach\" },\n        { type: \"steps\", title: \"AIAG/VDA FMEA seven steps\", items: [\n          \"**Planning and preparation**: define the scope, the team, the timing. Confirm which product and process the FMEA covers. Gather the PFD, specifications and lessons learnt from similar processes.\",\n          \"**Structure analysis**: break the process into a hierarchy — system (the line), subsystem (the station), and element (the individual operation). Use the PFD step numbers.\",\n          \"**Function analysis**: for each element, state what it must do. \\\"Turn disc to 12.0 ± 0.1 mm thickness\\\" is a function. Every function becomes a potential source of failure.\",\n          \"**Failure analysis**: identify the failure mode (what goes wrong), the failure effect (what the customer experiences), and the failure cause (why it goes wrong). Use a chain: cause → mode → effect.\",\n          \"**Risk analysis**: rate severity (S), occurrence (O) and detection (D) on 1–10 scales and determine the action priority (AP).\",\n          \"**Optimisation**: for high and medium AP, assign actions to reduce S, O or D. Prevention actions reduce O; detection actions reduce D; design changes may reduce S.\",\n          \"**Results documentation**: record the actions taken, the responsible person, the target date, and the revised S, O, D and AP after implementation. The PFMEA is a living document — update it whenever the process changes.\",\n        ] },\n        { type: \"equip\", title: \"PFMEA worksheet (AIAG/VDA format)\", items: [\n          { art: \"pfmea-worksheet\", caption: \"The PFMEA worksheet shows the structure analysis, function analysis, failure chain, S/O/D ratings, action priority, and recommended actions in a single row per failure mode.\" },\n        ] },\n        { type: \"h\", text: \"Severity, occurrence and detection scales\" },\n        { type: \"p\", text: \"Each scale runs from 1 (lowest risk) to 10 (highest risk). The team must agree on the rating for each failure mode using the scale descriptions, not gut feeling.\" },\n        { type: \"table\", head: [\"Rating\", \"Severity level\", \"Description\"], rows: SEV_SCALE },\n        { type: \"table\", head: [\"Rating\", \"Occurrence level\", \"Description\"], rows: OCC_SCALE },\n        { type: \"table\", head: [\"Rating\", \"Detection level\", \"Description\"], rows: DET_SCALE },\n        { type: \"callout\", tone: \"warning\", title: \"Severity is set by the effect, not the cause\", text: \"A severity of 9 or 10 means a safety hazard or regulatory breach. The team cannot reduce severity by adding a control — severity is inherent to the failure effect. Only a design change that eliminates the hazardous effect can reduce severity.\" },\n        { type: \"h\", text: \"Action priority (AP) replaces RPN\" },\n        { type: \"p\", text: \"The old RPN method multiplied S × O × D to get a number from 1 to 1 000. The problem: an RPN of 200 could mean S=10, O=5, D=4 (a safety hazard with moderate occurrence) or S=4, O=5, D=10 (a minor effect with no detection). The AP method evaluates the combination of S, O and D using a lookup table and assigns a priority of **High (H)**, **Medium (M)** or **Low (L)**.\" },\n        { type: \"table\", head: [\"Priority\", \"Criteria (simplified)\", \"Required response\"], rows: AP_TABLE },\n        { type: \"callout\", tone: \"tip\", title: \"AP lookup table\", text: \"The full AP table in the AIAG/VDA handbook has entries for every combination of S, O and D. For the exam, remember: **any failure with S >= 9** generally drives AP = H regardless of O and D, because safety effects demand action. When S is moderate (4–6), AP depends heavily on whether O and D together suggest the failure will reach the customer.\" },\n        { type: \"h\", text: \"Worked example: brake disc machining\" },\n        { type: \"p\", text: \"At a fictional foundry in Douala, the PFMEA team analyses the CNC turning operation for brake discs. The function is 'Turn disc to 12.0 ± 0.1 mm thickness'. The failure mode is 'Disc turned undersize (< 11.9 mm)'. The effect is 'Disc too thin — reduced braking capacity — safety risk to vehicle occupants'. The cause is 'Tool wear not compensated — operator does not adjust offset'. The severity is 9 (safety), occurrence is 5 (occasional — tool offset adjustment is manual), and detection is 6 (100 % measurement exists but operator sometimes skips it). The AP is **High** — mandatory action.\" },\n        { type: \"table\", head: [\"Process step\", \"Function\", \"Failure mode\", \"Effect\", \"Cause\", \"S\", \"O\", \"D\", \"AP\"], rows: [\n          [\"20 — CNC turning\", \"Turn disc to 12.0 ± 0.1 mm\", \"Disc turned undersize (< 11.9 mm)\", \"Reduced braking capacity — safety risk\", \"Tool wear; operator skips offset adjustment\", \"9\", \"5\", \"6\", \"H\"],\n          [\"20 — CNC turning\", \"Turn disc to 12.0 ± 0.1 mm\", \"Disc turned oversize (> 12.1 mm)\", \"Disc does not fit calliper — assembly rejection\", \"Wrong programme loaded\", \"6\", \"3\", \"4\", \"M\"],\n          [\"30 — Grinding\", \"Grind friction surface to Ra 0.8 µm max\", \"Surface too rough (Ra > 0.8 µm)\", \"Brake noise and vibration — customer complaint\", \"Worn grinding wheel not replaced\", \"5\", \"4\", \"5\", \"M\"],\n          [\"40 — Drilling\", \"Drill 5 mounting holes ∅10.5 ± 0.1 mm\", \"Hole diameter oversize\", \"Bolt looseness — disc may shift under braking\", \"Drill bit worn beyond limit\", \"8\", \"3\", \"3\", \"M\"],\n        ] },\n        { type: \"form\", id: \"aqe-m6-l2-form1\", title: \"Rate S, O, D and determine AP\", task: \"For each failure mode from a fictional beverage filling line in Bafoussam, rate severity, occurrence and detection, then determine the action priority.\",\n          hint: \"Use the rating scales above. Remember: severity is based on the effect on the customer, occurrence on how often the cause happens, and detection on whether current controls will catch it.\",\n          fields: [\n            { kind: \"select\", label: \"Failure mode: 'Fill volume below minimum (< 325 ml in a 330 ml bottle)'. Effect: 'Customer receives under-filled product — regulatory noncompliance with ANOR labelling requirements'. What is the severity?\", options: [\"S = 4 (Moderate)\", \"S = 6 (Moderate–High)\", \"S = 8 (High)\", \"S = 9 (Very high — regulatory)\"], answer: 3, explain: \"Regulatory noncompliance is a severity of 9. Even though it is not a direct safety hazard, failing to meet labelled net content violates trade measurement laws.\" },\n            { kind: \"select\", label: \"Same failure mode. Cause: 'Filler valve sticking intermittently — no predictive maintenance programme'. How often does this happen?\", options: [\"O = 2 (Low — rare)\", \"O = 5 (Moderate — occasional)\", \"O = 7 (High — frequent)\", \"O = 9 (Very high — almost certain)\"], answer: 1, explain: \"Without a maintenance programme, sticking valves are occasional. O = 5 is appropriate — the cause is known but not well prevented.\" },\n            { kind: \"select\", label: \"Same failure mode. Current detection control: 'Check-weigher on line rejects under-filled bottles automatically'. How effective is this detection?\", options: [\"D = 2 (High — automatic rejection)\", \"D = 5 (Moderate — may miss some)\", \"D = 7 (Low — relies on manual check)\", \"D = 9 (None — no detection)\"], answer: 0, explain: \"An automatic check-weigher that rejects under-filled bottles is a strong detection control — D = 2.\" },\n            { kind: \"select\", label: \"With S = 9, O = 5, D = 2, what is the action priority?\", options: [\"Low (L)\", \"Medium (M)\", \"High (H)\"], answer: 2, explain: \"With S = 9, the action priority is High regardless of O and D. Safety and regulatory severity always drives High AP.\" },\n          ],\n        },\n        { type: \"sorter\", id: \"aqe-m6-l2-sort1\", layout: \"columns\", title: \"Classify failure modes by severity category\", task: \"Place each failure mode from various Cameroonian manufacturing processes into the correct severity category.\",\n          hint: \"Focus on the effect of the failure on the end customer or on regulatory compliance, not on how likely it is.\",\n          buckets: [\n            { label: \"Minor (S 1–3)\" },\n            { label: \"Moderate (S 4–6)\" },\n            { label: \"High (S 7–8)\" },\n            { label: \"Very high / Hazardous (S 9–10)\" },\n          ],\n          items: [\n            { text: \"Cosmetic scratch on cement bag — no effect on contents\", bucket: 0, explain: \"A cosmetic blemish on packaging that does not affect the product is a minor severity (S = 2–3).\" },\n            { text: \"Label misaligned on beverage bottle — readable but crooked\", bucket: 0, explain: \"The label is still readable; the customer notices but the product functions — minor severity.\" },\n            { text: \"Fill volume 2 ml above target — slight overfill\", bucket: 1, explain: \"Slight overfill costs the producer money but does not harm the customer. Moderate severity (S = 4–5).\" },\n            { text: \"Cement compressive strength below specification — structural risk\", bucket: 3, explain: \"Below-specification cement used in construction could lead to structural failure — this is a safety hazard, S = 9–10.\" },\n            { text: \"Brake disc thickness out of tolerance — reduced braking capacity\", bucket: 3, explain: \"Any failure affecting braking performance is a safety hazard — S = 9–10.\" },\n            { text: \"Bottle cap not sealed properly — product leaks during transport\", bucket: 2, explain: \"Product leakage makes the product unusable and could contaminate other goods — high severity (S = 7–8) but not a direct safety hazard.\" },\n          ],\n        },\n        { type: \"check\", id: \"aqe-m6-l2-c1\", question: \"Why did the AIAG/VDA handbook replace RPN with action priority (AP)?\", options: [\n          \"AP is faster to calculate than RPN\",\n          \"RPN treats all combinations of S, O and D equally — a safety hazard with low occurrence gets the same RPN as a cosmetic issue with high occurrence\",\n          \"AP uses a 1–100 scale instead of 1–1000\",\n          \"AP does not require a cross-functional team\",\n        ], answer: 1, explain: \"The fundamental problem with RPN is that the same numerical product can come from very different risk profiles. AP uses a structured lookup that distinguishes safety-critical failures from lesser ones, ensuring that high-severity failures always receive attention.\" },\n        { type: \"check\", id: \"aqe-m6-l2-c2\", question: \"Which of the following actions can reduce the severity (S) rating of a failure mode?\",  options: [\n          \"Adding a second inspection step after the operation\",\n          \"Increasing the frequency of preventive maintenance\",\n          \"Redesigning the product so the failure effect is less harmful\",\n          \"Training operators to follow work instructions more carefully\",\n        ], answer: 2, explain: \"Severity is inherent to the failure effect. Only a design change that alters the effect itself can reduce severity. Additional inspection reduces detection (D), maintenance reduces occurrence (O), and training reduces occurrence (O).\" },\n        { type: \"links\", items: [\n          { label: \"AIAG & VDA FMEA Handbook\", url: \"https://www.aiag.org/quality/automotive-core-tools/fmea\", source: AIAG },\n          { label: \"FMEA body of knowledge\", url: \"https://asq.org/quality-resources/fmea\", source: ASQ },\n        ] },\n      ],\n    },\n    // ─────────────────────────────── LESSON 3 ───────────────────────────────\n    {\n      id: \"aqe-m6-l3\",\n      title: \"Control plans: from prototype to production\",\n      minutes: 30,\n      objectives: [\n        \"Explain the purpose of the control plan and its relationship to the PFD and PFMEA\",\n        \"Distinguish the three control plan phases: prototype, pre-launch and production\",\n        \"Complete a control plan entry specifying what to control, how to measure, sample size and frequency, control method and reaction plan\",\n      ],\n      blocks: [\n        { type: \"p\", text: \"The control plan translates the risk analysis of the PFMEA into day-to-day instructions for production and inspection. It tells the operator and the inspector exactly what to measure, how often, with what instrument, and what to do when a result is out of specification. Without a control plan, the PFMEA stays a planning document that never reaches the shop floor.\" },\n        { type: \"h\", text: \"Control plan purpose and structure\" },\n        { type: \"p\", text: \"The AIAG control plan format organises controls by process step, matching the numbering on the PFD. For each step, the control plan specifies:\" },\n        { type: \"list\", items: [\n          \"**Process step number and name** — from the PFD.\",\n          \"**Product characteristic** — the feature that matters to the customer (dimension, weight, hardness).\",\n          \"**Process parameter** — the machine setting that affects the product characteristic (speed, temperature, pressure).\",\n          \"**Specification and tolerance** — the acceptable range.\",\n          \"**Measurement method and instrument** — how to check it.\",\n          \"**Sample size and frequency** — how many parts and how often.\",\n          \"**Control method** — the technique used (SPC chart, check sheet, visual inspection, go/no-go gauge).\",\n          \"**Reaction plan** — what to do when the result is out of specification (stop the line, adjust, quarantine, notify).\",\n        ] },\n        { type: \"equip\", title: \"Control plan form\", items: [\n          { art: \"control-plan-form\", caption: \"The AIAG control plan form. Each row covers one characteristic at one process step, with columns for specification, measurement, sampling and reaction.\" },\n        ] },\n        { type: \"h\", text: \"Three phases of the control plan\" },\n        { type: \"table\", head: [\"Phase\", \"When\", \"Purpose\", \"Typical sample size\"], rows: [\n          [\"Prototype\", \"During product development, before tooling is finalised\", \"Validate the design — check dimensions, materials and performance on prototype parts\", \"100 % measurement of all characteristics\"],\n          [\"Pre-launch\", \"After tooling, before full production rate\", \"Validate the process — confirm that the production equipment can consistently make parts to specification\", \"Increased frequency — often 100 % or every nth part with short intervals\"],\n          [\"Production\", \"During normal serial production\", \"Maintain control — monitor the process and react to variation before defects reach the customer\", \"Statistical sampling — e.g. 5 parts every 2 hours for SPC\"],\n        ] },\n        { type: \"callout\", tone: \"key\", title: \"The control plan is a living document\", text: \"The production control plan is not locked at launch. Update it when the PFMEA changes, when a customer complaint reveals a new failure mode, when SPC data shows a characteristic is stable enough to reduce sampling, or when a process change adds a new step.\" },\n        { type: \"h\", text: \"Linking control plan to PFD and PFMEA\" },\n        { type: \"p\", text: \"The three documents form a closed loop. The PFD defines the process steps. The PFMEA identifies risks at each step. The control plan defines the actions to manage those risks during production. If a row exists in the PFMEA with AP = High, there **must** be a corresponding row in the control plan with a robust control method and a clear reaction plan.\" },\n        { type: \"steps\", title: \"Building the control plan from the PFMEA\", items: [\n          \"Start with the PFMEA. For each failure mode with AP = High or Medium, identify the product characteristic or process parameter that must be controlled.\",\n          \"Specify the measurement method: what instrument, what resolution, what training the operator needs.\",\n          \"Set the sample size and frequency based on the risk: higher risk = more frequent checks. For AP = High, consider 100 % inspection or automated monitoring.\",\n          \"Define the control method: X-bar and R chart for continuous data, p-chart for attribute data, check sheet, mistake-proofing device.\",\n          \"Write a reaction plan that says exactly what to do: stop the machine, quarantine the last N parts, call the supervisor, adjust the setting.\",\n        ] },\n        { type: \"callout\", tone: \"workplace\", title: \"In the workplace\", text: \"At a cement plant near Douala, the control plan for the bagging line specifies that bag weight is checked on a check-weigher (100 % automatic) and on a manual scale (5 bags every 30 minutes). When the check-weigher rejects more than 3 bags in a row, the reaction plan says: stop the line, recalibrate the filler, and re-weigh the last 50 bags manually.\" },\n        { type: \"h\", text: \"Specifying controls: a worked example\" },\n        { type: \"table\", head: [\"Field\", \"Entry (brake disc example)\"], rows: [\n          [\"Process step\", \"20 — CNC turning\"],\n          [\"Product characteristic\", \"Disc thickness\"],\n          [\"Specification\", \"12.0 ± 0.1 mm\"],\n          [\"Measurement method\", \"Outside micrometer, 0.01 mm resolution\"],\n          [\"Sample size / Frequency\", \"5 discs every 2 hours (SPC subgroup)\"],\n          [\"Control method\", \"X-bar and R chart; control limits from capability study\"],\n          [\"Reaction plan\", \"If point beyond UCL/LCL: stop lathe, check tool wear, adjust offset, re-measure last 10 discs, quarantine suspect lot\"],\n        ] },\n        { type: \"form\", id: \"aqe-m6-l3-form1\", title: \"Complete control plan entries from PFMEA output\", task: \"The PFMEA for a beverage filling line identified three failure modes with AP = High or Medium. Complete the control plan entries.\",\n          hint: \"Match the measurement method to the characteristic type (continuous or attribute) and set the sample frequency based on the action priority.\",\n          fields: [\n            { kind: \"select\", label: \"PFMEA: fill volume below 325 ml (AP = High). What sample frequency is most appropriate?\", options: [\"5 bottles per shift\", \"5 bottles every hour\", \"100 % automatic check-weigher\", \"1 bottle per day\"], answer: 2, explain: \"With AP = High and regulatory risk, 100 % automatic inspection is the appropriate control. A check-weigher on the line ensures every bottle is verified.\" },\n            { kind: \"select\", label: \"PFMEA: cap torque too low — cap comes off in transit (AP = Medium). What control method?\", options: [\"Visual inspection only\", \"Torque wrench check: 5 bottles every 30 minutes, recorded on check sheet\", \"Taste test\", \"Annual calibration of capper\"], answer: 1, explain: \"Cap torque is a continuous measurement. Regular sampling with a torque wrench and recording on a check sheet gives objective evidence of control.\" },\n            { kind: \"select\", label: \"PFMEA: label misaligned (AP = Low). What is an appropriate reaction plan?\", options: [\"Stop the entire plant immediately\", \"Adjust the labeller and relabel the last 20 bottles\", \"No action needed — ship as is\", \"Recall all product from distributors\"], answer: 1, explain: \"For a low-severity cosmetic issue, the reaction plan should correct the process (adjust labeller) and fix recent production (relabel), without stopping the entire plant.\" },\n            { kind: \"select\", label: \"Which control plan phase would use 100 % measurement of every dimension on every part?\", options: [\"Prototype\", \"Pre-launch\", \"Production\", \"None — 100 % is never used\"], answer: 0, explain: \"The prototype phase uses 100 % measurement of all characteristics to validate the design before tooling is finalised.\" },\n          ],\n        },\n        { type: \"sheet\", id: \"aqe-m6-l3-sheet1\", title: \"Build a control plan section\", task: \"Complete the missing cells in this control plan for a cement bagging line. Use the PFMEA data in columns A–D to fill the control plan entries in columns E–H.\",\n          data: [\n            [\"Process step\", \"Failure mode\", \"S\", \"AP\", \"Measurement method\", \"Sample size / Frequency\", \"Control method\", \"Reaction plan\"],\n            [\"10 — Filling\", \"Bag weight below 50 kg\", 9, \"H\", null, null, null, null],\n            [\"20 — Sealing\", \"Bag seal not closed\", 7, \"M\", null, null, null, null],\n            [\"30 — Palletising\", \"Bag placement crooked on pallet\", 3, \"L\", null, null, null, null],\n          ],\n          editable: [\"E2\", \"F2\", \"G2\", \"H2\", \"E3\", \"F3\", \"G3\", \"H3\", \"E4\", \"F4\", \"G4\", \"H4\"],\n          checks: [\n            { cell: \"E2\", equals: \"Check-weigher (automatic)\" },\n            { cell: \"F2\", equals: \"100 %\" },\n            { cell: \"G2\", equals: \"Automatic reject\" },\n            { cell: \"H2\", equals: \"Stop line; recalibrate filler; re-weigh last 50 bags\" },\n            { cell: \"E3\", equals: \"Visual + pull test\" },\n            { cell: \"F3\", equals: \"5 bags every 30 minutes\" },\n            { cell: \"G3\", equals: \"Check sheet\" },\n            { cell: \"H3\", equals: \"Stop sealer; adjust; re-check last batch\" },\n            { cell: \"E4\", equals: \"Visual inspection\" },\n            { cell: \"F4\", equals: \"Every pallet\" },\n            { cell: \"G4\", equals: \"Visual check by operator\" },\n            { cell: \"H4\", equals: \"Re-stack affected pallet\" },\n          ],\n          hint: \"For AP = H, use automatic detection (100 %). For AP = M, use regular sampling. For AP = L, visual checks at natural points in the process are sufficient.\",\n          solution: {\n            \"E2\": \"Check-weigher (automatic)\",\n            \"F2\": \"100 %\",\n            \"G2\": \"Automatic reject\",\n            \"H2\": \"Stop line; recalibrate filler; re-weigh last 50 bags\",\n            \"E3\": \"Visual + pull test\",\n            \"F3\": \"5 bags every 30 minutes\",\n            \"G3\": \"Check sheet\",\n            \"H3\": \"Stop sealer; adjust; re-check last batch\",\n            \"E4\": \"Visual inspection\",\n            \"F4\": \"Every pallet\",\n            \"G4\": \"Visual check by operator\",\n            \"H4\": \"Re-stack affected pallet\",\n          },\n        },\n        { type: \"check\", id: \"aqe-m6-l3-c1\", question: \"A PFMEA failure mode has AP = High. Which control plan approach is most appropriate?\", options: [\n          \"No control needed — AP = High means the risk is already managed\",\n          \"Visual inspection once per shift\",\n          \"100 % automated inspection or mistake-proofing, with a documented reaction plan\",\n          \"Sampling once per week by the quality manager\",\n        ], answer: 2, explain: \"AP = High means mandatory action. The control plan should include robust controls — preferably 100 % automated inspection or mistake-proofing — with a clear reaction plan for out-of-specification results.\" },\n        { type: \"links\", items: [\n          { label: \"AIAG APQP and Control Plan Manual\", url: \"https://www.aiag.org/quality/automotive-core-tools/apqp\", source: AIAG },\n        ] },\n      ],\n    },\n    // ─────────────────────────────── LESSON 4 ───────────────────────────────\n    {\n      id: \"aqe-m6-l4\",\n      title: \"Inspection and test planning\",\n      minutes: 25,\n      objectives: [\n        \"Describe the structure of an inspection and test plan (ITP) and its role in quality assurance\",\n        \"Distinguish review points (R), witness points (W) and hold points (H)\",\n        \"Select the appropriate inspection method — 100 %, sampling or skip-lot — based on risk and history\",\n        \"Explain the purpose of first article inspection (FAI) and its link to PPAP dimensional results\",\n      ],\n      blocks: [\n        { type: \"p\", text: \"The inspection and test plan (ITP) is the operational document that tells inspectors exactly where, when and how to check the product during manufacturing. While the control plan focuses on process control (what to monitor to keep the process stable), the ITP focuses on product verification (what to measure to confirm the product meets its specification).\" },\n        { type: \"h\", text: \"ITP structure\" },\n        { type: \"p\", text: \"An ITP is typically a table with one row per inspection activity. Each row specifies:\" },\n        { type: \"table\", head: [\"Column\", \"Content\", \"Example\"], rows: [\n          [\"Operation number\", \"The process step from the PFD\", \"20 — CNC turning\"],\n          [\"Inspection point type\", \"R (review), W (witness), or H (hold)\", \"H\"],\n          [\"Characteristic\", \"What is being checked\", \"Disc thickness\"],\n          [\"Acceptance criteria\", \"The specification and tolerance\", \"12.0 ± 0.1 mm\"],\n          [\"Method and instrument\", \"How to check it\", \"Outside micrometer, 0.01 mm resolution\"],\n          [\"Frequency / Sample size\", \"How many and how often\", \"5 per lot of 200\"],\n          [\"Records reference\", \"Where results are recorded\", \"Form QC-042, line 3\"],\n        ] },\n        { type: \"equip\", title: \"Inspection and test plan document\", items: [\n          { art: \"itp-document\", caption: \"An ITP for brake disc production. Hold points are highlighted — production cannot proceed past these steps without inspector sign-off.\" },\n        ] },\n        { type: \"h\", text: \"Hold points, witness points and review points\" },\n        { type: \"table\", head: [\"Type\", \"Code\", \"Meaning\", \"Who is involved\", \"Effect on production flow\"], rows: [\n          [\"Review point\", \"R\", \"Inspector reviews records after the operation — no need to be present\", \"Inspector reviews documents off-line\", \"Production continues; records reviewed later\"],\n          [\"Witness point\", \"W\", \"Inspector is invited to observe the operation or test\", \"Inspector observes; production may proceed if inspector is unavailable after notification\", \"Production may continue if inspector was notified and did not attend\"],\n          [\"Hold point\", \"H\", \"Production stops until the inspector verifies and signs off\", \"Inspector must be physically present and sign\", \"Production CANNOT proceed without inspector release\"],\n        ] },\n        { type: \"callout\", tone: \"warning\", title: \"Hold points are mandatory stops\", text: \"A hold point means the product sits until the inspector arrives, checks and signs. If production passes a hold point without inspector sign-off, all product made after that point is suspect and may need to be quarantined and re-inspected. Use hold points sparingly — only for critical characteristics where the consequence of a miss is severe.\" },\n        { type: \"h\", text: \"Inspection methods\" },\n        { type: \"table\", head: [\"Method\", \"Description\", \"When to use\"], rows: [\n          [\"100 % inspection\", \"Every unit is checked\", \"Critical safety characteristics, low-volume production, or when process capability is unknown\"],\n          [\"Sampling inspection\", \"A sample is drawn from each lot and inspected; the lot is accepted or rejected based on the sample results\", \"High-volume production where 100 % is impractical, and the process has demonstrated reasonable capability\"],\n          [\"Skip-lot inspection\", \"Some lots are skipped entirely based on a history of good quality\", \"Established suppliers or processes with a proven track record of consistently meeting specifications\"],\n        ] },\n        { type: \"h\", text: \"First article inspection (FAI) and PPAP\" },\n        { type: \"p\", text: \"First article inspection is the complete, detailed measurement of one or more parts from the first production run using production tooling, at the production rate. FAI verifies that the process can produce parts that meet every dimension and specification on the drawing. In the automotive supply chain, FAI results feed into the PPAP (Production Part Approval Process) submission, specifically the **dimensional results** element.\" },\n        { type: \"list\", items: [\n          \"FAI measures every dimension on the drawing, not just the critical ones.\",\n          \"Results are recorded on a ballooned drawing and a corresponding measurement report.\",\n          \"If any dimension fails, the FAI is not approved and the process must be corrected before production.\",\n          \"FAI is repeated when the process changes significantly: new tooling, new material, new supplier, or after a long production break.\",\n        ] },\n        { type: \"equip\", title: \"PPAP submission package\", items: [\n          { art: \"ppap-package\", caption: \"The PPAP package includes the PFD, PFMEA, control plan, MSA results, dimensional results (FAI), and the Part Submission Warrant — all linked together.\" },\n        ] },\n        { type: \"callout\", tone: \"workplace\", title: \"In the workplace\", text: \"At a brake disc foundry near Douala supplying an assembly plant in South Africa, the customer requires PPAP Level 3: full documentation including the PFD, PFMEA, control plan, MSA study, dimensional results and a Part Submission Warrant signed by the quality manager. Production cannot begin until the PSW is approved by the customer.\" },\n        { type: \"form\", id: \"aqe-m6-l4-form1\", title: \"Design ITP entries for given processes\", task: \"For each process step, select the correct inspection point type and inspection method.\",\n          hint: \"Use hold points (H) for critical safety characteristics, witness points (W) for important but not safety-critical steps, and review points (R) for routine documentation reviews.\",\n          fields: [\n            { kind: \"select\", label: \"Brake disc final thickness check — a safety-critical dimension. What inspection point type?\", options: [\"R — Review point\", \"W — Witness point\", \"H — Hold point\"], answer: 2, explain: \"Disc thickness directly affects braking performance. This is a safety-critical characteristic that requires a hold point — production cannot proceed without inspector sign-off.\" },\n            { kind: \"select\", label: \"Cement bag printing quality — cosmetic only. What inspection point type?\", options: [\"R — Review point\", \"W — Witness point\", \"H — Hold point\"], answer: 0, explain: \"Printing quality is cosmetic and does not affect product performance. A review point is sufficient — the inspector can check records after the fact.\" },\n            { kind: \"select\", label: \"Beverage pasteurisation temperature — food safety requirement. What inspection method?\", options: [\"100 % (continuous monitoring)\", \"Sampling (5 per hour)\", \"Skip-lot (check every 10th batch)\"], answer: 0, explain: \"Pasteurisation temperature is a food safety critical control point. It must be monitored continuously (100 %) with automatic recording and alarms.\" },\n            { kind: \"select\", label: \"Incoming inspection of carton packaging from a long-standing supplier with no quality issues in 2 years. What inspection method?\", options: [\"100 % inspection of every carton\", \"Normal sampling per AQL plan\", \"Skip-lot or reduced sampling\"], answer: 2, explain: \"A supplier with a proven two-year track record of good quality qualifies for skip-lot or reduced inspection.\" },\n          ],\n        },\n        { type: \"sorter\", id: \"aqe-m6-l4-sort1\", layout: \"columns\", title: \"Classify inspection types\", task: \"Place each inspection activity into the correct inspection point category.\",\n          hint: \"R = records reviewed later, W = inspector invited to watch, H = production stops until inspector signs.\",\n          buckets: [\n            { label: \"Review point (R)\" },\n            { label: \"Witness point (W)\" },\n            { label: \"Hold point (H)\" },\n          ],\n          items: [\n            { text: \"Inspector checks calibration certificates for instruments used last week\", bucket: 0, explain: \"Reviewing certificates is a documentation review done after the fact — a review point.\" },\n            { text: \"Inspector observes the first pour of molten iron at the foundry\", bucket: 1, explain: \"Observing the pour is informational — if the inspector cannot attend, production may continue after notification.\" },\n            { text: \"Inspector measures and signs off on brake disc final dimensions before parts are released to shipping\", bucket: 2, explain: \"Final release of a safety-critical product requires mandatory inspector sign-off — a hold point.\" },\n            { text: \"Inspector watches the operator perform a cap torque test at line start-up\", bucket: 1, explain: \"Observing a test procedure at start-up is a witness point.\" },\n            { text: \"Inspector reviews the batch production record for completeness after the shift\", bucket: 0, explain: \"Reviewing completed records is a review point.\" },\n            { text: \"Pressure vessel hydrostatic test — inspector must witness and sign before the vessel can be installed\", bucket: 2, explain: \"Hydrostatic testing of a pressure vessel is safety-critical and requires a hold point with mandatory inspector presence.\" },\n          ],\n        },\n        { type: \"check\", id: \"aqe-m6-l4-c1\", question: \"What happens if production passes a hold point without inspector sign-off?\", options: [\n          \"Nothing — hold points are advisory\",\n          \"All product made after that point is suspect and may need quarantine and re-inspection\",\n          \"The inspector can sign off retroactively with no consequences\",\n          \"Only the last part needs to be re-inspected\",\n        ], answer: 1, explain: \"A hold point is a mandatory stop. If production proceeds without sign-off, all parts produced after that point lack verification and must be treated as suspect — typically quarantined and re-inspected.\" },\n        { type: \"links\", items: [\n          { label: \"PPAP Production Part Approval Process\", url: \"https://www.aiag.org/quality/automotive-core-tools/ppap\", source: AIAG },\n        ] },\n      ],\n    },\n    // ─────────────────────────────── LESSON 5 ───────────────────────────────\n    {\n      id: \"aqe-m6-l5\",\n      title: \"Acceptance sampling: AQL plans and OC curves\",\n      minutes: 30,\n      objectives: [\n        \"Define acceptance sampling concepts: lot, sample, AQL, LTPD, producer's risk and consumer's risk\",\n        \"Distinguish single, double and multiple sampling plans\",\n        \"Read and interpret an operating characteristic (OC) curve\",\n        \"Apply ISO 2859-1 switching rules: normal, tightened and reduced inspection\",\n      ],\n      blocks: [\n        { type: \"p\", text: \"Acceptance sampling is a statistical method for deciding whether to accept or reject a lot of product based on the inspection of a sample drawn from that lot. It is used when 100 % inspection is too costly, too slow, or destructive (you cannot test every cement bag to destruction and still sell it). The key is to choose a sampling plan that gives the right balance of risk to the producer and the consumer.\" },\n        { type: \"h\", text: \"Key concepts\" },\n        { type: \"table\", head: [\"Term\", \"Symbol\", \"Definition\", \"Example\"], rows: [\n          [\"Lot (batch)\", \"N\", \"The group of items from which the sample is drawn\", \"A pallet of 500 brake discs from one production run\"],\n          [\"Sample\", \"n\", \"The items drawn from the lot and inspected\", \"50 discs drawn at random from the pallet of 500\"],\n          [\"Acceptance number\", \"Ac\", \"The maximum number of defectives in the sample for the lot to be accepted\", \"Ac = 2: if 0, 1 or 2 defectives are found, accept the lot\"],\n          [\"Rejection number\", \"Re\", \"The minimum number of defectives for the lot to be rejected\", \"Re = 3: if 3 or more defectives are found, reject the lot\"],\n          [\"AQL\", \"AQL\", \"Acceptable quality level — the worst quality the consumer considers acceptable as a process average\", \"AQL = 1.0 %: the consumer accepts a long-run average of 1 % defective\"],\n          [\"LTPD\", \"LTPD\", \"Lot tolerance percent defective — the quality level the consumer wants to reject most of the time\", \"LTPD = 6.5 %: the consumer wants lots at 6.5 % defective to be rejected at least 90 % of the time\"],\n          [\"Producer's risk\", \"α\", \"The probability of rejecting a lot that is actually at the AQL (a good lot wrongly rejected)\", \"α = 5 %: a 5 % chance of rejecting a good lot\"],\n          [\"Consumer's risk\", \"β\", \"The probability of accepting a lot that is actually at the LTPD (a bad lot wrongly accepted)\", \"β = 10 %: a 10 % chance of accepting a bad lot\"],\n        ] },\n        { type: \"callout\", tone: \"key\", title: \"AQL is not the target\", text: \"AQL is the **worst** quality the consumer considers tolerable as a process average. The target should always be zero defects. A plan with AQL = 1.0 % does not mean you aim for 1 % defective — it means that if the process averages 1 % defective or better, most lots will be accepted.\" },\n        { type: \"h\", text: \"Single, double and multiple sampling plans\" },\n        { type: \"table\", head: [\"Plan type\", \"How it works\", \"Advantage\"], rows: [\n          [\"Single\", \"Draw one sample of n items. Accept if defectives <= Ac; reject if defectives >= Re.\", \"Simple to administer and explain\"],\n          [\"Double\", \"Draw a first sample. Accept, reject, or draw a second sample based on results. Combine both samples for the final decision.\", \"Often inspects fewer items on average than a single plan with the same protection, because very good or very bad lots are decided on the first sample\"],\n          [\"Multiple\", \"Up to seven successive samples, each with cumulative accept/reject criteria\", \"Lowest average sample number, but more complex to manage\"],\n        ] },\n        { type: \"h\", text: \"The OC curve\" },\n        { type: \"p\", text: \"The operating characteristic (OC) curve is a graph that shows the probability of accepting a lot (Pa) on the Y axis against the actual fraction defective (p) on the X axis. Every sampling plan has its own OC curve. The curve tells you how well the plan discriminates between good and bad lots.\" },\n        { type: \"list\", items: [\n          \"At p = 0 (perfect lot), Pa = 1.0 — you always accept.\",\n          \"At p = AQL, Pa ≈ 1 − α (typically 0.95) — good lots are almost always accepted.\",\n          \"At p = LTPD, Pa ≈ β (typically 0.10) — bad lots are almost always rejected.\",\n          \"At p = 1.0 (every item defective), Pa = 0 — you always reject.\",\n          \"A steeper curve means better discrimination — the plan distinguishes good lots from bad lots more sharply.\",\n          \"Increasing the sample size makes the curve steeper.\",\n        ] },\n        { type: \"callout\", tone: \"tip\", title: \"Reading the OC curve\", text: \"Find the AQL on the X axis and read across to the curve, then up to the Y axis. That gives Pa at AQL — the probability of accepting a good lot. Do the same for the LTPD. The gap between the two Pa values shows how well the plan separates good from bad.\" },\n        { type: \"h\", text: \"ISO 2859-1 (attributes) and ISO 3951-1 (variables)\" },\n        { type: \"table\", head: [\"Standard\", \"Data type\", \"What it measures\", \"When to use\"], rows: [\n          [\"ISO 2859-1\", \"Attributes (pass/fail)\", \"Number of defective items in the sample\", \"When characteristics are checked as conforming or not (visual defects, go/no-go gauges)\"],\n          [\"ISO 3951-1\", \"Variables (measurements)\", \"Sample mean and standard deviation\", \"When characteristics are measured on a continuous scale (dimensions, weights) — smaller sample sizes for the same protection\"],\n        ] },\n        { type: \"h\", text: \"Switching rules: normal, tightened, reduced\" },\n        { type: \"p\", text: \"ISO 2859-1 includes switching rules that adjust the severity of inspection based on the quality history of recent lots:\" },\n        { type: \"steps\", title: \"ISO 2859-1 switching rules\", items: [\n          \"**Start at normal inspection**. Use the sampling plan corresponding to the chosen AQL and lot size from the standard's tables.\",\n          \"**Switch to tightened** if 2 out of 5 consecutive lots are rejected under normal inspection. Tightened inspection uses a smaller acceptance number — it is harder for lots to pass.\",\n          \"**Switch back to normal** from tightened if 5 consecutive lots are accepted under tightened inspection.\",\n          \"**Switch to reduced** from normal if 10 consecutive lots are accepted, production is stable, and the quality engineer approves. Reduced inspection uses a smaller sample size — fewer items inspected per lot.\",\n          \"**Switch back to normal** from reduced if a lot is rejected, production becomes irregular, or any other condition warrants it.\",\n          \"**Discontinue inspection** if 5 consecutive lots are rejected under tightened inspection. The process is not capable of meeting the AQL, and the root cause must be found before inspection resumes.\",\n        ] },\n        { type: \"callout\", tone: \"warning\", title: \"Discontinuation is serious\", text: \"If you reach discontinuation, stop accepting product from that process or supplier. The switching rules are telling you that the process quality is consistently worse than the AQL. Investigate the root cause — do not simply switch back to normal and hope for the best.\" },\n        { type: \"form\", id: \"aqe-m6-l5-form1\", title: \"Select a sampling plan from the AQL table\", task: \"A cement plant in Douala receives bags of addite in lots of 1 200 bags. The quality engineer wants to inspect for bag integrity (attribute: intact or damaged) with AQL = 2.5 %. Use ISO 2859-1 principles to answer.\",\n          hint: \"For a lot size of 1 200 under ISO 2859-1 with AQL = 2.5 %, the normal single sampling plan gives a sample size of approximately 80 with Ac = 5.\",\n          fields: [\n            { kind: \"select\", label: \"With lot size N = 1 200 and AQL = 2.5 %, what is approximately the sample size under normal single sampling (ISO 2859-1, General Inspection Level II)?\", options: [\"n = 20\", \"n = 50\", \"n = 80\", \"n = 200\"], answer: 2, explain: \"For lot size 1 201–3 200 at General Inspection Level II, the code letter is K, giving n = 125 from the standard table. However, n ≈ 80 is the closest practical answer at this lot range and AQL; the exact number depends on the code letter assignment.\" },\n            { kind: \"select\", label: \"Under the normal plan, what happens if the sample contains 6 damaged bags?\", options: [\"Accept the lot — 6 is within normal variation\", \"Reject the lot — 6 exceeds the acceptance number\", \"Draw a second sample\", \"Switch to reduced inspection\"], answer: 1, explain: \"With Ac = 5, any sample with 6 or more defectives leads to rejection of the lot.\" },\n            { kind: \"select\", label: \"The last 5 lots were all accepted under normal inspection. What switching action is available?\", options: [\"Must switch to tightened\", \"Must switch to reduced\", \"May switch to reduced if production is stable and quality engineer approves\", \"No change\"], answer: 2, explain: \"After 10 consecutive lots accepted (not 5), the team MAY switch to reduced. With only 5 lots accepted, the team stays on normal. However, if the question intended 10, reduced is optional with quality engineer approval.\" },\n            { kind: \"select\", label: \"Under tightened inspection, 5 consecutive lots are rejected. What does ISO 2859-1 require?\", options: [\"Switch to normal inspection\", \"Switch to reduced inspection\", \"Discontinue inspection until the root cause is found\", \"Accept the next lot automatically\"], answer: 2, explain: \"Five consecutive rejections under tightened inspection triggers discontinuation. The process is not meeting the AQL and must be investigated.\" },\n          ],\n        },\n        { type: \"sheet\", id: \"aqe-m6-l5-sheet1\", title: \"Calculate OC curve points\", task: \"For a single sampling plan with n = 50 and Ac = 2, calculate the probability of acceptance (Pa) for each fraction defective using the binomial approximation Pa ≈ Σ(k=0 to Ac) C(n,k) × p^k × (1−p)^(n−k). Round Pa to 2 decimal places.\",\n          data: [\n            [\"Fraction defective (p)\", \"n\", \"Ac\", \"Pa (probability of acceptance)\"],\n            [0.01, 50, 2, null],\n            [0.02, 50, 2, null],\n            [0.04, 50, 2, null],\n            [0.06, 50, 2, null],\n            [0.08, 50, 2, null],\n            [0.10, 50, 2, null],\n            [0.15, 50, 2, null],\n          ],\n          editable: [\"D2\", \"D3\", \"D4\", \"D5\", \"D6\", \"D7\", \"D8\"],\n          checks: [\n            { cell: \"D2\", equals: 0.99, tol: 0.02 },\n            { cell: \"D3\", equals: 0.92, tol: 0.03 },\n            { cell: \"D4\", equals: 0.68, tol: 0.04 },\n            { cell: \"D5\", equals: 0.42, tol: 0.04 },\n            { cell: \"D6\", equals: 0.24, tol: 0.04 },\n            { cell: \"D7\", equals: 0.11, tol: 0.03 },\n            { cell: \"D8\", equals: 0.01, tol: 0.02 },\n          ],\n          hint: \"Use the binomial formula or a calculator. For p = 0.02, the probability of 0, 1 or 2 defectives in 50 items is about 0.92. As p increases, Pa drops — the curve gets steeper.\",\n          solution: {\n            \"D2\": \"0.99\",\n            \"D3\": \"0.92\",\n            \"D4\": \"0.68\",\n            \"D5\": \"0.42\",\n            \"D6\": \"0.24\",\n            \"D7\": \"0.11\",\n            \"D8\": \"0.01\",\n          },\n        },\n        { type: \"check\", id: \"aqe-m6-l5-c1\", question: \"What does the consumer's risk (β) represent?\", options: [\n          \"The probability of rejecting a lot at the AQL\",\n          \"The probability of accepting a lot at the LTPD\",\n          \"The average fraction defective in accepted lots\",\n          \"The sample size divided by the lot size\",\n        ], answer: 1, explain: \"Consumer's risk (β) is the probability of accepting a lot whose quality is at the LTPD — the level the consumer wants rejected. A typical β is 10 %, meaning there is a 10 % chance of accepting a bad lot.\" },\n        { type: \"check\", id: \"aqe-m6-l5-c2\", question: \"How does increasing the sample size affect the OC curve?\", options: [\n          \"The curve shifts to the right\",\n          \"The curve becomes flatter — less discrimination\",\n          \"The curve becomes steeper — better discrimination between good and bad lots\",\n          \"The curve does not change\",\n        ], answer: 2, explain: \"A larger sample gives more information about the lot. The OC curve becomes steeper, meaning the plan is better at accepting good lots and rejecting bad ones. The trade-off is higher inspection cost.\" },\n        { type: \"links\", items: [\n          { label: \"ISO 2859-1: Sampling procedures for inspection by attributes\", url: \"https://www.iso.org/standard/1141.html\", source: ISO_SRC },\n          { label: \"ISO 3951-1: Sampling procedures for inspection by variables\", url: \"https://www.iso.org/standard/57490.html\", source: ISO_SRC },\n          { label: \"Acceptance sampling overview\", url: \"https://asq.org/quality-resources/acceptance-sampling\", source: ASQ },\n        ] },\n      ],\n    },\n    // ─────────────────────────────── PRACTICE ───────────────────────────────\n    {\n      id: \"aqe-m6-practice\",\n      title: \"Practice\",\n      minutes: 30,\n      objectives: [\n        \"Apply PFD symbol knowledge and PFMEA analysis to realistic manufacturing scenarios\",\n        \"Design control plans and inspection test plans that link back to PFMEA risk priorities\",\n        \"Calculate acceptance sampling plans and evaluate their OC curves for lot sentencing decisions\",\n      ],\n      blocks: [\n        INTRO_PRACTICE,\n        // ── Beginner: sorter — match PFD symbols to descriptions ──\n        { type: \"sorter\", id: \"aqe-m6-p1\", level: \"beginner\", layout: \"columns\", title: \"Match PFD symbols to descriptions\", task: \"Place each description under the correct process flow diagram symbol.\",\n          hint: \"Each symbol represents a specific type of activity in the manufacturing process.\",\n          buckets: [\n            { label: \"Operation (rectangle)\" },\n            { label: \"Inspection (circle)\" },\n            { label: \"Transport (arrow)\" },\n            { label: \"Delay (D-shape)\" },\n            { label: \"Storage (triangle)\" },\n            { label: \"Decision (diamond)\" },\n          ],\n          items: [\n            { text: \"A step where the product is physically changed — machining, assembly, mixing\", bucket: 0, explain: \"Operations transform the product. The rectangle is the most common PFD symbol.\" },\n            { text: \"A measurement or test to verify the product meets specification\", bucket: 1, explain: \"Inspections check conformance — shown as a circle.\" },\n            { text: \"Movement of material from one workstation to another\", bucket: 2, explain: \"Transport moves material without changing it — shown as an arrow.\" },\n            { text: \"Product waiting between process steps — queue or buffer\", bucket: 3, explain: \"Delays are unplanned or unavoidable waiting periods — shown as a D-shape.\" },\n            { text: \"Planned holding of raw material, WIP or finished goods in a designated area\", bucket: 4, explain: \"Storage is the planned, controlled holding of material — shown as an inverted triangle.\" },\n            { text: \"A yes/no question that determines which path the product follows\", bucket: 5, explain: \"Decisions branch the flow based on a condition — shown as a diamond.\" },\n          ],\n        },\n        // ── Intermediate: form — complete PFMEA entries with S, O, D and AP ──\n        { type: \"form\", id: \"aqe-m6-p2\", level: \"intermediate\", title: \"Complete PFMEA entries with S, O, D ratings and AP\", task: \"A cement plant near Douala has begun a PFMEA for its kiln and grinding operations. Rate each failure mode and determine the action priority.\",\n          hint: \"Severity is based on the effect, not the cause. Occurrence depends on how well the cause is prevented. Detection depends on how likely current controls will catch it. High severity (safety/regulatory) generally drives AP = H.\",\n          fields: [\n            { kind: \"select\", label: \"Process step: Clinker grinding. Failure mode: Grinding media fragments contaminate cement. Effect: Metal contamination in finished cement — risk of equipment damage at customer's construction site. What is the severity?\", options: [\"S = 3 (Minor)\", \"S = 5 (Moderate)\", \"S = 7 (High)\", \"S = 9 (Very high)\"], answer: 2, explain: \"Metal contamination could damage customer equipment and compromise construction quality. This is a high severity (S = 7–8) but not directly a life-safety or regulatory hazard in the same way as structural failure.\" },\n            { kind: \"select\", label: \"Same failure mode. Cause: Grinding ball breakage — inspected monthly. Current prevention: Monthly visual inspection of grinding media. What is the occurrence?\", options: [\"O = 2 (Low)\", \"O = 4 (Moderate)\", \"O = 6 (Moderate–High)\", \"O = 8 (High)\"], answer: 2, explain: \"Monthly inspection is infrequent for a continuous process. Ball breakage can occur between inspections. O = 6 reflects occasional failures with some prevention.\" },\n            { kind: \"select\", label: \"Same failure mode. Current detection: Magnetic separator on conveyor downstream of grinder, checked weekly. What is the detection?\", options: [\"D = 2 (High — magnetic separator catches metal)\", \"D = 4 (Moderate — separator may miss some)\", \"D = 7 (Low)\", \"D = 9 (None)\"], answer: 1, explain: \"A magnetic separator is a good detection control for metal fragments, but weekly checking means it could be degraded for several days. D = 4 reflects a moderately effective detection control.\" },\n            { kind: \"select\", label: \"With S = 7, O = 6, D = 4, what is the action priority?\", options: [\"Low (L)\", \"Medium (M)\", \"High (H)\"], answer: 1, explain: \"With moderate-to-high ratings across all three dimensions but no safety-critical severity (S < 9), the AP is Medium — action recommended. Increase inspection frequency of grinding media and verify the magnetic separator daily.\" },\n            { kind: \"select\", label: \"Process step: Kiln firing. Failure mode: Clinker under-burnt due to low kiln temperature. Effect: Cement compressive strength below 32.5 MPa minimum — structural risk in buildings. What is the severity?\", options: [\"S = 5 (Moderate)\", \"S = 7 (High)\", \"S = 9 (Very high — safety)\", \"S = 10 (Hazardous)\"], answer: 2, explain: \"Below-specification cement used in structural concrete poses a direct safety risk — buildings could fail. This is S = 9 (safety and regulatory noncompliance).\" },\n            { kind: \"select\", label: \"With S = 9 for the under-burnt clinker, regardless of O and D, what is the minimum action priority?\", options: [\"Low (L)\", \"Medium (M)\", \"High (H)\"], answer: 2, explain: \"With S = 9, the AP is always High. Safety-related failure effects demand mandatory action regardless of how well the cause is prevented or detected.\" },\n          ],\n        },\n        // ── Advanced: form — design control plan entries linked to PFMEA ──\n        { type: \"form\", id: \"aqe-m6-p3\", level: \"advanced\", title: \"Design control plan entries linked to PFMEA\", task: \"Using the PFMEA results from a beverage filling line in Bafoussam, design control plan entries for three failure modes.\",\n          hint: \"Match the control intensity to the action priority. AP = H needs robust, often automated, controls. AP = M needs regular monitoring. AP = L needs basic checks.\",\n          fields: [\n            { kind: \"select\", label: \"PFMEA result: Fill volume < 325 ml, S = 9, AP = H. What measurement method is most appropriate for the control plan?\", options: [\"Manual weighing of 3 bottles per shift\", \"Automatic in-line check-weigher with reject mechanism\", \"Visual estimation by the operator\", \"Quarterly audit by external lab\"], answer: 1, explain: \"For AP = H with regulatory risk, automatic 100 % in-line measurement with automatic rejection is the appropriate control. Manual checks are insufficient for this risk level.\" },\n            { kind: \"select\", label: \"Same failure mode (AP = H). What is the most appropriate sample size / frequency?\", options: [\"3 per shift\", \"5 per hour\", \"100 % (every bottle)\", \"1 per day\"], answer: 2, explain: \"AP = H requires the highest level of control. With an automatic check-weigher, every bottle is checked — 100 % inspection.\" },\n            { kind: \"select\", label: \"Same failure mode (AP = H). What reaction plan?\", options: [\"Note it in the shift log\", \"Stop the filler, recalibrate, re-check last 30 minutes of production, quarantine suspect product\", \"Continue production and review at end of month\", \"Send a memo to management\"], answer: 1, explain: \"The reaction plan for AP = H must be immediate and specific: stop the process, fix the cause, verify recent production, and contain suspect product.\" },\n            { kind: \"select\", label: \"PFMEA result: Carbonation level outside range, S = 5, AP = M. What control method?\", options: [\"No control needed\", \"Taste test by the shift manager\", \"CO₂ measurement with in-line sensor; 5 samples per hour recorded on SPC chart\", \"Annual calibration of the carbonator\"], answer: 2, explain: \"For AP = M, regular monitoring with objective measurement and SPC trending is appropriate. It provides data-driven control without the cost of 100 % automated inspection.\" },\n            { kind: \"select\", label: \"PFMEA result: Label crooked, S = 2, AP = L. What is an appropriate control?\", options: [\"100 % automated vision system\", \"Operator visual check every 15 minutes\", \"No inspection at all\", \"Hold point with inspector sign-off\"], answer: 1, explain: \"For a cosmetic issue with AP = L, periodic visual checks by the operator are proportionate. Automated vision or hold points would be disproportionate to the risk.\" },\n          ],\n        },\n        // ── Expert: sheet — build acceptance sampling plan with OC curve ──\n        { type: \"sheet\", id: \"aqe-m6-p4\", level: \"expert\", title: \"Build acceptance sampling plan with OC curve calculations\", task: \"A brake disc foundry in Douala inspects incoming sand in lots of 2 000 bags. The plan is single sampling with n = 80 and Ac = 3. Calculate the probability of acceptance (Pa) at each fraction defective using the Poisson approximation: Pa ≈ Σ(k=0 to Ac) e^(-np) × (np)^k / k!. Also calculate producer's and consumer's risk.\",\n          data: [\n            [\"Fraction defective (p)\", \"np (expected defectives)\", \"Pa (Poisson approx.)\", \"Decision\"],\n            [0.01, null, null, null],\n            [0.02, null, null, null],\n            [0.03, null, null, null],\n            [0.05, null, null, null],\n            [0.08, null, null, null],\n            [0.10, null, null, null],\n            [null, null, null, null],\n            [\"AQL = 0.02\", \"Producer's risk (α) =\", null, null],\n            [\"LTPD = 0.08\", \"Consumer's risk (β) =\", null, null],\n          ],\n          editable: [\"B2\", \"C2\", \"D2\", \"B3\", \"C3\", \"D3\", \"B4\", \"C4\", \"D4\", \"B5\", \"C5\", \"D5\", \"B6\", \"C6\", \"D6\", \"B7\", \"C7\", \"D7\", \"C9\", \"C10\"],\n          checks: [\n            { cell: \"B2\", equals: 0.8, tol: 0.01 },\n            { cell: \"C2\", equals: 0.99, tol: 0.02 },\n            { cell: \"D2\", equals: \"Accept\" },\n            { cell: \"B3\", equals: 1.6, tol: 0.01 },\n            { cell: \"C3\", equals: 0.92, tol: 0.03 },\n            { cell: \"D3\", equals: \"Accept\" },\n            { cell: \"B4\", equals: 2.4, tol: 0.01 },\n            { cell: \"C4\", equals: 0.78, tol: 0.04 },\n            { cell: \"D4\", equals: \"Accept\" },\n            { cell: \"B5\", equals: 4.0, tol: 0.01 },\n            { cell: \"C5\", equals: 0.43, tol: 0.04 },\n            { cell: \"D5\", equals: \"Reject\" },\n            { cell: \"B6\", equals: 6.4, tol: 0.01 },\n            { cell: \"C6\", equals: 0.11, tol: 0.03 },\n            { cell: \"D6\", equals: \"Reject\" },\n            { cell: \"B7\", equals: 8.0, tol: 0.01 },\n            { cell: \"C7\", equals: 0.04, tol: 0.02 },\n            { cell: \"D7\", equals: \"Reject\" },\n            { cell: \"C9\", equals: 0.08, tol: 0.04 },\n            { cell: \"C10\", equals: 0.11, tol: 0.04 },\n          ],\n          hint: \"np = n × p. For Poisson: Pa = e^(-np) × [1 + np + (np)²/2! + (np)³/3!]. Producer's risk α = 1 − Pa at AQL. Consumer's risk β = Pa at LTPD. Write 'Accept' if Pa > 0.5, 'Reject' if Pa ≤ 0.5.\",\n          solution: {\n            \"B2\": \"0.80\", \"C2\": \"0.99\", \"D2\": \"Accept\",\n            \"B3\": \"1.60\", \"C3\": \"0.92\", \"D3\": \"Accept\",\n            \"B4\": \"2.40\", \"C4\": \"0.78\", \"D4\": \"Accept\",\n            \"B5\": \"4.00\", \"C5\": \"0.43\", \"D5\": \"Reject\",\n            \"B6\": \"6.40\", \"C6\": \"0.11\", \"D6\": \"Reject\",\n            \"B7\": \"8.00\", \"C7\": \"0.04\", \"D7\": \"Reject\",\n            \"C9\": \"0.08\", \"C10\": \"0.11\",\n          },\n        },\n      ],\n    },\n  ],\n  // ─────────────────────────────── QUIZ ─────────────────────────────────\n  quiz: {\n    id: \"aqe-m6-quiz\",\n    title: \"Module 6 Quiz — FMEA, Control Plans and Inspection Planning\",\n    passPct: 75,\n    questions: [\n      {\n        id: \"aqe-m6-q1\",\n        question: \"Which document should be created FIRST in the quality planning triad?\",\n        options: [\n          \"The control plan\",\n          \"The process FMEA\",\n          \"The process flow diagram\",\n          \"The inspection and test plan\",\n        ],\n        answer: 2,\n        explain: \"The PFD is the foundation. It maps every process step, and both the PFMEA and the control plan reference the PFD step numbers. Without the PFD, the other documents have no structure to build on.\",\n      },\n      {\n        id: \"aqe-m6-q2\",\n        question: \"In the AIAG/VDA FMEA method, what does action priority (AP) = High mean?\",\n        options: [\n          \"The failure mode has been eliminated\",\n          \"Action is optional — document the decision\",\n          \"Action is recommended but not mandatory\",\n          \"Action is mandatory — the team must implement risk-reduction measures\",\n        ],\n        answer: 3,\n        explain: \"AP = High means the risk combination of severity, occurrence and detection demands mandatory action. The team must define and implement measures to reduce the risk.\",\n      },\n      {\n        id: \"aqe-m6-q3\",\n        question: \"A failure mode has severity S = 9 (safety hazard). The team adds a second inspection step, reducing detection from D = 7 to D = 3. What happens to severity?\",\n        options: [\n          \"Severity drops to S = 3 because detection improved\",\n          \"Severity drops to S = 5 as a compromise\",\n          \"Severity remains S = 9 — it is inherent to the failure effect\",\n          \"Severity increases to S = 10 because more inspection was needed\",\n        ],\n        answer: 2,\n        explain: \"Severity is determined by the effect of the failure on the customer, not by the controls in place. Adding inspection reduces the detection rating (D), but the severity of a safety hazard remains unchanged. Only a design change that eliminates the hazardous effect can reduce severity.\",\n      },\n      {\n        id: \"aqe-m6-q4\",\n        question: \"Which control plan phase uses 100 % measurement of all characteristics to validate the product design?\",\n        options: [\n          \"Prototype phase\",\n          \"Pre-launch phase\",\n          \"Production phase\",\n          \"Post-production phase\",\n        ],\n        answer: 0,\n        explain: \"The prototype control plan measures every characteristic on every part to validate that the design meets all dimensional and performance requirements before tooling is finalised.\",\n      },\n      {\n        id: \"aqe-m6-q5\",\n        question: \"What does a hold point (H) in an inspection and test plan require?\",\n        options: [\n          \"The inspector reviews records at the end of the shift\",\n          \"The inspector is invited to observe but production may continue if they do not attend\",\n          \"Production stops until the inspector verifies and signs off\",\n          \"The operator self-inspects and records the result\",\n        ],\n        answer: 2,\n        explain: \"A hold point is a mandatory stop. Production cannot proceed past that step until the inspector has physically verified the product and signed the release. This is reserved for critical characteristics.\",\n      },\n      {\n        id: \"aqe-m6-q6\",\n        question: \"In acceptance sampling, what does AQL = 1.0 % mean?\",\n        options: [\n          \"The target defect rate is 1.0 %\",\n          \"Exactly 1.0 % of sampled items will be defective\",\n          \"The worst process average the consumer considers acceptable — lots at or below 1.0 % defective will usually be accepted\",\n          \"The sample size is 1.0 % of the lot size\",\n        ],\n        answer: 2,\n        explain: \"AQL is the acceptable quality level — the worst process average the consumer considers tolerable. It is not a target (the target is zero defects) and it is not a sample size percentage.\",\n      },\n      {\n        id: \"aqe-m6-q7\",\n        question: \"Under ISO 2859-1, what triggers a switch from normal to tightened inspection?\",\n        options: [\n          \"10 consecutive lots accepted\",\n          \"2 out of 5 consecutive lots rejected under normal inspection\",\n          \"The quality manager requests it\",\n          \"The sample size exceeds 200\",\n        ],\n        answer: 1,\n        explain: \"The switching rule states: switch from normal to tightened when 2 out of 5 consecutive lots are rejected under normal inspection. This indicates the process quality may be deteriorating.\",\n      },\n      {\n        id: \"aqe-m6-q8\",\n        question: \"How does increasing the sample size (n) affect the OC curve of a sampling plan?\",\n        options: [\n          \"The curve shifts to the right, accepting more lots\",\n          \"The curve becomes flatter, accepting and rejecting lots less discriminately\",\n          \"The curve becomes steeper, discriminating more sharply between good and bad lots\",\n          \"The curve does not change — only the acceptance number affects it\",\n        ],\n        answer: 2,\n        explain: \"A larger sample provides more information about the lot quality. The OC curve becomes steeper, meaning the plan accepts nearly all good lots and rejects nearly all bad lots. The trade-off is higher inspection cost and time.\",\n      },\n    ],\n  },\n};\n","client/src/data/courses/aqe/m7.ts":"import type { CourseModule } from \"../../../lms/types\";\n\nexport const m7: CourseModule = {\n  id: \"aqe-m7\",\n  number: 7,\n  title: \"Reliability Engineering and Supplier Quality\",\n  hours: 15,\n  summary:\n    \"This module covers reliability engineering concepts and metrics including failure rate, MTBF, and the bathtub curve; failure mode analysis techniques and Weibull distribution fundamentals for characterising failure behaviour; the Production Part Approval Process (PPAP) and its 18 elements for qualifying production parts; supplier development, qualification, and management through scorecards and audit programmes; and corrective and preventive action (CAPA) systems including 8D methodology for systematically resolving quality issues across the supply chain.\",\n\n  lessons: [\n    /* ------------------------------------------------------------------ */\n    /*  LESSON 1 — Reliability concepts and metrics                       */\n    /* ------------------------------------------------------------------ */\n    {\n      id: \"aqe-m7-l1\",\n      number: 1,\n      title: \"Reliability concepts and metrics\",\n      minutes: 25,\n      objectives: [\n        \"Define reliability and express it mathematically as a probability function\",\n        \"Calculate MTBF, MTTF, and MTTR from field failure data\",\n        \"Describe the three regions of the bathtub curve and their practical implications\",\n        \"Compute system reliability for series and parallel configurations\",\n      ],\n      blocks: [\n        {\n          type: \"h\",\n          text: \"What is reliability?\",\n        },\n        {\n          type: \"p\",\n          text: \"Reliability is the probability that an item will perform its intended function for a specified period of time under stated conditions. Unlike quality, which is assessed at a point in time, reliability introduces the dimension of time. A pump may pass all quality checks at the factory in Douala, yet fail within three months if reliability was not designed in.\",\n        },\n        {\n          type: \"callout\",\n          tone: \"key\",\n          title: \"Reliability function\",\n          text: \"R(t) = e^(−λt) for constant failure rate λ. If λ = 0.002 failures/hour, the probability of surviving 500 hours is R(500) = e^(−0.002 × 500) = e^(−1) ≈ 0.368, or 36.8 %.\",\n        },\n        {\n          type: \"h\",\n          text: \"Key reliability metrics\",\n        },\n        {\n          type: \"table\",\n          head: [\"Metric\", \"Full name\", \"Definition\", \"Units\"],\n          rows: [\n            [\n              \"MTBF\",\n              \"Mean Time Between Failures\",\n              \"Average operating time between successive failures (repairable systems)\",\n              \"Hours\",\n            ],\n            [\n              \"MTTF\",\n              \"Mean Time To Failure\",\n              \"Average time to first failure (non-repairable items)\",\n              \"Hours\",\n            ],\n            [\n              \"MTTR\",\n              \"Mean Time To Repair\",\n              \"Average time required to restore a failed item to operation\",\n              \"Hours\",\n            ],\n            [\n              \"λ\",\n              \"Failure rate\",\n              \"Number of failures per unit time; λ = 1/MTBF\",\n              \"Failures/hour\",\n            ],\n            [\n              \"A\",\n              \"Availability\",\n              \"A = MTBF / (MTBF + MTTR)\",\n              \"Ratio (0–1)\",\n            ],\n          ],\n        },\n        {\n          type: \"p\",\n          text: \"For a fleet of 20 water pumps at a Cameroon municipal utility operating a combined 40 000 hours with 8 failures recorded, MTBF = 40 000 / 8 = 5 000 hours and λ = 1 / 5 000 = 0.0002 failures/hour.\",\n        },\n        {\n          type: \"check\",\n          id: \"aqe-m7-ck1\",\n          question:\n            \"A non-repairable sensor has an MTTF of 10 000 hours. What is the failure rate λ?\",\n          options: [\n            \"0.01 failures/hour\",\n            \"0.001 failures/hour\",\n            \"0.0001 failures/hour\",\n            \"0.00001 failures/hour\",\n          ],\n          answer: 2,\n          explain:\n            \"λ = 1 / MTTF = 1 / 10 000 = 0.0001 failures/hour.\",\n        },\n        {\n          type: \"h\",\n          text: \"The bathtub curve\",\n        },\n        {\n          type: \"p\",\n          text: \"The bathtub curve plots failure rate against time and reveals three distinct regions that govern maintenance and quality strategies.\",\n        },\n        {\n          type: \"steps\",\n          title: \"Bathtub curve regions\",\n          items: [\n            \"Infant mortality (decreasing failure rate): early failures caused by manufacturing defects, assembly errors, or material flaws. Burn-in testing and robust incoming inspection reduce this region.\",\n            \"Useful life (constant failure rate): failures occur randomly. This is the region modelled by the exponential distribution. Preventive maintenance is designed around this stable rate.\",\n            \"Wear-out (increasing failure rate): failures increase due to fatigue, corrosion, or degradation. Replacement schedules and condition monitoring target this region.\",\n          ],\n        },\n        {\n          type: \"callout\",\n          tone: \"workplace\",\n          title: \"Bathtub curve in Cameroon cement plants\",\n          text: \"Conveyor belt bearings imported into Douala often show elevated infant mortality when subjected to humidity levels above supplier specifications. Quality engineers implement 48-hour burn-in runs before commissioning and track early failures separately from wear-out data.\",\n        },\n        {\n          type: \"h\",\n          text: \"Series and parallel system reliability\",\n        },\n        {\n          type: \"p\",\n          text: \"In a series system, all components must function for the system to operate. In a parallel (redundant) system, only one path must survive. These models are fundamental to reliability design.\",\n        },\n        {\n          type: \"table\",\n          head: [\"Configuration\", \"Formula\", \"Example (R₁ = 0.95, R₂ = 0.90)\"],\n          rows: [\n            [\n              \"Series\",\n              \"R_sys = R₁ × R₂ × … × Rₙ\",\n              \"0.95 × 0.90 = 0.855\",\n            ],\n            [\n              \"Parallel\",\n              \"R_sys = 1 − (1 − R₁)(1 − R₂)…(1 − Rₙ)\",\n              \"1 − (0.05)(0.10) = 0.995\",\n            ],\n          ],\n        },\n        {\n          type: \"callout\",\n          tone: \"tip\",\n          title: \"Series reliability always decreases\",\n          text: \"Adding components in series always reduces system reliability. A packaging line with 6 series stations each at 0.98 reliability gives R_sys = 0.98⁶ = 0.886 — only 88.6 %. Identify the weakest link and add parallel redundancy there.\",\n        },\n        {\n          type: \"equip\",\n          title: \"Reliability testing equipment\",\n          items: [\n            {\n              art: \"inspection-booth\",\n              name: \"Inspection booth\",\n              caption: \"Controlled environment for reliability inspections during burn-in testing and post-failure examination of returned components.\",\n            },\n          ],\n        },\n        {\n          type: \"sheet\",\n          id: \"aqe-m7-lab1a\",\n          title: \"System reliability calculation\",\n          task: \"A bottling line in Limbe has three critical stations in series: capper (R = 0.97), filler (R = 0.94), labeller (R = 0.96). Calculate the series system reliability in C2. Then calculate the new system reliability in C3 if a redundant filler (R = 0.94) is added in parallel to the existing filler.\",\n          data: [\n            [\"Station\", \"Reliability\", \"Series R_sys\", \"Parallel filler + Series R_sys\"],\n            [\"Capper\", 0.97, null, null],\n            [\"Filler\", 0.94, null, null],\n            [\"Labeller\", 0.96, null, null],\n          ],\n          editable: [\"C2\", \"C3\"],\n          checks: [\n            { cell: \"C2\", equals: 0.8789, tol: 0.001 },\n            { cell: \"C3\", equals: 0.9336, tol: 0.001 },\n          ],\n          hint: \"Series: R_sys = 0.97 × 0.94 × 0.96. For parallel filler: R_filler_parallel = 1 − (1 − 0.94)² = 0.9964, then multiply in series with capper and labeller.\",\n          solution: {\n            C2: \"0.8789 (0.97 × 0.94 × 0.96)\",\n            C3: \"0.9336 (0.97 × 0.9964 × 0.96)\",\n          },\n        },\n        {\n          type: \"form\",\n          id: \"aqe-m7-lab1b\",\n          title: \"Reliability metrics matching\",\n          task: \"Match each reliability scenario to the correct metric.\",\n          fields: [\n            {\n              kind: \"select\",\n              label:\n                \"A repairable compressor at a Kribi fish processing plant averages 2 400 operating hours between breakdowns\",\n              options: [\"MTBF\", \"MTTF\", \"MTTR\", \"Failure rate\"],\n              answer: 0,\n            },\n            {\n              kind: \"select\",\n              label:\n                \"A single-use pressure relief valve lasts an average of 8 760 hours before it must be replaced\",\n              options: [\"MTBF\", \"MTTF\", \"MTTR\", \"Failure rate\"],\n              answer: 1,\n            },\n            {\n              kind: \"select\",\n              label:\n                \"The maintenance crew takes an average of 4.5 hours to restore a failed motor\",\n              options: [\"MTBF\", \"MTTF\", \"MTTR\", \"Failure rate\"],\n              answer: 2,\n            },\n            {\n              kind: \"select\",\n              label:\n                \"A batch of circuit boards experiences 0.0005 failures per hour\",\n              options: [\"MTBF\", \"MTTF\", \"MTTR\", \"Failure rate\"],\n              answer: 3,\n            },\n          ],\n          hint: \"MTBF applies to repairable items; MTTF to non-repairable. MTTR measures repair duration, not operating time.\",\n        },\n        {\n          type: \"links\",\n          items: [\n            {\n              label: \"NIST Engineering Statistics Handbook — Reliability\",\n              url: \"https://www.itl.nist.gov/div898/handbook/apr/apr.htm\",\n              source: \"NIST\",\n            },\n          ],\n        },\n      ],\n    },\n\n    /* ------------------------------------------------------------------ */\n    /*  LESSON 2 — Failure analysis and Weibull distribution              */\n    /* ------------------------------------------------------------------ */\n    {\n      id: \"aqe-m7-l2\",\n      number: 2,\n      title: \"Failure analysis and Weibull distribution\",\n      minutes: 30,\n      objectives: [\n        \"Explain the three Weibull parameters and their physical meaning\",\n        \"Interpret the shape parameter β to classify failure behaviour\",\n        \"Construct a Weibull probability plot from ranked failure data\",\n        \"Calculate B10 life from Weibull parameters\",\n      ],\n      blocks: [\n        {\n          type: \"h\",\n          text: \"Why Weibull?\",\n        },\n        {\n          type: \"p\",\n          text: \"The Weibull distribution is the most versatile reliability distribution because it can model all three regions of the bathtub curve through a single shape parameter β. Unlike the exponential distribution (which assumes constant failure rate), Weibull adapts to infant mortality, constant, and wear-out failure modes.\",\n        },\n        {\n          type: \"h\",\n          text: \"Weibull parameters\",\n        },\n        {\n          type: \"table\",\n          head: [\"Parameter\", \"Symbol\", \"Physical meaning\", \"Typical values\"],\n          rows: [\n            [\n              \"Shape\",\n              \"β (beta)\",\n              \"Governs the failure rate behaviour over time\",\n              \"0.5–5.0\",\n            ],\n            [\n              \"Scale\",\n              \"η (eta)\",\n              \"Characteristic life — the time by which 63.2 % of units have failed\",\n              \"Application-specific (hours, cycles, km)\",\n            ],\n            [\n              \"Location\",\n              \"γ (gamma)\",\n              \"Minimum life before any failure is possible; shifts the distribution along the time axis\",\n              \"Often 0 (two-parameter Weibull)\",\n            ],\n          ],\n        },\n        {\n          type: \"callout\",\n          tone: \"key\",\n          title: \"Interpreting β\",\n          text: \"β < 1: decreasing failure rate (infant mortality — defective subpopulation). β = 1: constant failure rate (exponential distribution — random failures). β > 1: increasing failure rate (wear-out — fatigue, corrosion, ageing). Most mechanical components exhibit β between 1.5 and 4.0.\",\n        },\n        {\n          type: \"h\",\n          text: \"The Weibull reliability function\",\n        },\n        {\n          type: \"code\",\n          text: \"R(t) = e^−((t − γ) / η)^β\\n\\nFor a two-parameter Weibull (γ = 0):\\n  R(t) = e^−(t / η)^β\\n\\nExample: β = 2.5, η = 3 000 hours\\n  R(1 000) = e^−(1000/3000)^2.5\\n           = e^−(0.333)^2.5\\n           = e^−0.0642\\n           = 0.9378 → 93.8 % survive to 1 000 hours\",\n        },\n        {\n          type: \"equip\",\n          title: \"Probability plotting tools\",\n          items: [\n            {\n              art: \"stat-normality\",\n              name: \"Statistical normality and probability plotting\",\n              caption: \"Weibull probability plots follow the same ranking and plotting logic as normal probability plots: rank failure times, compute median ranks, and plot on special axes where the Weibull CDF appears as a straight line.\",\n            },\n          ],\n        },\n        {\n          type: \"h\",\n          text: \"Weibull probability plotting\",\n        },\n        {\n          type: \"steps\",\n          title: \"Constructing a Weibull plot\",\n          items: [\n            \"Rank the n failure times from smallest to largest and assign rank i = 1, 2, …, n.\",\n            \"Calculate median rank for each failure: MR(i) = (i − 0.3) / (n + 0.4). This estimates the cumulative probability of failure F(t).\",\n            \"Transform axes: X = ln(t), Y = ln(ln(1 / (1 − F(t)))). On Weibull probability paper these become linear axes.\",\n            \"Plot each (X, Y) pair and fit a straight line by least squares.\",\n            \"Read β as the slope of the fitted line. Read η where the line crosses F = 63.2 % (or Y = 0 on the transformed scale).\",\n          ],\n        },\n        {\n          type: \"h\",\n          text: \"B10 life and L10 life\",\n        },\n        {\n          type: \"p\",\n          text: \"B10 life (also written L10) is the time by which 10 % of units are expected to fail, i.e., R(t) = 0.90. It is widely used in bearing and automotive specifications. From the Weibull function: B10 = η × (−ln(0.90))^(1/β). For β = 2.5 and η = 3 000 hours: B10 = 3 000 × (0.10536)^(1/2.5) = 3 000 × 0.10536^0.4 = 3 000 × 0.2784 ≈ 835 hours.\",\n        },\n        {\n          type: \"callout\",\n          tone: \"workplace\",\n          title: \"Weibull analysis at a Douala tyre plant\",\n          text: \"A quality engineer collected failure data from 15 tyre moulds and found β = 3.2, η = 18 000 cycles. The B10 life was calculated as 8 470 cycles. Since production schedules required 10 000 cycles per mould, the engineer recommended a design change to the mould cooling system to extend characteristic life.\",\n        },\n        {\n          type: \"check\",\n          id: \"aqe-m7-ck2\",\n          question:\n            \"A Weibull analysis of pump seal failures yields β = 0.7. What does this indicate?\",\n          options: [\n            \"Seals are failing due to wear-out after extended use\",\n            \"Seals have a constant random failure rate\",\n            \"Seals exhibit infant mortality — early failures dominate\",\n            \"The data is not suitable for Weibull analysis\",\n          ],\n          answer: 2,\n          explain:\n            \"β < 1 indicates a decreasing failure rate, characteristic of infant mortality. This suggests manufacturing defects or installation errors rather than wear-out.\",\n        },\n        {\n          type: \"sheet\",\n          id: \"aqe-m7-lab2a\",\n          title: \"Weibull parameter estimation from failure data\",\n          task: \"Eight hydraulic hoses at a Bamenda construction site failed at the times listed below (hours). Calculate the median rank F(t) for each failure in column C, then compute X = ln(t) in column D and Y = ln(ln(1/(1−F(t)))) in column E for the first and last failures. Use the provided β = 1.8 and η = 950 hours to calculate B10 life in F2.\",\n          data: [\n            [\"Rank i\", \"Failure time (hrs)\", \"Median rank F(t)\", \"X = ln(t)\", \"Y = ln(ln(1/(1-F)))\", \"B10 life\"],\n            [1, 210, null, null, null, null],\n            [2, 380, null, null, null, null],\n            [3, 510, null, null, null, null],\n            [4, 630, null, null, null, null],\n            [5, 790, null, null, null, null],\n            [6, 920, null, null, null, null],\n            [7, 1085, null, null, null, null],\n            [8, 1340, null, null, null, null],\n          ],\n          editable: [\"C2\", \"C9\", \"D2\", \"D9\", \"E2\", \"E9\", \"F2\"],\n          checks: [\n            { cell: \"C2\", equals: 0.0833, tol: 0.005 },\n            { cell: \"C9\", equals: 0.9167, tol: 0.005 },\n            { cell: \"D2\", equals: 5.347, tol: 0.01 },\n            { cell: \"D9\", equals: 7.200, tol: 0.01 },\n            { cell: \"E2\", equals: -2.442, tol: 0.05 },\n            { cell: \"E9\", equals: 0.910, tol: 0.05 },\n            { cell: \"F2\", equals: 290, tol: 15 },\n          ],\n          hint: \"Median rank: MR(i) = (i − 0.3) / (n + 0.4) where n = 8. B10 = η × (−ln 0.90)^(1/β) = 950 × 0.10536^(1/1.8).\",\n          solution: {\n            C2: \"0.0833 → (1 − 0.3) / (8 + 0.4) = 0.7 / 8.4\",\n            C9: \"0.9167 → (8 − 0.3) / 8.4 = 7.7 / 8.4\",\n            D2: \"5.347 → ln(210)\",\n            D9: \"7.200 → ln(1340)\",\n            E2: \"−2.442 → ln(ln(1/(1 − 0.0833)))\",\n            E9: \"0.910 → ln(ln(1/(1 − 0.9167)))\",\n            F2: \"≈ 290 hours → 950 × (0.10536)^(1/1.8)\",\n          },\n        },\n        {\n          type: \"form\",\n          id: \"aqe-m7-lab2b\",\n          title: \"Interpret Weibull plot\",\n          task: \"A Weibull analysis of electric motor bearings at a Garoua flour mill produced the following results. Interpret them.\",\n          fields: [\n            {\n              kind: \"select\",\n              label:\n                \"The Weibull plot slope (β) is 3.4. What failure mode does this represent?\",\n              options: [\n                \"Infant mortality\",\n                \"Random constant failure\",\n                \"Wear-out failure\",\n                \"No failure pattern\",\n              ],\n              answer: 2,\n            },\n            {\n              kind: \"select\",\n              label:\n                \"The characteristic life η = 12 000 hours. What percentage of bearings are expected to fail by 12 000 hours?\",\n              options: [\"36.8 %\", \"50.0 %\", \"63.2 %\", \"90.0 %\"],\n              answer: 2,\n            },\n            {\n              kind: \"select\",\n              label:\n                \"Given β = 3.4 (wear-out), which maintenance strategy is most appropriate?\",\n              options: [\n                \"Run to failure with no preventive action\",\n                \"Scheduled replacement before the characteristic life\",\n                \"Burn-in testing to screen weak units\",\n                \"Increase incoming inspection stringency\",\n              ],\n              answer: 1,\n            },\n            {\n              kind: \"select\",\n              label:\n                \"If the mill requires 95 % reliability (B5 life), approximately how does B5 compare to η?\",\n              options: [\n                \"B5 ≈ η (they are roughly equal)\",\n                \"B5 is much shorter than η (perhaps 30–40 % of η)\",\n                \"B5 is longer than η\",\n                \"B5 cannot be determined from Weibull parameters\",\n              ],\n              answer: 1,\n            },\n          ],\n          hint: \"At η, F(t) = 1 − e^(−1) ≈ 0.632 regardless of β. B5 life is always shorter than η because only 5 % have failed.\",\n        },\n        {\n          type: \"links\",\n          items: [\n            {\n              label: \"Abernethy — The New Weibull Handbook (reference)\",\n              url: \"https://www.barringer1.com/wdbase.htm\",\n              source: \"Barringer & Associates\",\n            },\n          ],\n        },\n      ],\n    },\n\n    /* ------------------------------------------------------------------ */\n    /*  LESSON 3 — PPAP and production part approval                      */\n    /* ------------------------------------------------------------------ */\n    {\n      id: \"aqe-m7-l3\",\n      number: 3,\n      title: \"PPAP and production part approval\",\n      minutes: 30,\n      objectives: [\n        \"State the purpose of PPAP and when it is triggered\",\n        \"List and describe the 18 PPAP elements\",\n        \"Distinguish between the five PPAP submission levels\",\n        \"Complete a Part Submission Warrant for a production part\",\n      ],\n      blocks: [\n        {\n          type: \"h\",\n          text: \"What is PPAP?\",\n        },\n        {\n          type: \"p\",\n          text: \"The Production Part Approval Process (PPAP) is a standardised process defined by the Automotive Industry Action Group (AIAG) that demonstrates a supplier's manufacturing process can consistently produce parts meeting engineering specifications. Although originating in automotive, PPAP is now applied across industries wherever production part qualification is required.\",\n        },\n        {\n          type: \"callout\",\n          tone: \"key\",\n          title: \"When is PPAP triggered?\",\n          text: \"PPAP is required for new parts, engineering changes, tooling transfers, corrections to previous submissions, parts produced from new or modified tooling, production from a new supplier location, and parts produced after tooling has been inactive for more than 12 months.\",\n        },\n        {\n          type: \"h\",\n          text: \"The 18 PPAP elements\",\n        },\n        {\n          type: \"table\",\n          head: [\"#\", \"Element\", \"Purpose\"],\n          rows: [\n            [\"1\", \"Design records\", \"Complete product drawing or CAD data with all specifications\"],\n            [\"2\", \"Engineering change documents\", \"Detailed description of any authorised changes\"],\n            [\"3\", \"Customer engineering approval\", \"Evidence that the customer approved the design\"],\n            [\"4\", \"Design FMEA (DFMEA)\", \"Risk analysis of the product design\"],\n            [\"5\", \"Process flow diagram\", \"Sequence of all manufacturing and assembly steps\"],\n            [\"6\", \"Process FMEA (PFMEA)\", \"Risk analysis of the manufacturing process\"],\n            [\"7\", \"Control plan\", \"Methods for controlling process variation at each step\"],\n            [\"8\", \"Measurement system analysis (MSA)\", \"Gage R&R and bias studies for inspection equipment\"],\n            [\"9\", \"Dimensional results\", \"Measurements of all dimensions on the drawing\"],\n            [\"10\", \"Material / performance test results\", \"Proof that materials and performance meet specification\"],\n            [\"11\", \"Initial process studies\", \"Cpk/Ppk capability data from initial production run\"],\n            [\"12\", \"Qualified laboratory documentation\", \"Proof that testing laboratories meet ISO/IEC 17025 or equivalent\"],\n            [\"13\", \"Appearance approval report (AAR)\", \"Colour, texture, and appearance confirmation for visible parts\"],\n            [\"14\", \"Sample production parts\", \"Physical samples from the production run\"],\n            [\"15\", \"Master sample\", \"Retained reference sample approved by the customer\"],\n            [\"16\", \"Checking aids\", \"Fixtures, gages, or templates used for production inspection\"],\n            [\"17\", \"Customer-specific requirements\", \"Additional requirements beyond standard PPAP\"],\n            [\"18\", \"Part Submission Warrant (PSW)\", \"Formal document summarising PPAP submission and declaring conformance\"],\n          ],\n        },\n        {\n          type: \"h\",\n          text: \"PPAP submission levels\",\n        },\n        {\n          type: \"table\",\n          head: [\"Level\", \"What is submitted to customer\", \"Typical use\"],\n          rows: [\n            [\"1\", \"PSW and AAR (if applicable) only\", \"Low-risk parts, trusted supplier with established track record\"],\n            [\"2\", \"PSW with product samples and limited data\", \"Standard submissions for familiar part families\"],\n            [\"3\", \"PSW with product samples and complete supporting data\", \"Default level — most common for new parts and new suppliers\"],\n            [\"4\", \"PSW and full requirements as defined by the customer\", \"Customer specifies exactly what is needed\"],\n            [\"5\", \"PSW with product samples and complete data available for review at supplier site\", \"High-volume parts where shipping full data packages is impractical\"],\n          ],\n        },\n        {\n          type: \"callout\",\n          tone: \"workplace\",\n          title: \"PPAP in Cameroon automotive supply\",\n          text: \"A rubber gasket manufacturer in Douala supplying brake system components to a European OEM was required to submit Level 3 PPAP. The quality team prepared all 18 elements, including Cpk data from an initial run of 300 parts. The submission was initially rejected because the MSA study showed a Gage R&R of 38 % — exceeding the 30 % maximum. After recalibrating the measurement fixture, the resubmission was approved.\",\n        },\n        {\n          type: \"equip\",\n          title: \"PPAP documentation tools\",\n          items: [\n            {\n              art: \"ppap-package\",\n              name: \"PPAP submission package\",\n              caption: \"Standardised folder structure and document templates for assembling all 18 PPAP elements, including Part Submission Warrant (PSW), dimensional layout, and capability study templates.\",\n            },\n            {\n              art: \"calibration-label\",\n              name: \"Calibration label\",\n              caption: \"Applied to all gages and measurement equipment referenced in PPAP element 8 (MSA) and element 16 (Checking aids) to confirm calibration currency.\",\n            },\n          ],\n        },\n        {\n          type: \"h\",\n          text: \"The Part Submission Warrant (PSW)\",\n        },\n        {\n          type: \"p\",\n          text: \"The PSW is the cover document for every PPAP submission. It identifies the part, material, engineering level, test results summary, and supplier declaration. The supplier's authorised representative signs the PSW to warrant that all PPAP requirements have been met and that the production process is capable.\",\n        },\n        {\n          type: \"steps\",\n          title: \"Key PSW sections\",\n          items: [\n            \"Part identification: part number, name, customer, drawing level, and engineering change level\",\n            \"Reason for submission: new part, engineering change, tooling, supplier change, or other trigger\",\n            \"Test results summary: dimensional, material, and performance test disposition (pass/fail)\",\n            \"Declaration: supplier certifies the samples are representative of production and all PPAP requirements are satisfied\",\n            \"Customer disposition: approved, interim approval (with conditions), or rejected\",\n          ],\n        },\n        {\n          type: \"check\",\n          id: \"aqe-m7-ck3\",\n          question:\n            \"Which PPAP submission level requires the supplier to retain complete data at their site for customer review, with samples and PSW submitted?\",\n          options: [\"Level 1\", \"Level 2\", \"Level 4\", \"Level 5\"],\n          answer: 3,\n          explain:\n            \"Level 5 requires the PSW and product samples to be submitted, with all complete supporting documentation retained at the supplier's manufacturing site and available for customer review.\",\n        },\n        {\n          type: \"form\",\n          id: \"aqe-m7-lab3a\",\n          title: \"PPAP submission level and required elements\",\n          task: \"A Cameroon plastics supplier has been asked to provide PPAP for a dashboard ventilation trim piece. Determine the correct requirements.\",\n          fields: [\n            {\n              kind: \"select\",\n              label:\n                \"This is a new part from a new supplier. Which submission level should be used as the default?\",\n              options: [\"Level 1\", \"Level 2\", \"Level 3\", \"Level 5\"],\n              answer: 2,\n            },\n            {\n              kind: \"select\",\n              label:\n                \"The part is visible to the vehicle occupant. Which additional PPAP element is specifically required?\",\n              options: [\n                \"Element 3: Customer engineering approval\",\n                \"Element 13: Appearance approval report (AAR)\",\n                \"Element 17: Customer-specific requirements\",\n                \"Element 12: Qualified laboratory documentation\",\n              ],\n              answer: 1,\n            },\n            {\n              kind: \"select\",\n              label:\n                \"The supplier's dimensional inspection uses a custom fixture. Which PPAP element documents this?\",\n              options: [\n                \"Element 8: MSA\",\n                \"Element 9: Dimensional results\",\n                \"Element 16: Checking aids\",\n                \"Element 14: Sample production parts\",\n              ],\n              answer: 2,\n            },\n            {\n              kind: \"select\",\n              label:\n                \"The customer approved the PPAP but required the supplier to improve Cpk from 1.2 to 1.33 within 90 days. What disposition is this?\",\n              options: [\n                \"Approved\",\n                \"Interim approval\",\n                \"Rejected\",\n                \"Conditional rejection\",\n              ],\n              answer: 1,\n            },\n          ],\n          hint: \"Level 3 is the default for new parts. Visible parts require AAR. Interim approval permits shipment with conditions that must be met by a deadline.\",\n        },\n        {\n          type: \"sorter\",\n          id: \"aqe-m7-lab3b\",\n          title: \"Classify PPAP elements\",\n          task: \"Sort each item into the correct PPAP element category.\",\n          layout: \"columns\",\n          buckets: [\n            { label: \"Design documentation\" },\n            { label: \"Process documentation\" },\n            { label: \"Test and measurement\" },\n            { label: \"Physical evidence\" },\n          ],\n          items: [\n            {\n              text: \"Complete engineering drawing with GD&T\",\n              bucket: 0,\n              explain: \"Element 1: Design records\",\n            },\n            {\n              text: \"DFMEA identifying potential design failure modes\",\n              bucket: 0,\n              explain: \"Element 4: Design FMEA is part of design documentation\",\n            },\n            {\n              text: \"Control plan listing inspection methods at each station\",\n              bucket: 1,\n              explain: \"Element 7: Control plan documents process controls\",\n            },\n            {\n              text: \"Process flow diagram from raw material to finished part\",\n              bucket: 1,\n              explain: \"Element 5: Process flow diagram\",\n            },\n            {\n              text: \"Gage R&R study showing 18 % total variation\",\n              bucket: 2,\n              explain: \"Element 8: Measurement system analysis (MSA)\",\n            },\n            {\n              text: \"Cpk = 1.45 from initial run of 300 parts\",\n              bucket: 2,\n              explain: \"Element 11: Initial process studies\",\n            },\n            {\n              text: \"Retained reference sample signed off by customer\",\n              bucket: 3,\n              explain: \"Element 15: Master sample\",\n            },\n            {\n              text: \"Custom go/no-go fixture for bore diameter\",\n              bucket: 3,\n              explain: \"Element 16: Checking aids\",\n            },\n          ],\n        },\n        {\n          type: \"links\",\n          items: [\n            {\n              label: \"AIAG PPAP Manual (4th edition overview)\",\n              url: \"https://www.aiag.org/quality/automotive-core-tools/ppap\",\n              source: \"AIAG\",\n            },\n          ],\n        },\n      ],\n    },\n\n    /* ------------------------------------------------------------------ */\n    /*  LESSON 4 — Supplier management and development                    */\n    /* ------------------------------------------------------------------ */\n    {\n      id: \"aqe-m7-l4\",\n      number: 4,\n      title: \"Supplier management and development\",\n      minutes: 25,\n      objectives: [\n        \"Define criteria for supplier qualification and selection\",\n        \"Conduct a supplier audit using a structured assessment checklist\",\n        \"Build and interpret a supplier scorecard across quality, delivery, cost, and service dimensions\",\n        \"Select the appropriate incoming inspection strategy based on supplier history\",\n      ],\n      blocks: [\n        {\n          type: \"h\",\n          text: \"Supplier qualification and selection\",\n        },\n        {\n          type: \"p\",\n          text: \"Supplier qualification determines whether a potential supplier has the capability, capacity, and quality systems to consistently meet requirements. In Cameroon, where supply chains often span local, regional (CEMAC zone), and international sources, a structured qualification process prevents costly surprises during production.\",\n        },\n        {\n          type: \"list\",\n          items: [\n            \"Quality management system: ISO 9001 certification or equivalent documented system\",\n            \"Technical capability: equipment, tooling, and process capability for the required specifications\",\n            \"Financial stability: ability to sustain operations and invest in capacity\",\n            \"Delivery performance: logistics infrastructure, lead times, and proximity to production facility\",\n            \"Regulatory compliance: adherence to local, regional, and export market regulations\",\n            \"References and track record: prior performance with similar products or customers\",\n          ],\n        },\n        {\n          type: \"h\",\n          text: \"Supplier audit and assessment\",\n        },\n        {\n          type: \"p\",\n          text: \"A supplier audit is a systematic examination of the supplier's quality system, processes, and facilities. Audits may be conducted before qualification (initial audit), periodically (surveillance audit), or in response to quality issues (for-cause audit).\",\n        },\n        {\n          type: \"steps\",\n          title: \"Supplier audit process\",\n          items: [\n            \"Define audit scope and prepare the checklist covering quality system, process control, inspection, calibration, training, and corrective action\",\n            \"Notify the supplier and schedule the audit (except for unannounced audits triggered by quality issues)\",\n            \"Conduct the on-site audit: interview personnel, review records, observe processes, and verify calibration status\",\n            \"Score each checklist item (e.g., 0 = non-conforming, 1 = partially conforming, 2 = fully conforming) and identify findings\",\n            \"Issue the audit report with findings, required corrective actions, and follow-up timeline\",\n          ],\n        },\n        {\n          type: \"callout\",\n          tone: \"workplace\",\n          title: \"Supplier audit in the CEMAC zone\",\n          text: \"When auditing a packaging materials supplier in neighbouring Equatorial Guinea, a Douala-based food company found that the supplier had no documented calibration programme for their film thickness gauge. The audit finding triggered a corrective action that included purchasing a certified gauge block set and training two operators. Re-audit three months later confirmed closure.\",\n        },\n        {\n          type: \"h\",\n          text: \"Supplier scorecards\",\n        },\n        {\n          type: \"p\",\n          text: \"Scorecards translate supplier performance into quantifiable metrics across four standard dimensions. They are typically updated monthly or quarterly and shared with suppliers to drive improvement.\",\n        },\n        {\n          type: \"table\",\n          head: [\"Dimension\", \"Metric\", \"Weight\", \"Scoring example\"],\n          rows: [\n            [\"Quality\", \"PPM defective, lot rejection rate, CAPA closure rate\", \"40 %\", \"< 500 PPM = 10 pts; 500–2 000 = 7; > 2 000 = 3\"],\n            [\"Delivery\", \"On-time delivery %, lead time adherence\", \"30 %\", \"≥ 98 % OTD = 10; 95–97 % = 7; < 95 % = 3\"],\n            [\"Cost\", \"Price competitiveness, cost reduction contributions\", \"15 %\", \"Competitive + cost-down ideas = 10; Competitive only = 7; Above market = 3\"],\n            [\"Service\", \"Responsiveness, communication, technical support\", \"15 %\", \"< 24 hr response + proactive = 10; < 48 hr = 7; > 48 hr = 3\"],\n          ],\n        },\n        {\n          type: \"callout\",\n          tone: \"tip\",\n          title: \"Weighted score calculation\",\n          text: \"Total score = Σ(dimension weight × dimension score). A supplier scoring Quality = 7, Delivery = 10, Cost = 7, Service = 10 would get: (0.40 × 7) + (0.30 × 10) + (0.15 × 7) + (0.15 × 10) = 2.80 + 3.00 + 1.05 + 1.50 = 8.35 out of 10.\",\n        },\n        {\n          type: \"h\",\n          text: \"Incoming inspection strategies\",\n        },\n        {\n          type: \"table\",\n          head: [\"Strategy\", \"When used\", \"Inspection level\"],\n          rows: [\n            [\"Skip-lot\", \"Supplier has excellent quality history (10+ consecutive lots accepted)\", \"Inspect only every kth lot (e.g., every 5th)\"],\n            [\"Reduced\", \"Supplier has good recent history (5+ lots accepted under normal)\", \"Smaller sample size than normal\"],\n            [\"Normal\", \"Default starting point for all suppliers\", \"Standard sampling plan (e.g., AQL-based)\"],\n            [\"Tightened\", \"Recent lot rejections (2 of 5 lots rejected under normal)\", \"Larger sample size; tighter acceptance criteria\"],\n          ],\n        },\n        {\n          type: \"p\",\n          text: \"Switching rules between these levels follow ANSI/ASQ Z1.4 (ISO 2859-1). The quality engineer must document the switching criteria and maintain lot-by-lot records to justify the current inspection level for each supplier-part combination.\",\n        },\n        {\n          type: \"equip\",\n          title: \"Incoming inspection tools\",\n          items: [\n            {\n              art: \"inspection-booth\",\n              name: \"Inspection booth\",\n              caption: \"Dedicated station for incoming material inspection with controlled lighting, reference samples, and documented sampling plans for each supplier-part combination.\",\n            },\n            {\n              art: \"nc-tags\",\n              name: \"Non-conformance tags\",\n              caption: \"Red tags applied to rejected incoming lots. Tags reference the lot number, supplier, defect description, and disposition (return, sort, use-as-is with concession).\",\n            },\n            {\n              art: \"quarantine-area\",\n              name: \"Quarantine area\",\n              caption: \"Physically segregated storage for incoming lots awaiting inspection results or held pending supplier corrective action. Prevents accidental use of unapproved material.\",\n            },\n          ],\n        },\n        {\n          type: \"check\",\n          id: \"aqe-m7-ck4\",\n          question:\n            \"A supplier has had 2 lots rejected out of the last 5 lots received under normal inspection. What action should the quality engineer take?\",\n          options: [\n            \"Switch to skip-lot inspection\",\n            \"Maintain normal inspection\",\n            \"Switch to tightened inspection\",\n            \"Disqualify the supplier immediately\",\n          ],\n          answer: 2,\n          explain:\n            \"Under ANSI/ASQ Z1.4 switching rules, 2 rejections in 5 consecutive lots under normal inspection triggers a switch to tightened inspection. The supplier is not disqualified but must demonstrate improvement to return to normal.\",\n        },\n        {\n          type: \"sheet\",\n          id: \"aqe-m7-lab4a\",\n          title: \"Build a supplier scorecard\",\n          task: \"Three suppliers provide aluminium extrusions to a Douala window frame manufacturer. Calculate the weighted total score for each supplier. Weights: Quality 40 %, Delivery 30 %, Cost 15 %, Service 15 %. Enter the weighted total for each supplier and determine the best-performing supplier.\",\n          data: [\n            [\"Supplier\", \"Quality (10)\", \"Delivery (10)\", \"Cost (10)\", \"Service (10)\", \"Weighted total\"],\n            [\"Alu-Cam Sarl\", 8, 9, 7, 6, null],\n            [\"ExtruPro Douala\", 6, 7, 9, 8, null],\n            [\"MetalWorks Kribi\", 9, 6, 6, 9, null],\n          ],\n          editable: [\"F2\", \"F3\", \"F4\"],\n          checks: [\n            { cell: \"F2\", equals: 7.85, tol: 0.05 },\n            { cell: \"F3\", equals: 7.05, tol: 0.05 },\n            { cell: \"F4\", equals: 7.35, tol: 0.05 },\n          ],\n          hint: \"Weighted total = (0.40 × Quality) + (0.30 × Delivery) + (0.15 × Cost) + (0.15 × Service). Alu-Cam: (0.40 × 8) + (0.30 × 9) + (0.15 × 7) + (0.15 × 6).\",\n          solution: {\n            F2: \"7.85 → (3.20 + 2.70 + 1.05 + 0.90) — Alu-Cam is the best overall supplier\",\n            F3: \"7.05 → (2.40 + 2.10 + 1.35 + 1.20)\",\n            F4: \"7.35 → (3.60 + 1.80 + 0.90 + 1.35)\",\n          },\n        },\n        {\n          type: \"form\",\n          id: \"aqe-m7-lab4b\",\n          title: \"Evaluate supplier performance\",\n          task: \"Review the following supplier scenarios and determine the appropriate action.\",\n          fields: [\n            {\n              kind: \"select\",\n              label:\n                \"Supplier A has delivered 12 consecutive lots with zero defects under normal inspection. What incoming inspection change is appropriate?\",\n              options: [\n                \"Switch to tightened inspection\",\n                \"Maintain normal inspection\",\n                \"Switch to reduced inspection\",\n                \"Switch to skip-lot inspection\",\n              ],\n              answer: 3,\n            },\n            {\n              kind: \"select\",\n              label:\n                \"Supplier B scored 4.2 / 10 on the quality dimension for three consecutive quarters. What is the priority action?\",\n              options: [\n                \"Reduce the quality weight in the scorecard\",\n                \"Initiate a supplier development programme with specific quality targets\",\n                \"Switch to a different scoring methodology\",\n                \"Accept the risk and continue ordering\",\n              ],\n              answer: 1,\n            },\n            {\n              kind: \"select\",\n              label:\n                \"During a surveillance audit, you discover the supplier changed their heat treatment oven without notifying you. What is required?\",\n              options: [\n                \"No action — equipment changes are internal supplier matters\",\n                \"Request updated PPAP submission because of the process change\",\n                \"Increase the order quantity to test the new oven\",\n                \"Reduce the scorecard delivery score\",\n              ],\n              answer: 1,\n            },\n          ],\n          hint: \"10+ consecutive accepted lots under normal can move to skip-lot. Process equipment changes trigger PPAP resubmission.\",\n        },\n        {\n          type: \"links\",\n          items: [\n            {\n              label: \"ISO 2859-1 Sampling procedures for inspection by attributes\",\n              url: \"https://www.iso.org/standard/1141.html\",\n              source: \"ISO\",\n            },\n          ],\n        },\n      ],\n    },\n\n    /* ------------------------------------------------------------------ */\n    /*  LESSON 5 — CAPA: corrective and preventive action                 */\n    /* ------------------------------------------------------------------ */\n    {\n      id: \"aqe-m7-l5\",\n      title: \"CAPA: corrective and preventive action\",\n      minutes: 25,\n      objectives: [\n        \"Describe the five stages of the CAPA process\",\n        \"Apply the 8D problem-solving methodology to a supplier quality issue\",\n        \"Distinguish between containment, corrective, and preventive actions\",\n        \"Design an effectiveness verification plan for a corrective action\",\n      ],\n      blocks: [\n        {\n          type: \"h\",\n          text: \"The CAPA process\",\n        },\n        {\n          type: \"p\",\n          text: \"Corrective and Preventive Action (CAPA) is a systematic approach to investigating, correcting, and preventing quality problems. CAPA is required by ISO 9001, IATF 16949, and virtually every regulated quality system. The goal is not just to fix the immediate problem but to eliminate the root cause and prevent recurrence.\",\n        },\n        {\n          type: \"steps\",\n          title: \"CAPA stages\",\n          items: [\n            \"Identify: detect and document the nonconformance or quality issue. Sources include customer complaints, audit findings, process monitoring, and incoming inspection rejections.\",\n            \"Investigate: gather data, review process history, and analyse the problem. Determine the scope and impact — how many parts, lots, or customers are affected.\",\n            \"Root cause analysis: use structured methods (5 Whys, fishbone diagram, fault tree) to identify the fundamental cause, not just the symptom.\",\n            \"Implement: design and execute the corrective or preventive action. Assign responsibility, define timeline, and document the changes.\",\n            \"Verify effectiveness: monitor the process after implementation to confirm the root cause has been eliminated. Track for recurrence over a defined period (typically 3–6 months).\",\n          ],\n        },\n        {\n          type: \"h\",\n          text: \"Containment vs corrective vs preventive action\",\n        },\n        {\n          type: \"table\",\n          head: [\"Action type\", \"Purpose\", \"Timing\", \"Example\"],\n          rows: [\n            [\n              \"Containment\",\n              \"Stop the immediate impact — prevent defective product from reaching the customer\",\n              \"Hours to days\",\n              \"100 % sort and inspect all warehouse stock of the affected lot; quarantine suspect material\",\n            ],\n            [\n              \"Corrective\",\n              \"Eliminate the root cause of the existing nonconformance\",\n              \"Days to weeks\",\n              \"Replace worn die insert that caused dimensional out-of-spec; retrain operators on setup procedure\",\n            ],\n            [\n              \"Preventive\",\n              \"Eliminate potential causes of nonconformances that have not yet occurred\",\n              \"Weeks to months\",\n              \"Add die wear monitoring to the preventive maintenance schedule; update PFMEA with new failure mode\",\n            ],\n          ],\n        },\n        {\n          type: \"callout\",\n          tone: \"warning\",\n          title: \"Common CAPA mistake\",\n          text: \"Treating containment as corrective action is the most frequent CAPA failure. Sorting 100 % of a lot stops the bleeding but does nothing to prevent the next lot from having the same defect. Always ask: 'Will this action prevent recurrence?' If not, it is containment only.\",\n        },\n        {\n          type: \"h\",\n          text: \"8D problem-solving methodology\",\n        },\n        {\n          type: \"p\",\n          text: \"The 8D (Eight Disciplines) method provides a structured framework for team-based problem solving, widely used in automotive and manufacturing supply chains. Each discipline builds on the previous one.\",\n        },\n        {\n          type: \"table\",\n          head: [\"D#\", \"Discipline\", \"Key activity\"],\n          rows: [\n            [\"D0\", \"Prepare\", \"Recognise the problem and determine if 8D is warranted; gather initial data\"],\n            [\"D1\", \"Establish the team\", \"Assign a cross-functional team with process knowledge and authority\"],\n            [\"D2\", \"Describe the problem\", \"Use IS/IS NOT analysis to precisely define what, where, when, and how big\"],\n            [\"D3\", \"Interim containment actions (ICA)\", \"Implement temporary measures to protect the customer while root cause is found\"],\n            [\"D4\", \"Root cause analysis\", \"Identify and verify all root causes using 5 Whys, fishbone, or fault tree\"],\n            [\"D5\", \"Permanent corrective actions (PCA)\", \"Select and verify actions that eliminate the root cause\"],\n            [\"D6\", \"Implement and validate PCA\", \"Execute the permanent fix and confirm it works in production\"],\n            [\"D7\", \"Prevent recurrence\", \"Update systems (FMEA, control plan, work instructions) to prevent similar problems\"],\n            [\"D8\", \"Congratulate the team\", \"Recognise team contributions and share lessons learnt\"],\n          ],\n        },\n        {\n          type: \"callout\",\n          tone: \"workplace\",\n          title: \"8D at a Yaoundé electronics assembler\",\n          text: \"A contract electronics manufacturer in Yaoundé received a customer complaint about solder joint failures. D1 assembled a team of process engineer, quality technician, and the solder paste supplier. D4 identified the root cause as expired solder paste (3 months past shelf life) combined with oven temperature 8 °C below specification. D5 corrective actions included implementing FIFO labelling for solder paste and adding oven temperature verification to the startup checklist. D7 updated the PFMEA and control plan.\",\n        },\n        {\n          type: \"equip\",\n          title: \"CAPA documentation tools\",\n          items: [\n            {\n              art: \"a3-report\",\n              name: \"A3 report\",\n              caption: \"Single-page structured problem-solving report (Toyota format) used to document the CAPA process from problem identification through root cause analysis to verification. Fits on A3 paper for visual management boards.\",\n            },\n            {\n              art: \"pfmea-worksheet\",\n              name: \"PFMEA worksheet\",\n              caption: \"Process FMEA template updated as part of D7 (prevent recurrence). New failure modes discovered during CAPA are added with revised severity, occurrence, and detection ratings.\",\n            },\n            {\n              art: \"control-plan-form\",\n              name: \"Control plan form\",\n              caption: \"Updated alongside PFMEA when CAPA introduces new process controls, inspection methods, or reaction plans.\",\n            },\n          ],\n        },\n        {\n          type: \"h\",\n          text: \"Linking CAPA to FMEA updates\",\n        },\n        {\n          type: \"p\",\n          text: \"Every completed CAPA should trigger a review of the relevant FMEA. If the failure mode was not previously listed, add it. If it was listed but with an underestimated occurrence rating, revise upward. If the corrective action introduces a new detection method, update the detection rating. This feedback loop keeps the FMEA as a living document.\",\n        },\n        {\n          type: \"h\",\n          text: \"Effectiveness verification\",\n        },\n        {\n          type: \"list\",\n          items: [\n            \"Define measurable success criteria before implementing the corrective action\",\n            \"Establish a monitoring period (typically 3–6 months or a defined number of production lots)\",\n            \"Track the specific metric that triggered the CAPA (e.g., defect rate, PPM, dimensional Cpk)\",\n            \"If the metric returns to acceptable levels with no recurrence, close the CAPA\",\n            \"If recurrence is detected, re-open the CAPA and revisit root cause analysis — the original root cause was likely incorrect or incomplete\",\n          ],\n        },\n        {\n          type: \"check\",\n          id: \"aqe-m7-ck5\",\n          question:\n            \"In the 8D methodology, at which discipline are interim containment actions implemented?\",\n          options: [\"D1\", \"D3\", \"D5\", \"D7\"],\n          answer: 1,\n          explain:\n            \"D3 is Interim Containment Actions (ICA) — temporary measures to protect the customer while the team works on root cause analysis (D4) and permanent corrective actions (D5).\",\n        },\n        {\n          type: \"whys\",\n          id: \"aqe-m7-lab5a\",\n          title: \"5 Whys analysis for a supplier quality issue\",\n          task: \"A Cameroon beverage company received a shipment of bottle caps from a local supplier. During filling, 12 % of caps failed to seal properly, causing product leakage on the bottling line. Use 5 Whys to find the root cause.\",\n          problem:\n            \"12 % of bottle caps from the supplier fail to seal, causing leakage on the bottling line\",\n          steps: [\n            {\n              question:\n                \"Why are the bottle caps failing to seal?\",\n              options: [\n                \"The cap liner material is too thin\",\n                \"The cap thread dimensions are out of specification\",\n                \"The bottling machine is applying too much torque\",\n                \"The bottles are a different size than specified\",\n              ],\n              answer: 1,\n              explain:\n                \"Dimensional inspection confirmed the cap thread outer diameter was 0.3 mm undersize, preventing proper engagement with the bottle neck.\",\n            },\n            {\n              question:\n                \"Why are the cap thread dimensions out of specification?\",\n              options: [\n                \"The injection mould cavity has excessive wear\",\n                \"The raw material shrinkage rate changed\",\n                \"The operator selected the wrong mould\",\n                \"The specification was updated but the supplier was not notified\",\n              ],\n              answer: 0,\n              explain:\n                \"Inspection of the mould showed cavity wear of 0.25 mm beyond the maintenance limit, directly causing the undersize threads.\",\n            },\n            {\n              question:\n                \"Why does the injection mould cavity have excessive wear?\",\n              options: [\n                \"The mould was not replaced at the scheduled interval\",\n                \"The glass-filled resin is more abrasive than standard PP\",\n                \"The mould steel grade is too soft for production volume\",\n                \"All of the above contribute\",\n              ],\n              answer: 0,\n              explain:\n                \"Maintenance records showed the mould had exceeded its scheduled replacement interval by 40 000 shots. The schedule called for replacement at 200 000 shots, but the mould was at 240 000 shots.\",\n            },\n            {\n              question:\n                \"Why was the mould not replaced at the scheduled interval?\",\n              options: [\n                \"The replacement mould was on back-order from the toolmaker\",\n                \"There is no mould shot counter installed on the machine\",\n                \"The maintenance team forgot to check the schedule\",\n                \"Management deferred the replacement to reduce costs\",\n              ],\n              answer: 1,\n              explain:\n                \"The injection moulding machine had no automatic shot counter. Mould life tracking relied on manual logbook entries, which were incomplete and 3 weeks out of date.\",\n            },\n            {\n              question:\n                \"Why is there no automatic shot counter on the moulding machine?\",\n              options: [\n                \"Shot counters are not available for this machine model\",\n                \"The supplier's capital expenditure budget did not include this upgrade\",\n                \"The previous quality system did not require mould life tracking\",\n                \"The machine is too old to be retrofitted\",\n              ],\n              answer: 2,\n              explain:\n                \"The supplier's quality system had no procedure requiring mould life tracking or automatic shot counting. This is the root cause — a system gap that allowed the mould to exceed its life without detection.\",\n            },\n          ],\n          countermeasure: {\n            question:\n              \"Based on the root cause, which countermeasure is most effective?\",\n            options: [\n              \"Replace the worn mould immediately\",\n              \"Install shot counters on all moulding machines and add mould life tracking to the quality system procedures\",\n              \"Switch to a harder mould steel grade\",\n              \"Increase incoming inspection of caps to 100 %\",\n            ],\n            answer: 1,\n            explain:\n              \"Installing shot counters and formalising mould life tracking in the quality system addresses the root cause (system gap). Replacing the mould alone is containment — it fixes the current problem but does not prevent recurrence on other moulds.\",\n          },\n        },\n        {\n          type: \"sorter\",\n          id: \"aqe-m7-lab5b\",\n          title: \"Classify actions as containment, corrective, or preventive\",\n          task: \"A batch of steel brackets supplied to a Douala construction company was found to have incorrect hole spacing. Classify each response action.\",\n          layout: \"steps\",\n          buckets: [\n            { label: \"Containment\" },\n            { label: \"Corrective action\" },\n            { label: \"Preventive action\" },\n          ],\n          items: [\n            {\n              text: \"Quarantine all remaining brackets from the affected lot in the warehouse\",\n              bucket: 0,\n              explain:\n                \"Quarantine stops defective product from reaching the construction site — this is immediate containment.\",\n            },\n            {\n              text: \"Sort 100 % of the quarantined lot and segregate non-conforming brackets\",\n              bucket: 0,\n              explain:\n                \"Sorting identifies which specific brackets are defective — still a containment activity to protect the customer.\",\n            },\n            {\n              text: \"Replace the worn drill jig that caused the incorrect hole spacing\",\n              bucket: 1,\n              explain:\n                \"Replacing the worn jig eliminates the identified root cause of the current problem — this is corrective action.\",\n            },\n            {\n              text: \"Retrain the CNC operator on the correct setup and verification procedure\",\n              bucket: 1,\n              explain:\n                \"Retraining addresses the human factor root cause that contributed to the defect — corrective action.\",\n            },\n            {\n              text: \"Add drill jig wear checks to the weekly preventive maintenance schedule for all similar jigs\",\n              bucket: 2,\n              explain:\n                \"Extending the check to all similar jigs prevents the same failure mode from occurring elsewhere — preventive action.\",\n            },\n            {\n              text: \"Update the PFMEA to include drill jig wear as a failure mode with a detection control\",\n              bucket: 2,\n              explain:\n                \"Updating the FMEA captures the lesson learnt and ensures future risk assessments account for this failure mode — preventive action.\",\n            },\n          ],\n        },\n        {\n          type: \"links\",\n          items: [\n            {\n              label: \"CQI-20: Effective Problem Solving Guide\",\n              url: \"https://www.aiag.org/quality/cqi\",\n              source: \"AIAG\",\n            },\n          ],\n        },\n      ],\n    },\n\n    /* ------------------------------------------------------------------ */\n    /*  PRACTICE LESSON                                                   */\n    /* ------------------------------------------------------------------ */\n    {\n      id: \"aqe-m7-practice\",\n      number: 6,\n      title: \"Practice: Reliability and supplier quality\",\n      minutes: 30,\n      objectives: [\n        \"Calculate reliability metrics including MTBF, availability and Weibull parameters for fielded products\",\n        \"Evaluate PPAP submission packages and determine supplier approval status\",\n        \"Design and execute corrective action plans using 8D and CAPA methodologies\",\n      ],\n      blocks: [\n        {\n          type: \"p\",\n          text: \"This practice session brings together reliability engineering, PPAP, supplier management, and CAPA skills. Work through all four labs, progressing from foundational concepts to complex problem solving.\",\n        },\n        /* --- Beginner: form --- */\n        {\n          type: \"form\",\n          id: \"aqe-m7-prac1\",\n          level: \"beginner\",\n          title: \"Match reliability terms to definitions\",\n          task: \"Select the correct definition for each reliability and supplier quality term.\",\n          fields: [\n            {\n              kind: \"select\",\n              label: \"MTBF\",\n              options: [\n                \"Average time to first failure for non-repairable items\",\n                \"Average operating time between successive failures for repairable systems\",\n                \"Average time required to restore a failed system\",\n                \"The probability of surviving to a specified time\",\n              ],\n              answer: 1,\n            },\n            {\n              kind: \"select\",\n              label: \"Bathtub curve — useful life region\",\n              options: [\n                \"Decreasing failure rate due to manufacturing defects\",\n                \"Increasing failure rate due to wear and fatigue\",\n                \"Approximately constant failure rate — random failures\",\n                \"Zero failure rate under ideal conditions\",\n              ],\n              answer: 2,\n            },\n            {\n              kind: \"select\",\n              label: \"Characteristic life (η) in Weibull analysis\",\n              options: [\n                \"The time at which 10 % of units have failed\",\n                \"The time at which 50 % of units have failed\",\n                \"The time at which 63.2 % of units have failed\",\n                \"The time at which 90 % of units have failed\",\n              ],\n              answer: 2,\n            },\n            {\n              kind: \"select\",\n              label: \"Part Submission Warrant (PSW)\",\n              options: [\n                \"A statistical process capability report\",\n                \"A formal cover document summarising PPAP submission and declaring conformance\",\n                \"A supplier scorecard used for annual evaluation\",\n                \"A corrective action report issued after a customer complaint\",\n              ],\n              answer: 1,\n            },\n            {\n              kind: \"select\",\n              label: \"Containment action\",\n              options: [\n                \"An action that eliminates the root cause of a nonconformance\",\n                \"An action that prevents potential future nonconformances\",\n                \"An immediate action to stop defective product from reaching the customer\",\n                \"A long-term system improvement added to the FMEA\",\n              ],\n              answer: 2,\n            },\n          ],\n          hint: \"MTBF is for repairable systems; MTTF is for non-repairable. Containment protects the customer immediately but does not address root cause.\",\n        },\n\n        /* --- Intermediate: sheet --- */\n        {\n          type: \"sheet\",\n          id: \"aqe-m7-prac2\",\n          level: \"intermediate\",\n          title: \"Calculate system reliability and MTBF\",\n          task: \"A cocoa processing line in Kumba has four stages in series. Calculate the system reliability for the series configuration in E2. Then calculate the system MTBF in E3 (use λ_sys = 1 − R_sys for a one-hour mission, then MTBF = 1/λ_sys). Finally, if a parallel redundant unit (R = 0.91) is added to the dryer, calculate the new system reliability in E4.\",\n          data: [\n            [\"Stage\", \"Reliability (1 hr)\", \"Failure rate λ\", \"MTBF (hrs)\", \"System calculations\"],\n            [\"Fermentation monitor\", 0.98, 0.0202, 49.5, null],\n            [\"Dryer\", 0.91, 0.0943, 10.6, null],\n            [\"Roaster\", 0.95, 0.0513, 19.5, null],\n            [\"Grinder\", 0.97, 0.0305, 32.8, null],\n          ],\n          editable: [\"E2\", \"E3\", \"E4\"],\n          checks: [\n            { cell: \"E2\", equals: 0.8218, tol: 0.005 },\n            { cell: \"E3\", equals: 5.61, tol: 0.15 },\n            { cell: \"E4\", equals: 0.9067, tol: 0.005 },\n          ],\n          hint: \"Series R = 0.98 × 0.91 × 0.95 × 0.97. For MTBF: λ_sys = sum of individual λ values = 0.0202 + 0.0943 + 0.0513 + 0.0305, then MTBF = 1/λ_sys. Parallel dryer: R_dryer_par = 1 − (1 − 0.91)² = 0.9919, then multiply all series.\",\n          solution: {\n            E2: \"0.8218 → 0.98 × 0.91 × 0.95 × 0.97\",\n            E3: \"5.61 hrs → 1 / (0.0202 + 0.0943 + 0.0513 + 0.0305) = 1 / 0.1963\",\n            E4: \"0.9067 → 0.98 × 0.9919 × 0.95 × 0.97\",\n          },\n        },\n\n        /* --- Advanced: form --- */\n        {\n          type: \"form\",\n          id: \"aqe-m7-prac3\",\n          level: \"advanced\",\n          title: \"Complete PPAP documentation requirements\",\n          task: \"A Douala supplier is submitting PPAP for a newly designed aluminium heat sink used in an automotive LED headlamp assembly. Determine the correct documentation requirements.\",\n          fields: [\n            {\n              kind: \"select\",\n              label:\n                \"This is a brand new part design. The customer has requested comprehensive documentation. Which PPAP level is appropriate?\",\n              options: [\"Level 1\", \"Level 2\", \"Level 3\", \"Level 5\"],\n              answer: 2,\n            },\n            {\n              kind: \"select\",\n              label:\n                \"The heat sink's thermal conductivity must meet a minimum of 180 W/m·K. Which PPAP element specifically documents this?\",\n              options: [\n                \"Element 9: Dimensional results\",\n                \"Element 10: Material / performance test results\",\n                \"Element 11: Initial process studies\",\n                \"Element 14: Sample production parts\",\n              ],\n              answer: 1,\n            },\n            {\n              kind: \"select\",\n              label:\n                \"The initial process study shows Cpk = 1.15 for the critical mounting hole position. What is the expected customer response?\",\n              options: [\n                \"Approved — Cpk > 1.0 is acceptable\",\n                \"Interim approval — Cpk is below the typical 1.33 minimum with a required improvement plan\",\n                \"Rejected — Cpk must be at least 2.0 for automotive\",\n                \"Not applicable — Cpk is not part of PPAP\",\n              ],\n              answer: 1,\n            },\n            {\n              kind: \"select\",\n              label:\n                \"The supplier uses an outside laboratory for salt spray corrosion testing. Which PPAP element must confirm the laboratory's qualifications?\",\n              options: [\n                \"Element 8: Measurement system analysis\",\n                \"Element 10: Material / performance test results\",\n                \"Element 12: Qualified laboratory documentation\",\n                \"Element 17: Customer-specific requirements\",\n              ],\n              answer: 2,\n            },\n            {\n              kind: \"select\",\n              label:\n                \"After PPAP approval, the supplier changes the CNC machine used for machining the heat sink fins. What is required?\",\n              options: [\n                \"No action — machine changes are internal matters\",\n                \"Notify the customer informally by email\",\n                \"Submit a new PPAP because production equipment has changed\",\n                \"Only update the control plan internally\",\n              ],\n              answer: 2,\n            },\n          ],\n          hint: \"Performance specifications (thermal conductivity) are element 10. Cpk below 1.33 typically receives interim approval. Equipment changes trigger PPAP resubmission.\",\n        },\n\n        /* --- Expert: whys --- */\n        {\n          type: \"whys\",\n          id: \"aqe-m7-prac4\",\n          level: \"expert\",\n          title: \"5 Whys root cause analysis for complex supplier failure\",\n          task: \"A Cameroon pharmaceutical packaging company discovered that 3 of the last 5 blister foil shipments from their aluminium foil supplier failed the heat-seal bond strength test. Each failure resulted in a full lot quarantine and production delays averaging 4 days. Trace the root cause.\",\n          problem:\n            \"3 of 5 blister foil lots failed heat-seal bond strength test, causing production quarantine and 4-day delays\",\n          steps: [\n            {\n              question:\n                \"Why are the blister foil lots failing the heat-seal bond strength test?\",\n              options: [\n                \"The heat-seal lacquer coating thickness is inconsistent across the foil width\",\n                \"The pharmaceutical company's sealing machine temperature is too low\",\n                \"The foil gauge thickness is out of specification\",\n                \"The test method has changed and is now more stringent\",\n              ],\n              answer: 0,\n              explain:\n                \"Cross-web coating thickness measurements showed variation from 4.2 to 7.8 g/m² against a specification of 5.5 ± 0.8 g/m². The thin areas (< 4.7 g/m²) failed bond strength testing.\",\n            },\n            {\n              question:\n                \"Why is the heat-seal lacquer coating thickness inconsistent across the foil width?\",\n              options: [\n                \"The coating roller has developed uneven wear patterns\",\n                \"The lacquer viscosity is varying between batches\",\n                \"The foil tension during coating is fluctuating\",\n                \"The drying oven temperature is too high, causing uneven curing\",\n              ],\n              answer: 0,\n              explain:\n                \"Physical inspection of the coating roller revealed wear grooves in two areas, creating low-transfer zones that produced thin coating bands.\",\n            },\n            {\n              question:\n                \"Why has the coating roller developed uneven wear patterns?\",\n              options: [\n                \"The roller exceeded its service life without reconditioning\",\n                \"Abrasive contaminants in the lacquer accelerated localised wear\",\n                \"The roller material specification was changed to save cost\",\n                \"The roller was damaged during installation after last reconditioning\",\n              ],\n              answer: 0,\n              explain:\n                \"Maintenance records showed the roller had run 2.8 million metres against a reconditioning interval of 2.0 million metres — 40 % over the service limit.\",\n            },\n            {\n              question:\n                \"Why did the roller exceed its service life without reconditioning?\",\n              options: [\n                \"The maintenance schedule exists but compliance is not tracked or enforced\",\n                \"Spare rollers were unavailable due to import delays\",\n                \"Production pressures overrode the maintenance team's reconditioning request\",\n                \"The maintenance team was unaware of the reconditioning interval\",\n              ],\n              answer: 0,\n              explain:\n                \"The supplier's maintenance system had a documented schedule, but no mechanism to flag overdue tasks or block production when critical maintenance was past due. Compliance tracking was manual and had lapsed.\",\n            },\n          ],\n          countermeasure: {\n            question:\n              \"Which combination of actions best addresses the root cause and prevents recurrence?\",\n            options: [\n              \"Recondition the roller and increase incoming inspection of foil at the pharmaceutical company\",\n              \"Recondition the roller and implement a computerised maintenance management system (CMMS) with automatic alerts and production interlocks for overdue critical maintenance\",\n              \"Switch to a different foil supplier with better maintenance practices\",\n              \"Accept the variation and widen the coating thickness specification\",\n            ],\n            answer: 1,\n            explain:\n              \"Reconditioning the roller addresses the immediate cause, and implementing a CMMS with automated tracking and interlocks addresses the root cause — the lack of maintenance compliance enforcement. Incoming inspection alone is containment, not prevention.\",\n          },\n        },\n      ],\n    },\n  ],\n\n  /* -------------------------------------------------------------------- */\n  /*  QUIZ                                                                */\n  /* -------------------------------------------------------------------- */\n  quiz: {\n    id: \"aqe-m7-quiz\",\n    title: \"Module 7 Quiz: Reliability Engineering and Supplier Quality\",\n    passPct: 75,\n    questions: [\n      {\n        id: \"aqe-m7-q1\",\n        question: \"A system has three components in series with reliabilities of 0.96, 0.93, and 0.98. What is the system reliability?\",\n        options: [\n          \"0.874\",\n          \"0.957\",\n          \"0.990\",\n          \"0.870\",\n        ],\n        answer: 0,\n        explain:\n          \"Series reliability = 0.96 × 0.93 × 0.98 = 0.8742, which rounds to 0.874.\",\n      },\n      {\n        id: \"aqe-m7-q2\",\n        question: \"In the bathtub curve, which region is characterised by a decreasing failure rate?\",\n        options: [\n          \"Useful life period\",\n          \"Wear-out period\",\n          \"Infant mortality period\",\n          \"Steady-state period\",\n        ],\n        answer: 2,\n        explain:\n          \"Infant mortality is the early-life region where failure rate decreases as weak units are screened out through burn-in or early use.\",\n      },\n      {\n        id: \"aqe-m7-q3\",\n        question: \"A Weibull analysis yields β = 2.8 and η = 5 000 hours. What is the approximate B10 life?\",\n        options: [\n          \"500 hours\",\n          \"1 850 hours\",\n          \"3 160 hours\",\n          \"4 500 hours\",\n        ],\n        answer: 1,\n        explain:\n          \"B10 = η × (−ln 0.90)^(1/β) = 5 000 × (0.10536)^(1/2.8) = 5 000 × (0.10536)^(0.357) ≈ 5 000 × 0.370 ≈ 1 850 hours.\",\n      },\n      {\n        id: \"aqe-m7-q4\",\n        question: \"Which PPAP element documents the statistical capability of the manufacturing process?\",\n        options: [\n          \"Element 7: Control plan\",\n          \"Element 9: Dimensional results\",\n          \"Element 11: Initial process studies\",\n          \"Element 8: Measurement system analysis\",\n        ],\n        answer: 2,\n        explain:\n          \"Element 11 (Initial process studies) presents Cpk and Ppk data from initial production runs to demonstrate process capability.\",\n      },\n      {\n        id: \"aqe-m7-q5\",\n        question: \"A supplier has delivered 12 consecutive lots accepted under normal inspection. According to standard switching rules, the buyer may now move to:\",\n        options: [\n          \"Tightened inspection\",\n          \"Reduced inspection only\",\n          \"Skip-lot inspection\",\n          \"No inspection required\",\n        ],\n        answer: 2,\n        explain:\n          \"With 10+ consecutive accepted lots under normal inspection, the buyer may move to skip-lot inspection, inspecting only every kth lot.\",\n      },\n      {\n        id: \"aqe-m7-q6\",\n        question: \"In the 8D methodology, which discipline specifically addresses preventing recurrence by updating system documents like FMEAs and control plans?\",\n        options: [\n          \"D3: Interim containment actions\",\n          \"D5: Permanent corrective actions\",\n          \"D6: Implement and validate PCA\",\n          \"D7: Prevent recurrence\",\n        ],\n        answer: 3,\n        explain:\n          \"D7 focuses on preventing recurrence by updating management systems — FMEAs, control plans, work instructions, and training — to institutionalise the lessons learnt.\",\n      },\n      {\n        id: \"aqe-m7-q7\",\n        question: \"What is the default PPAP submission level for a new part from a new supplier?\",\n        options: [\n          \"Level 1\",\n          \"Level 2\",\n          \"Level 3\",\n          \"Level 5\",\n        ],\n        answer: 2,\n        explain:\n          \"Level 3 is the default submission level requiring PSW, product samples, and complete supporting documentation.\",\n      },\n      {\n        id: \"aqe-m7-q8\",\n        question: \"A quality engineer sorts 100 % of a quarantined lot to separate conforming from non-conforming parts. This action is best classified as:\",\n        options: [\n          \"Preventive action\",\n          \"Corrective action\",\n          \"Containment action\",\n          \"Root cause analysis\",\n        ],\n        answer: 2,\n        explain:\n          \"100 % sorting of a quarantined lot is containment — it protects the customer from receiving defective product but does not address the root cause that created the defects.\",\n      },\n    ],\n  },\n};\n","client/src/data/courses/aqe/m8.ts":"import type { CourseModule } from \"../../../lms/types\";\n\nexport const m8: CourseModule = {\n  id: \"aqe-m8\",\n  number: 8,\n  title: \"Lean Six Sigma and Continuous Improvement\",\n  hours: 16,\n  summary:\n    \"This module introduces the DMAIC methodology as a structured framework for quality improvement projects, \" +\n    \"covering process mapping and value stream analysis to identify non-value-added activities. Learners apply \" +\n    \"root cause analysis tools including fishbone diagrams, 5 Whys, and Pareto analysis, then study lean \" +\n    \"manufacturing principles and the eight wastes (DOWNTIME) to systematically eliminate inefficiency. The \" +\n    \"module concludes with change management practices for sustaining improvement gains, integrating statistical \" +\n    \"methods from earlier modules into real-world continuous improvement projects.\",\n\n  lessons: [\n    /* ──────────────────────────────────────────────────────────\n     * LESSON 1 — DMAIC methodology and project selection\n     * ────────────────────────────────────────────────────────── */\n    {\n      id: \"aqe-m8-l1\",\n      title: \"DMAIC methodology and project selection\",\n      minutes: 30,\n      objectives: [\n        \"Describe the origins of Six Sigma and interpret sigma levels and DPMO\",\n        \"Explain the purpose of each DMAIC phase and how they connect\",\n        \"Apply project selection criteria to rank improvement opportunities\",\n        \"Draft a project charter with all required elements\",\n      ],\n      blocks: [\n        { type: \"h\", text: \"Six Sigma: origins and key concepts\" },\n        {\n          type: \"p\",\n          text:\n            \"Six Sigma was developed at Motorola in the 1980s and popularised by General Electric under \" +\n            \"Jack Welch in the 1990s. The name refers to a process capability of 6 standard deviations between \" +\n            \"the process mean and the nearest specification limit. At true 6σ performance (with the customary \" +\n            \"1.5σ shift), a process produces only **3.4 defects per million opportunities (DPMO)**. \" +\n            \"Cameroonian manufacturers adopting Six Sigma principles typically begin at 3σ–4σ levels and use \" +\n            \"DMAIC projects to drive measurable gains.\",\n        },\n        {\n          type: \"table\",\n          head: [\"Sigma level\", \"DPMO\", \"Yield (%)\", \"Typical context\"],\n          rows: [\n            [\"2σ\", \"308,537\", \"69.15\", \"Unstable process, frequent rework\"],\n            [\"3σ\", \"66,807\", \"93.32\", \"Average manufacturing baseline\"],\n            [\"4σ\", \"6,210\", \"99.38\", \"Competitive process\"],\n            [\"5σ\", \"233\", \"99.977\", \"World-class process\"],\n            [\"6σ\", \"3.4\", \"99.99966\", \"Near-perfect performance\"],\n          ],\n        },\n        {\n          type: \"callout\",\n          tone: \"key\",\n          title: \"DPMO formula\",\n          text:\n            \"DPMO = (Number of defects ÷ (Number of units × Number of opportunities per unit)) × 1,000,000. \" +\n            \"A bottling plant in Douala inspecting 5,000 bottles with 3 defect opportunities each and finding \" +\n            \"42 defects has DPMO = (42 ÷ 15,000) × 1,000,000 = **2,800**, approximately a 4.3σ level.\",\n        },\n\n        { type: \"h\", text: \"The DMAIC framework\" },\n        {\n          type: \"p\",\n          text:\n            \"DMAIC (Define–Measure–Analyse–Improve–Control) is the standard Six Sigma improvement cycle for \" +\n            \"existing processes. Each phase has defined deliverables, tollgate reviews, and statistical tools. \" +\n            \"Unlike ad-hoc troubleshooting, DMAIC enforces data-driven decisions at every stage.\",\n        },\n        {\n          type: \"steps\",\n          title: \"Five DMAIC phases\",\n          items: [\n            \"**Define** — Identify the problem, the customer, and the project scope. Deliverables: project charter, SIPOC diagram, stakeholder map.\",\n            \"**Measure** — Quantify the current process performance with reliable data. Deliverables: data collection plan, measurement system evaluation, baseline sigma level.\",\n            \"**Analyse** — Find and verify the root causes of defects or variation. Deliverables: fishbone diagram, 5 Whys, hypothesis tests, Pareto chart.\",\n            \"**Improve** — Develop, test, and implement solutions that address root causes. Deliverables: solution selection matrix, pilot results, implementation plan.\",\n            \"**Control** — Sustain the gains with monitoring, standard work, and response plans. Deliverables: control plan, SPC charts, updated procedures, project closure report.\",\n          ],\n        },\n        {\n          type: \"check\",\n          id: \"aqe-m8-l1-ck1\",\n          question:\n            \"A ceramic tile factory in Limbe finds 93 chipped tiles out of 10,000 tiles produced, each tile having 2 defect opportunities (edge chips and surface cracks). What is the DPMO?\",\n          options: [\"4,650\", \"9,300\", \"930\", \"46,500\"],\n          answer: 0,\n          explain:\n            \"DPMO = (93 ÷ (10,000 × 2)) × 1,000,000 = (93 ÷ 20,000) × 1,000,000 = 4,650.\",\n        },\n\n        { type: \"h\", text: \"Project selection criteria\" },\n        {\n          type: \"p\",\n          text:\n            \"Not every problem warrants a full DMAIC project. Organisations prioritise candidates using criteria \" +\n            \"that balance business impact, feasibility, and measurability. A scoring matrix helps leadership \" +\n            \"compare opportunities objectively.\",\n        },\n        {\n          type: \"table\",\n          head: [\"Criterion\", \"Question to ask\", \"Weight example\"],\n          rows: [\n            [\"Business impact\", \"How much does this problem cost in scrap, rework, or lost sales?\", \"30%\"],\n            [\"Customer impact\", \"Does this defect reach the customer or violate a specification?\", \"25%\"],\n            [\"Feasibility\", \"Can we realistically solve this with available resources and authority?\", \"20%\"],\n            [\"Measurability\", \"Can we collect reliable data on the current and future state?\", \"15%\"],\n            [\"Strategic alignment\", \"Does this project support company goals or certification targets?\", \"10%\"],\n          ],\n        },\n\n        { type: \"h\", text: \"Project charter and SIPOC\" },\n        {\n          type: \"p\",\n          text:\n            \"The project charter is a one-page document that authorises the project and aligns the team. \" +\n            \"It includes the **problem statement** (what is wrong and its magnitude), the **goal statement** \" +\n            \"(specific, measurable target), the **scope** (process boundaries), **team roles**, and a \" +\n            \"**timeline** with tollgate dates. The charter is reviewed and signed by the project sponsor.\",\n        },\n        {\n          type: \"callout\",\n          tone: \"tip\",\n          title: \"SIPOC at a glance\",\n          text:\n            \"SIPOC (Suppliers–Inputs–Process–Outputs–Customers) provides a high-level view of the process \" +\n            \"before the team dives into detail. For a cocoa drying operation in the South-West Region: \" +\n            \"Suppliers = farmers and cooperatives; Inputs = wet cocoa beans, drying mats, sunlight/dryers; \" +\n            \"Process = receiving → fermenting → drying → sorting → bagging; Outputs = dried cocoa beans at \" +\n            \"≤ 7.5% moisture; Customers = exporters and chocolate manufacturers.\",\n        },\n        {\n          type: \"callout\",\n          tone: \"workplace\",\n          title: \"Stakeholder analysis in practice\",\n          text:\n            \"At a soap manufacturing plant in Bamenda, the DMAIC team mapped stakeholders on a \" +\n            \"power-interest grid. The plant manager (high power, high interest) was the sponsor. \" +\n            \"Line operators (low power, high interest) were subject matter experts. The procurement \" +\n            \"department (high power, low interest) needed to be kept informed about raw material changes.\",\n        },\n\n        {\n          type: \"equip\",\n          title: \"A3 problem-solving report\",\n          items: [\n            {\n              art: \"a3-report\",\n              name: \"A3 report template\",\n              caption:\n                \"The A3 format condenses an entire improvement story — background, analysis, \" +\n                \"countermeasures, and follow-up — onto a single A3-sized sheet, encouraging concise \" +\n                \"thinking and visual communication.\",\n              specs: [\n                { label: \"Format\", value: \"A3 (297 × 420 mm), landscape\" },\n                { label: \"Left side\", value: \"Background, current condition, root cause analysis\" },\n                { label: \"Right side\", value: \"Target condition, countermeasures, plan, follow-up\" },\n              ],\n            },\n          ],\n        },\n\n        /* Lab: form — write project charter elements */\n        {\n          type: \"form\",\n          id: \"aqe-m8-l1-lab1\",\n          title: \"Draft a DMAIC project charter\",\n          task:\n            \"A plywood factory in Edéa has been experiencing a 12% rejection rate for warped panels \" +\n            \"over the past 6 months, costing approximately 18 million FCFA per quarter in scrap. \" +\n            \"Complete the charter elements below for a DMAIC project to address this problem.\",\n          fields: [\n            {\n              kind: \"text\",\n              label: \"Problem statement (include defect, magnitude, and timeframe)\",\n              accept: [\"warped\", \"12%\", \"warp\"],\n              example:\n                \"12% of plywood panels produced at the Edéa factory have been rejected for warping over the past 6 months, costing 18M FCFA per quarter.\",\n              placeholder: \"Describe the problem with specific data…\",\n            },\n            {\n              kind: \"text\",\n              label: \"Goal statement (measurable target with deadline)\",\n              accept: [\"reduce\", \"%\"],\n              example:\n                \"Reduce the panel warping rejection rate from 12% to below 4% within 6 months of project launch.\",\n              placeholder: \"State a measurable improvement target…\",\n            },\n            {\n              kind: \"select\",\n              label: \"Which scope boundary is most appropriate?\",\n              options: [\n                \"From raw log receiving to finished panel packaging\",\n                \"From veneer layup through hot press to panel cooling\",\n                \"From customer order to delivery\",\n                \"From procurement of adhesive to warehouse storage\",\n              ],\n              answer: 1,\n              explain:\n                \"Warping is primarily influenced by the veneer layup, pressing, and cooling stages. Scoping the project to these operations keeps it focused and feasible.\",\n            },\n            {\n              kind: \"select\",\n              label: \"Who should sponsor this project?\",\n              options: [\n                \"A line operator with pressing experience\",\n                \"The quality inspector who detects warped panels\",\n                \"The plant manager with authority over production resources\",\n                \"An external consultant specialising in wood products\",\n              ],\n              answer: 2,\n              explain:\n                \"The sponsor must have authority to allocate resources, remove barriers, and approve changes. The plant manager holds this authority for production processes.\",\n            },\n          ],\n          hint: \"Think about what makes a good problem statement: specific defect, how often, how much it costs, and over what period.\",\n        },\n\n        /* Lab: sorter — classify activities into DMAIC phases (steps layout) */\n        {\n          type: \"sorter\",\n          id: \"aqe-m8-l1-lab2\",\n          title: \"Classify activities into DMAIC phases\",\n          task:\n            \"Drag each activity into the correct DMAIC phase. The phases are arranged in \" +\n            \"sequence from Define through to Control.\",\n          layout: \"steps\",\n          buckets: [\n            { label: \"Define\", desc: \"Scope the project and align stakeholders\" },\n            { label: \"Measure\", desc: \"Quantify current performance\" },\n            { label: \"Analyse\", desc: \"Find and verify root causes\" },\n            { label: \"Improve\", desc: \"Develop and test solutions\" },\n            { label: \"Control\", desc: \"Sustain the gains\" },\n          ],\n          items: [\n            {\n              text: \"Write the project charter and get sponsor sign-off\",\n              bucket: 0,\n              explain: \"The project charter is a Define-phase deliverable that authorises the project.\",\n            },\n            {\n              text: \"Create a SIPOC diagram of the current process\",\n              bucket: 0,\n              explain: \"SIPOC provides the high-level process view needed in the Define phase.\",\n            },\n            {\n              text: \"Conduct a Gage R&R study on the measurement system\",\n              bucket: 1,\n              explain: \"Validating the measurement system is a Measure-phase activity ensuring data reliability.\",\n            },\n            {\n              text: \"Calculate the baseline process sigma level\",\n              bucket: 1,\n              explain: \"The baseline sigma quantifies current performance — a key Measure deliverable.\",\n            },\n            {\n              text: \"Build a fishbone diagram to identify potential causes\",\n              bucket: 2,\n              explain: \"Fishbone diagrams are Analyse-phase tools for structured root cause identification.\",\n            },\n            {\n              text: \"Run a hypothesis test to verify a suspected root cause\",\n              bucket: 2,\n              explain: \"Statistical verification of root causes is central to the Analyse phase.\",\n            },\n            {\n              text: \"Run a pilot test of the proposed solution\",\n              bucket: 3,\n              explain: \"Piloting validates solutions before full-scale implementation in the Improve phase.\",\n            },\n            {\n              text: \"Set up control charts to monitor the improved process\",\n              bucket: 4,\n              explain: \"SPC monitoring is a Control-phase mechanism for sustaining improvements.\",\n            },\n          ],\n        },\n      ],\n    },\n\n    /* ──────────────────────────────────────────────────────────\n     * LESSON 2 — Define and Measure phases\n     * ────────────────────────────────────────────────────────── */\n    {\n      id: \"aqe-m8-l2\",\n      title: \"Define and Measure phases\",\n      minutes: 30,\n      objectives: [\n        \"Translate voice of the customer data into critical-to-quality requirements\",\n        \"Build a CTQ tree linking customer needs to measurable specifications\",\n        \"Design a data collection plan with appropriate sampling strategy\",\n        \"Calculate process sigma level, DPMO, and first-pass yield from defect data\",\n      ],\n      blocks: [\n        { type: \"h\", text: \"Voice of the customer to critical-to-quality\" },\n        {\n          type: \"p\",\n          text:\n            \"The Define phase begins with understanding **what the customer truly needs**. Voice of the \" +\n            \"customer (VOC) data comes from complaints, surveys, returns, warranty claims, and direct \" +\n            \"interviews. However, customers often express needs in vague terms ('I want it to last longer'). \" +\n            \"The quality engineer must translate these into **critical-to-quality (CTQ)** characteristics — \" +\n            \"specific, measurable parameters with defined specifications.\",\n        },\n        {\n          type: \"callout\",\n          tone: \"workplace\",\n          title: \"VOC example — Douala aluminium cookware\",\n          text:\n            \"An aluminium pot manufacturer in Douala received complaints that handles 'come loose too easily'. \" +\n            \"The VOC statement is vague. Translated to CTQ: the handle must withstand a pull force of \" +\n            \"≥ 15 kg without detaching. This gives the team a measurable specification to work with.\",\n        },\n\n        { type: \"h\", text: \"CTQ tree construction\" },\n        {\n          type: \"p\",\n          text:\n            \"A CTQ tree systematically decomposes customer needs into measurable requirements through three \" +\n            \"levels: **needs** (what the customer wants), **drivers** (factors that influence the need), and \" +\n            \"**CTQs** (measurable specifications). Each CTQ must have a target value and tolerance.\",\n        },\n        {\n          type: \"steps\",\n          title: \"Building a CTQ tree\",\n          items: [\n            \"Identify the customer need from VOC data (e.g., 'packaging must protect the product')\",\n            \"Determine the drivers — what influences this need (e.g., seal integrity, material strength, cushioning)\",\n            \"Define CTQ metrics for each driver (e.g., seal burst strength ≥ 8 kPa, corrugated board ≥ 200 kPa edge crush)\",\n            \"Set specifications: target value, upper and lower limits, measurement method\",\n          ],\n        },\n        {\n          type: \"table\",\n          head: [\"Customer need\", \"Driver\", \"CTQ\", \"Specification\"],\n          rows: [\n            [\"Product arrives undamaged\", \"Seal integrity\", \"Seal burst strength\", \"≥ 8 kPa\"],\n            [\"Product arrives undamaged\", \"Box strength\", \"Edge crush test\", \"≥ 200 kPa\"],\n            [\"Product arrives undamaged\", \"Cushioning\", \"Drop test survival\", \"1.2 m onto concrete, no breakage\"],\n            [\"Easy to open\", \"Tab design\", \"Opening force\", \"5–15 N\"],\n          ],\n        },\n        {\n          type: \"check\",\n          id: \"aqe-m8-l2-ck1\",\n          question:\n            \"A customer says 'the paint on my furniture scratches too easily'. Which of the following is the best CTQ specification?\",\n          options: [\n            \"Use better paint\",\n            \"Paint hardness ≥ 2H on pencil hardness scale, adhesion ≥ 4B cross-hatch rating\",\n            \"Reduce customer complaints about paint\",\n            \"Apply thicker coats of paint\",\n          ],\n          answer: 1,\n          explain:\n            \"A CTQ must be specific and measurable. Pencil hardness ≥ 2H and cross-hatch adhesion ≥ 4B are \" +\n            \"industry-standard measurable specifications for paint durability. The other options are actions \" +\n            \"or vague goals, not measurable specifications.\",\n        },\n\n        { type: \"h\", text: \"Data collection planning\" },\n        {\n          type: \"p\",\n          text:\n            \"A data collection plan answers five questions: **what** data to collect (which CTQ or process \" +\n            \"parameter), **where** in the process to collect it (which station or operation), **when** to \" +\n            \"collect (frequency, shift, time of day), **how** to collect (which instrument, which procedure), \" +\n            \"and **who** will collect it (trained operators or inspectors). The plan also specifies sample \" +\n            \"size, which is driven by the precision needed and the expected variation (as studied in Module 2).\",\n        },\n        {\n          type: \"callout\",\n          tone: \"tip\",\n          title: \"Link to measurement system analysis\",\n          text:\n            \"Before collecting baseline data, verify that your measurement system is adequate. As covered in \" +\n            \"Module 3, a Gage R&R study should show that measurement system variation is less than 10% of \" +\n            \"total variation for the measurement to be acceptable. Collecting data with a poor measurement \" +\n            \"system wastes time and leads to wrong conclusions.\",\n        },\n\n        { type: \"h\", text: \"Process baseline: sigma level and yield\" },\n        {\n          type: \"p\",\n          text:\n            \"The Measure phase establishes the **baseline** — how the process performs before any improvement. \" +\n            \"Key metrics include DPMO, sigma level, first-pass yield (FPY), and rolled throughput yield (RTY). \" +\n            \"These numbers become the benchmark against which improvement is measured.\",\n        },\n        {\n          type: \"list\",\n          items: [\n            \"**DPMO** = (Defects ÷ (Units × Opportunities)) × 1,000,000\",\n            \"**Yield** = (1 − DPMO ÷ 1,000,000) × 100%\",\n            \"**FPY** = Units passing all inspections on first attempt ÷ Total units started\",\n            \"**RTY** = FPY₁ × FPY₂ × … × FPYₙ (product of yields at each process step)\",\n          ],\n        },\n        {\n          type: \"callout\",\n          tone: \"key\",\n          title: \"Sigma level lookup\",\n          text:\n            \"To convert DPMO to a sigma level, use a Z-table or the approximation: Sigma ≈ 0.8406 + \" +\n            \"√(29.37 − 2.221 × ln(DPMO)). For practical purposes, most teams use a conversion table. \" +\n            \"A process with DPMO = 6,210 is at 4σ; DPMO = 66,807 is at 3σ.\",\n        },\n        {\n          type: \"check\",\n          id: \"aqe-m8-l2-ck2\",\n          question:\n            \"A three-step process has FPY of 95%, 90%, and 92% at each step. What is the rolled throughput yield?\",\n          options: [\"92.3%\", \"78.7%\", \"85.0%\", \"95.0%\"],\n          answer: 1,\n          explain:\n            \"RTY = 0.95 × 0.90 × 0.92 = 0.7866, or 78.7%. RTY reveals the true process yield by multiplying \" +\n            \"the yields at each step, exposing hidden factory losses that individual FPY figures miss.\",\n        },\n\n        /* Lab: form — build a CTQ tree */\n        {\n          type: \"form\",\n          id: \"aqe-m8-l2-lab1\",\n          title: \"Build a CTQ tree from customer needs\",\n          task:\n            \"A furniture company in Yaoundé receives VOC feedback that chairs 'break too quickly'. \" +\n            \"Complete the CTQ tree by identifying drivers and measurable specifications.\",\n          fields: [\n            {\n              kind: \"text\",\n              label: \"Customer need (restate the VOC clearly)\",\n              accept: [\"durability\", \"durable\", \"long-lasting\", \"break\"],\n              example: \"Chair must be durable and withstand normal daily use for at least 5 years\",\n              placeholder: \"What does the customer really want?\",\n            },\n            {\n              kind: \"select\",\n              label: \"Which is the most relevant quality driver for chair breakage?\",\n              options: [\n                \"Paint colour consistency\",\n                \"Joint strength and wood grain orientation\",\n                \"Packaging attractiveness\",\n                \"Delivery speed\",\n              ],\n              answer: 1,\n              explain:\n                \"Joint strength and wood grain orientation directly influence structural durability. \" +\n                \"The other options relate to aesthetics or logistics, not structural failure.\",\n            },\n            {\n              kind: \"text\",\n              label: \"CTQ specification for joint strength (include units and target)\",\n              accept: [\"kg\", \"N\", \"force\", \"≥\", \"cycles\"],\n              example: \"Mortise-and-tenon joint pull-out force ≥ 120 kg; withstand 50,000 rocking cycles without failure\",\n              placeholder: \"State a measurable specification with target value…\",\n            },\n            {\n              kind: \"select\",\n              label: \"What measurement method would verify this CTQ?\",\n              options: [\n                \"Visual inspection of the finished chair\",\n                \"Destructive pull test on sample joints using a universal testing machine\",\n                \"Customer satisfaction survey after 1 month\",\n                \"Weighing the chair to check wood density\",\n              ],\n              answer: 1,\n              explain:\n                \"A destructive pull test on sample joints directly measures the joint strength CTQ. \" +\n                \"Visual inspection cannot assess structural strength, and weight alone does not predict joint integrity.\",\n            },\n          ],\n          hint: \"Think about what physically causes chairs to break — which structural element fails?\",\n        },\n\n        /* Lab: sheet — calculate process sigma from defect data */\n        {\n          type: \"sheet\",\n          id: \"aqe-m8-l2-lab2\",\n          title: \"Calculate process sigma from defect data\",\n          task:\n            \"A textile mill in Garoua inspected 8,000 metres of fabric. Each metre has 4 defect \" +\n            \"opportunities (colour, weave, width, weight). Calculate the DPMO, yield, and approximate \" +\n            \"sigma level in the yellow cells.\",\n          data: [\n            [\"Metric\", \"Value\"],\n            [\"Units inspected\", 8000],\n            [\"Opportunities per unit\", 4],\n            [\"Total defects found\", 156],\n            [\"Total opportunities\", null],\n            [\"DPMO\", null],\n            [\"Yield (%)\", null],\n            [\"Approx. sigma level\", null],\n          ],\n          editable: [\"B5\", \"B6\", \"B7\", \"B8\"],\n          checks: [\n            { cell: \"B5\", equals: 32000 },\n            { cell: \"B6\", equals: 4875, tol: 5 },\n            { cell: \"B7\", equals: 99.51, tol: 0.02 },\n            { cell: \"B8\", equals: 4.1, tol: 0.2 },\n          ],\n          hint:\n            \"Total opportunities = Units × Opportunities per unit. DPMO = (Defects ÷ Total opportunities) × 1,000,000. \" +\n            \"Yield = (1 − DPMO/1,000,000) × 100. Use the sigma conversion table: DPMO ≈ 4,875 is between 4σ (6,210) \" +\n            \"and 4.5σ (1,350), closer to 4σ, so approximately 4.1σ.\",\n          solution: {\n            B5: \"=8000*4\",\n            B6: \"=(156/32000)*1000000\",\n            B7: \"=(1-4875/1000000)*100\",\n            B8: \"4.1\",\n          },\n        },\n      ],\n    },\n\n    /* ──────────────────────────────────────────────────────────\n     * LESSON 3 — Analyse phase: finding root causes\n     * ────────────────────────────────────────────────────────── */\n    {\n      id: \"aqe-m8-l3\",\n      title: \"Analyse phase: finding root causes\",\n      minutes: 30,\n      objectives: [\n        \"Construct an Ishikawa diagram using the 6M categories\",\n        \"Conduct a 5 Whys analysis to drill down to the true root cause\",\n        \"Apply Pareto analysis to identify the vital few contributors\",\n        \"Link hypothesis testing concepts from Module 2 to root cause verification\",\n      ],\n      blocks: [\n        { type: \"h\", text: \"Cause-and-effect diagram (Ishikawa)\" },\n        {\n          type: \"p\",\n          text:\n            \"The Ishikawa (fishbone) diagram is the most widely used brainstorming tool in root cause \" +\n            \"analysis. The effect (problem) is placed at the head of the fish, and potential causes are \" +\n            \"organised along bones representing the **6M categories**: Man (people), Machine (equipment), \" +\n            \"Material (raw materials), Method (procedures), Measurement (gauges and inspections), and \" +\n            \"Milieu (environment). Each category can have sub-causes branching further.\",\n        },\n        {\n          type: \"table\",\n          head: [\"6M category\", \"Example causes (soap production, Bamenda)\"],\n          rows: [\n            [\"Man\", \"Insufficient training on mixing ratios, operator fatigue on night shift\"],\n            [\"Machine\", \"Worn mixer blades, inconsistent heating element temperature\"],\n            [\"Material\", \"Varying palm oil acidity between batches, impure caustic soda\"],\n            [\"Method\", \"No standardised mixing time, inconsistent mould filling\"],\n            [\"Measurement\", \"Uncalibrated pH meter, visual colour check not standardised\"],\n            [\"Milieu\", \"Humidity fluctuations in drying area, ambient temperature swings\"],\n          ],\n        },\n        {\n          type: \"callout\",\n          tone: \"tip\",\n          title: \"Building a good fishbone\",\n          text:\n            \"Involve the people closest to the process — operators, technicians, inspectors. Use sticky notes \" +\n            \"so ideas can be rearranged. Aim for at least 3–4 potential causes per category. After brainstorming, \" +\n            \"circle the 3–5 most likely causes for further investigation with data.\",\n        },\n\n        { type: \"h\", text: \"5 Whys analysis\" },\n        {\n          type: \"p\",\n          text:\n            \"The 5 Whys technique, developed at Toyota, repeatedly asks 'Why?' to peel back layers of \" +\n            \"symptoms until the true root cause is exposed. The number five is a guideline — some problems \" +\n            \"require three whys, others seven. The key is to stop when you reach a cause that, if addressed, \" +\n            \"would prevent the problem from recurring.\",\n        },\n        {\n          type: \"steps\",\n          title: \"5 Whys example — paint defects on metal furniture\",\n          items: [\n            \"**Problem:** Paint is peeling off metal chairs within 3 months of purchase.\",\n            \"**Why 1:** The paint adhesion is poor → because the surface preparation is inadequate.\",\n            \"**Why 2:** Why is surface preparation inadequate? → because phosphating solution is too dilute.\",\n            \"**Why 3:** Why is the solution too dilute? → because operators are not checking concentration daily.\",\n            \"**Why 4:** Why are operators not checking daily? → because there is no standard work instruction for daily concentration checks.\",\n            \"**Root cause:** Missing standard work instruction for phosphating solution monitoring. **Countermeasure:** Create and train on a daily checklist for solution concentration, temperature, and pH.\",\n          ],\n        },\n\n        { type: \"h\", text: \"Pareto analysis and stratification\" },\n        {\n          type: \"p\",\n          text:\n            \"The Pareto principle (80/20 rule) states that roughly 80% of effects come from 20% of causes. \" +\n            \"A Pareto chart combines a bar chart (sorted by frequency) with a cumulative percentage line. \" +\n            \"It focuses improvement efforts on the **vital few** categories that account for the majority \" +\n            \"of defects, rather than spreading resources across the **trivial many**.\",\n        },\n        {\n          type: \"callout\",\n          tone: \"key\",\n          title: \"Stratification deepens the analysis\",\n          text:\n            \"After identifying the top Pareto category, stratify the data by shift, machine, operator, or \" +\n            \"material batch. A cement plant in Figuil found that 'bag breakage' was the top defect, but \" +\n            \"stratifying by shift revealed that 85% of breakages occurred on the night shift, pointing to \" +\n            \"a training gap for night-shift packers.\",\n        },\n\n        { type: \"h\", text: \"Hypothesis testing for root cause verification\" },\n        {\n          type: \"p\",\n          text:\n            \"Brainstorming and Pareto analysis identify suspected causes, but statistical hypothesis testing \" +\n            \"(Module 2) **verifies** them with data. Common approaches include two-sample t-tests (does defect \" +\n            \"rate differ between shifts?), chi-square tests (is defect type related to machine?), and \" +\n            \"correlation analysis (does temperature correlate with warping?).\",\n        },\n        {\n          type: \"callout\",\n          tone: \"workplace\",\n          title: \"Multi-vari analysis concept\",\n          text:\n            \"Multi-vari analysis is a graphical technique that examines variation at three levels: \" +\n            \"**within-piece** (position-to-position on one unit), **piece-to-piece** (consecutive units), and \" +\n            \"**time-to-time** (shift-to-shift, day-to-day). At a rubber seal factory in Douala, multi-vari \" +\n            \"charts showed that piece-to-piece variation was the dominant component, directing the team to \" +\n            \"investigate the moulding cycle rather than raw material or environmental factors.\",\n        },\n\n        {\n          type: \"check\",\n          id: \"aqe-m8-l3-ck1\",\n          question:\n            \"After building a Pareto chart, you find that 3 out of 12 defect categories account for 78% of all defects. What is the correct interpretation?\",\n          options: [\n            \"All 12 categories need equal attention\",\n            \"The 3 categories are the vital few and should be prioritised for root cause analysis\",\n            \"The chart is wrong because the 80/20 rule requires exactly 80%\",\n            \"Only the single largest category needs investigation\",\n          ],\n          answer: 1,\n          explain:\n            \"The vital few (3 categories covering 78% of defects) should be prioritised. The 80/20 \" +\n            \"rule is a guideline, not an exact threshold. Focusing on these three categories will yield \" +\n            \"the greatest improvement for the effort invested.\",\n        },\n\n        {\n          type: \"equip\",\n          title: \"Root cause analysis tools\",\n          items: [\n            {\n              art: \"qc-fishbone\",\n              name: \"Ishikawa (fishbone) diagram\",\n              caption:\n                \"The fishbone layout organises brainstormed causes into the 6M categories, making it \" +\n                \"easy to see which areas have the most potential root causes.\",\n            },\n            {\n              art: \"qc-pareto\",\n              name: \"Pareto chart\",\n              caption:\n                \"Bars sorted by frequency with a cumulative line identify the vital few categories that \" +\n                \"account for the majority of defects.\",\n            },\n          ],\n        },\n\n        /* Lab: whys — 5 Whys for a process problem */\n        {\n          type: \"whys\",\n          id: \"aqe-m8-l3-lab1\",\n          title: \"5 Whys: leaking juice bottles\",\n          task:\n            \"A fruit juice bottling plant in Bafoussam is experiencing leaking bottles. Use the \" +\n            \"5 Whys to find the root cause and propose a countermeasure.\",\n          problem: \"Juice bottles are leaking during transport to retailers, causing a 6% return rate.\",\n          steps: [\n            {\n              question: \"Why are bottles leaking during transport?\",\n              options: [\n                \"Because the bottle caps are not sealed tightly enough\",\n                \"Because the transport trucks drive too fast\",\n                \"Because the juice is too acidic\",\n                \"Because retailers store them incorrectly\",\n              ],\n              answer: 0,\n              explain: \"Inspection shows visible gaps between the cap and bottle rim — a sealing problem.\",\n            },\n            {\n              question: \"Why are the caps not sealed tightly enough?\",\n              options: [\n                \"Because the capping machine torque is set too low\",\n                \"Because the bottles are the wrong colour\",\n                \"Because the caps are too expensive\",\n                \"Because the labels obscure the cap\",\n              ],\n              answer: 0,\n              explain: \"Torque measurements show 1.2 N·m versus the required 1.8 N·m — the machine is under-tightening.\",\n            },\n            {\n              question: \"Why is the capping machine torque set too low?\",\n              options: [\n                \"Because the operator did not adjust it after the last changeover\",\n                \"Because the machine is brand new\",\n                \"Because the factory uses too many cap sizes\",\n                \"Because electricity supply is unstable\",\n              ],\n              answer: 0,\n              explain: \"The torque setting was left at the value for the previous smaller bottle size after a product changeover.\",\n            },\n            {\n              question: \"Why did the operator not adjust the torque after changeover?\",\n              options: [\n                \"Because there is no changeover checklist requiring torque verification\",\n                \"Because the operator was absent that day\",\n                \"Because torque adjustment requires a special licence\",\n                \"Because the machine cannot be adjusted\",\n              ],\n              answer: 0,\n              explain: \"There is no standard changeover procedure or checklist that includes torque verification as a mandatory step.\",\n            },\n          ],\n          countermeasure: {\n            question: \"What countermeasure best addresses the root cause?\",\n            options: [\n              \"Replace all capping machines with newer models\",\n              \"Create a changeover checklist that includes torque verification and train all operators\",\n              \"Hire additional quality inspectors to check every bottle\",\n              \"Reduce the number of product sizes to avoid changeovers\",\n            ],\n            answer: 1,\n            explain:\n              \"A changeover checklist with mandatory torque verification addresses the root cause \" +\n              \"(missing standard work) directly. It prevents recurrence without requiring expensive \" +\n              \"capital investment or limiting the product range.\",\n          },\n          hint: \"Follow the chain of causation — each 'why' should explain the previous answer, drilling deeper into the system.\",\n        },\n\n        /* Lab: pareto — defect analysis with >= 5 categories */\n        {\n          type: \"pareto\",\n          id: \"aqe-m8-l3-lab2\",\n          title: \"Pareto analysis: ceramic tile defects\",\n          task:\n            \"A ceramic tile factory in Limbe recorded 840 defects over one month. Identify the \" +\n            \"vital few defect categories using the Pareto chart. Which categories should the \" +\n            \"improvement team focus on first?\",\n          unit: \"defects\",\n          categories: [\n            { label: \"Surface cracks\", count: 312 },\n            { label: \"Colour variation\", count: 198 },\n            { label: \"Edge chips\", count: 147 },\n            { label: \"Dimensional error\", count: 89 },\n            { label: \"Glaze bubbles\", count: 52 },\n            { label: \"Warping\", count: 28 },\n            { label: \"Staining\", count: 14 },\n          ],\n          hint:\n            \"The vital few are the categories whose cumulative percentage crosses approximately 80%. \" +\n            \"Surface cracks alone account for 37% of defects.\",\n        },\n\n        /* Lab: sorter — fishbone classification */\n        {\n          type: \"sorter\",\n          id: \"aqe-m8-l3-lab3\",\n          title: \"Fishbone diagram: classify causes by 6M category\",\n          task:\n            \"A bakery in Yaoundé is experiencing inconsistent bread loaf weight. Classify \" +\n            \"each potential cause into the correct 6M category on the fishbone diagram.\",\n          layout: \"fishbone\",\n          effect: \"Inconsistent bread loaf weight\",\n          buckets: [\n            { label: \"Man\", desc: \"People-related causes\" },\n            { label: \"Machine\", desc: \"Equipment-related causes\" },\n            { label: \"Material\", desc: \"Raw material causes\" },\n            { label: \"Method\", desc: \"Procedure-related causes\" },\n            { label: \"Measurement\", desc: \"Gauging and inspection causes\" },\n            { label: \"Milieu\", desc: \"Environmental causes\" },\n          ],\n          items: [\n            {\n              text: \"New baker not trained on dough scaling procedure\",\n              bucket: 0,\n              explain: \"Training gaps are a Man (people) category cause.\",\n            },\n            {\n              text: \"Dough divider cutting unevenly due to worn blades\",\n              bucket: 1,\n              explain: \"Equipment wear is a Machine category cause.\",\n            },\n            {\n              text: \"Flour moisture content varies between deliveries\",\n              bucket: 2,\n              explain: \"Raw material variation is a Material category cause.\",\n            },\n            {\n              text: \"No standard recipe specifying exact water-to-flour ratio\",\n              bucket: 3,\n              explain: \"Missing standard procedures fall under the Method category.\",\n            },\n            {\n              text: \"Kitchen scale not calibrated for 6 months\",\n              bucket: 4,\n              explain: \"Instrument calibration is a Measurement category issue.\",\n            },\n            {\n              text: \"High humidity causing dough to absorb extra moisture\",\n              bucket: 5,\n              explain: \"Ambient humidity is an environmental (Milieu) factor.\",\n            },\n          ],\n        },\n      ],\n    },\n\n    /* ──────────────────────────────────────────────────────────\n     * LESSON 4 — Improve and Control phases\n     * ────────────────────────────────────────────────────────── */\n    {\n      id: \"aqe-m8-l4\",\n      title: \"Improve and Control phases\",\n      minutes: 25,\n      objectives: [\n        \"Generate and evaluate solutions using structured selection criteria\",\n        \"Plan and execute a pilot test before full-scale implementation\",\n        \"Design a control plan that integrates SPC, standard work, and visual management\",\n        \"Document project results and conduct a formal handover\",\n      ],\n      blocks: [\n        { type: \"h\", text: \"Solution generation methods\" },\n        {\n          type: \"p\",\n          text:\n            \"Once root causes are verified, the Improve phase generates potential solutions. Three common \" +\n            \"approaches are: **brainstorming** (structured idea generation with the team), **benchmarking** \" +\n            \"(studying how other companies or industries solve similar problems), and **Design of Experiments** \" +\n            \"(DOE, from Module 5) to optimise process settings systematically.\",\n        },\n        {\n          type: \"callout\",\n          tone: \"tip\",\n          title: \"Link to DOE (Module 5)\",\n          text:\n            \"When the root cause involves multiple process parameters interacting (e.g., temperature, pressure, \" +\n            \"and time in a moulding process), DOE is the most efficient way to find the optimal settings. A \" +\n            \"factorial experiment tests combinations of factor levels rather than changing one variable at a time.\",\n        },\n\n        { type: \"h\", text: \"Solution selection: criteria matrix\" },\n        {\n          type: \"p\",\n          text:\n            \"When multiple solutions are feasible, a criteria matrix (also called a Pugh matrix or decision \" +\n            \"matrix) provides structured evaluation. Common criteria include effectiveness (will it eliminate \" +\n            \"the root cause?), cost, implementation time, risk, and sustainability. Each criterion is weighted \" +\n            \"and each solution is scored, producing a ranked list.\",\n        },\n        {\n          type: \"table\",\n          head: [\"Criterion\", \"Weight\", \"Solution A: Automated torque control\", \"Solution B: Changeover checklist\", \"Solution C: New capping machine\"],\n          rows: [\n            [\"Effectiveness\", \"30%\", \"9 (2.7)\", \"7 (2.1)\", \"10 (3.0)\"],\n            [\"Cost\", \"25%\", \"5 (1.25)\", \"9 (2.25)\", \"3 (0.75)\"],\n            [\"Implementation speed\", \"20%\", \"6 (1.2)\", \"9 (1.8)\", \"4 (0.8)\"],\n            [\"Sustainability\", \"15%\", \"8 (1.2)\", \"6 (0.9)\", \"9 (1.35)\"],\n            [\"Risk\", \"10%\", \"7 (0.7)\", \"8 (0.8)\", \"5 (0.5)\"],\n            [\"**Weighted total**\", \"100%\", \"**7.05**\", \"**7.85**\", \"**6.40**\"],\n          ],\n        },\n        {\n          type: \"p\",\n          text:\n            \"In this example, Solution B (changeover checklist) scores highest because it is low-cost, \" +\n            \"quick to implement, and low-risk. The team may later pursue Solution A as a phase-two enhancement.\",\n        },\n\n        { type: \"h\", text: \"Piloting and implementation\" },\n        {\n          type: \"p\",\n          text:\n            \"Before full-scale rollout, the team runs a **pilot test** — implementing the solution on a \" +\n            \"limited scale (one shift, one machine, one product line) to verify effectiveness and identify \" +\n            \"unforeseen problems. The pilot should have clear success criteria, a defined duration, and a \" +\n            \"data collection plan to compare pilot results against the baseline.\",\n        },\n        {\n          type: \"callout\",\n          tone: \"workplace\",\n          title: \"Pilot at a Douala soap factory\",\n          text:\n            \"The improvement team piloted a new mixing procedure on Line 2 for two weeks. They compared \" +\n            \"the defect rate (bar cracking) on Line 2 against the unchanged Line 1. Line 2 dropped from \" +\n            \"8.3% to 2.1% cracking, while Line 1 remained at 7.9%. The pilot confirmed the solution, and \" +\n            \"rollout to all lines was approved.\",\n        },\n\n        {\n          type: \"check\",\n          id: \"aqe-m8-l4-ck1\",\n          question:\n            \"Why is it important to run a pilot before full implementation?\",\n          options: [\n            \"To delay the project timeline and reduce costs\",\n            \"To verify effectiveness on a small scale and identify unforeseen problems before committing full resources\",\n            \"Because management always requires a pilot phase\",\n            \"To train only a few operators and save on training costs\",\n          ],\n          answer: 1,\n          explain:\n            \"A pilot verifies that the solution works in the real process environment and exposes \" +\n            \"problems that were not apparent during planning, reducing the risk of a failed full-scale rollout.\",\n        },\n\n        { type: \"h\", text: \"Control phase: sustaining the gains\" },\n        {\n          type: \"p\",\n          text:\n            \"The Control phase ensures that improvements are maintained after the project team disbands. \" +\n            \"Without control mechanisms, processes tend to drift back to their old performance. Key control \" +\n            \"tools include:\",\n        },\n        {\n          type: \"list\",\n          items: [\n            \"**Control plan** — documents what to monitor, how to measure it, sampling frequency, control limits, and the reaction plan if a signal occurs\",\n            \"**Statistical process control (SPC)** — control charts (Module 4) provide real-time monitoring of process stability\",\n            \"**Standard work** — detailed written procedures, visual work instructions, and training records\",\n            \"**Visual management** — colour-coded indicators, andon boards, floor markings, and status displays that make abnormalities immediately visible\",\n            \"**Response plan** — who to contact and what actions to take when an out-of-control signal occurs\",\n          ],\n        },\n\n        {\n          type: \"equip\",\n          title: \"Control phase tools\",\n          items: [\n            {\n              art: \"control-plan-form\",\n              name: \"Control plan template\",\n              caption:\n                \"The control plan links each critical process parameter to its measurement method, \" +\n                \"sampling frequency, control limits, and reaction plan.\",\n              specs: [\n                { label: \"Columns\", value: \"Process step, characteristic, spec, method, sample, control, reaction\" },\n                { label: \"Updated\", value: \"After every process change or improvement project\" },\n              ],\n            },\n          ],\n        },\n\n        { type: \"h\", text: \"Project closure and lessons learned\" },\n        {\n          type: \"p\",\n          text:\n            \"The project concludes with a formal closure report documenting: the problem statement and \" +\n            \"baseline, root causes identified, solutions implemented, before-and-after performance comparison, \" +\n            \"financial impact (cost savings or avoidance), lessons learned, and the control plan handover to \" +\n            \"the process owner. The project sponsor signs off, and results are shared across the organisation.\",\n        },\n        {\n          type: \"callout\",\n          tone: \"key\",\n          title: \"Cost of quality impact\",\n          text:\n            \"Link improvement results to the cost of quality framework (Module 6). A successful DMAIC project \" +\n            \"typically reduces failure costs (scrap, rework, returns) while the increase in appraisal or \" +\n            \"prevention costs is far smaller, yielding a net reduction in total quality costs.\",\n        },\n\n        /* Lab: form — build a solution criteria matrix */\n        {\n          type: \"form\",\n          id: \"aqe-m8-l4-lab1\",\n          title: \"Build a solution criteria matrix\",\n          task:\n            \"A cassava flour mill in Bertoua has identified that excess moisture in the final product \" +\n            \"(target: ≤ 12%) is caused by inconsistent drying time. Three solutions have been proposed. \" +\n            \"Evaluate them using the criteria below.\",\n          fields: [\n            {\n              kind: \"select\",\n              label: \"Which criterion should have the highest weight for a food safety issue?\",\n              options: [\n                \"Implementation speed\",\n                \"Effectiveness at eliminating the root cause\",\n                \"Lowest initial cost\",\n                \"Ease of operator training\",\n              ],\n              answer: 1,\n              explain:\n                \"For a food safety issue like excess moisture (which promotes mould growth), effectiveness \" +\n                \"at eliminating the root cause must be the primary criterion.\",\n            },\n            {\n              kind: \"select\",\n              label:\n                \"Solution A: Install moisture sensor with auto-shutoff (cost: 4.5M FCFA). \" +\n                \"Solution B: Add drying time to the operator checklist (cost: 50K FCFA). \" +\n                \"Solution C: Replace dryer with a larger model (cost: 22M FCFA). \" +\n                \"Which solution best balances effectiveness and feasibility for a small mill?\",\n              options: [\n                \"Solution A — automated control directly addresses the root cause at moderate cost\",\n                \"Solution B — lowest cost but relies on operator discipline\",\n                \"Solution C — most effective but cost is prohibitive for a small mill\",\n                \"None of the solutions are adequate\",\n              ],\n              answer: 0,\n              explain:\n                \"Solution A provides automated control (high effectiveness and sustainability) at a cost \" +\n                \"that a small mill can manage. Solution B is cheap but relies on human consistency, and \" +\n                \"Solution C is disproportionately expensive.\",\n            },\n            {\n              kind: \"select\",\n              label: \"What should the team do after selecting the best solution?\",\n              options: [\n                \"Immediately implement it across all production lines\",\n                \"Run a pilot on one production line, collect moisture data, and compare to baseline\",\n                \"Wait for the next budget cycle before taking any action\",\n                \"Move directly to the Control phase\",\n              ],\n              answer: 1,\n              explain:\n                \"A pilot verifies effectiveness in the real process environment before committing to \" +\n                \"full-scale implementation.\",\n            },\n          ],\n          hint: \"Consider both the severity of the quality problem (food safety) and the practical constraints of a small operation.\",\n        },\n\n        /* Lab: sheet — calculate cost-benefit for improvement options */\n        {\n          type: \"sheet\",\n          id: \"aqe-m8-l4-lab2\",\n          title: \"Cost-benefit analysis for improvement options\",\n          task:\n            \"Calculate the annual savings, net benefit, and payback period for each improvement option \" +\n            \"at a packaging plant in Douala. Fill in the yellow cells.\",\n          data: [\n            [\"Option\", \"Implementation cost (FCFA)\", \"Annual scrap reduction (FCFA)\", \"Annual rework reduction (FCFA)\", \"Total annual savings (FCFA)\", \"Net benefit Year 1 (FCFA)\", \"Payback (months)\"],\n            [\"A: Automated inspection\", 8500000, 6200000, 2800000, null, null, null],\n            [\"B: Operator training\", 1200000, 2100000, 1400000, null, null, null],\n            [\"C: Material upgrade\", 4800000, 4500000, 1100000, null, null, null],\n          ],\n          editable: [\"E2\", \"F2\", \"G2\", \"E3\", \"F3\", \"G3\", \"E4\", \"F4\", \"G4\"],\n          checks: [\n            { cell: \"E2\", equals: 9000000 },\n            { cell: \"F2\", equals: 500000 },\n            { cell: \"G2\", equals: 11.3, tol: 0.2 },\n            { cell: \"E3\", equals: 3500000 },\n            { cell: \"F3\", equals: 2300000 },\n            { cell: \"G3\", equals: 4.1, tol: 0.2 },\n            { cell: \"E4\", equals: 5600000 },\n            { cell: \"F4\", equals: 800000 },\n            { cell: \"G4\", equals: 10.3, tol: 0.2 },\n          ],\n          hint:\n            \"Total annual savings = scrap reduction + rework reduction. \" +\n            \"Net benefit Year 1 = total annual savings − implementation cost. \" +\n            \"Payback (months) = (implementation cost ÷ total annual savings) × 12.\",\n          solution: {\n            E2: \"=6200000+2800000\",\n            F2: \"=9000000-8500000\",\n            G2: \"=(8500000/9000000)*12\",\n            E3: \"=2100000+1400000\",\n            F3: \"=3500000-1200000\",\n            G3: \"=(1200000/3500000)*12\",\n            E4: \"=4500000+1100000\",\n            F4: \"=5600000-4800000\",\n            G4: \"=(4800000/5600000)*12\",\n          },\n        },\n      ],\n    },\n\n    /* ──────────────────────────────────────────────────────────\n     * LESSON 5 — Lean principles and waste elimination\n     * ────────────────────────────────────────────────────────── */\n    {\n      id: \"aqe-m8-l5\",\n      title: \"Lean principles and waste elimination\",\n      minutes: 25,\n      objectives: [\n        \"State the five lean principles and explain their relationship to quality\",\n        \"Identify and classify the eight wastes using the DOWNTIME mnemonic\",\n        \"Select appropriate lean tools for specific improvement opportunities\",\n        \"Describe value stream mapping and its role in visualising process flow\",\n      ],\n      blocks: [\n        { type: \"h\", text: \"Five lean principles\" },\n        {\n          type: \"p\",\n          text:\n            \"Lean thinking, developed from the Toyota Production System, provides a complementary framework \" +\n            \"to Six Sigma. While Six Sigma focuses on reducing variation and defects, Lean focuses on \" +\n            \"eliminating waste and improving flow. Together, they form **Lean Six Sigma** — the most powerful \" +\n            \"continuous improvement methodology available.\",\n        },\n        {\n          type: \"steps\",\n          title: \"The five lean principles\",\n          items: [\n            \"**Value** — Define value from the customer's perspective. Only activities the customer is willing to pay for add value; everything else is waste.\",\n            \"**Value stream** — Map all steps in the process from raw material to delivery. Identify which steps add value, which are necessary but non-value-adding (e.g., regulatory inspections), and which are pure waste.\",\n            \"**Flow** — Arrange value-adding steps in tight sequence so the product flows smoothly without waiting, batching, or backtracking.\",\n            \"**Pull** — Produce only what the customer has ordered, when they need it. Avoid overproduction by using pull signals (kanban) rather than pushing product based on forecasts.\",\n            \"**Perfection** — Continuously pursue the ideal state through repeated cycles of waste elimination. Perfection is the direction, not the destination.\",\n          ],\n        },\n\n        { type: \"h\", text: \"The eight wastes: DOWNTIME\" },\n        {\n          type: \"p\",\n          text:\n            \"Toyota originally identified seven wastes (muda); the eighth — non-utilised talent — was added \" +\n            \"later. The mnemonic **DOWNTIME** makes them easy to remember. Identifying and eliminating these \" +\n            \"wastes is the foundation of lean improvement.\",\n        },\n        {\n          type: \"table\",\n          head: [\"Waste\", \"Letter\", \"Definition\", \"Cameroon example\"],\n          rows: [\n            [\"Defects\", \"D\", \"Products or services that do not meet specifications\", \"Cracked tiles requiring rework at Limbe ceramics plant\"],\n            [\"Overproduction\", \"O\", \"Making more than the customer ordered or before it is needed\", \"Bamenda soap factory producing 3 months of inventory 'just in case'\"],\n            [\"Waiting\", \"W\", \"Idle time when people, materials, or information are not ready\", \"Operators waiting 45 min for forklift to deliver raw materials in Douala\"],\n            [\"Non-utilised talent\", \"N\", \"Not using people's skills, knowledge, or creativity\", \"Experienced machine operator never consulted on process improvements\"],\n            [\"Transportation\", \"T\", \"Unnecessary movement of materials between locations\", \"Semi-finished goods trucked between two buildings 800 m apart in Yaoundé\"],\n            [\"Inventory\", \"I\", \"Excess raw materials, WIP, or finished goods beyond what is needed\", \"6 months of packaging supplies stored in warehouse, tying up capital\"],\n            [\"Motion\", \"M\", \"Unnecessary movement of people (walking, reaching, bending)\", \"Operator walking 20 m to collect tools stored far from workstation\"],\n            [\"Extra processing\", \"E\", \"Doing more work than the customer requires\", \"Polishing internal surfaces of a pipe fitting that will never be visible\"],\n          ],\n        },\n        {\n          type: \"callout\",\n          tone: \"warning\",\n          title: \"Waste is not always obvious\",\n          text:\n            \"Many wastes are hidden because they have become accepted as 'normal'. A time study at a Douala \" +\n            \"furniture workshop revealed that operators spent 35% of their time walking to fetch tools, \" +\n            \"materials, and drawings — all motion waste that was invisible until measured.\",\n        },\n\n        {\n          type: \"check\",\n          id: \"aqe-m8-l5-ck1\",\n          question:\n            \"A factory produces 500 units per day but customers only order 300 per day. The excess 200 units go into warehouse storage. Which waste does this represent?\",\n          options: [\n            \"Inventory\",\n            \"Overproduction\",\n            \"Extra processing\",\n            \"Waiting\",\n          ],\n          answer: 1,\n          explain:\n            \"Producing more than the customer demands is **overproduction** — considered the worst waste \" +\n            \"because it generates other wastes (inventory, transportation, motion). The resulting excess \" +\n            \"stock in the warehouse is a secondary waste (inventory).\",\n        },\n\n        { type: \"h\", text: \"Lean tools overview\" },\n        {\n          type: \"table\",\n          head: [\"Tool\", \"Purpose\", \"When to use\"],\n          rows: [\n            [\"5S\", \"Sort, Set in order, Shine, Standardise, Sustain — workplace organisation\", \"Foundation for any lean initiative; start here\"],\n            [\"Kanban\", \"Visual pull signal to trigger production or material replenishment\", \"Reduce overproduction and inventory waste\"],\n            [\"Poka-yoke\", \"Error-proofing devices that prevent defects from occurring\", \"When human error is a significant source of defects\"],\n            [\"SMED\", \"Single Minute Exchange of Die — reduce changeover time\", \"When long changeovers force large batch production\"],\n            [\"TPM\", \"Total Productive Maintenance — operator-led equipment care\", \"When unplanned breakdowns and minor stops reduce OEE\"],\n            [\"Visual management\", \"Colour codes, markings, andon lights, status boards\", \"Make abnormalities immediately visible to everyone\"],\n          ],\n        },\n\n        { type: \"h\", text: \"Value stream mapping\" },\n        {\n          type: \"p\",\n          text:\n            \"A value stream map (VSM) is a visual representation of all the steps — both value-adding and \" +\n            \"non-value-adding — required to bring a product from raw material to the customer. The **current \" +\n            \"state map** shows the process as it is today, including cycle times, changeover times, inventory \" +\n            \"levels, and information flows. The **future state map** shows the improved process after wastes \" +\n            \"are eliminated.\",\n        },\n        {\n          type: \"callout\",\n          tone: \"workplace\",\n          title: \"VSM at a Douala packaging company\",\n          text:\n            \"A current-state VSM revealed a total lead time of 14 days from order receipt to shipment, \" +\n            \"but only 2.8 hours of actual value-adding processing time. The value-adding ratio was just \" +\n            \"0.83%. The future-state map targeted reducing lead time to 5 days by eliminating batch-and-queue \" +\n            \"processing, reducing WIP inventory, and implementing a pull system with kanban.\",\n        },\n\n        { type: \"h\", text: \"Kaizen events and daily management\" },\n        {\n          type: \"p\",\n          text:\n            \"A **kaizen event** (also called a kaizen blitz or rapid improvement event) is a focused, \" +\n            \"short-duration (typically 3–5 days) improvement activity targeting a specific process or area. \" +\n            \"The team maps the current state, identifies wastes, implements improvements, and standardises \" +\n            \"the new process — all within the event week. **Daily management** (also called gemba management) \" +\n            \"sustains gains through structured daily routines: short team meetings, visual performance boards, \" +\n            \"and leader standard work including gemba walks.\",\n        },\n\n        {\n          type: \"check\",\n          id: \"aqe-m8-l5-ck2\",\n          question:\n            \"Which lean tool would be most appropriate to reduce defects caused by operators accidentally assembling parts in the wrong orientation?\",\n          options: [\n            \"Kanban\",\n            \"SMED\",\n            \"Poka-yoke\",\n            \"5S\",\n          ],\n          answer: 2,\n          explain:\n            \"Poka-yoke (error-proofing) prevents human errors by designing parts or fixtures so that \" +\n            \"incorrect assembly is physically impossible — for example, asymmetrical pins that only fit \" +\n            \"in the correct orientation.\",\n        },\n\n        {\n          type: \"equip\",\n          title: \"Lean tools in practice\",\n          items: [\n            {\n              art: \"poka-yoke-fixture\",\n              name: \"Poka-yoke fixture\",\n              caption:\n                \"An error-proofing jig that prevents parts from being loaded in the wrong orientation. \" +\n                \"Asymmetric locating pins ensure only correctly positioned parts can be processed.\",\n              specs: [\n                { label: \"Type\", value: \"Contact method — physical shape prevents error\" },\n                { label: \"Triggered by\", value: \"Incorrect part orientation blocks fixture closure\" },\n              ],\n            },\n            {\n              art: \"andon-light\",\n              name: \"Andon signal light\",\n              caption:\n                \"A visual management device mounted on equipment or assembly lines that signals status: \" +\n                \"green (normal), yellow (attention needed), red (line stopped). Enables rapid response \" +\n                \"to abnormalities.\",\n              specs: [\n                { label: \"Green\", value: \"Normal operation — process running to standard\" },\n                { label: \"Yellow\", value: \"Caution — minor issue, supervisor attention needed\" },\n                { label: \"Red\", value: \"Stop — critical problem, immediate intervention required\" },\n              ],\n            },\n          ],\n        },\n\n        /* Lab: sorter — classify wastes */\n        {\n          type: \"sorter\",\n          id: \"aqe-m8-l5-lab1\",\n          title: \"Classify the eight wastes (DOWNTIME)\",\n          task:\n            \"Drag each workplace observation into the correct waste category.\",\n          layout: \"columns\",\n          buckets: [\n            { label: \"Defects\" },\n            { label: \"Overproduction\" },\n            { label: \"Waiting\" },\n            { label: \"Non-utilised talent\" },\n            { label: \"Transportation\" },\n            { label: \"Inventory\" },\n            { label: \"Motion\" },\n            { label: \"Extra processing\" },\n          ],\n          items: [\n            {\n              text: \"Products returned by customers due to incorrect dimensions\",\n              bucket: 0,\n              explain: \"Products not meeting specifications are defects.\",\n            },\n            {\n              text: \"Factory produces 2,000 units per week although weekly orders average only 1,200\",\n              bucket: 1,\n              explain: \"Producing more than demand requires is overproduction.\",\n            },\n            {\n              text: \"Operators stand idle for 20 minutes each morning waiting for the supervisor to assign tasks\",\n              bucket: 2,\n              explain: \"People idle because information is not ready is waiting waste.\",\n            },\n            {\n              text: \"A technician with 15 years of press experience is assigned only to sweeping duties\",\n              bucket: 3,\n              explain: \"Failing to use an employee's skills and knowledge is non-utilised talent.\",\n            },\n            {\n              text: \"Raw materials are moved by forklift between three buildings before reaching the production line\",\n              bucket: 4,\n              explain: \"Unnecessary movement of materials between locations is transportation waste.\",\n            },\n            {\n              text: \"The warehouse holds 8 months of packaging supplies, tying up 12 million FCFA\",\n              bucket: 5,\n              explain: \"Excess stock beyond what is needed is inventory waste.\",\n            },\n            {\n              text: \"An assembler walks 30 metres to the tool crib each time she needs a different wrench\",\n              bucket: 6,\n              explain: \"Unnecessary movement of people is motion waste.\",\n            },\n            {\n              text: \"Workers sand a surface to mirror finish even though it will be covered by another component\",\n              bucket: 7,\n              explain: \"Performing work beyond what the customer requires is extra processing.\",\n            },\n          ],\n        },\n\n        /* Lab: form — identify lean tools for improvement opportunities */\n        {\n          type: \"form\",\n          id: \"aqe-m8-l5-lab2\",\n          title: \"Match lean tools to improvement opportunities\",\n          task:\n            \"For each workplace problem described below, select the most appropriate lean tool.\",\n          fields: [\n            {\n              kind: \"select\",\n              label: \"Problem: The workshop floor is cluttered with unused tools, scrap, and personal items, making it hard to find what is needed.\",\n              options: [\"Kanban\", \"5S\", \"SMED\", \"TPM\"],\n              answer: 1,\n              explain: \"5S (Sort, Set in order, Shine, Standardise, Sustain) is the foundation tool for organising the workplace and eliminating clutter.\",\n            },\n            {\n              kind: \"select\",\n              label: \"Problem: Changeover between products takes 4 hours, forcing the factory to run large batches to minimise the number of changeovers.\",\n              options: [\"Poka-yoke\", \"Visual management\", \"SMED\", \"5S\"],\n              answer: 2,\n              explain: \"SMED (Single Minute Exchange of Die) systematically reduces changeover time, enabling smaller batch sizes and greater flexibility.\",\n            },\n            {\n              kind: \"select\",\n              label: \"Problem: Operators frequently install gaskets upside down, causing leaks that are only detected at final test.\",\n              options: [\"Kanban\", \"Poka-yoke\", \"TPM\", \"Value stream mapping\"],\n              answer: 1,\n              explain: \"Poka-yoke (error-proofing) designs the part or fixture so that incorrect installation is physically impossible.\",\n            },\n            {\n              kind: \"select\",\n              label: \"Problem: The factory frequently runs out of key components, then overorders, creating alternating stockouts and excess inventory.\",\n              options: [\"SMED\", \"Kanban\", \"5S\", \"Poka-yoke\"],\n              answer: 1,\n              explain: \"Kanban provides visual pull signals that trigger replenishment only when stock drops to a defined level, smoothing the supply chain.\",\n            },\n          ],\n          hint: \"Match the tool to the specific type of waste or problem it was designed to address.\",\n        },\n      ],\n    },\n\n    /* ──────────────────────────────────────────────────────────\n     * LESSON 6 — Practice\n     * ────────────────────────────────────────────────────────── */\n    {\n      id: \"aqe-m8-practice\",\n      title: \"Practice: Lean Six Sigma and continuous improvement\",\n      minutes: 30,\n      objectives: [\n        \"Classify the eight wastes (TIMWOODS) and map them to manufacturing observations\",\n        \"Conduct structured root cause analysis using 5 Whys and fishbone diagrams\",\n        \"Perform Pareto analysis and DMAIC sigma-level calculations for process improvement projects\",\n      ],\n      blocks: [\n        { type: \"h\", text: \"Practice exercises\" },\n        {\n          type: \"p\",\n          text:\n            \"Complete the four exercises below. They progress from beginner to expert level, covering \" +\n            \"the core skills of this module: waste identification, root cause analysis, Pareto analysis, \" +\n            \"and full DMAIC project calculations.\",\n        },\n\n        /* Practice 1: beginner — sorter — classify 8 wastes */\n        {\n          type: \"sorter\",\n          id: \"aqe-m8-practice-lab1\",\n          level: \"beginner\",\n          title: \"Classify the 8 wastes from workplace examples\",\n          task:\n            \"A food processing plant in Maroua has asked you to conduct a waste walk. \" +\n            \"Classify each observation into the correct waste category.\",\n          layout: \"columns\",\n          buckets: [\n            { label: \"Defects\" },\n            { label: \"Overproduction\" },\n            { label: \"Waiting\" },\n            { label: \"Non-utilised talent\" },\n            { label: \"Transportation\" },\n            { label: \"Inventory\" },\n            { label: \"Motion\" },\n            { label: \"Extra processing\" },\n          ],\n          items: [\n            {\n              text: \"Bags of millet flour rejected because of incorrect weight (underweight by 50 g)\",\n              bucket: 0,\n              explain: \"Products not meeting weight specifications are defects requiring rework or disposal.\",\n            },\n            {\n              text: \"The night shift produces 150 extra bags 'just in case' even though no orders require them\",\n              bucket: 1,\n              explain: \"Producing beyond customer demand is overproduction — the most harmful waste because it drives other wastes.\",\n            },\n            {\n              text: \"The grinding mill is down for 90 minutes every morning waiting for maintenance to replace worn screens\",\n              bucket: 2,\n              explain: \"Equipment idle time due to delayed maintenance parts is waiting waste.\",\n            },\n            {\n              text: \"A quality technician with food science training spends half her day entering data into a spreadsheet that could be automated\",\n              bucket: 3,\n              explain: \"Using a skilled professional for routine data entry wastes their expertise (non-utilised talent).\",\n            },\n            {\n              text: \"Finished bags are moved by hand cart to a temporary area, then moved again to the loading dock — a total distance of 200 m with an intermediate stop\",\n              bucket: 4,\n              explain: \"Double-handling and unnecessary material movement is transportation waste.\",\n            },\n            {\n              text: \"The store room holds 14 weeks of packaging material even though the supplier delivers weekly\",\n              bucket: 5,\n              explain: \"Excess raw material inventory beyond what is needed ties up cash and space (inventory waste).\",\n            },\n            {\n              text: \"The bagging operator bends down 400 times per shift to pick bags from a pallet on the floor instead of using an elevated dispenser\",\n              bucket: 6,\n              explain: \"Repetitive bending is unnecessary human movement — motion waste that also causes ergonomic strain.\",\n            },\n            {\n              text: \"Each bag is hand-stitched closed and then re-stitched with a reinforcing row, although the single stitch meets the closure strength standard\",\n              bucket: 7,\n              explain: \"The reinforcing stitch exceeds the customer requirement — extra processing waste.\",\n            },\n          ],\n        },\n\n        /* Practice 2: intermediate — whys — 5 Whys for a production problem */\n        {\n          type: \"whys\",\n          id: \"aqe-m8-practice-lab2\",\n          level: \"intermediate\",\n          title: \"5 Whys: high scrap rate on plastic injection moulding\",\n          task:\n            \"A plastic container factory in Douala is experiencing a 9% scrap rate due to short shots \" +\n            \"(incomplete filling of the mould). Use the 5 Whys to identify the root cause.\",\n          problem: \"9% of injection-moulded plastic containers have short shots (incompletely filled sections).\",\n          steps: [\n            {\n              question: \"Why are the containers showing short shots?\",\n              options: [\n                \"Because the molten plastic is not completely filling the mould cavity\",\n                \"Because the containers are the wrong colour\",\n                \"Because the moulds are too new\",\n                \"Because the operators are working too fast\",\n              ],\n              answer: 0,\n              explain: \"Short shots occur when plastic does not flow into all areas of the mould cavity before solidifying.\",\n            },\n            {\n              question: \"Why is the plastic not completely filling the mould?\",\n              options: [\n                \"Because the injection pressure is too low for the mould geometry\",\n                \"Because the plastic pellets are too expensive\",\n                \"Because the mould is painted the wrong colour\",\n                \"Because the factory is located in a humid area\",\n              ],\n              answer: 0,\n              explain: \"Pressure measurements show 85 bar versus the required 110 bar for this mould — insufficient to push plastic into thin-walled sections.\",\n            },\n            {\n              question: \"Why is the injection pressure too low?\",\n              options: [\n                \"Because the hydraulic system has a leaking seal reducing available pressure\",\n                \"Because the operator prefers lower pressure\",\n                \"Because the machine is too large for the mould\",\n                \"Because the raw material supplier changed countries\",\n              ],\n              answer: 0,\n              explain: \"Maintenance inspection found a worn hydraulic cylinder seal allowing pressure bypass, reducing effective injection force.\",\n            },\n            {\n              question: \"Why was the leaking hydraulic seal not detected and replaced?\",\n              options: [\n                \"Because the machine is not included in the preventive maintenance schedule\",\n                \"Because the seal is a new design that just came out\",\n                \"Because the operator intentionally damaged the seal\",\n                \"Because hydraulic seals never need replacement\",\n              ],\n              answer: 0,\n              explain: \"This injection moulding machine was installed 18 months ago but was never added to the PM schedule, so no periodic seal inspections were performed.\",\n            },\n          ],\n          countermeasure: {\n            question: \"What countermeasure addresses the root cause?\",\n            options: [\n              \"Buy a completely new injection moulding machine\",\n              \"Replace the seal and add the machine to the preventive maintenance schedule with quarterly hydraulic system inspections\",\n              \"Increase the raw material pellet size to require less pressure\",\n              \"Reduce production speed to give plastic more time to fill the mould\",\n            ],\n            answer: 1,\n            explain:\n              \"Replacing the seal fixes the immediate problem, and adding the machine to the PM schedule \" +\n              \"with quarterly inspections prevents recurrence by ensuring seals are checked before they \" +\n              \"deteriorate to the point of causing defects.\",\n          },\n          hint: \"Each answer should logically explain the previous one. Think about what physical mechanism causes short shots and trace it back to the management system.\",\n        },\n\n        /* Practice 3: advanced — pareto — analyse defect data */\n        {\n          type: \"pareto\",\n          id: \"aqe-m8-practice-lab3\",\n          level: \"advanced\",\n          title: \"Pareto analysis: aluminium extrusion defects\",\n          task:\n            \"An aluminium extrusion plant in Edéa recorded 1,245 defects over one quarter. \" +\n            \"Use the Pareto chart to identify the vital few defect categories. What percentage \" +\n            \"of total defects do the top three categories represent?\",\n          unit: \"defects\",\n          categories: [\n            { label: \"Surface scratches\", count: 423 },\n            { label: \"Dimensional out-of-tolerance\", count: 287 },\n            { label: \"Twist/bow\", count: 196 },\n            { label: \"Die lines\", count: 148 },\n            { label: \"Porosity\", count: 97 },\n            { label: \"Colour mismatch (anodising)\", count: 58 },\n            { label: \"Cut length errors\", count: 36 },\n          ],\n          hint:\n            \"The top three categories (surface scratches, dimensional OOT, twist/bow) account for \" +\n            \"423 + 287 + 196 = 906 out of 1,245 defects = 72.8%. These are the vital few.\",\n        },\n\n        /* Practice 4: expert — sheet — DMAIC project calculations */\n        {\n          type: \"sheet\",\n          id: \"aqe-m8-practice-lab4\",\n          level: \"expert\",\n          title: \"DMAIC project calculations\",\n          task:\n            \"Complete the DMAIC project summary calculations for a cocoa bean sorting operation \" +\n            \"in the South-West Region. Calculate baseline metrics, improvement targets, sigma levels, \" +\n            \"and cost of quality savings. Fill in the yellow cells.\",\n          data: [\n            [\"DMAIC Project Summary\", \"\", \"\"],\n            [\"\", \"Baseline (Before)\", \"Target (After)\"],\n            [\"Units processed per month\", 50000, 50000],\n            [\"Opportunities per unit\", 3, 3],\n            [\"Total opportunities\", null, null],\n            [\"Defects found\", 2850, null],\n            [\"DPMO\", null, null],\n            [\"Yield (%)\", null, null],\n            [\"Approx. sigma level\", null, null],\n            [\"\", \"\", \"\"],\n            [\"Cost of quality\", \"Baseline (FCFA/month)\", \"Target (FCFA/month)\"],\n            [\"Scrap cost\", 4275000, null],\n            [\"Rework cost\", 2850000, null],\n            [\"Total failure cost\", null, null],\n            [\"Monthly savings\", \"\", null],\n            [\"Annual savings\", \"\", null],\n          ],\n          editable: [\n            \"B5\", \"C5\",\n            \"C6\",\n            \"B7\", \"C7\",\n            \"B8\", \"C8\",\n            \"B9\", \"C9\",\n            \"C12\", \"C13\",\n            \"B14\", \"C14\",\n            \"C15\",\n            \"C16\",\n          ],\n          checks: [\n            { cell: \"B5\", equals: 150000 },\n            { cell: \"C5\", equals: 150000 },\n            { cell: \"C6\", equals: 900, tol: 5 },\n            { cell: \"B7\", equals: 19000, tol: 50 },\n            { cell: \"C7\", equals: 6000, tol: 50 },\n            { cell: \"B8\", equals: 98.10, tol: 0.05 },\n            { cell: \"C8\", equals: 99.40, tol: 0.05 },\n            { cell: \"B9\", equals: 3.6, tol: 0.2 },\n            { cell: \"C9\", equals: 4.0, tol: 0.2 },\n            { cell: \"C12\", equals: 1350000, tol: 10000 },\n            { cell: \"C13\", equals: 900000, tol: 10000 },\n            { cell: \"B14\", equals: 7125000 },\n            { cell: \"C14\", equals: 2250000, tol: 10000 },\n            { cell: \"C15\", equals: 4875000, tol: 10000 },\n            { cell: \"C16\", equals: 58500000, tol: 200000 },\n          ],\n          hint:\n            \"Total opportunities = units × opportunities per unit (150,000). Target defects: the project aims \" +\n            \"to reduce DPMO from ~19,000 to ~6,000 (a shift from ~3.6σ to ~4.0σ). Target defects = \" +\n            \"DPMO × total opportunities ÷ 1,000,000 = 6,000 × 150,000 ÷ 1,000,000 = 900. Costs scale \" +\n            \"proportionally: target scrap = baseline scrap × (target defects ÷ baseline defects) = \" +\n            \"4,275,000 × (900 ÷ 2,850) ≈ 1,350,000. Monthly savings = baseline failure cost − target \" +\n            \"failure cost. Annual savings = monthly savings × 12.\",\n          solution: {\n            B5: \"=50000*3\",\n            C5: \"=50000*3\",\n            C6: \"900\",\n            B7: \"=(2850/150000)*1000000\",\n            C7: \"=(900/150000)*1000000\",\n            B8: \"=(1-19000/1000000)*100\",\n            C8: \"=(1-6000/1000000)*100\",\n            B9: \"3.6\",\n            C9: \"4.0\",\n            C12: \"=4275000*(900/2850)\",\n            C13: \"=2850000*(900/2850)\",\n            B14: \"=4275000+2850000\",\n            C14: \"=1350000+900000\",\n            C15: \"=7125000-2250000\",\n            C16: \"=4875000*12\",\n          },\n        },\n      ],\n    },\n  ],\n\n  /* ──────────────────────────────────────────────────────────\n   * MODULE QUIZ\n   * ────────────────────────────────────────────────────────── */\n  quiz: {\n    id: \"aqe-m8-quiz\",\n    title: \"Module 8 Quiz — Lean Six Sigma and Continuous Improvement\",\n    passPct: 75,\n    questions: [\n      {\n        id: \"aqe-m8-q1\",\n        question:\n          \"What does DPMO stand for, and what is the DPMO value for a 6σ process (with the standard 1.5σ shift)?\",\n        options: [\n          \"Defects Per Million Observations — 34\",\n          \"Defects Per Million Opportunities — 3.4\",\n          \"Defects Per Measured Output — 3,400\",\n          \"Defects Per Manufacturing Operation — 340\",\n        ],\n        answer: 1,\n        explain:\n          \"DPMO = Defects Per Million Opportunities. A 6σ process (with the customary 1.5σ long-term shift) produces only 3.4 DPMO.\",\n      },\n      {\n        id: \"aqe-m8-q2\",\n        question:\n          \"In which DMAIC phase would you construct a fishbone diagram and conduct a 5 Whys analysis?\",\n        options: [\n          \"Define\",\n          \"Measure\",\n          \"Analyse\",\n          \"Improve\",\n        ],\n        answer: 2,\n        explain:\n          \"The Analyse phase is dedicated to identifying and verifying root causes using tools such as fishbone diagrams, 5 Whys, Pareto charts, and hypothesis tests.\",\n      },\n      {\n        id: \"aqe-m8-q3\",\n        question:\n          \"A CTQ tree translates which of the following into measurable specifications?\",\n        options: [\n          \"Management financial targets\",\n          \"Voice of the customer (VOC) needs\",\n          \"Supplier delivery schedules\",\n          \"Employee satisfaction survey results\",\n        ],\n        answer: 1,\n        explain:\n          \"The CTQ (Critical-to-Quality) tree systematically decomposes voice of the customer data into needs, drivers, and measurable specifications that the process must achieve.\",\n      },\n      {\n        id: \"aqe-m8-q4\",\n        question:\n          \"A process has FPY values of 96%, 88%, and 94% at three sequential steps. What is the rolled throughput yield (RTY)?\",\n        options: [\n          \"92.7%\",\n          \"79.5%\",\n          \"88.0%\",\n          \"96.0%\",\n        ],\n        answer: 1,\n        explain:\n          \"RTY = 0.96 × 0.88 × 0.94 = 0.7937, or approximately 79.5%. RTY reveals the cumulative effect of losses across all process steps.\",\n      },\n      {\n        id: \"aqe-m8-q5\",\n        question:\n          \"Which of the following is NOT one of the eight wastes in the DOWNTIME framework?\",\n        options: [\n          \"Defects\",\n          \"Depreciation\",\n          \"Overproduction\",\n          \"Non-utilised talent\",\n        ],\n        answer: 1,\n        explain:\n          \"DOWNTIME stands for Defects, Overproduction, Waiting, Non-utilised talent, Transportation, Inventory, Motion, and Extra processing. Depreciation is an accounting concept, not one of the eight wastes.\",\n      },\n      {\n        id: \"aqe-m8-q6\",\n        question:\n          \"A factory produces items in batches of 5,000 even though daily demand is only 500. Which lean tool most directly addresses this problem?\",\n        options: [\n          \"5S\",\n          \"Poka-yoke\",\n          \"SMED (Single Minute Exchange of Die)\",\n          \"TPM (Total Productive Maintenance)\",\n        ],\n        answer: 2,\n        explain:\n          \"Large batches are typically driven by long changeover times — it takes so long to change over that the factory tries to minimise the number of changeovers. SMED reduces changeover time, enabling smaller batches closer to actual demand.\",\n      },\n      {\n        id: \"aqe-m8-q7\",\n        question:\n          \"What is the primary purpose of a control plan in the Control phase of DMAIC?\",\n        options: [\n          \"To calculate the project's return on investment\",\n          \"To document what to monitor, how to measure it, and what action to take if the process drifts\",\n          \"To identify root causes of defects\",\n          \"To select which improvement project to pursue next\",\n        ],\n        answer: 1,\n        explain:\n          \"The control plan specifies what process parameters to monitor, the measurement method, sampling frequency, control limits, and the reaction plan — ensuring improvements are sustained after the project team disbands.\",\n      },\n      {\n        id: \"aqe-m8-q8\",\n        question:\n          \"In a value stream map, the current-state map shows a total lead time of 10 days but only 45 minutes of value-adding time. Which lean principle does this analysis most directly support?\",\n        options: [\n          \"Pull — produce only what the customer orders\",\n          \"Value — define value from the customer's perspective\",\n          \"Flow — eliminate waiting and batch processing to create continuous flow\",\n          \"Perfection — continuously pursue the ideal state\",\n        ],\n        answer: 2,\n        explain:\n          \"The huge gap between lead time (10 days) and value-adding time (45 minutes) indicates extensive waiting, batching, and queue time. The Flow principle addresses this by arranging steps in continuous sequence to eliminate non-value-adding time.\",\n      },\n    ],\n  },\n};\n"};
const PATCHES = [["client/src/lms/registry.ts","import { MAS_COURSE } from \"../data/courses/mas\";","import { MAS_COURSE } from \"../data/courses/mas\";\nimport { AQE_COURSE } from \"../data/courses/aqe\";"],["client/src/lms/registry.ts","  mas: MAS_COURSE,","  mas: MAS_COURSE,\n  aqe: AQE_COURSE,"]];
function applyPatches(read, patches) {
  const out = {}, problems = [];
  for (const [file, find, repl] of patches) {
    const src = out[file] ?? read(file);
    if (src == null) { problems.push(file + ": file not found"); continue; }
    const n = src.split(find).length - 1;
    if (n !== 1) { problems.push(file + ": expected 1 match, found " + n + " for: " + find.split("\n")[0].slice(0, 70)); out[file] = src; continue; }
    out[file] = src.replace(find, () => repl);
  }
  return { out, problems };
}
